import React, { useCallback, useMemo, useState } from "react";
import { Check, Clock3, Search, Trophy } from "lucide-react";
import MatchResultDialog from "../../leaderboard/components/MatchResultDialog";
import { getMatchParticipants, playerIdKey, resolveMatchResult } from "../../../state/matchResults";

const focusStyle = "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-pickle-tan focus-visible:ring-offset-2";
const courtKey = (match) => String(match.courtId ?? match.courtName ?? "unknown");
const courtLabel = (match) => match.courtName || `Court ${match.courtId ?? "—"}`;

function when(match) {
  const stamp = match.endTime || match.startTime;
  return stamp ? new Date(stamp).toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }) : "Time unavailable";
}

function duration(match) {
  const ms = match.durationMs ?? (match.endTime && match.startTime ? match.endTime - match.startTime : 0);
  return ms > 0 ? `${Math.floor(ms / 60000)}m ${Math.floor((ms % 60000) / 1000)}s` : "—";
}

export default function MatchHistoryTable({ matches = [], players = [], sessionId, onRecordResult, showFilters = true }) {
  const [search, setSearch] = useState("");
  const [court, setCourt] = useState("all");
  const [filter, setFilter] = useState("all");
  const [editingMatch, setEditingMatch] = useState(null);
  const closeEditor = useCallback(() => setEditingMatch(null), []);
  const entries = useMemo(() => matches.map((match) => ({
    match, participants: getMatchParticipants(match, players), result: resolveMatchResult(match),
  })).sort((a, b) => (b.match.endTime || b.match.startTime || 0) - (a.match.endTime || a.match.startTime || 0)), [matches, players]);
  const courts = Array.from(new Map(entries.map(({ match }) => [courtKey(match), courtLabel(match)])).entries());
  const searched = !showFilters ? entries : entries.filter(({ match, participants }) => (court === "all" || courtKey(match) === court)
    && (!search.trim() || participants.some((p) => p.name.toLowerCase().includes(search.trim().toLowerCase()))));
  const counts = {
    all: searched.length,
    needs: searched.filter(({ match, result }) => match.status === "completed" && !result.recorded).length,
    recorded: searched.filter(({ result }) => result.recorded).length,
  };
  const visible = !showFilters ? entries : searched.filter(({ match, result }) => filter === "all" || (filter === "recorded" ? result.recorded : match.status === "completed" && !result.recorded));
  const pending = entries.filter(({ match, result }) => match.status === "completed" && !result.recorded).length;

  return (
    <section aria-label="Match history" className="flex h-full min-h-0 flex-col">
      <div className="shrink-0 space-y-4 pb-4">
        <div className="flex items-center gap-3 rounded-2xl border border-pickle-tan/20 bg-pickle-tan/10 px-4 py-3">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white text-pickle-tan"><Trophy size={20} /></span>
          <div><p className="text-sm font-semibold text-pickle-green">{pending ? `${pending} ${pending === 1 ? "match needs" : "matches need"} a result` : "Results shape the standings"}</p>
            <p className="mt-0.5 hidden sm:block text-xs text-slate-600">Choose the winning pair and final score. Rankings update when you save.</p></div>
        </div>
        {showFilters && <div className="flex gap-2 sm:gap-3">
          <label className="relative min-w-0 flex-1"><Search aria-hidden="true" size={18} className="absolute left-3 top-3.5 text-slate-400" />
            <input aria-label="Search match players" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search players…"
              className={`h-11 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-3 text-sm text-slate-800 placeholder:text-slate-400 ${focusStyle}`} /></label>
          <select aria-label="Filter matches by court" value={court} onChange={(e) => setCourt(e.target.value)} className={`h-11 max-w-[120px] shrink-0 rounded-xl border border-slate-200 bg-white px-2 text-sm text-slate-700 sm:max-w-none sm:px-3 ${focusStyle}`}>
            <option value="all">All courts</option>{courts.map(([key, name]) => <option key={key} value={key}>{name}</option>)}
          </select>
        </div>}
        {showFilters ? <div className="flex flex-wrap gap-2" aria-label="Filter matches by result">
          {[['all', 'All'], ['needs', 'Needs result'], ['recorded', 'Recorded']].map(([key, label]) => <button key={key} type="button" aria-pressed={filter === key} onClick={() => setFilter(key)}
            className={`min-h-[44px] rounded-full border px-3 text-xs font-semibold sm:px-4 ${filter === key ? "border-pickle-green bg-pickle-green text-white" : "border-slate-200 bg-white text-slate-600 hover:border-pickle-tan"} ${focusStyle}`}>{label} <span className={`ml-1 rounded-full px-1.5 py-0.5 tabular-nums ${filter === key ? "bg-white/15" : "bg-slate-100"}`}>{counts[key]}</span></button>)}
        </div> : <p className="text-xs font-medium text-slate-500">{entries.length} {entries.length === 1 ? "match" : "matches"} this session · Newest first</p>}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto custom-scrollbar">
        {visible.length ? <div className="space-y-3 pb-2">
          {visible.map(({ match, participants, result }) => {
            const namesFor = (team) => (match.teams?.[team] || []).map((id) => participants.find((p) => playerIdKey(p.id) === playerIdKey(id))?.name || `Player ${id}`).join(" & ");
            const winner = result.winner === "blue" ? "blue" : "green";
            const loser = winner === "green" ? "blue" : "green";
            const draw = result.winner === "tie";
            return <article key={match.id} aria-label={`${courtLabel(match)} match ${when(match)}`} className="rounded-2xl border border-slate-200 bg-white p-4 sm:grid sm:grid-cols-[140px_minmax(0,1fr)_auto] sm:items-center sm:gap-5 sm:p-5">
              <div className="mb-3 flex items-start justify-between gap-3 sm:mb-0 sm:block">
                <div><p className="text-sm font-semibold text-slate-800">{courtLabel(match)}</p><p className="mt-1 text-xs text-slate-500">{when(match)}</p>
                  <p className="mt-1 flex items-center gap-1 text-xs text-slate-400"><Clock3 size={12} aria-hidden="true" />{duration(match)}</p></div>
                <span className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full px-2 py-1 text-[11px] font-semibold sm:mt-2 ${result.recorded ? "bg-emerald-50 text-emerald-800" : match.status === "in_progress" ? "bg-slate-100 text-slate-600" : "bg-amber-50 text-amber-800"}`}>
                  {result.recorded && <Check size={12} />}{result.recorded ? draw ? "Draw" : "Recorded" : match.status === "in_progress" ? "In progress" : "Needs result"}</span>
              </div>
              {result.recorded ? <div className="space-y-2">
                {[winner, loser].map((team, index) => <div key={team} className={`flex items-center justify-between gap-3 rounded-xl px-3 py-2 ${index === 0 && !draw ? "bg-emerald-50/70" : "bg-slate-50"}`}>
                  <div className="min-w-0"><p className={`flex items-center gap-1 text-[11px] font-semibold ${team === "green" ? "text-emerald-800" : "text-blue-800"}`}>{index === 0 && !draw && <Trophy size={12} />}{draw ? team === "green" ? "Green" : "Blue" : index === 0 ? "Winner" : "Loser"}</p><p className="mt-0.5 break-words text-sm font-semibold text-slate-800">{namesFor(team)}</p></div>
                  <span className="shrink-0 text-2xl font-semibold tabular-nums text-pickle-green">{result.score[team]}</span>
                </div>)}
              </div> : <div className="flex flex-wrap gap-2">{participants.map((p, index) => <span key={`${p.id}-${index}`} className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-sm font-medium text-slate-700">{p.name}</span>)}{!participants.length && <p className="text-sm text-slate-500">Player details are missing.</p>}</div>}
              <div className="mt-4 sm:mt-0"><button type="button" disabled={match.status !== "completed"} onClick={() => setEditingMatch(match)}
                className={`min-h-[44px] w-full rounded-xl border px-4 text-sm font-semibold sm:w-auto ${result.recorded ? "border-slate-200 text-pickle-green hover:bg-slate-50" : "border-pickle-green bg-pickle-green text-white hover:bg-pickle-green/90"} disabled:cursor-not-allowed disabled:border-slate-200 disabled:bg-slate-100 disabled:text-slate-400 ${focusStyle}`}>{match.status === "in_progress" ? "Playing" : result.recorded ? "Edit result" : "Record result"}</button></div>
            </article>;
          })}
        </div> : <div className="flex flex-col items-center justify-center rounded-2xl border border-dashed border-pickle-green/20 bg-white px-5 py-12 text-center">
          <Trophy size={28} className="mb-3 text-pickle-tan" /><p className="text-base font-semibold text-slate-800">{entries.length ? "No matches fit these filters" : "No matches yet"}</p>
          <p className="mt-1 max-w-sm text-sm text-slate-500">{entries.length ? "Try another player name, court, or result filter." : "Finish a match on the courts, then record the winners and score here."}</p>
          {entries.length > 0 && <button type="button" onClick={() => { setSearch(""); setCourt("all"); setFilter("all"); }} className={`mt-4 min-h-[44px] rounded-xl px-4 text-sm font-semibold text-pickle-green hover:bg-pickle-green/5 ${focusStyle}`}>Clear filters</button>}
        </div>}
      </div>
      {editingMatch && <MatchResultDialog match={editingMatch} players={players} sessionId={sessionId} onRecordResult={onRecordResult} onClose={closeEditor} />}
    </section>
  );
}
