/**
 * calculateGroupStandings(groupId, allPartners, allMatches)
 * Returns sorted array of standing rows for a single group.
 *
 * StandingRow: { partner, wins, losses, points, pointsScored, pointsConceded, pointDiff }
 */
export function calculateGroupStandings(groupId, allPartners, allMatches) {
  const groupPartners = allPartners.filter((p) => p.group_id === groupId && !p.withdrawn);
  const completedMatches = allMatches.filter(
    (m) =>
      m.group_id === groupId &&
      m.phase === "group_stage" &&
      (m.status === "completed" || m.status === "bye")
  );

  const records = {};
  groupPartners.forEach((p) => {
    records[p.id] = {
      partner: p,
      wins: 0,
      losses: 0,
      points: 0,
      pointsScored: 0,
      pointsConceded: 0,
    };
  });

  for (const match of completedMatches) {
    const { partner_a_id, partner_b_id, winner_id, scores, status } = match;

    if (status === "bye") {
      // Bye = free win, 3 points
      if (winner_id && records[winner_id]) {
        records[winner_id].wins += 1;
        records[winner_id].points += 3;
      }
      continue;
    }

    // Count wins/losses/points
    if (winner_id) {
      const loserId = winner_id === partner_a_id ? partner_b_id : partner_a_id;
      if (records[winner_id]) {
        records[winner_id].wins += 1;
        records[winner_id].points += 3;
      }
      if (loserId && records[loserId]) {
        records[loserId].losses += 1;
        records[loserId].points += 1;
      }
    } else {
      // No winner recorded yet — treat as loss for both (shouldn't happen for completed)
      if (records[partner_a_id]) records[partner_a_id].losses += 1;
      if (records[partner_b_id]) records[partner_b_id].losses += 1;
    }

    // Tally game scores
    if (Array.isArray(scores)) {
      for (const game of scores) {
        const aScore = Number(game.partner_a || 0);
        const bScore = Number(game.partner_b || 0);
        if (partner_a_id && records[partner_a_id]) {
          records[partner_a_id].pointsScored += aScore;
          records[partner_a_id].pointsConceded += bScore;
        }
        if (partner_b_id && records[partner_b_id]) {
          records[partner_b_id].pointsScored += bScore;
          records[partner_b_id].pointsConceded += aScore;
        }
      }
    }
  }

  const rows = Object.values(records).map((r) => ({
    ...r,
    pointDiff: r.pointsScored - r.pointsConceded,
  }));

  // Sort with tiebreaker order
  rows.sort((a, b) => {
    // 1. Total points
    if (b.points !== a.points) return b.points - a.points;
    // 2. Head-to-head
    const h2h = getHeadToHead(a.partner.id, b.partner.id, completedMatches);
    if (h2h === "a") return -1;
    if (h2h === "b") return 1;
    // 3. Point differential
    if (b.pointDiff !== a.pointDiff) return b.pointDiff - a.pointDiff;
    // 4. Points scored
    if (b.pointsScored !== a.pointsScored) return b.pointsScored - a.pointsScored;
    // 5. Equal (admin decides)
    return 0;
  });

  return rows;
}

/**
 * getHeadToHead(partnerAId, partnerBId, completedMatches)
 * Returns "a" | "b" | "tie"
 */
export function getHeadToHead(partnerAId, partnerBId, completedMatches) {
  const h2hMatches = completedMatches.filter(
    (m) =>
      (m.partner_a_id === partnerAId && m.partner_b_id === partnerBId) ||
      (m.partner_a_id === partnerBId && m.partner_b_id === partnerAId)
  );

  let aWins = 0;
  let bWins = 0;

  for (const m of h2hMatches) {
    if (m.winner_id === partnerAId) aWins++;
    else if (m.winner_id === partnerBId) bWins++;
  }

  if (aWins > bWins) return "a";
  if (bWins > aWins) return "b";
  return "tie";
}

/**
 * getAdvancingPartners(division, groups, allPartners, allMatches)
 * Returns seeded array of partners advancing from groups to playoffs.
 * advance_count per group, seeded by: group winners first, then runners-up, etc.
 */
export function getAdvancingPartners(division, groups, allPartners, allMatches) {
  const standings = groups.map((g) => ({
    group: g,
    rows: calculateGroupStandings(g.id, allPartners, allMatches),
  }));

  const advancing = [];
  const advanceCount = division.advance_count || 2;

  for (let rank = 0; rank < advanceCount; rank++) {
    standings.forEach(({ rows }) => {
      if (rows[rank]) {
        advancing.push({ ...rows[rank].partner, groupRank: rank + 1 });
      }
    });
  }

  return advancing;
}
