import { useState, useEffect, useCallback, useMemo } from "react";
import toast from "react-hot-toast";
import { loadTournamentState, saveTournamentState } from "../storage/tournamentStorage";
import { generateId } from "../utils/ids";
import { generateRoundRobin } from "../utils/roundRobin";
import { generateSchedule } from "../utils/scheduler";
import { determineMatchWinner, getTournamentSettings } from "../utils/matchValidation";
import { getAdvancingPartners } from "../utils/standings";
import { generateSingleEliminationBracket } from "../utils/bracket";

export default function useTournamentManager() {
  const [tournaments, setTournaments] = useState(() => loadTournamentState().tournaments);
  const [divisions, setDivisions] = useState(() => loadTournamentState().divisions);
  const [groups, setGroups] = useState(() => loadTournamentState().groups);
  const [partners, setPartners] = useState(() => loadTournamentState().partners);
  const [matches, setMatches] = useState(() => loadTournamentState().matches);

  // Persist on every change
  useEffect(() => {
    saveTournamentState({ tournaments, divisions, groups, partners, matches });
  }, [tournaments, divisions, groups, partners, matches]);

  // ─── Derived selectors ────────────────────────────────────────────────────

  const allTournaments = useMemo(
    () => Object.values(tournaments).sort((a, b) => new Date(b.created_at) - new Date(a.created_at)),
    [tournaments]
  );

  const getDivisionsForTournament = useCallback(
    (tid) => Object.values(divisions).filter((d) => d.tournament_id === tid),
    [divisions]
  );

  const getGroupsForDivision = useCallback(
    (did) => Object.values(groups).filter((g) => g.division_id === did),
    [groups]
  );

  const getPartnersForDivision = useCallback(
    (did) => Object.values(partners).filter((p) => p.division_id === did),
    [partners]
  );

  const getPartnersForGroup = useCallback(
    (gid) => Object.values(partners).filter((p) => p.group_id === gid),
    [partners]
  );

  const getPartnersForTournament = useCallback(
    (tid) => Object.values(partners).filter((p) => p.tournament_id === tid),
    [partners]
  );

  const getMatchesForTournament = useCallback(
    (tid) => Object.values(matches).filter((m) => m.tournament_id === tid),
    [matches]
  );

  const getMatchesForGroup = useCallback(
    (gid) => Object.values(matches).filter((m) => m.group_id === gid),
    [matches]
  );

  // ─── Tournament CRUD ──────────────────────────────────────────────────────

  const createTournament = useCallback((data) => {
    const id = generateId();
    const now = new Date().toISOString();
    const tournament = {
      id,
      name: data.name || "New Tournament",
      // format field lives at division level (not tournament level) since storage v4
      start_date: data.start_date || null,
      end_date: data.end_date || null,
      match_duration: data.match_duration || 60,
      daily_window_start: data.daily_window_start || "08:00",
      daily_window_end: data.daily_window_end || "20:00",
      games_per_day: data.games_per_day != null ? Number(data.games_per_day) : 0,
      points_to_win: data.points_to_win || 11,
      win_by: data.win_by || 2,
      best_of: data.best_of || 1,
      scoring_type: data.scoring_type || "rally",
      courts: (() => {
        if (data.courts?.length) return data.courts;
        const count = Number(data.court_count) || 4;
        return Array.from({ length: count }, (_, i) => `Court ${i + 1}`);
      })(),
      phase: "setup",
      sponsors: [],
      display_settings: {
        slideshow_interval: 15,
        sponsor_slideshow_interval: 8,
        transition_enabled: true,
      },
      created_at: now,
      updated_at: now,
    };
    setTournaments((prev) => ({ ...prev, [id]: tournament }));
    toast.success("Tournament created.");
    return id;
  }, []);

  const updateTournament = useCallback((tournamentId, updates) => {
    setTournaments((prev) => {
      if (!prev[tournamentId]) return prev;
      return {
        ...prev,
        [tournamentId]: {
          ...prev[tournamentId],
          ...updates,
          updated_at: new Date().toISOString(),
        },
      };
    });
  }, []);

  // ─── Sponsor management ───────────────────────────────────────────────────

  const addSponsor = useCallback((tournamentId, { name }) => {
    const id = generateId();
    const now = new Date().toISOString();
    setTournaments((prev) => {
      const t = prev[tournamentId];
      if (!t) return prev;
      const sponsors = [...(t.sponsors || [])];
      sponsors.push({ id, name, enabled: true, order: sponsors.length, created_at: now });
      return { ...prev, [tournamentId]: { ...t, sponsors, updated_at: now } };
    });
    toast.success("Sponsor added.");
    return id;
  }, []);

  const removeSponsor = useCallback((tournamentId, sponsorId) => {
    setTournaments((prev) => {
      const t = prev[tournamentId];
      if (!t) return prev;
      const sponsors = (t.sponsors || []).filter((s) => s.id !== sponsorId);
      return { ...prev, [tournamentId]: { ...t, sponsors, updated_at: new Date().toISOString() } };
    });
  }, []);

  const updateSponsor = useCallback((tournamentId, sponsorId, updates) => {
    setTournaments((prev) => {
      const t = prev[tournamentId];
      if (!t) return prev;
      const sponsors = (t.sponsors || []).map((s) =>
        s.id === sponsorId ? { ...s, ...updates } : s
      );
      return { ...prev, [tournamentId]: { ...t, sponsors, updated_at: new Date().toISOString() } };
    });
  }, []);

  const reorderSponsors = useCallback((tournamentId, orderedIds) => {
    setTournaments((prev) => {
      const t = prev[tournamentId];
      if (!t) return prev;
      const map = Object.fromEntries((t.sponsors || []).map((s) => [s.id, s]));
      const sponsors = orderedIds
        .filter((id) => map[id])
        .map((id, idx) => ({ ...map[id], order: idx }));
      return { ...prev, [tournamentId]: { ...t, sponsors, updated_at: new Date().toISOString() } };
    });
  }, []);

  const updateDisplaySettings = useCallback((tournamentId, settings) => {
    setTournaments((prev) => {
      const t = prev[tournamentId];
      if (!t) return prev;
      const display_settings = { ...(t.display_settings || {}), ...settings };
      return { ...prev, [tournamentId]: { ...t, display_settings, updated_at: new Date().toISOString() } };
    });
  }, []);

  const deleteTournament = useCallback((tournamentId) => {
    setTournaments((prev) => {
      const next = { ...prev };
      delete next[tournamentId];
      return next;
    });
    setDivisions((prev) => {
      const next = {};
      Object.values(prev).forEach((d) => {
        if (d.tournament_id !== tournamentId) next[d.id] = d;
      });
      return next;
    });
    // Groups store tournament_id (added in createGroup) so we can cascade directly
    setGroups((prev) => {
      const next = {};
      Object.values(prev).forEach((g) => {
        if (g.tournament_id !== tournamentId) next[g.id] = g;
      });
      return next;
    });
    setPartners((prev) => {
      const next = {};
      Object.values(prev).forEach((p) => {
        if (p.tournament_id !== tournamentId) next[p.id] = p;
      });
      return next;
    });
    setMatches((prev) => {
      const next = {};
      Object.values(prev).forEach((m) => {
        if (m.tournament_id !== tournamentId) next[m.id] = m;
      });
      return next;
    });
    toast.success("Tournament deleted.");
  }, []);

  // ─── Division CRUD ────────────────────────────────────────────────────────

  const createDivision = useCallback((tournamentId, data) => {
    const id = generateId();
    const now = new Date().toISOString();
    const division = {
      id,
      tournament_id: tournamentId,
      name: data.name || "New Division",
      age_bracket: data.age_bracket || "",
      gender_category: data.gender_category || "mixed",
      max_group_size: data.max_group_size || 5,
      advance_count: data.advance_count || 2,
      format: data.format || "round_robin",
      created_at: now,
    };
    setDivisions((prev) => ({ ...prev, [id]: division }));
    return id;
  }, []);

  const updateDivision = useCallback((divisionId, updates) => {
    setDivisions((prev) => {
      if (!prev[divisionId]) return prev;
      return { ...prev, [divisionId]: { ...prev[divisionId], ...updates } };
    });
  }, []);

  const deleteDivision = useCallback((divisionId) => {
    setDivisions((prev) => {
      const next = { ...prev };
      delete next[divisionId];
      return next;
    });
    // Remove associated groups
    const groupIdsToRemove = new Set();
    setGroups((prev) => {
      const next = {};
      Object.values(prev).forEach((g) => {
        if (g.division_id === divisionId) {
          groupIdsToRemove.add(g.id);
        } else {
          next[g.id] = g;
        }
      });
      return next;
    });
    // Unassign partners from this division's groups
    setPartners((prev) => {
      const next = {};
      Object.values(prev).forEach((p) => {
        if (p.division_id === divisionId) {
          next[p.id] = { ...p, division_id: null, group_id: null };
        } else {
          next[p.id] = p;
        }
      });
      return next;
    });
  }, []);

  // ─── Group CRUD ───────────────────────────────────────────────────────────

  const createGroup = useCallback((divisionId, name, tournamentId) => {
    const id = generateId();
    const now = new Date().toISOString();
    setGroups((prev) => ({
      ...prev,
      [id]: { id, division_id: divisionId, tournament_id: tournamentId, name, created_at: now },
    }));
    return id;
  }, []);

  const updateGroup = useCallback((groupId, updates) => {
    setGroups((prev) => {
      if (!prev[groupId]) return prev;
      return { ...prev, [groupId]: { ...prev[groupId], ...updates } };
    });
  }, []);

  const deleteGroup = useCallback((groupId) => {
    setGroups((prev) => {
      const next = { ...prev };
      delete next[groupId];
      return next;
    });
    // Unassign partners from this group
    setPartners((prev) => {
      const next = {};
      Object.values(prev).forEach((p) => {
        if (p.group_id === groupId) {
          next[p.id] = { ...p, group_id: null };
        } else {
          next[p.id] = p;
        }
      });
      return next;
    });
  }, []);

  const autoCreateGroups = useCallback((divisionId, count, tournamentId) => {
    const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    const ids = [];
    for (let i = 0; i < count; i++) {
      const name = `Group ${letters[i] || i + 1}`;
      const id = createGroup(divisionId, name, tournamentId);
      ids.push(id);
    }
    return ids;
  }, [createGroup]);

  // ─── Partner CRUD ─────────────────────────────────────────────────────────

  const addPartner = useCallback((data) => {
    const id = generateId();
    const now = new Date().toISOString();
    const partner = {
      id,
      tournament_id: data.tournament_id,
      division_id: data.division_id,
      group_id: data.group_id || null,
      team_name: data.team_name || "",
      player_1_name: data.player_1_name || "",
      player_2_name: data.player_2_name || "",
      seed: data.seed || null,
      withdrawn: false,
      // Extended player details
      player_1_dob: data.player_1_dob || null,
      player_2_dob: data.player_2_dob || null,
      player_1_gender: data.player_1_gender || null,
      player_2_gender: data.player_2_gender || null,
      player_1_phone: data.player_1_phone || null,
      player_2_phone: data.player_2_phone || null,
      player_1_rating: data.player_1_rating != null ? Number(data.player_1_rating) : null,
      player_2_rating: data.player_2_rating != null ? Number(data.player_2_rating) : null,
      created_at: now,
    };
    setPartners((prev) => ({ ...prev, [id]: partner }));
    return id;
  }, []);

  const updatePartner = useCallback((partnerId, updates) => {
    setPartners((prev) => {
      if (!prev[partnerId]) return prev;
      return { ...prev, [partnerId]: { ...prev[partnerId], ...updates } };
    });
  }, []);

  const removePartner = useCallback(
    (partnerId, tournamentPhase) => {
      if (tournamentPhase === "setup") {
        setPartners((prev) => {
          const next = { ...prev };
          delete next[partnerId];
          return next;
        });
      } else {
        // Mark withdrawn
        setPartners((prev) => {
          if (!prev[partnerId]) return prev;
          return { ...prev, [partnerId]: { ...prev[partnerId], withdrawn: true } };
        });

        // Forfeit scheduled matches; advance opponent in playoff bracket
        setMatches((prev) => {
          const now = new Date().toISOString();
          // Resolve tournament_id before modifying matches
          const tournamentId = Object.values(prev).find(
            (m) => m.partner_a_id === partnerId || m.partner_b_id === partnerId
          )?.tournament_id;

          let next = { ...prev };

          Object.values(prev).forEach((m) => {
            if (
              m.status === "scheduled" &&
              (m.partner_a_id === partnerId || m.partner_b_id === partnerId)
            ) {
              const opponentId =
                m.partner_a_id === partnerId ? m.partner_b_id : m.partner_a_id;
              next[m.id] = {
                ...m,
                status: "completed",
                winner_id: opponentId,
                scores: [],
                completed_at: now,
              };

              // Advance opponent to next round slot in the playoff bracket
              if (m.phase === "playoff" && m.bracket_position != null) {
                const nextRound = m.round + 1;
                const nextPosition = Math.ceil(m.bracket_position / 2);
                const nextMatch = Object.values(next).find(
                  (nm) =>
                    nm.division_id === m.division_id &&
                    nm.phase === "playoff" &&
                    nm.round === nextRound &&
                    nm.bracket_position === nextPosition &&
                    (nm.bracket_type === "winners" || nm.bracket_type === null)
                );
                if (nextMatch) {
                  const slotKey =
                    m.bracket_position % 2 !== 0 ? "partner_a_id" : "partner_b_id";
                  next[nextMatch.id] = { ...next[nextMatch.id], [slotKey]: opponentId };
                }
              }
            }
          });

          // Auto-complete tournament if all playoff matches are now resolved
          if (tournamentId) {
            const tournament = tournaments[tournamentId];
            if (tournament?.phase === "playoffs") {
              const allPlayoffDone = Object.values(next)
                .filter((m) => m.tournament_id === tournamentId && m.phase === "playoff")
                .every((m) => ["completed", "bye", "cancelled"].includes(m.status));
              if (allPlayoffDone) {
                setTournaments((prev) => ({
                  ...prev,
                  [tournamentId]: {
                    ...prev[tournamentId],
                    phase: "completed",
                    updated_at: now,
                  },
                }));
                toast.success("🏆 Tournament completed! All brackets resolved.");
              }
            }
          }

          return next;
        });

        toast.success("Partner withdrawn. Pending matches forfeited.");
      }
    },
    [tournaments]
  );

  const assignPartnerToGroup = useCallback((partnerId, groupId) => {
    setPartners((prev) => {
      if (!prev[partnerId]) return prev;
      return { ...prev, [partnerId]: { ...prev[partnerId], group_id: groupId } };
    });
  }, []);

  const shuffleGroupAssignments = useCallback(
    (divisionId) => {
      const divPartners = Object.values(partners).filter(
        (p) => p.division_id === divisionId && !p.withdrawn
      );
      const divGroups = Object.values(groups).filter((g) => g.division_id === divisionId);
      if (divGroups.length === 0) {
        toast.error("No groups found for this division.");
        return;
      }

      // Fisher-Yates shuffle
      const shuffled = [...divPartners];
      for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
      }

      // Distribute round-robin across groups
      setPartners((prev) => {
        const next = { ...prev };
        shuffled.forEach((p, i) => {
          next[p.id] = { ...next[p.id], group_id: divGroups[i % divGroups.length].id };
        });
        return next;
      });

      toast.success("Groups shuffled.");
    },
    [partners, groups]
  );

  // ─── Per-group match generation ───────────────────────────────────────────

  /**
   * Generate matches for a single group, format-aware.
   * - Round Robin:         generates a full RR schedule (phase: "group_stage")
   * - Single Elimination:  generates an SE bracket for this group (phase: "group_stage"
   *                        with bracket_position / round fields so BracketingTab can
   *                        render them as a draw without a separate playoff advance step)
   *
   * Drops existing unplayed (scheduled + bye) matches for the group first,
   * then creates fresh matches — no scheduling (no date/time/court assigned yet).
   */
  const generateGroupMatches = useCallback((groupId) => {
    const group = groups[groupId];
    if (!group) {
      toast.error("Group not found.");
      return;
    }

    const grpPartners = Object.values(partners).filter(
      (p) => p.group_id === groupId && !p.withdrawn
    );
    if (grpPartners.length < 2) {
      toast.error("Need at least 2 partners in this group to generate matches.");
      return;
    }

    const divisionFormat = divisions[group.division_id]?.format || "round_robin";

    const meta = {
      tournament_id: group.tournament_id,
      division_id: group.division_id,
      group_id: groupId,
    };

    let newMatches;
    if (divisionFormat === "single_elimination") {
      // SE bracket: sort partners by seed (nulls last), then generate
      const sorted = [...grpPartners].sort((a, b) => {
        if (a.seed == null && b.seed == null) return 0;
        if (a.seed == null) return 1;
        if (b.seed == null) return -1;
        return a.seed - b.seed;
      });
      // generateSingleEliminationBracket stamps phase: "playoff" & group_id: null
      // We override both to keep these in the group_stage scope with a group reference.
      const bracketMatches = generateSingleEliminationBracket(sorted, meta);
      newMatches = bracketMatches.map((m) => ({
        ...m,
        group_id: groupId,
        phase: "group_stage",
      }));
    } else {
      newMatches = generateRoundRobin(grpPartners, meta);
    }

    setMatches((prev) => {
      const next = {};
      Object.values(prev).forEach((m) => {
        // Keep: not this group, or already has a real result (completed/in_progress/cancelled)
        const isRealResult = ["completed", "in_progress", "cancelled"].includes(m.status);
        if (m.group_id !== groupId || isRealResult) {
          next[m.id] = m;
        }
        // Drop: scheduled + bye matches for this group → replaced below
      });
      newMatches.forEach((m) => { next[m.id] = m; });
      return next;
    });

    const label = divisionFormat === "single_elimination" ? "bracket match" : "match";
    toast.success(
      `${newMatches.length} ${label}${newMatches.length !== 1 ? "es" : ""} generated for ${group.name}.`
    );
  }, [groups, partners, divisions]);

  /**
   * Generate matches for ALL groups in a division at once.
   * Adds to existing matches (does not drop them — caller should clearMatchesForDivision first).
   */
  const generateAllDivisionMatches = useCallback((divisionId) => {
    const divGroups = Object.values(groups).filter((g) => g.division_id === divisionId);
    if (divGroups.length === 0) {
      toast.error("No groups in this division.");
      return;
    }

    const divisionFormat = divisions[divisionId]?.format || "round_robin";
    const allNewMatches = [];

    divGroups.forEach((g) => {
      const grpPartners = Object.values(partners).filter(
        (p) => p.group_id === g.id && !p.withdrawn
      );
      if (grpPartners.length < 2) return;

      const meta = {
        tournament_id: g.tournament_id,
        division_id: divisionId,
        group_id: g.id,
      };

      let newMatches;
      if (divisionFormat === "single_elimination") {
        const sorted = [...grpPartners].sort((a, b) => {
          if (a.seed == null && b.seed == null) return 0;
          if (a.seed == null) return 1;
          if (b.seed == null) return -1;
          return a.seed - b.seed;
        });
        const bracketMatches = generateSingleEliminationBracket(sorted, meta);
        newMatches = bracketMatches.map((m) => ({ ...m, group_id: g.id, phase: "group_stage" }));
      } else {
        newMatches = generateRoundRobin(grpPartners, meta);
      }
      allNewMatches.push(...newMatches);
    });

    if (allNewMatches.length === 0) {
      toast.error("No matches generated. Make sure groups have at least 2 partners each.");
      return;
    }

    setMatches((prev) => {
      const next = { ...prev };
      allNewMatches.forEach((m) => { next[m.id] = m; });
      return next;
    });

    toast.success(
      `${allNewMatches.length} match${allNewMatches.length !== 1 ? "es" : ""} generated for ${divGroups.length} group${divGroups.length !== 1 ? "s" : ""}.`
    );
  }, [groups, partners, divisions]);

  /**
   * Clear ALL group_stage matches for a division.
   * Call this before re-generating if you want a fresh slate.
   */
  const clearMatchesForDivision = useCallback((divisionId) => {
    setMatches((prev) => {
      const next = {};
      Object.values(prev).forEach((m) => {
        if (m.division_id === divisionId && m.phase === "group_stage") return; // drop
        next[m.id] = m;
      });
      return next;
    });
  }, []);

  /**
   * Schedule all currently-unscheduled matches for a tournament.
   * Uses the same court / games-per-day settings as the tournament.
   */
  const autoScheduleUnscheduled = useCallback((tournamentId) => {
    const tournament = tournaments[tournamentId];
    if (!tournament) return;

    const unscheduled = Object.values(matches).filter(
      (m) =>
        m.tournament_id === tournamentId &&
        !m.scheduled_date &&
        m.status === "scheduled"
    );

    if (unscheduled.length === 0) {
      toast("No unscheduled matches to assign.", { icon: "ℹ️" });
      return;
    }

    // Use today as fallback start date, cap end date to 30 days max to prevent hangs
    const today = new Date().toISOString().split("T")[0];
    const startDate = tournament.start_date || today;
    const capEnd = new Date(startDate + "T00:00:00");
    capEnd.setDate(capEnd.getDate() + 29);
    const maxEnd = capEnd.toISOString().split("T")[0];
    const endDate = tournament.end_date
      ? (tournament.end_date <= maxEnd ? tournament.end_date : maxEnd)
      : startDate;

    const cappedTournament = { ...tournament, start_date: startDate, end_date: endDate };

    const availableCourts = tournament.courts?.length
      ? tournament.courts
      : ["Court 1", "Court 2", "Court 3", "Court 4"];
    const courtNames =
      tournament.games_per_day === 0
        ? availableCourts
        : availableCourts.slice(
            0,
            Math.max(1, Math.ceil(unscheduled.length / (tournament.games_per_day || 4)))
          );

    const scheduled = generateSchedule(unscheduled, cappedTournament, courtNames);
    const scheduledOk = scheduled.filter((m) => !m.could_not_schedule);

    if (scheduledOk.length === 0) {
      toast.error("Could not auto-schedule. Check tournament dates/settings and try assigning courts manually.");
      return;
    }

    setMatches((prev) => {
      const next = { ...prev };
      scheduledOk.forEach((m) => { next[m.id] = m; });
      return next;
    });

    toast.success(
      `${scheduledOk.length} match${scheduledOk.length !== 1 ? "es" : ""} auto-scheduled.`
    );
  }, [tournaments, matches]);

  // ─── Match schedule edit ──────────────────────────────────────────────────

  const updateMatchSchedule = useCallback((matchId, { date, time, court }) => {
    setMatches((prev) => {
      if (!prev[matchId]) return prev;
      return {
        ...prev,
        [matchId]: {
          ...prev[matchId],
          scheduled_date: date ?? prev[matchId].scheduled_date,
          scheduled_time: time ?? prev[matchId].scheduled_time,
          court: court ?? prev[matchId].court,
        },
      };
    });
  }, []);

  const updateMatchStatus = useCallback((matchId, status) => {
    setMatches((prev) => {
      if (!prev[matchId]) return prev;
      return { ...prev, [matchId]: { ...prev[matchId], status } };
    });
  }, []);

  const updateMatchLiveScore = useCallback((matchId, liveScore) => {
    setMatches((prev) => {
      if (!prev[matchId]) return prev;
      return { ...prev, [matchId]: { ...prev[matchId], live_score: liveScore } };
    });
  }, []);

  /**
   * Manually override the participants in a match (admin edit).
   * Resets winner, status, and scores so the match can be replayed.
   */
  const updateMatchPartners = useCallback((matchId, { partner_a_id, partner_b_id }) => {
    setMatches((prev) => {
      if (!prev[matchId]) return prev;
      return {
        ...prev,
        [matchId]: {
          ...prev[matchId],
          // Use !== undefined so that explicitly passing null clears the slot to TBD
          partner_a_id: partner_a_id !== undefined ? partner_a_id : prev[matchId].partner_a_id,
          partner_b_id: partner_b_id !== undefined ? partner_b_id : prev[matchId].partner_b_id,
          winner_id: null,
          status: "scheduled",
          scores: [],
          completed_at: null,
        },
      };
    });
  }, []);

  // ─── Record match result ──────────────────────────────────────────────────

  const recordMatchResult = useCallback(
    (matchId, scores, tournamentId) => {
      setMatches((prevMatches) => {
        const match = prevMatches[matchId];
        if (!match) return prevMatches;
        const tournament = tournaments[tournamentId || match.tournament_id];
        if (!tournament) return prevMatches;

        const settings = getTournamentSettings(tournament);
        const winnerSide = determineMatchWinner(scores, settings);
        if (!winnerSide) {
          toast.error("Scores are invalid — check that the winning team has enough points and margin.");
          return prevMatches;
        }

        const winnerId =
          winnerSide === "a" ? match.partner_a_id : match.partner_b_id;
        const now = new Date().toISOString();

        let updatedMatches = {
          ...prevMatches,
          [matchId]: {
            ...match,
            scores,
            winner_id: winnerId,
            status: "completed",
            completed_at: now,
          },
        };

        // Auto-advance winner in bracket (works for both playoff AND SE group_stage)
        if (match.bracket_position != null) {
          const nextRound = match.round + 1;
          const nextPosition = Math.ceil(match.bracket_position / 2);
          const nextMatch = Object.values(updatedMatches).find(
            (m) =>
              m.division_id === match.division_id &&
              m.phase === match.phase &&
              // For group_stage SE brackets, scope to same group
              (match.group_id ? m.group_id === match.group_id : !m.group_id) &&
              m.round === nextRound &&
              m.bracket_position === nextPosition &&
              (m.bracket_type === "winners" || m.bracket_type == null)
          );

          if (nextMatch) {
            // Odd bracket_position → partner_a slot; even → partner_b
            const slotKey = match.bracket_position % 2 !== 0 ? "partner_a_id" : "partner_b_id";
            updatedMatches = {
              ...updatedMatches,
              [nextMatch.id]: { ...nextMatch, [slotKey]: winnerId },
            };
          }
        }

        // Check auto-complete: all playoff matches for tournament are done
        const tid = tournament.id;
        const playoffMatchesForTournament = Object.values(updatedMatches).filter(
          (m) => m.tournament_id === tid && m.phase === "playoff"
        );
        const allPlayoffDone =
          playoffMatchesForTournament.length > 0 &&
          playoffMatchesForTournament.every((m) =>
            ["completed", "bye", "cancelled"].includes(m.status)
          );

        if (allPlayoffDone && (tournament.phase === "playoffs" || tournament.phase === "group_stage")) {
          setTournaments((prev) => ({
            ...prev,
            [tid]: { ...prev[tid], phase: "completed", updated_at: now },
          }));
          toast.success("🏆 Tournament completed! All brackets resolved.");
        }

        return updatedMatches;
      });
    },
    [tournaments]
  );

  // ─── Phase transitions ────────────────────────────────────────────────────

  const startTournament = useCallback(
    (tournamentId) => {
      const tournament = tournaments[tournamentId];
      if (!tournament) return;

      // Validate: divisions, groups, partner minimums, and no unassigned partners
      const divs = Object.values(divisions).filter((d) => d.tournament_id === tournamentId);
      if (divs.length === 0) {
        toast.error("Create at least one division before starting.");
        return;
      }

      const allGroups = Object.values(groups);
      const allPartners = Object.values(partners);
      let valid = true;

      for (const div of divs) {
        const divGroups = allGroups.filter((g) => g.division_id === div.id);
        if (divGroups.length === 0) {
          toast.error(`Division "${div.name}" has no groups. Add groups first.`);
          valid = false;
          break;
        }
        for (const grp of divGroups) {
          const grpPartners = allPartners.filter((p) => p.group_id === grp.id && !p.withdrawn);
          if (grpPartners.length < 2) {
            toast.error(`Group "${grp.name}" in "${div.name}" needs at least 2 partners.`);
            valid = false;
            break;
          }
        }
        if (!valid) break;
      }

      const unassigned = allPartners.filter(
        (p) => p.tournament_id === tournamentId && !p.group_id && !p.withdrawn
      );
      if (unassigned.length > 0) {
        toast.error(`${unassigned.length} partner(s) are unassigned to a group.`);
        valid = false;
      }

      if (!valid) return;

      // Flip phase — matches are generated per-group in the Groups tab
      setTournaments((prev) => ({
        ...prev,
        [tournamentId]: {
          ...prev[tournamentId],
          phase: "group_stage",
          updated_at: new Date().toISOString(),
        },
      }));

      const existingGroupMatches = Object.values(matches).filter(
        (m) => m.tournament_id === tournamentId && m.phase === "group_stage"
      );
      if (existingGroupMatches.length === 0) {
        toast.success(
          "Tournament started! Use Generate in the Groups tab to create matches.",
          { duration: 4000 }
        );
      } else {
        toast.success(`Tournament started! ${existingGroupMatches.length} matches ready.`);
      }
    },
    [tournaments, divisions, groups, partners, matches]
  );

  const advanceToPlayoffs = useCallback(
    (tournamentId, force = false) => {
      const tournament = tournaments[tournamentId];
      if (!tournament) return;

      const divs = Object.values(divisions).filter((d) => d.tournament_id === tournamentId);
      const allGroups = Object.values(groups);
      const allPartners = Object.values(partners);
      const allMatches = Object.values(matches);

      const groupStageMatches = allMatches.filter(
        (m) => m.tournament_id === tournamentId && m.phase === "group_stage"
      );
      const incompleteCount = groupStageMatches.filter(
        (m) => !["completed", "bye", "cancelled"].includes(m.status)
      ).length;

      if (incompleteCount > 0 && !force) {
        toast.error(
          `${incompleteCount} group match(es) are not finished. Use "Force Advance" to proceed anyway.`
        );
        return;
      }
      if (incompleteCount > 0 && force) {
        toast(`${incompleteCount} incomplete match(es) — using current standings.`, { icon: "⚠️" });
      }

      // Build playoffs for each division
      const newPlayoffMatches = [];
      for (const div of divs) {
        const divGroups = allGroups.filter((g) => g.division_id === div.id);
        if (divGroups.length === 0) continue;

        const advancing = getAdvancingPartners(div, divGroups, allPartners, allMatches);
        if (advancing.length < 2) continue;

        const bracketMatches = generateSingleEliminationBracket(advancing, {
          tournament_id: tournamentId,
          division_id: div.id,
        });
        newPlayoffMatches.push(...bracketMatches);
      }

      if (newPlayoffMatches.length === 0) {
        toast.error("No partners advanced. Check your division settings.");
        return;
      }

      // Schedule playoff matches using configured courts
      const playoffCourts = tournament.courts?.length
        ? tournament.courts
        : ["Court 1", "Court 2", "Court 3", "Court 4"];
      const scheduledPlayoffs = generateSchedule(
        newPlayoffMatches.filter((m) => m.status !== "bye"),
        tournament,
        playoffCourts
      );
      const byePlayoffs = newPlayoffMatches.filter((m) => m.status === "bye");
      const allNew = [...scheduledPlayoffs, ...byePlayoffs];

      const newMatchesMap = {};
      allNew.forEach((m) => { newMatchesMap[m.id] = m; });

      setMatches((prev) => ({ ...prev, ...newMatchesMap }));
      setTournaments((prev) => ({
        ...prev,
        [tournamentId]: {
          ...prev[tournamentId],
          phase: "playoffs",
          updated_at: new Date().toISOString(),
        },
      }));
      toast.success(`Playoffs started! ${allNew.length} bracket matches generated.`);
    },
    [tournaments, divisions, groups, partners, matches]
  );

  // ─── Regenerate schedule ─────────────────────────────────────────────────

  const regenerateSchedule = useCallback(
    (tournamentId) => {
      const tournament = tournaments[tournamentId];
      if (!tournament) return;
      setMatches((prev) => {
        const unplayed = Object.values(prev).filter(
          (m) =>
            m.tournament_id === tournamentId &&
            m.status === "scheduled"
        );
        if (unplayed.length === 0) return prev;
        const availableCourts = tournament.courts?.length
          ? tournament.courts
          : ["Court 1", "Court 2", "Court 3", "Court 4"];
        const courtNames =
          tournament.games_per_day === 0
            ? availableCourts
            : availableCourts.slice(
                0,
                Math.max(1, Math.ceil(unplayed.length / (tournament.games_per_day || 4)))
              );
        const rescheduled = generateSchedule(unplayed, tournament, courtNames);
        const next = { ...prev };
        rescheduled.forEach((m) => { next[m.id] = m; });
        return next;
      });
    },
    [tournaments]
  );

  // ─── Shuffle all groups (all divisions) ──────────────────────────────────

  const shuffleAllGroups = useCallback(
    (tournamentId) => {
      const divs = Object.values(divisions).filter((d) => d.tournament_id === tournamentId);
      divs.forEach((div) => shuffleGroupAssignments(div.id));
    },
    [divisions, shuffleGroupAssignments]
  );

  // ─── Shuffle match order within a group ──────────────────────────────────

  /**
   * Shuffles the display/scheduling order of unplayed group_stage matches in a group.
   * For scheduled matches: swaps their date/time/court assignments randomly.
   * For unscheduled matches: re-stamps created_at to randomize order.
   */
  const shuffleGroupMatchOrder = useCallback((groupId) => {
    setMatches((prev) => {
      const groupMatches = Object.values(prev).filter(
        (m) => m.group_id === groupId && m.phase === "group_stage" && m.status === "scheduled"
      );
      if (groupMatches.length < 2) return prev;

      // Separate scheduled (have court/date) from bare (no court)
      const withSchedule = groupMatches.filter((m) => m.scheduled_date || m.court);
      const bare = groupMatches.filter((m) => !m.scheduled_date && !m.court);

      const next = { ...prev };

      if (withSchedule.length >= 2) {
        // Fisher-Yates shuffle of schedule slots
        const slots = withSchedule.map((m) => ({
          scheduled_date: m.scheduled_date,
          scheduled_time: m.scheduled_time,
          court: m.court,
        }));
        for (let i = slots.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [slots[i], slots[j]] = [slots[j], slots[i]];
        }
        withSchedule.forEach((m, i) => {
          next[m.id] = { ...next[m.id], ...slots[i] };
        });
      }

      if (bare.length >= 2) {
        // Shuffle created_at to change display order
        const timestamps = bare.map((m) => m.created_at);
        for (let i = timestamps.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [timestamps[i], timestamps[j]] = [timestamps[j], timestamps[i]];
        }
        bare.forEach((m, i) => {
          next[m.id] = { ...next[m.id], created_at: timestamps[i] };
        });
      }

      return next;
    });
    toast.success("Match order shuffled.");
  }, []);

  // ─── Per-division playoff advancement ────────────────────────────────────

  /**
   * Advance a single division to playoffs based on its format + group count.
   *
   * Logic:
   * - SE + 1 group → already IS the bracket, no advance possible
   * - RR + 1 group + advance_count=1 → champion = group winner, no bracket
   * - Everything else → generate SE playoff bracket for advancing partners
   *
   * Does NOT require the global tournament phase to already be "group_stage".
   */
  const advanceDivisionToPlayoffs = useCallback(
    (divisionId, force = false) => {
      const division = divisions[divisionId];
      if (!division) return;

      const tournament = tournaments[division.tournament_id];
      if (!tournament) return;

      const divGroups = Object.values(groups).filter((g) => g.division_id === divisionId);
      const allPartners = Object.values(partners);
      const allMatchesArr = Object.values(matches);
      const groupCount = divGroups.length;
      const fmt = division.format || "round_robin";
      const advCount = division.advance_count ?? 2;

      // Determine if a separate playoff bracket is needed
      if (fmt === "single_elimination" && groupCount === 1) {
        toast.error(`"${division.name}" uses Single Elimination with 1 group — the group bracket IS the final. No advance needed.`);
        return;
      }

      if (fmt === "round_robin" && groupCount === 1 && advCount <= 1) {
        // The winner of the single RR group is already the champion
        const standing = getAdvancingPartners(division, divGroups, allPartners, allMatchesArr);
        if (standing.length >= 1) {
          toast.success(`🏆 ${standing[0].team_name} is the ${division.name} champion!`);
        } else {
          toast.error("Complete round robin matches to determine the champion.");
        }
        return;
      }

      // Check if playoff bracket already exists for this division
      const existingPlayoffs = allMatchesArr.filter(
        (m) => m.division_id === divisionId && m.phase === "playoff"
      );
      if (existingPlayoffs.length > 0) {
        toast.error(`Playoff bracket already generated for "${division.name}".`);
        return;
      }

      // Check completion of group stage for this division
      const divGroupStageMatches = allMatchesArr.filter(
        (m) => m.division_id === divisionId && m.phase === "group_stage"
      );
      const incompleteCount = divGroupStageMatches.filter(
        (m) => !["completed", "bye", "cancelled"].includes(m.status)
      ).length;

      if (incompleteCount > 0 && !force) {
        toast.error(
          `${incompleteCount} match(es) still incomplete in "${division.name}". Force advance to proceed anyway.`
        );
        return;
      }
      if (incompleteCount > 0 && force) {
        toast(`${incompleteCount} incomplete match(es) — using current standings.`, { icon: "⚠️" });
      }

      // Gather advancing partners
      const advancing = getAdvancingPartners(division, divGroups, allPartners, allMatchesArr);
      if (advancing.length < 2) {
        toast.error(`Not enough advancing partners in "${division.name}". Check division settings and match results.`);
        return;
      }

      // Generate SE playoff bracket for this division
      const bracketMatches = generateSingleEliminationBracket(advancing, {
        tournament_id: tournament.id,
        division_id: divisionId,
      });

      if (bracketMatches.length === 0) {
        toast.error("Could not generate playoff bracket.");
        return;
      }

      const newMatchesMap = {};
      bracketMatches.forEach((m) => { newMatchesMap[m.id] = m; });

      setMatches((prev) => ({ ...prev, ...newMatchesMap }));

      // Promote tournament to "playoffs" phase if not already there or completed
      if (tournament.phase === "group_stage" || tournament.phase === "setup") {
        setTournaments((prev) => ({
          ...prev,
          [tournament.id]: {
            ...prev[tournament.id],
            phase: "playoffs",
            updated_at: new Date().toISOString(),
          },
        }));
      }

      const playable = bracketMatches.filter((m) => m.status !== "bye").length;
      toast.success(
        `Playoffs generated for "${division.name}"! ${playable} bracket match${playable !== 1 ? "es" : ""}.`
      );
    },
    [divisions, tournaments, groups, partners, matches]
  );

  // ─── Export ───────────────────────────────────────────────────────────────

  const exportTournamentData = useCallback(
    (tournamentId) => {
      const tournament = tournaments[tournamentId];
      if (!tournament) return;
      const divs = getDivisionsForTournament(tournamentId);
      const grps = divs.flatMap((d) => getGroupsForDivision(d.id));
      const parts = getPartnersForTournament(tournamentId);
      const mats = getMatchesForTournament(tournamentId);
      const data = { tournament, divisions: divs, groups: grps, partners: parts, matches: mats };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${tournament.name.replace(/\s+/g, "_")}_export.json`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Tournament data exported.");
    },
    [tournaments, getDivisionsForTournament, getGroupsForDivision, getPartnersForTournament, getMatchesForTournament]
  );

  return {
    // State maps
    tournaments,
    divisions,
    groups,
    partners,
    matches,
    // Derived
    allTournaments,
    getDivisionsForTournament,
    getGroupsForDivision,
    getPartnersForDivision,
    getPartnersForGroup,
    getPartnersForTournament,
    getMatchesForTournament,
    getMatchesForGroup,
    // Tournament actions
    createTournament,
    updateTournament,
    deleteTournament,
    // Sponsor actions
    addSponsor,
    removeSponsor,
    updateSponsor,
    reorderSponsors,
    updateDisplaySettings,
    // Division actions
    createDivision,
    updateDivision,
    deleteDivision,
    // Group actions
    createGroup,
    updateGroup,
    deleteGroup,
    autoCreateGroups,
    // Partner actions
    addPartner,
    updatePartner,
    removePartner,
    assignPartnerToGroup,
    shuffleGroupAssignments,
    // Match actions
    updateMatchSchedule,
    updateMatchStatus,
    updateMatchLiveScore,
    updateMatchPartners,
    recordMatchResult,
    // Match generation
    generateGroupMatches,
    generateAllDivisionMatches,
    clearMatchesForDivision,
    autoScheduleUnscheduled,
    // Phase transitions
    startTournament,
    advanceToPlayoffs,
    advanceDivisionToPlayoffs,
    // Match order
    shuffleGroupMatchOrder,
    // Setters for algorithm phases
    setMatches,
    setTournaments,
    // Export
    exportTournamentData,
    // Tools
    regenerateSchedule,
    shuffleAllGroups,
  };
}
