import LZString from "lz-string";
import { CURRENT_STATE_VERSION, normalizeStateMeta, withStateEnvelope } from "./schema";

// Persistence layer.
//
// IndexedDB is the durable source of truth (large quota → no more "storage
// full" issues as match/session history accumulates). To keep the rest of the
// app unchanged, an in-memory `cache` is hydrated once by bootstrapStorage()
// before React renders, so loadState()/saveState() stay synchronous.
//
// A compressed localStorage copy is written best-effort on every save. It is
// NOT the source of truth — it exists only to:
//   1. keep the cross-tab `storage` event working for the Display board, and
//   2. provide a synchronous fallback if IndexedDB is ever unavailable.
// If localStorage is full the mirror is silently skipped; IndexedDB still saves.

const LS_KEY = "picklestudioAppState";
const COMPRESSION_PREFIX = "LZ1:";

const IDB_NAME = "picklestudioDB";
const IDB_VERSION = 1;
const STORE = "appState";
const STATE_ID = "current";
const MIGRATION_FLAG_ID = "migratedFromLocalStorage";

let cache = null; // enveloped state object; source for synchronous reads
let idb = null; // open IDBDatabase, or null when unavailable
let idbReady = false;

const getLocalStorage = () => {
  if (typeof window !== "undefined" && window.localStorage) {
    return window.localStorage;
  }
  return null;
};

// Serialize + compress a payload for the localStorage mirror.
export function encodeState(payload) {
  return COMPRESSION_PREFIX + LZString.compressToUTF16(JSON.stringify(payload));
}

// Decode a raw stored string. Accepts both the compressed format and legacy
// raw-JSON, so existing installs migrate transparently.
export function decodeRawState(raw) {
  if (!raw || typeof raw !== "string") return null;
  try {
    if (raw.startsWith(COMPRESSION_PREFIX)) {
      const json = LZString.decompressFromUTF16(raw.slice(COMPRESSION_PREFIX.length));
      return json ? JSON.parse(json) : null;
    }
    return JSON.parse(raw);
  } catch (err) {
    console.error("Failed to decode stored state", err);
    return null;
  }
}

// ─── IndexedDB helpers ────────────────────────────────────────────────────────

function openIdb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") {
      reject(new Error("IndexedDB unavailable"));
      return;
    }
    const req = indexedDB.open(IDB_NAME, IDB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: "id" });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function idbGet(db, id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, "readonly");
    const r = tx.objectStore(STORE).get(id);
    r.onsuccess = () => resolve(r.result);
    r.onerror = () => reject(r.error);
  });
}

function idbPut(db, record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE, "readwrite");
    tx.objectStore(STORE).put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error || new Error("Browser storage transaction failed."));
    tx.onabort = () => reject(tx.error || new Error("Browser storage transaction was aborted."));
  });
}

function persistToIdb(payload) {
  if (!idbReady || !idb) return null;
  return idbPut(idb, { id: STATE_ID, value: payload, savedAt: new Date().toISOString() });
}

function mirrorToLocalStorage(payload) {
  const ls = getLocalStorage();
  if (!ls) return false;
  try {
    ls.setItem(LS_KEY, encodeState(payload));
    return true;
  } catch {
    return false;
  }
}

// ─── Bootstrap (run once before React renders) ──────────────────────────────────

export async function bootstrapStorage() {
  const ls = getLocalStorage();

  try {
    idb = await openIdb();
    idbReady = true;
  } catch (err) {
    console.warn("IndexedDB unavailable; using localStorage only.", err);
    idb = null;
    idbReady = false;
  }

  if (idbReady) {
    try {
      const existing = await idbGet(idb, STATE_ID);
      if (existing && existing.value) {
        // IndexedDB already holds state — it is the source of truth.
        cache = existing.value;
      } else {
        // No IndexedDB state yet. Do a one-time migration from localStorage.
        const flag = await idbGet(idb, MIGRATION_FLAG_ID);
        const legacy = ls ? decodeRawState(ls.getItem(LS_KEY)) : null;
        if (!flag && legacy) {
          cache = legacy;
          await idbPut(idb, { id: STATE_ID, value: legacy, savedAt: new Date().toISOString() });
        }
        // Mark migration complete so later refreshes never re-import.
        await idbPut(idb, { id: MIGRATION_FLAG_ID, value: true, at: new Date().toISOString() });
      }
    } catch (err) {
      console.error("IndexedDB bootstrap failed; falling back to localStorage.", err);
      idbReady = false;
      cache = ls ? decodeRawState(ls.getItem(LS_KEY)) : null;
    }
  } else {
    cache = ls ? decodeRawState(ls.getItem(LS_KEY)) : null;
  }

  return { usingIndexedDb: idbReady, hasState: !!cache };
}

// ─── Synchronous app-facing API (reads/writes the in-memory cache) ──────────────

export function saveState(state = {}, callbacks = {}) {
  try {
    const payload = withStateEnvelope(state);
    cache = payload; // immediate, synchronous read consistency
    const durableSave = persistToIdb(payload);
    const mirrored = mirrorToLocalStorage(payload);
    const saved = durableSave || (mirrored ? Promise.resolve() : Promise.reject(new Error("Browser storage is unavailable or full.")));
    saved.then(() => callbacks.onPersisted?.()).catch((error) => {
      console.error("State save failed", error);
      callbacks.onError?.(error);
    });
    return payload;
  } catch (err) {
    console.error("Failed to save state", err);
    callbacks.onError?.(err);
    return null;
  }
}

export function loadState() {
  try {
    if (!cache) return null;
    const parsed = cache;

    const legacyMeta = parsed.meta || {};
    const normalizedMeta = normalizeStateMeta({
      ...legacyMeta,
      seededAt: legacyMeta.seededAt || parsed.seededAt || null,
      seedSource: legacyMeta.seedSource || parsed.seedSource || null,
      seedLabel: legacyMeta.seedLabel || parsed.seedLabel || null,
      lastSavedAt:
        legacyMeta.lastSavedAt ||
        legacyMeta.savedAt ||
        parsed.lastSavedAt ||
        parsed.savedAt ||
        null,
      stateVersion: legacyMeta.stateVersion || parsed.version || CURRENT_STATE_VERSION,
    });

    // STRICT ONLINE MODE: Remove Calendar Data from Local Persistence
    // We do NOT want to load stale V1 or V2 bookings from disk.
    // They must come from the server sync.
    const sanitized = { ...parsed };
    delete sanitized.bookings;
    delete sanitized.calendarCourts;
    delete sanitized.bookingsV2;
    delete sanitized.slotsV2;

    return {
      ...sanitized,
      meta: normalizedMeta,
      version: parsed.version || CURRENT_STATE_VERSION,
    };
  } catch (err) {
    console.error("Failed to load state", err);
    return null;
  }
}
