import React, { useMemo } from "react";

const formatCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

const RentalGroupCard = ({ group, onSettle }) => {
    const [isOpen, setIsOpen] = React.useState(false);

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col overflow-hidden">
            <div
                className="p-4 flex flex-col gap-3 cursor-pointer hover:bg-slate-50 transition-colors"
                onClick={() => setIsOpen(!isOpen)}
            >
                {/* Header: Renter Info */}
                <div className="flex justify-between items-start">
                    <div>
                        <div className="flex items-center gap-2">
                            <div className="font-bold text-slate-900 text-base">{group.renterName}</div>
                            {group.renterId && <span className="text-[10px] px-1.5 py-0.5 bg-slate-100 text-slate-500 rounded font-mono">ID: {group.renterId}</span>}
                        </div>
                        <div className="text-xs text-slate-500 font-medium flex items-center gap-2">
                            <span>{group.date}</span>
                            <span className="text-slate-300">•</span>
                            <span>{group.bookings.length} Booking{group.bookings.length !== 1 ? 's' : ''}</span>
                            <span className={`text-slate-400 transform transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}>▼</span>
                        </div>
                    </div>
                    <div className="text-right">
                        <div className="font-bold text-slate-900 text-lg">{formatCurrency(group.totalPrice)}</div>
                        <div className="text-[10px] text-rose-500 font-bold uppercase tracking-wider">Unpaid</div>
                    </div>
                </div>
            </div>

            {/* List of Courts/Slots in this Group (Collapsible) */}
            {isOpen && (
                <div className="bg-slate-50 border-t border-slate-100 p-3 space-y-3 animate-in slide-in-from-top-2 duration-200">

                    {/* Renter Details (Expanded) */}
                    {(group.contact || group.email) && (
                        <div className="text-xs text-slate-500 bg-white p-2 rounded border border-slate-100 flex flex-col gap-1">
                            <div className="font-semibold text-slate-700">Renter Details</div>
                            <div className="flex items-center gap-3">
                                {group.contact && <span>📞 {group.contact}</span>}
                                {group.email && <span>✉️ {group.email}</span>}
                            </div>
                        </div>
                    )}

                    {/* Bookings List */}
                    <div className="space-y-1">
                        {group.bookings.map(b => (
                            <div key={b.id} className="flex justify-between text-xs text-slate-600 bg-white p-2 rounded border border-slate-100">
                                <span>
                                    <span className="font-semibold">{b.courtName || `Court ${b.courtId}`}</span>
                                    <span className="mx-1 text-slate-300">|</span>
                                    {b.startTime} - {b.endTime}
                                </span>
                                <span className="text-slate-400">{formatCurrency(b.rentalPrice)}</span>
                            </div>
                        ))}
                    </div>

                    {/* Action Footer */}
                    <div className="pt-1 flex justify-end">
                        <button
                            onClick={(e) => {
                                e.stopPropagation();
                                onSettle(group.ids);
                            }}
                            className="px-4 py-2 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 rounded-lg text-xs font-bold transition-colors w-full sm:w-auto"
                        >
                            Settle Group ({group.bookings.length})
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

const SessionCard = ({ session, onSettlePlayer }) => {
    const [isOpen, setIsOpen] = React.useState(false);

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div
                className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex justify-between items-center cursor-pointer hover:bg-slate-100 transition-colors"
                onClick={() => setIsOpen(!isOpen)}
            >
                <div className="flex items-center gap-2">
                    <div className="text-xs font-bold text-slate-700">
                        {new Date(session.startedAt || Date.now()).toLocaleDateString(undefined, { weekday: 'long' })} • {session.title || session.name || "Open Play"}
                    </div>
                    <span className={`text-slate-400 transform transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}>▼</span>
                </div>
                <div className="text-[10px] font-bold text-rose-600 uppercase tracking-wide">
                    {session.filteredUnpaidPlayers.length} Unpaid Players
                </div>
            </div>

            {isOpen && (
                <div className="divide-y divide-slate-100 animate-in slide-in-from-top-2 duration-200">
                    {session.filteredUnpaidPlayers.map(p => (
                        <div key={p.id} className="p-3 flex items-center justify-between hover:bg-slate-50 transition-colors">
                            <div className="flex items-center gap-3">
                                <div>
                                    <div className="text-sm font-medium text-slate-900">{p.name || 'Unknown Player'}</div>
                                    <div className="text-xs text-slate-500">{formatCurrency(p.price || 0)}</div>
                                </div>
                            </div>
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onSettlePlayer(session.id, p.id);
                                }}
                                className="px-3 py-1.5 bg-white border border-slate-200 hover:border-emerald-300 hover:text-emerald-700 text-slate-600 rounded-md text-xs font-medium transition-all"
                            >
                                Mark Paid
                            </button>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default function UnpaidDetailsModal({ isOpen, onClose, unpaidRentals = [], unpaidSessions = [], onSettleRental, onSettleSessionPlayer, onViewBooking, defaultOpFee = 250 }) {
    const [filterText, setFilterText] = React.useState("");
    const [activeTab, setActiveTab] = React.useState('rentals'); // 'rentals' | 'sessions'

    // Group rentals for Table display (similar to History)
    const rentalRows = useMemo(() => {
        if (!isOpen) return [];
        const groups = {};
        unpaidRentals.forEach(r => {
            const id = r.id; // Booking ID
            if (!groups[id]) {
                groups[id] = {
                    id: r.id,
                    date: r.date,
                    title: r.title || "Rental",
                    renterName: r.renterName || "Unknown",
                    renterContact: r.renterContact || r.renterEmail,
                    courtNames: r.courtName, // Pre-formatted in DashboardV2Page
                    startTime: r.startTime,
                    endTime: r.endTime,
                    totalPrice: Number(r.rentalPrice) || 0,
                    status: 'Unpaid' // By definition in this list
                };
            }
        });

        // Convert to array and sort desc date
        let rows = Object.values(groups).sort((a, b) => b.date.localeCompare(a.date));

        if (filterText) {
            const lower = filterText.toLowerCase();
            rows = rows.filter(r =>
                r.renterName.toLowerCase().includes(lower) ||
                r.date.includes(lower) ||
                r.title.toLowerCase().includes(lower)
            );
        }
        return rows;
    }, [unpaidRentals, isOpen, filterText]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-gray-100 flex flex-col gap-4 bg-white sticky top-0 z-10 rounded-t-2xl">
                    <div className="flex justify-between items-center">
                        <div>
                            <h2 className="text-lg font-bold text-slate-900">Pending Payments</h2>
                            <p className="text-xs text-slate-500 uppercase tracking-wide">Action Required</p>
                        </div>
                        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors">✕</button>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="flex bg-slate-100 p-1 rounded-lg">
                            <button
                                onClick={() => setActiveTab('rentals')}
                                className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'rentals' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Rentals ({unpaidRentals.length})
                            </button>
                            <button
                                onClick={() => setActiveTab('sessions')}
                                className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'sessions' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Open Play ({unpaidSessions.length})
                            </button>
                        </div>
                        <div className="relative flex-1">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
                            <input
                                type="text"
                                placeholder="Filter..."
                                className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-500"
                                value={filterText}
                                onChange={(e) => setFilterText(e.target.value)}
                            />
                        </div>
                    </div>
                </div>

                <div className="p-0 overflow-y-auto flex-1 bg-white relative">
                    {activeTab === 'rentals' && (
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 text-slate-500 text-[11px] font-semibold tracking-wide uppercase sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="py-3 px-4">Date</th>
                                    <th className="py-3 px-4">Booking / Renter</th>
                                    <th className="py-3 px-4">Courts</th>
                                    <th className="py-3 px-4">Time</th>
                                    <th className="py-3 px-4 text-right">Balance</th>
                                    <th className="py-3 px-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {rentalRows.length === 0 ? (
                                    <tr><td colSpan="6" className="p-8 text-center text-slate-400 text-sm">No unpaid rentals found.</td></tr>
                                ) : (
                                    rentalRows.map(row => (
                                        <tr
                                            key={row.id}
                                            className="hover:bg-slate-50 transition-colors cursor-pointer group"
                                            onClick={() => onViewBooking && onViewBooking(row.id)}
                                        >
                                            <td className="py-3 px-4 text-xs font-mono text-slate-600 whitespace-nowrap">{row.date}</td>
                                            <td className="py-3 px-4">
                                                <div className="text-sm font-semibold text-slate-900">{row.title}</div>
                                                <div className="text-xs text-slate-500">{row.renterName}</div>
                                            </td>
                                            <td className="py-3 px-4 text-xs text-slate-600">{row.courtNames}</td>
                                            <td className="py-3 px-4 text-xs font-mono text-slate-500 whitespace-nowrap">{row.startTime} - {row.endTime}</td>
                                            <td className="py-3 px-4 text-right">
                                                <div className="text-sm font-bold text-rose-600">{formatCurrency(row.totalPrice)}</div>
                                            </td>
                                            <td className="py-3 px-4 text-center">
                                                <button
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        onSettleRental(row.id);
                                                    }}
                                                    className="px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded text-xs font-bold hover:bg-emerald-100 transition-colors shadow-sm"
                                                >
                                                    Settle
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    )}

                    {activeTab === 'sessions' && (
                        <table className="w-full text-left border-collapse">
                            <thead className="bg-slate-50 text-slate-500 text-[11px] font-semibold tracking-wide uppercase sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="py-3 px-4">Date / Session</th>
                                    <th className="py-3 px-4">Player</th>
                                    <th className="py-3 px-4 text-right">Fee</th>
                                    <th className="py-3 px-4 text-center">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {(() => {
                                    // Flatten players from all unpaid sessions
                                    const rows = [];
                                    unpaidSessions.forEach(session => {
                                        const dateStr = new Date(session.startedAt).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' });
                                        const timeStr = new Date(session.startedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

                                        const unpaidPlayers = session.players.filter(p => (p.paymentStatus || 'not_paid') === 'not_paid' || p.paymentStatus === 'unpaid');

                                        unpaidPlayers.forEach(p => {
                                            rows.push({
                                                sessionId: session.id,
                                                playerId: p.id,
                                                sessionLabel: `Session #${session.id.slice(-4)}`,
                                                dateDisplay: `${dateStr} • ${timeStr}`,
                                                playerName: p.name || 'Unknown',
                                                amount: Number(p.price) || defaultOpFee,
                                                rawDate: session.startedAt
                                            });
                                        });
                                    });

                                    // Sort by newest session
                                    rows.sort((a, b) => new Date(b.rawDate) - new Date(a.rawDate));

                                    // Filter
                                    const filteredRows = filterText
                                        ? rows.filter(r => r.playerName.toLowerCase().includes(filterText.toLowerCase()))
                                        : rows;

                                    if (filteredRows.length === 0) {
                                        return <tr><td colSpan="4" className="p-8 text-center text-slate-400 text-sm">No unpaid open play fees found.</td></tr>;
                                    }

                                    return filteredRows.map((row, idx) => (
                                        <tr key={`${row.sessionId}-${row.playerId}-${idx}`} className="hover:bg-slate-50 transition-colors">
                                            <td className="py-3 px-4">
                                                <div className="text-xs font-bold text-slate-700">{row.sessionLabel}</div>
                                                <div className="text-[10px] text-slate-500">{row.dateDisplay}</div>
                                            </td>
                                            <td className="py-3 px-4">
                                                <div className="text-sm font-semibold text-slate-900">{row.playerName}</div>
                                            </td>
                                            <td className="py-3 px-4 text-right">
                                                <div className="text-sm font-bold text-rose-600">{formatCurrency(row.amount)}</div>
                                            </td>
                                            <td className="py-3 px-4 text-center">
                                                <button
                                                    onClick={() => onSettleSessionPlayer(row.sessionId, row.playerId)}
                                                    className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 rounded text-xs font-bold hover:border-emerald-300 hover:text-emerald-700 transition-colors shadow-sm"
                                                >
                                                    Mark Paid
                                                </button>
                                            </td>
                                        </tr>
                                    ));
                                })()}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>
        </div>
    );
}
