import React, { useState, useCallback } from "react";

import { CourtList, MatchQueue, PlayerTable } from "./index";
import MoveMatchModal from "./components/MoveMatchModal";
import ReclubModal from "./components/ReclubModal";
import PartnersConfigModal from "./components/PartnersConfigModal";
import MatchProposalModal from "./components/MatchProposalModal";
import { SurfaceCard, ConfirmationModal } from "../../common/components";
import { useAppState } from "../../app/providers";
import { selectQueueState } from "../../state/selectors";

import toast from "react-hot-toast";

export default function QueuePage() {
  const [reclubOpen, setReclubOpen] = useState(false);
  const [confirmCloseOpen, setConfirmCloseOpen] = useState(false);
  const [confirmCancelOpen, setConfirmCancelOpen] = useState(false);
  const [cancelReason, setCancelReason] = useState("");
  const [infoModal, setInfoModal] = useState({ isOpen: false, title: "", message: "" });
  const closeInfoModal = () => setInfoModal(prev => ({ ...prev, isOpen: false }));

  // New State for Move Match
  const [moveMatchModal, setMoveMatchModal] = useState({ isOpen: false, fromCourtId: null });
  // New State for Return to Queue
  const [returnCourtId, setReturnCourtId] = useState(null);
  const [partnersModalOpen, setPartnersModalOpen] = useState(false);

  const {
    courts,
    players,
    matchQueue,
    matches,
    currentOpSession,
    opSessions,
    importReclubParticipants,
    addCourt,
    removeCourt,
    clearExtraCourts,
    updateCourtName,
    addPlayer,
    updateGender,
    removePlayer,
    clearAllPlayers,
    assignPlayerToCourt,
    removePlayerFromCourt,
    stopPlayer,
    resumePlayer,
    previewAutoQueue,
    confirmAutoQueue,
    updateLevel,
    renamePlayer,
    addToQueue,
    addQueue,
    removeQueue,
    removeFromQueue,
    sendQueueToCourt,
    setCourtTeam,
    completeMatch,
    updatePaymentStatus,
    markPlayerArrived,
    markAllPaid,
    markAllArrived,
    startOpSession,
    closeOpSession,
    cancelOpSession,
    clearQueue,

    manualUnlockCourt,
    requestedMatches,
    addRequestedMatch,
    removeRequestedMatch,
    promoteRequestedMatchToQueue,
    moveMatch, // 👈 New
    returnToQueue, // 👈 New
    partners, // 👈 New
    addPartner, // 👈 New
    removePartner, // 👈 New
    togglePartner, // 👈 New
    settings, // 👈 New: Access settings for default fee
  } = useAppState(selectQueueState);

  // New State for Start Session Confirmation
  const [confirmStartOpen, setConfirmStartOpen] = useState(false);
  const [sessionFeeInput, setSessionFeeInput] = useState("250"); // Default string

  // Reset fee input when modal opens (handled in effect or when button clicked)
  React.useEffect(() => {
    if (confirmStartOpen && settings?.defaultOpFee) {
      setSessionFeeInput(String(settings.defaultOpFee));
    }
  }, [confirmStartOpen, settings]);

  // Derive duplicate names reactively
  const duplicateNames = React.useMemo(() => {
    const counts = {};
    const dups = new Set();
    players.forEach(p => {
      const name = p.name.toUpperCase();
      counts[name] = (counts[name] || 0) + 1;
      if (counts[name] > 1) dups.add(name);
    });
    return Array.from(dups);
  }, [players]);

  const handleStartSession = () => {
    startOpSession(sessionFeeInput); // Pass custom fee
    setConfirmStartOpen(false);
    toast.success("Session started - Queue is now active");
  };

  const handleCompleteMatch = (courtId) => {
    completeMatch(courtId);
  };

  const handleReturnToQueue = (courtId) => {
    setReturnCourtId(courtId);
  };

  const confirmReturnToQueue = () => {
    console.log("Confirming return to queue for court:", returnCourtId);
    if (returnCourtId) {
      returnToQueue(returnCourtId);
      toast.success("Returned players to Waiting List");
      setReturnCourtId(null);
    }
  };

  const handleRequestMove = (courtId) => {
    setMoveMatchModal({ isOpen: true, fromCourtId: courtId });
  };

  const renderPaymentSummary = () => {
    const summary = { cash: 0, gcash: 0, free: 0, notPaid: 0 };
    const unpaid = [];
    (players || []).forEach((p) => {
      const status = (p.paymentStatus || "not_paid").toLowerCase();
      // Handle 'paid' generic status (e.g. from Mark All Paid) as Cash/Paid
      if (status === "cash" || status === "paid") summary.cash += 1;
      else if (status === "gcash") summary.gcash += 1;
      else if (status === "free") summary.free += 1;
      else {
        summary.notPaid += 1;
        unpaid.push(p);
      }
    });

    const total = summary.cash + summary.gcash + summary.free + summary.notPaid;

    return (
      <div className="mb-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div className="border rounded-lg p-2 bg-slate-50">
          <h3 className="text-[11px] font-semibold text-slate-800 mb-1">Payment summary</h3>
          <ul className="space-y-0.5 text-[11px] text-slate-700">
            <li>Total players: {total}</li>
            <li className="text-emerald-700">Paid (Cash / Generic): {summary.cash}</li>
            <li className="text-sky-700">Paid (GCash): {summary.gcash}</li>
            <li className="text-slate-700">Free / comped: {summary.free}</li>
            <li className="text-amber-700 font-medium">Unpaid: {summary.notPaid}</li>
          </ul>
        </div>
        <div className="border rounded-lg p-2 bg-amber-50">
          <h3 className="text-[11px] font-semibold text-amber-800 mb-1">Unpaid players</h3>
          {unpaid.length === 0 ? (
            <p className="text-[11px] text-amber-700">All players are marked as paid or free.</p>
          ) : (
            <ul className="max-h-32 overflow-auto text-[11px] text-amber-900 list-disc list-inside">
              {unpaid.map((p) => (
                <li key={p.id}>{p.name}</li>
              ))}
            </ul>
          )}
          <p className="mt-1 text-[10px] text-amber-800">
            Make sure this list matches your cashier records before ending the session.
          </p>
        </div>
      </div>
    );
  };

  // ── Match Proposal Modal state ─────────────────────────────────────────────
  const [proposalOpen, setProposalOpen] = useState(false);
  const [proposalData, setProposalData] = useState(null);
  const [proposalGenerating, setProposalGenerating] = useState(false);
  // Track groups already shown so "Try Different" never repeats the same group
  const [seenGroups, setSeenGroups] = useState([]);
  // Keep the current options so Re-generate uses the same settings
  const [lastGenerateOptions, setLastGenerateOptions] = useState({});

  const handleAutoBuild = useCallback(
    (options = {}) => {
      const excludeIds = requestedMatches.flatMap((m) => m.playerIds);
      const result = previewAutoQueue({ excludeIds, partners, ...options });

      // Record this group as "seen" so Try Different avoids it
      if (result.groupIds?.length > 0) {
        setSeenGroups([result.groupIds]);
      } else {
        setSeenGroups([]);
      }

      setLastGenerateOptions({ excludeIds, partners, ...options });
      setProposalData(result);
      setProposalOpen(true);
    },
    [previewAutoQueue, requestedMatches, partners]
  );

  const handleReGenerate = useCallback(() => {
    setProposalGenerating(true);
    // Small timeout so the button's loading state is visible
    setTimeout(() => {
      const excludeIds = requestedMatches.flatMap((m) => m.playerIds);
      // Build exclusion list: all groups seen so far (so each Re-generate is unique)
      const excludeGroups = seenGroups.map((ids) => ids.map(String).sort());
      const result = previewAutoQueue({ ...lastGenerateOptions, excludeIds, partners, excludeGroups });

      if (result.groupIds?.length > 0) {
        setSeenGroups((prev) => [...prev, result.groupIds]);
      }

      setProposalData(result);
      setProposalGenerating(false);
    }, 300);
  }, [previewAutoQueue, lastGenerateOptions, requestedMatches, partners, seenGroups]);

  const handleConfirmProposal = useCallback(() => {
    if (!proposalData?.groupIds?.length) return;
    confirmAutoQueue(proposalData.groupIds, proposalData.reason || "Auto");
    setProposalOpen(false);
    setProposalData(null);
    setSeenGroups([]);
    toast.success("Match queued! ✅");
  }, [proposalData, confirmAutoQueue]);

  return (
    <div className="p-4 w-full h-full flex flex-col overflow-hidden bg-pickle-cream">
      <div className="flex items-center justify-between mb-4">
        <h1 className="text-4xl font-display text-pickle-green">Queue System</h1>
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2 text-xs text-pickle-green/70">
            <span className="font-medium">
              {currentOpSession ? currentOpSession.name : "No active OP session"}
            </span>
            {currentOpSession ? (
              <span>
                Started {new Date(currentOpSession.startedAt).toLocaleTimeString()}
              </span>
            ) : (
              <span>
                {opSessions.length} past session{opSessions.length === 1 ? "" : "s"}
              </span>
            )}
            {!currentOpSession && (
              <span className="inline-flex items-center gap-1 mt-1 text-[11px] text-amber-900 bg-amber-100 px-2 py-0.5 rounded-full border border-amber-200">
                <span className="w-1.5 h-1.5 rounded-full bg-amber-600" />
                Queue locked until a session is started
              </span>
            )}
          </div>
          {currentOpSession ? (
            <div className="flex items-center gap-2">
              <button
                onClick={() => setConfirmCloseOpen(true)}
                className="px-4 py-2 rounded-full text-xs font-medium bg-red-600 text-white hover:bg-red-700 shadow-sm transition-colors"
              >
                Close Session
              </button>
              <button
                onClick={() => setConfirmCancelOpen(true)}
                className="px-4 py-2 rounded-full text-xs font-medium bg-pickle-tan text-white hover:bg-[#8a723e] shadow-sm transition-colors"
              // Using pickle-tan for secondary danger/warn
              >
                Cancel Session
              </button>
            </div>
          ) : (
            <button
              onClick={() => {
                if (currentOpSession) return;
                setConfirmStartOpen(true);
              }}
              className="px-4 py-2 rounded-full text-xs font-medium bg-pickle-green text-pickle-cream hover:bg-pickle-green/90 shadow-sm transition-transform active:scale-95"
            >
              Start Session
            </button>
          )}
          <button
            onClick={() => window.open(window.location.href.split('#')[0] + "#/display", "dink_display", "width=1280,height=720")}
            className="text-sm text-pickle-green font-medium underline decoration-pickle-green/30 hover:decoration-pickle-green transition-all ml-2"
          >
            Open Display
          </button>
        </div>
      </div>

      <div className="mt-2 grid grid-cols-1 md:grid-cols-12 gap-4 flex-1 min-h-0 overflow-x-hidden relative">
        {/* BLOCKER OVERLAY */}
        {!currentOpSession && (
          <div className="absolute inset-0 z-50 bg-white/60 backdrop-blur-[2px] flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-300">
            <div className="bg-white p-6 rounded-2xl shadow-xl flex flex-col items-center text-center max-w-sm border border-slate-100">
              <div className="w-12 h-12 rounded-full bg-pickle-green/10 flex items-center justify-center mb-4 text-2xl text-pickle-green">
                🔒
              </div>
              <h3 className="text-lg font-display text-slate-800 mb-2">Queue System Locked</h3>
              <p className="text-xs text-slate-500 mb-6 leading-relaxed">
                Please start an Open Play Session to manage players, courts, and matches. This ensures all your stats are tracked correctly.
              </p>
              <button
                onClick={() => setConfirmStartOpen(true)}
                className="bg-pickle-green text-pickle-cream px-6 py-2.5 rounded-full text-sm font-medium hover:bg-pickle-green/90 shadow-lg shadow-pickle-green/20 hover:scale-[1.02] transition-all"
              >
                Start New Session
              </button>
            </div>
          </div>
        )}

        <div className="md:col-span-6 flex flex-col min-h-0 overflow-x-hidden">
          <SurfaceCard className="flex-1 min-h-0 pr-1 border-pickle-green/10 shadow-sm" padded={false} bodyClassName="h-full p-3 bg-white/50 backdrop-blur-sm">
            <PlayerTable
              players={players}
              matches={matches}
              onAddPlayer={addPlayer}
              onRemovePlayer={removePlayer}
              onClearAll={clearAllPlayers}
              onSaveSessionAndClear={() => {
                if (currentOpSession) {
                  closeOpSession();
                }
                clearQueue();
                clearAllPlayers();
              }}
              onUpdateLevel={updateLevel}
              onStopPlayer={stopPlayer}
              onResumePlayer={resumePlayer}
              onUpdateGender={updateGender}
              onUpdatePaymentStatus={updatePaymentStatus}
              onMarkArrived={markPlayerArrived}
              onMarkAllPaid={markAllPaid}
              onMarkAllArrived={markAllArrived}
              disabled={!currentOpSession}
              matchQueue={matchQueue}
              onAddToQueue={addToQueue}
              onRenamePlayer={renamePlayer}
              onOpenReclub={() => setReclubOpen(true)}
              duplicateNames={duplicateNames}
              requestedMatches={requestedMatches}
              partners={partners}
            />
          </SurfaceCard>
        </div>

        <div className="md:col-span-3 flex flex-col min-h-0 overflow-x-hidden">
          <SurfaceCard padded={false} bodyClassName="flex-1 overflow-hidden p-3 bg-white/50 backdrop-blur-sm" className="border-pickle-green/10 shadow-sm h-full flex flex-col overflow-hidden">
            <MatchQueue
              players={players}
              courts={courts}
              queue={matchQueue}
              requestedMatches={requestedMatches}
              onAddRequestedMatch={addRequestedMatch}
              onRemoveRequestedMatch={removeRequestedMatch}
              onPromoteRequestedMatch={promoteRequestedMatchToQueue}
              onAddQueue={addQueue}
              onRemoveQueue={removeQueue}
              onRemoveFromQueue={removeFromQueue}
              onSendQueueToCourt={sendQueueToCourt}
              onAutoBuild={handleAutoBuild}
              compact
              disabled={!currentOpSession}
              partners={partners}
              onOpenPartners={() => setPartnersModalOpen(true)}
            />
          </SurfaceCard>
        </div>

        <div className="md:col-span-3 flex flex-col min-h-0 overflow-x-hidden">
          <div className="mb-2 flex gap-2 justify-end">
            <button
              onClick={() => {
                const bc = new BroadcastChannel("dink_manager");
                bc.postMessage({ type: "CLOSE_MODAL" });
                bc.close();
                toast.success("Display modals closed");
              }}
              className="px-4 py-2 rounded-full text-xs font-medium bg-pickle-tan text-white hover:bg-[#8a723e] shadow-sm transition-colors"
              title="Force close any open modals on the Display Screen"
            >
              Close Modal
            </button>

            <button
              onClick={addCourt}
              className="bg-pickle-green text-pickle-cream px-4 py-2 rounded-full text-xs font-medium hover:bg-pickle-green/90 transition-colors shadow-sm"
            >
              + Add Court
            </button>
            <button
              onClick={clearExtraCourts}
              className="border border-pickle-green text-pickle-green px-4 py-2 rounded-full text-xs font-medium hover:bg-pickle-green/10 transition-colors"
            >
              Clear Extras
            </button>
          </div>
          <SurfaceCard padded={false} bodyClassName="flex-1 overflow-y-auto p-3 bg-transparent shadow-none" className="bg-transparent shadow-none border-none">
            <CourtList
              courts={courts}
              players={players}
              onAssign={assignPlayerToCourt}
              onRemove={removePlayerFromCourt}
              onUnlockCourt={manualUnlockCourt}
              onRemoveCourt={removeCourt}
              onUpdateCourtName={updateCourtName}
              onSetTeams={setCourtTeam}
              onCompleteMatch={handleCompleteMatch}
              noTopMargin
              className="grid grid-cols-1 gap-3"
              compact
              onRequestMove={handleRequestMove}
              onReturnToQueue={handleReturnToQueue}
            />
          </SurfaceCard>
        </div>
      </div>

      <footer className="text-center text-pickle-green/40 text-[10px] mt-4 font-mono">
        POWERED BY <span className="font-bold text-pickle-green/60">DINK MANAGER</span>
      </footer>

      <ReclubModal
        open={reclubOpen}
        onClose={() => setReclubOpen(false)}
        onImportParticipants={(payload) => {
          const result = importReclubParticipants(payload);
          setReclubOpen(false);
        }}
      />

      <PartnersConfigModal
        isOpen={partnersModalOpen}
        onClose={() => setPartnersModalOpen(false)}
        players={players}
        partners={partners}
        onAddPartner={addPartner}
        onRemovePartner={removePartner}
        onTogglePartner={togglePartner}
      />

      {!!returnCourtId && (
        <ConfirmationModal
          isOpen={!!returnCourtId}
          onCancel={() => setReturnCourtId(null)}
          onConfirm={confirmReturnToQueue}
          title="Return Match to Queue"
          message="Are you sure you want to put this match back in the queue? Active wait time for these players will be restored."
          confirmLabel="Yes, Return to Queue"
          cancelLabel="Cancel"
          isDestructive={false}
        />
      )}

      <MoveMatchModal
        isOpen={moveMatchModal.isOpen}
        onClose={() => setMoveMatchModal({ isOpen: false, fromCourtId: null })}
        fromCourtName={courts.find(c => c.id === moveMatchModal.fromCourtId)?.name}
        courts={courts}
        onMove={(targetId) => {
          moveMatch(moveMatchModal.fromCourtId, targetId);
          setMoveMatchModal({ isOpen: false, fromCourtId: null });
        }}
      />

      {confirmCloseOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full mx-4 p-6 text-xs border border-pickle-green/10">
            <h2 className="text-lg font-display text-pickle-green mb-2">
              Review payments before ending session
            </h2>
            <p className="text-xs text-gray-600 mb-4 font-body">
              This will save a snapshot of the current Open Play session and clear players, queue, and courts.
              Please review payment statuses first.
            </p>
            {renderPaymentSummary()}
            <div className="flex flex-col sm:flex-row gap-2 justify-end mt-4">

              <button
                type="button"
                onClick={() => {
                  closeOpSession();
                  clearQueue();
                  clearAllPlayers();
                  setConfirmCloseOpen(false);
                }}
                className="bg-red-600 text-white px-4 py-2 rounded-full text-xs font-medium hover:bg-red-700"
              >
                Close and Clear
              </button>
              <button
                type="button"
                onClick={() => setConfirmCloseOpen(false)}
                className="border border-slate-200 text-slate-600 px-4 py-2 rounded-full text-xs font-medium hover:bg-slate-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmCancelOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full mx-4 p-6 text-xs border border-pickle-green/10">
            <h2 className="text-lg font-display text-pickle-green mb-2">Cancel current session</h2>
            <p className="text-xs text-gray-600 mb-4">
              This will delete the in-progress session without saving a summary.
            </p>
            <label className="block text-xs font-bold text-gray-800 mb-1 uppercase tracking-wide">
              Optional reason
            </label>
            <textarea
              rows="3"
              className="w-full border border-slate-200 rounded-lg p-2 text-xs focus:ring-pickle-green focus:border-pickle-green"
              placeholder="e.g. Rain delay, power outage"
              value={cancelReason}
              onChange={(e) => setCancelReason(e.target.value)}
            />
            <div className="flex flex-col sm:flex-row gap-2 justify-end mt-4">
              <button
                type="button"
                onClick={() => {
                  cancelOpSession(cancelReason.trim() || undefined);
                  clearQueue();
                  clearAllPlayers();
                  setCancelReason("");
                  setConfirmCancelOpen(false);
                }}
                className="bg-pickle-tan text-white px-4 py-2 text-xs font-medium rounded-full hover:bg-[#8a723e]"
              >
                Delete Session
              </button>
              <button
                type="button"
                onClick={() => {
                  setCancelReason("");
                  setConfirmCancelOpen(false);
                }}
                className="border border-slate-200 text-slate-600 px-4 py-2 text-xs font-medium rounded-full hover:bg-slate-50"
              >
                Keep Session
              </button>
            </div>
          </div>
        </div>
      )}

      {/* START SESSION CONFIRMATION MODAL */}
      {confirmStartOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full mx-4 p-6 border border-pickle-green/20">
            <h2 className="text-xl font-display text-pickle-green mb-2">Start Open Play Session</h2>
            <p className="text-sm text-slate-600 mb-4">
              Starting a new session will reset the queue and court status. Previous session data will be saved to history.
            </p>

            <div className="mb-6">
              <label className="block text-xs font-bold text-slate-700 mb-1 uppercase tracking-wider">
                Session Fee (PHP)
              </label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">₱</span>
                <input
                  type="number"
                  value={sessionFeeInput}
                  onChange={(e) => setSessionFeeInput(e.target.value)}
                  className="w-full pl-7 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-pickle-green focus:border-pickle-green outline-none font-medium text-slate-900"
                  placeholder="250"
                />
              </div>
              <p className="text-[10px] text-slate-400 mt-1">
                This fee will be applied to all players in this session.
              </p>
            </div>

            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmStartOpen(false)}
                className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleStartSession}
                className="px-6 py-2 text-sm font-bold text-white bg-pickle-green hover:bg-pickle-green/90 rounded-lg shadow-sm transition-transform active:scale-95"
              >
                Start Session
              </button>
            </div>
          </div>
        </div>
      )}


      <MatchProposalModal
        isOpen={proposalOpen}
        proposal={proposalData}
        onConfirm={handleConfirmProposal}
        onReGenerate={handleReGenerate}
        onClose={() => {
          setProposalOpen(false);
          setProposalData(null);
          setSeenGroups([]);
        }}
        isRegenerating={proposalGenerating}
      />
      <ConfirmationModal
        isOpen={infoModal.isOpen}
        title={infoModal.title}
        message={infoModal.message}
        confirmLabel="OK"
        cancelLabel={null}
        onConfirm={closeInfoModal}
        onCancel={closeInfoModal}
      />
    </div>
  );
}

