import React from "react";
import { ClipboardList, Pencil } from "lucide-react";

const STATUS_CHIP = {
  scheduled: { label: "Scheduled", cls: "bg-slate-100 text-slate-500" },
  in_progress: { label: "Live", cls: "bg-amber-100 text-amber-700" },
  completed: { label: "Done", cls: "bg-green-100 text-green-700" },
  bye: { label: "BYE", cls: "bg-slate-100 text-slate-400" },
};

export default function BracketMatchCard({ match, partnerA, partnerB, onScore, onEdit, isCompact = false }) {
  const isBye = match.status === "bye";
  const isCompleted = match.status === "completed";
  const isTbd = !partnerA && !partnerB;

  if (isTbd) {
    return (
      <div className={`border border-dashed border-slate-200 rounded-xl bg-slate-50 ${isCompact ? "p-2" : "p-3"}`}>
        <div className={`text-slate-300 text-center py-1 ${isCompact ? "text-[10px]" : "text-xs font-medium"}`}>TBD</div>
      </div>
    );
  }

  const winnerIsA = isCompleted && match.winner_id === match.partner_a_id;
  const winnerIsB = isCompleted && match.winner_id === match.partner_b_id;
  const chip = STATUS_CHIP[match.status] || STATUS_CHIP.scheduled;

  return (
    <div className={`border rounded-xl bg-white shadow-sm overflow-hidden ${isCompact ? "text-xs" : "text-sm"}`}>
      {/* Partner A row */}
      <div
        className={`flex items-center gap-2 border-b border-slate-100 ${isCompact ? "px-2 py-1.5" : "px-3 py-2"}
          ${winnerIsA ? "bg-pickle-green/10 border-l-[3px] border-l-pickle-green" : ""}
          ${!isCompleted && !isBye ? "hover:bg-slate-50" : ""}
        `}
      >
        <span className={`flex-1 font-semibold truncate ${isCompact ? "max-w-[90px]" : "max-w-[120px]"} ${winnerIsA ? "text-pickle-green" : "text-slate-800"}`}>
          {partnerA?.team_name || "TBD"}
        </span>
        {isCompleted && winnerIsA && <span className="text-pickle-green font-bold text-base leading-none">✓</span>}
      </div>

      {/* Partner B row */}
      <div
        className={`flex items-center gap-2 ${isCompact ? "px-2 py-1.5" : "px-3 py-2"}
          ${winnerIsB ? "bg-pickle-green/10 border-l-[3px] border-l-pickle-green" : ""}
          ${isBye ? "opacity-40" : ""}
          ${!isCompleted && !isBye ? "hover:bg-slate-50" : ""}
        `}
      >
        <span className={`flex-1 font-semibold truncate ${isCompact ? "max-w-[90px]" : "max-w-[120px]"} ${winnerIsB ? "text-pickle-green" : "text-slate-500"}`}>
          {partnerB ? partnerB.team_name : isBye ? "BYE" : "TBD"}
        </span>
        {isCompleted && winnerIsB && <span className="text-pickle-green font-bold text-base leading-none">✓</span>}
      </div>

      {/* Footer: status chip + action buttons */}
      {!isTbd && (
        <div className={`flex items-center justify-between gap-1 border-t border-slate-100 bg-slate-50/60 ${isCompact ? "px-1.5 py-0.5" : "px-2 py-1"}`}>
          <span className={`rounded-full font-semibold leading-none ${isCompact ? "text-[8px] px-1.5 py-0.5" : "text-[9px] px-2 py-0.5"} ${chip.cls}`}>
            {chip.label}
          </span>
          {!isBye && (onScore || onEdit) && (partnerA || partnerB) && (
            <div className="flex items-center gap-0.5">
              {onScore && (
                <button
                  onClick={() => onScore(match)}
                  className={`rounded text-slate-400 hover:text-pickle-green hover:bg-pickle-green/10 transition-colors ${isCompact ? "p-0.5" : "p-1"}`}
                  title={isCompleted ? "View / Edit Scores" : "Record Scores"}
                >
                  <ClipboardList size={isCompact ? 10 : 13} />
                </button>
              )}
              {onEdit && !isCompleted && (
                <button
                  onClick={() => onEdit(match)}
                  className={`rounded text-slate-400 hover:text-amber-500 hover:bg-amber-50 transition-colors ${isCompact ? "p-0.5" : "p-1"}`}
                  title="Edit participants"
                >
                  <Pencil size={isCompact ? 10 : 12} />
                </button>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
