import React, { useState, useEffect } from "react";
import DisplaySponsor from "./DisplaySponsor";

export default function DisplaySponsorSlideshow({ tournament }) {
  const sponsors = (tournament?.sponsors || []).filter((s) => s.enabled);
  const interval = (tournament?.display_settings?.sponsor_slideshow_interval || 8) * 1000;

  const [idx, setIdx] = useState(0);

  useEffect(() => {
    if (sponsors.length <= 1) return;
    const t = setInterval(() => setIdx((i) => (i + 1) % sponsors.length), interval);
    return () => clearInterval(t);
  }, [sponsors.length, interval]);

  if (sponsors.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-pickle-cream/30 font-oswald text-2xl uppercase tracking-widest">
        No Sponsors Added
      </div>
    );
  }

  const sponsor = sponsors[idx % sponsors.length];

  return (
    <div className="flex-1 flex flex-col">
      <DisplaySponsor sponsor={sponsor} tournament={tournament} />
      {sponsors.length > 1 && (
        <div className="shrink-0 flex justify-center gap-2 pb-4">
          {sponsors.map((_, i) => (
            <div
              key={i}
              className={`w-2 h-2 rounded-full transition-all ${i === idx ? "bg-pickle-cream" : "bg-white/20"}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}
