import React, { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Check, Trophy, X } from "lucide-react";
import { createRecordedMatch, getMatchParticipants, playerIdKey, resolveMatchResult } from "../../../state/matchResults";

const focusStyle = "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-pickle-tan focus-visible:ring-offset-2";

export default function MatchResultDialog({ match, players, sessionId, onRecordResult, onClose }) {
  const participants = useMemo(() => getMatchParticipants(match, players), [match, players]);
  const result = resolveMatchResult(match);
  const existingWinner = result.winner === "green" || result.winner === "blue" ? result.winner : null;
  const [winnerIds, setWinnerIds] = useState(() => existingWinner ? (match.teams[existingWinner] || []).map(playerIdKey) : []);
  const [winnerScore, setWinnerScore] = useState(() => existingWinner ? String(result.score[existingWinner]) : "11");
  const [loserScore, setLoserScore] = useState(() => existingWinner ? String(result.score[existingWinner === "green" ? "blue" : "green"]) : "");
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);
  const savingRef = useRef(false);
  const dialogRef = useRef(null);
  const invalidLineup = participants.length !== 4 || new Set(participants.map((p) => playerIdKey(p.id))).size !== 4;
  const winners = participants.filter((p) => winnerIds.includes(playerIdKey(p.id)));
  const losers = participants.filter((p) => !winnerIds.includes(playerIdKey(p.id)));
  let validation = "";
  try { createRecordedMatch(match, { winnerIds, winnerScore, loserScore }, players); }
  catch (err) { validation = err.message; }

  useEffect(() => {
    const previousFocus = document.activeElement;
    const dialog = dialogRef.current;
    dialog?.querySelector("[data-first-player]")?.focus();
    if (!dialog?.contains(document.activeElement)) dialog?.focus();
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        event.preventDefault();
        if (!savingRef.current) onClose();
      }
      if (event.key !== "Tab") return;
      const focusable = Array.from(dialog.querySelectorAll("button:not(:disabled), input:not(:disabled), [tabindex='0']"));
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) {
        event.preventDefault(); last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault(); first?.focus();
      }
    };
    dialog.addEventListener("keydown", onKeyDown);
    return () => { dialog.removeEventListener("keydown", onKeyDown); previousFocus?.focus(); };
  }, [onClose]);

  const toggleWinner = (id) => {
    setError("");
    setWinnerIds((prev) => prev.includes(id) ? prev.filter((pid) => pid !== id) : prev.length < 2 ? [...prev, id] : prev);
  };

  const submit = async (event) => {
    event.preventDefault();
    if (savingRef.current) return;
    if (validation) { setError(validation); return; }
    savingRef.current = true;
    setSaving(true);
    setError("");
    try {
      if (typeof onRecordResult !== "function") throw new Error("Result saving is unavailable. Please reopen this page.");
      await onRecordResult({ matchId: match.id, sessionId, winnerIds, winnerScore, loserScore });
      onClose();
    } catch (err) {
      setError(err.message || "Could not save this result. Please try again.");
      savingRef.current = false;
      setSaving(false);
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[110] flex items-end justify-center bg-pickle-green/40 backdrop-blur-sm sm:items-center sm:p-6">
      <div className="absolute inset-0" aria-hidden="true" onClick={() => !savingRef.current && onClose()} />
      <form ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="match-result-title" aria-describedby="match-result-description"
        tabIndex={-1} onSubmit={submit} aria-busy={saving}
        className="relative flex max-h-[94dvh] w-full flex-col overflow-hidden rounded-t-3xl bg-[#FFFBF2] shadow-2xl outline-none sm:max-w-xl sm:rounded-3xl">
        <header className="flex shrink-0 items-start justify-between gap-4 border-b border-pickle-green/10 bg-white px-5 py-5 sm:px-7">
          <div>
            <div className="mb-1 text-xs font-semibold uppercase tracking-wider text-pickle-tan">{match.courtName || `Court ${match.courtId ?? "—"}`} · Match result</div>
            <h2 id="match-result-title" className="!font-body text-xl font-semibold text-pickle-green">{result.recorded ? "Edit result" : "Record result"}</h2>
            <p id="match-result-description" className="mt-1 text-sm text-slate-600">Choose who won, then enter the final score.</p>
          </div>
          <button type="button" aria-label="Close result editor" disabled={saving} onClick={onClose}
            className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-full text-slate-500 hover:bg-slate-100 disabled:opacity-50 ${focusStyle}`}><X size={20} /></button>
        </header>
        <div className="min-h-0 space-y-6 overflow-y-auto px-5 py-5 sm:px-7">
          <section aria-labelledby="winner-selection-title">
            <div className="mb-3 flex items-center justify-between gap-3">
              <h3 id="winner-selection-title" className="!font-body text-base font-semibold text-slate-900">Who won?</h3>
              <span aria-live="polite" className="rounded-full bg-pickle-green/5 px-3 py-1 text-xs font-semibold text-pickle-green">{winnerIds.length}/2 selected</span>
            </div>
            {invalidLineup && <p role="alert" className="mb-3 rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">This match needs four distinct recorded players before a result can be saved. Its recorded players are incomplete.</p>}
            <div className="grid grid-cols-2 gap-3">
              {participants.map((player, index) => {
                const key = playerIdKey(player.id);
                const selected = winnerIds.includes(key);
                return <button key={`${key}-${index}`} type="button" data-first-player={index === 0 ? true : undefined}
                  aria-label={player.name} aria-pressed={selected} disabled={saving || invalidLineup || (!selected && winnerIds.length === 2)}
                  onClick={() => toggleWinner(key)}
                  className={`flex min-h-[76px] items-center gap-3 rounded-2xl border p-3 text-left transition-colors disabled:cursor-not-allowed ${selected ? "border-pickle-green bg-pickle-green text-white shadow-sm" : "border-pickle-green/15 bg-white text-slate-800 hover:border-pickle-tan disabled:opacity-50"} ${focusStyle}`}>
                  <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full border ${selected ? "border-white/30 bg-white/15" : "border-slate-200 bg-slate-50"}`}>
                    {selected ? <Check size={17} /> : <span className="text-xs font-semibold">{index + 1}</span>}
                  </span>
                  <span className="min-w-0 break-words text-sm font-semibold leading-snug">{player.name}{selected && <span className="mt-0.5 block text-xs font-normal text-white/80">Winner</span>}</span>
                </button>;
              })}
            </div>
            <p className="mt-2 text-xs text-slate-500">Tap a selected player again to change the winning pair.</p>
          </section>
          <section aria-labelledby="final-score-title">
            <h3 id="final-score-title" className="mb-3 !font-body text-base font-semibold text-slate-900">Final score</h3>
            <div className="space-y-3">
              {[{ label: "Winners · Green", names: winners, value: winnerScore, set: setWinnerScore, winner: true },
                { label: "Losers · Blue", names: winnerIds.length === 2 ? losers : [], value: loserScore, set: setLoserScore, winner: false }].map((side) => (
                  <label key={side.label} className={`flex items-center gap-4 rounded-2xl border bg-white p-4 ${side.winner ? "border-emerald-200" : "border-blue-200"}`}>
                    <span className="min-w-0 flex-1">
                      <span className={`flex items-center gap-1.5 text-xs font-semibold ${side.winner ? "text-emerald-800" : "text-blue-800"}`}>{side.winner && <Trophy size={14} />}{side.label}</span>
                      <span className="mt-1 block break-words text-sm font-semibold text-slate-800">{side.names.length ? side.names.map((p) => p.name).join(" & ") : side.winner ? "Select two winners above" : "The other two players"}</span>
                    </span>
                    <input aria-label={side.winner ? "Winning score" : "Losing score"} type="text" inputMode="numeric" autoComplete="off"
                      disabled={saving} value={side.value} placeholder="—" onChange={(e) => { side.set(e.target.value); setError(""); }}
                      className={`h-14 w-[76px] shrink-0 rounded-xl border border-slate-200 bg-slate-50 text-center text-2xl font-semibold tabular-nums text-slate-900 ${focusStyle}`} />
                  </label>
                ))}
            </div>
            <p className="mt-2 text-xs text-slate-500">Both scores are required. You can change 11 for longer games.</p>
          </section>
          {!validation && <p aria-live="polite" className="rounded-xl border border-pickle-tan/20 bg-pickle-tan/10 p-3 text-sm leading-relaxed text-pickle-green"><strong>{winners.map((p) => p.name).join(" & ")}</strong> won <strong>{winnerScore}–{loserScore}</strong> against {losers.map((p) => p.name).join(" & ")}.</p>}
          {error && <p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800">{error}</p>}
          {validation && !error && winnerIds.length === 2 && loserScore !== "" && <p aria-live="polite" className="text-sm text-amber-800">{validation}</p>}
        </div>
        <footer className="flex shrink-0 items-center justify-end gap-3 border-t border-pickle-green/10 bg-white px-5 py-4 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-7">
          <button type="button" disabled={saving} onClick={onClose} className={`min-h-[44px] rounded-xl px-5 text-sm font-semibold text-slate-600 hover:bg-slate-100 disabled:opacity-50 ${focusStyle}`}>Cancel</button>
          <button type="submit" disabled={saving || !!validation} className={`min-h-[44px] rounded-xl bg-pickle-green px-6 text-sm font-semibold text-white shadow-sm hover:bg-pickle-green/90 disabled:cursor-not-allowed disabled:opacity-40 ${focusStyle}`}>{saving ? "Saving…" : "Save result"}</button>
        </footer>
      </form>
    </div>, document.body
  );
}
