import React from "react";

const STATUS_STYLE = {
  in_progress: { border: "border-green-500/70", bg: "bg-green-500/10", badge: "bg-green-500/30 text-green-200", label: "LIVE" },
  scheduled:   { border: "border-amber-400/50",  bg: "bg-amber-500/5",  badge: "bg-amber-400/25 text-amber-200",  label: "UP NEXT" },
  completed:   { border: "border-white/15",       bg: "",                badge: "bg-white/10 text-white/50",       label: "DONE" },
  idle:        { border: "border-white/10",       bg: "",                badge: "bg-white/5 text-white/25",        label: "IDLE" },
};

function fmt12(time24) {
  if (!time24) return "";
  const [h, m] = time24.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

/** Return card width% for a given total count, for flex-wrap centering */
function getCardWidthPct(count) {
  if (count === 1) return 75;
  if (count === 2) return 45;
  if (count === 3) return 30;
  if (count === 4) return 45; // 2×2
  if (count <= 6) return 30;  // 3 per row
  return 22;                  // 4 per row
}

export default function DisplayLiveCourts({ tournament, matches, partners, divisions }) {
  const courts = tournament.courts || [];
  const partnerMap = Object.fromEntries(partners.map((p) => [p.id, p]));
  const divMap = Object.fromEntries(divisions.map((d) => [d.id, d]));

  function getCourtInfo(courtName) {
    const courtMatches = matches.filter(
      (m) => m.tournament_id === tournament.id && m.court === courtName
    );
    const live = courtMatches.find((m) => m.status === "in_progress");
    if (live) return { match: live, status: "in_progress" };
    const upcoming = courtMatches
      .filter((m) => m.status === "scheduled" && m.partner_a_id && m.partner_b_id)
      .sort((a, b) => {
        const da = (a.scheduled_date || "") + (a.scheduled_time || "");
        const db = (b.scheduled_date || "") + (b.scheduled_time || "");
        return da.localeCompare(db);
      })[0];
    if (upcoming) return { match: upcoming, status: "scheduled" };
    const last = courtMatches
      .filter((m) => m.status === "completed")
      .sort((a, b) => (b.completed_at || "").localeCompare(a.completed_at || ""))[0];
    if (last) return { match: last, status: "completed" };
    return { match: null, status: "idle" };
  }

  if (courts.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="text-pickle-cream/30 font-oswald font-bold text-5xl uppercase tracking-widest">No Courts Configured</div>
      </div>
    );
  }

  const cardWidthPct = getCardWidthPct(courts.length);

  return (
    <div className="flex-1 flex items-center justify-center p-6 overflow-auto">
      <div
        className="flex flex-wrap justify-center gap-5 content-center w-full h-full"
      >
        {courts.map((courtName) => {
          const { match, status } = getCourtInfo(courtName);
          const style = STATUS_STYLE[status] || STATUS_STYLE.idle;
          const teamA = match ? partnerMap[match.partner_a_id] : null;
          const teamB = match ? partnerMap[match.partner_b_id] : null;
          const div = match ? divMap[match.division_id] : null;

          // Live score (running game counter) vs completed game scores
          const liveScore = status === "in_progress" ? match.live_score : null;
          const completedScores = match?.scores?.length > 0 ? match.scores : null;

          return (
            <div
              key={courtName}
              style={{ width: `${cardWidthPct}%`, minWidth: "220px", maxWidth: "520px" }}
              className={`bg-white/10 border-2 ${style.border} ${style.bg} rounded-3xl p-7 flex flex-col gap-4`}
            >
              {/* Court name + status badge */}
              <div className="flex items-center justify-between gap-3">
                <span className="font-oswald font-bold text-white text-3xl uppercase tracking-wide leading-none">
                  {courtName}
                </span>
                <span className={`text-base font-bold px-4 py-1.5 rounded-full whitespace-nowrap ${style.badge}`}>
                  {style.label}
                </span>
              </div>

              {/* Match info */}
              {match ? (
                <div className="flex-1 flex flex-col justify-center gap-2">
                  {/* Team A row */}
                  <div className="flex items-center justify-between gap-3">
                    <span className="font-oswald font-bold text-white text-3xl leading-tight flex-1 min-w-0 truncate">
                      {teamA?.team_name || "TBD"}
                    </span>
                    {liveScore != null && (
                      <span className={`font-oswald font-bold text-4xl tabular-nums ${liveScore.partner_a > liveScore.partner_b ? "text-pickle-gold" : "text-white/70"}`}>
                        {liveScore.partner_a ?? 0}
                      </span>
                    )}
                  </div>

                  <div className="text-white/30 font-body text-xl text-center">vs</div>

                  {/* Team B row */}
                  <div className="flex items-center justify-between gap-3">
                    <span className="font-oswald font-bold text-white text-3xl leading-tight flex-1 min-w-0 truncate">
                      {teamB?.team_name || "TBD"}
                    </span>
                    {liveScore != null && (
                      <span className={`font-oswald font-bold text-4xl tabular-nums ${liveScore.partner_b > liveScore.partner_a ? "text-pickle-gold" : "text-white/70"}`}>
                        {liveScore.partner_b ?? 0}
                      </span>
                    )}
                  </div>

                  {/* Completed game scores */}
                  {completedScores && status !== "idle" && (
                    <div className="text-pickle-gold font-oswald font-bold text-xl mt-1 text-center">
                      {completedScores.map((g, i) => (
                        <span key={i}>{i > 0 ? " · " : ""}{g.partner_a}–{g.partner_b}</span>
                      ))}
                    </div>
                  )}

                  {/* Division */}
                  {div && (
                    <div className="text-pickle-cream/40 text-base font-body mt-1">{div.name}</div>
                  )}

                  {/* Scheduled time for upcoming */}
                  {status === "scheduled" && match.scheduled_time && (
                    <div className="text-pickle-cream/60 font-oswald font-bold text-2xl mt-1">
                      {fmt12(match.scheduled_time)}
                    </div>
                  )}
                </div>
              ) : (
                <div className="flex-1 flex items-center justify-center">
                  <span className="text-white/20 font-oswald font-bold text-2xl uppercase tracking-wide">Available</span>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
