/**
 * autoAssignGroups - randomly distributes partners across groups
 * respecting maxGroupSize. Returns a map of { partnerId: groupId }.
 */
export function autoAssignGroups(partners, groups, maxGroupSize) {
  if (!groups.length) return {};

  // Fisher-Yates shuffle
  const shuffled = [...partners];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  const assignments = {};
  shuffled.forEach((p, i) => {
    assignments[p.id] = groups[i % groups.length].id;
  });
  return assignments;
}

/**
 * snakeSeedPartners - distributes seeded partners using snake-draft order.
 * Seed 1 → Group A, Seed 2 → Group B, ..., Seed N → last group,
 * Seed N+1 → last group again, Seed N+2 → second-to-last, etc.
 * Returns a map of { partnerId: groupId }.
 */
export function snakeSeedPartners(seededPartners, groups) {
  if (!groups.length) return {};

  const n = groups.length;
  const assignments = {};

  seededPartners.forEach((p, i) => {
    const round = Math.floor(i / n);
    const posInRound = i % n;
    const groupIndex = round % 2 === 0 ? posInRound : n - 1 - posInRound;
    assignments[p.id] = groups[groupIndex].id;
  });

  return assignments;
}

/**
 * suggestGroupCount - returns the recommended number of groups based on partner count.
 */
export function suggestGroupCount(partnerCount, maxGroupSize) {
  if (partnerCount <= 0) return 1;
  return Math.ceil(partnerCount / maxGroupSize);
}
