/**
 * parseTime(timeStr) — converts "HH:MM" to minutes from midnight
 */
function parseTime(timeStr) {
  if (!timeStr) return 0;
  const [h, m] = timeStr.split(":").map(Number);
  return h * 60 + (m || 0);
}

/**
 * formatTime(minutes) — converts minutes from midnight to "HH:MM"
 */
function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

/**
 * addDays(dateStr, days) — returns a new YYYY-MM-DD string
 */
function addDays(dateStr, days) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().split("T")[0];
}

/**
 * generateTimeSlots(startDate, endDate, windowStart, windowEnd, matchDuration)
 * Returns array of { date: "YYYY-MM-DD", time: "HH:MM" }
 */
export function generateTimeSlots(startDate, endDate, windowStart, windowEnd, matchDuration) {
  const slots = [];
  if (!startDate || !endDate) return slots;

  const windowStartMin = parseTime(windowStart || "08:00");
  const windowEndMin = parseTime(windowEnd || "20:00");
  const durationMin = Number(matchDuration) || 60;

  let current = startDate;
  while (current <= endDate) {
    let timeMin = windowStartMin;
    while (timeMin + durationMin <= windowEndMin) {
      slots.push({ date: current, time: formatTime(timeMin) });
      timeMin += durationMin;
    }
    current = addDays(current, 1);
  }
  return slots;
}

/**
 * generateSchedule(unscheduledMatches, tournament, courtNames)
 * Assigns date/time/court to each match subject to constraints.
 * Returns a new array of match objects with schedule fields filled in.
 */
export function generateSchedule(unscheduledMatches, tournament, courtNames = ["Court 1"]) {
  if (!unscheduledMatches.length) return [];

  const rawGamesPerDay = Number(tournament.games_per_day);
  // 0 = unlimited: schedule everything on the start date with no daily cap
  const unlimitedPerDay = rawGamesPerDay === 0;
  const maxPerCourtPerDay = unlimitedPerDay ? Infinity : rawGamesPerDay || 4;

  // When unlimited, use only the start date to pack all games on day 1
  const scheduleEndDate = unlimitedPerDay
    ? tournament.start_date
    : (tournament.end_date || tournament.start_date);

  const slots = generateTimeSlots(
    tournament.start_date,
    scheduleEndDate,
    tournament.daily_window_start,
    tournament.daily_window_end,
    tournament.match_duration
  );

  if (!slots.length) {
    // No date configured — return matches without schedule
    return unscheduledMatches.map((m) => ({ ...m, could_not_schedule: true }));
  }

  // Track usage: courtDayCount[date][court] = count
  const courtDayCount = {};
  // Track partner busy slots: partnerSlots[partnerId][date+time] = true
  const partnerSlots = {};

  const isPartnerBusy = (partnerId, date, time) => {
    if (!partnerId) return false;
    return !!(partnerSlots[partnerId] && partnerSlots[partnerId][`${date}|${time}`]);
  };

  const markPartnerBusy = (partnerId, date, time) => {
    if (!partnerId) return;
    if (!partnerSlots[partnerId]) partnerSlots[partnerId] = {};
    partnerSlots[partnerId][`${date}|${time}`] = true;
  };

  const isCourtFull = (date, court) => {
    if (unlimitedPerDay) return false;
    return (courtDayCount[date]?.[court] || 0) >= maxPerCourtPerDay;
  };

  const markCourtUsed = (date, court) => {
    if (!courtDayCount[date]) courtDayCount[date] = {};
    courtDayCount[date][court] = (courtDayCount[date][court] || 0) + 1;
  };

  const scheduled = [];

  for (const match of unscheduledMatches) {
    let assigned = false;

    for (const slot of slots) {
      if (assigned) break;
      const { date, time } = slot;

      for (const court of courtNames) {
        if (isCourtFull(date, court)) continue;
        if (isPartnerBusy(match.partner_a_id, date, time)) continue;
        if (isPartnerBusy(match.partner_b_id, date, time)) continue;

        // Assign
        markCourtUsed(date, court);
        markPartnerBusy(match.partner_a_id, date, time);
        markPartnerBusy(match.partner_b_id, date, time);

        scheduled.push({
          ...match,
          scheduled_date: date,
          scheduled_time: time,
          court,
          could_not_schedule: false,
        });
        assigned = true;
        break;
      }
    }

    if (!assigned) {
      scheduled.push({ ...match, could_not_schedule: true });
    }
  }

  return scheduled;
}
