import React, { useMemo } from "react";
import { calculateGroupStandings } from "../../utils/standings";

export default function DisplayStandings({ tournament, divisions, groups, partners, matches, filterDivisionId }) {
  const allPartners = useMemo(() => partners, [partners]);
  const allMatches = useMemo(() => matches, [matches]);

  const shownDivisions = filterDivisionId
    ? divisions.filter((d) => d.id === filterDivisionId)
    : divisions.filter((d) => d.tournament_id === tournament.id);

  if (shownDivisions.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <div className="text-pickle-cream/40 font-oswald font-bold text-4xl uppercase tracking-widest">No Divisions</div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col items-center justify-center p-6 overflow-auto">
      <div className="w-full max-w-6xl space-y-10">
        {shownDivisions.map((div) => {
          const divGroups = groups.filter((g) => g.division_id === div.id);
          return (
            <div key={div.id}>
              <h2 className="font-oswald font-bold text-pickle-cream text-5xl mb-5 uppercase tracking-wide text-center">
                {div.name}
              </h2>
              <div className={`grid gap-6 ${divGroups.length > 2 ? "grid-cols-2" : "grid-cols-1"}`}>
                {divGroups.map((grp) => {
                  const rows = calculateGroupStandings(grp.id, allPartners, allMatches);
                  return (
                    <div key={grp.id} className="bg-white/10 rounded-3xl overflow-hidden">
                      {/* Group header */}
                      <div className="bg-white/15 px-6 py-4 text-center">
                        <span className="font-oswald font-bold text-white text-3xl tracking-wide">{grp.name}</span>
                      </div>
                      <table className="w-full">
                        <thead>
                          <tr className="text-pickle-cream/50 text-base uppercase tracking-widest font-oswald border-b border-white/10">
                            <th className="px-6 py-4 text-left w-12">#</th>
                            <th className="px-6 py-4 text-left">Team</th>
                            <th className="px-6 py-4 text-center w-20">W</th>
                            <th className="px-6 py-4 text-center w-20">L</th>
                            <th className="px-6 py-4 text-center w-24">Pts</th>
                            <th className="px-6 py-4 text-center w-24">PD</th>
                          </tr>
                        </thead>
                        <tbody>
                          {rows.map((row, idx) => (
                            <tr
                              key={row.partner.id}
                              className={`border-t border-white/10 ${idx < (div.advance_count || 2) ? "bg-pickle-green/25" : ""}`}
                            >
                              <td className="px-6 py-4 text-pickle-cream/50 font-oswald text-2xl">{idx + 1}</td>
                              <td className="px-6 py-4 font-oswald font-bold text-white text-2xl">{row.partner.team_name}</td>
                              <td className="px-6 py-4 text-center text-white font-oswald text-2xl font-bold">{row.wins}</td>
                              <td className="px-6 py-4 text-center text-white/50 font-oswald text-2xl">{row.losses}</td>
                              <td className="px-6 py-4 text-center text-pickle-gold font-oswald text-2xl font-bold">{row.points}</td>
                              <td className={`px-6 py-4 text-center font-oswald text-2xl ${row.pointDiff >= 0 ? "text-green-300" : "text-red-300"}`}>
                                {row.pointDiff > 0 ? "+" : ""}{row.pointDiff}
                              </td>
                            </tr>
                          ))}
                          {rows.length === 0 && (
                            <tr>
                              <td colSpan={6} className="px-6 py-8 text-center text-white/30 font-oswald text-xl">
                                No matches played yet
                              </td>
                            </tr>
                          )}
                        </tbody>
                      </table>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
