import React, { useMemo } from "react";
import { Trophy } from "lucide-react";

export default function DisplayResults({ tournament, matches, partners, divisions }) {
  const partnerMap = useMemo(() => Object.fromEntries(partners.map((p) => [p.id, p])), [partners]);
  const divMap = useMemo(() => Object.fromEntries(divisions.map((d) => [d.id, d])), [divisions]);

  const recent = useMemo(() => {
    return matches
      .filter((m) => m.tournament_id === tournament.id && m.status === "completed" && m.winner_id && m.status !== "bye")
      .sort((a, b) => (b.completed_at || "").localeCompare(a.completed_at || ""))
      .slice(0, 10);
  }, [matches, tournament.id]);

  if (recent.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-center">
        <div className="text-pickle-cream/30 font-oswald font-bold text-4xl uppercase tracking-widest">No Results Yet</div>
      </div>
    );
  }

  return (
    <div className="flex-1 p-6 overflow-auto flex flex-col justify-center">
      <div className="max-w-5xl mx-auto w-full space-y-3">
        {recent.map((m, idx) => {
          const teamA = partnerMap[m.partner_a_id];
          const teamB = partnerMap[m.partner_b_id];
          const div = divMap[m.division_id];
          const aWon = m.winner_id === m.partner_a_id;
          const bWon = m.winner_id === m.partner_b_id;
          const scoreStr = m.scores?.map((g) => `${g.partner_a}–${g.partner_b}`).join(", ") || "";

          return (
            <div
              key={m.id}
              className={`flex items-center gap-5 rounded-2xl px-7 py-5 ${idx % 2 === 0 ? "bg-white/10" : "bg-white/5"}`}
            >
              {/* Court */}
              <div className="w-24 shrink-0 text-right text-pickle-cream/40 font-oswald text-xl">
                {m.court || ""}
              </div>

              {/* Teams */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3">
                  {aWon && <Trophy size={20} className="text-pickle-gold shrink-0" />}
                  <span className={`font-oswald font-bold text-2xl ${aWon ? "text-pickle-gold" : "text-white/50"}`}>
                    {teamA?.team_name || "TBD"}
                  </span>
                </div>
                <div className="flex items-center gap-3 mt-2">
                  {bWon && <Trophy size={20} className="text-pickle-gold shrink-0" />}
                  <span className={`font-oswald text-2xl ${bWon ? "text-pickle-gold" : "text-white/50"}`}>
                    {teamB?.team_name || "TBD"}
                  </span>
                </div>
              </div>

              {/* Score + division */}
              <div className="shrink-0 text-right">
                {scoreStr && (
                  <div className="text-pickle-gold font-oswald font-bold text-2xl">{scoreStr}</div>
                )}
                {div && (
                  <div className="text-pickle-cream/30 text-base font-body mt-1">{div.name}</div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
