import { generateId } from "./ids";

const BYE_ID = "__BYE__";

/**
 * generateRoundRobin(partners, meta)
 * Implements the circle method for round-robin scheduling.
 * partners: array of partner objects with { id }
 * meta: { tournament_id, division_id, group_id }
 * Returns an array of match objects (flat, without IDs assigned to DB yet).
 */
export function generateRoundRobin(partners, meta = {}) {
  const n = partners.length;
  if (n < 2) return [];

  // If odd, add a BYE phantom
  let pool = [...partners];
  if (n % 2 !== 0) {
    pool.push({ id: BYE_ID });
  }

  const size = pool.length;
  const fixed = pool[0];
  let rotating = pool.slice(1);
  const matches = [];

  for (let round = 1; round <= size - 1; round++) {
    // Fixed vs last in rotating
    const pairs = [[fixed, rotating[size - 2]]];

    // Pair from outside in
    for (let i = 0; i < size / 2 - 1; i++) {
      pairs.push([rotating[i], rotating[size - 3 - i]]);
    }

    pairs.forEach(([a, b]) => {
      const aIsBye = a.id === BYE_ID;
      const bIsBye = b.id === BYE_ID;
      const isBye = aIsBye || bIsBye;
      const realPartnerId = aIsBye ? b.id : a.id;

      matches.push({
        id: generateId(),
        tournament_id: meta.tournament_id || null,
        division_id: meta.division_id || null,
        group_id: meta.group_id || null,
        phase: "group_stage",
        round,
        bracket_type: null,
        bracket_position: null,
        partner_a_id: isBye ? realPartnerId : a.id,
        partner_b_id: isBye ? null : b.id,
        winner_id: isBye ? realPartnerId : null,
        scores: [],
        scheduled_date: null,
        scheduled_time: null,
        court: null,
        status: isBye ? "bye" : "scheduled",
        created_at: new Date().toISOString(),
        completed_at: isBye ? new Date().toISOString() : null,
      });
    });

    // Rotate: move last element to front of rotating
    rotating = [rotating[size - 2], ...rotating.slice(0, size - 2)];
  }

  return matches;
}
