import React, { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import toast, { Toaster } from 'react-hot-toast';
import { useAppState } from "../../app/providers";
import { selectDashboardState } from "../../state/selectors";
import { buildRangeReport, computeDailyMetricsLastNDays, computeUtilizationForLastNDays } from "./utils/reports";
import MetricTile from "./components/MetricTile";
import RevenueDetailModal from "./components/RevenueDetailModal";
import GameplayDetailModal from "./components/GameplayDetailModal";
import RentalDetailModal from "./components/RentalDetailModal";
import UnpaidDetailsModal from "./components/UnpaidDetailsModal";
import SettlePaymentModal from "./components/SettlePaymentModal";
import ReportGenerationModal from "./components/ReportGenerationModal";
import BookingManagerModal from "../calendar/v2/BookingManagerModal"; // Added for viewing details
import { FileText } from "lucide-react";

// Enhanced Master Report Modal acts as a Summary Gateway
const MasterReportModal = ({ isOpen, onClose, data, range }) => {
    if (!isOpen || !data) return null;
    const { openPlay, rentals } = data;
    const totalIncome = (openPlay?.totalIncome || 0) + (rentals?.totalIncome || 0);
    const formatCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-auto flex flex-col">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center sticky top-0 bg-white z-10">
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900">Facility Report</h2>
                        <p className="text-sm text-slate-500 font-medium">{range === 'day' ? 'Daily' : range === 'week' ? 'Weekly' : 'Monthly'} Summary • {data.date}</p>
                    </div>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-500">✕</button>
                </div>

                <div className="p-8 bg-slate-50/50">
                    {/* Executive Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                        <div className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
                            <p className="text-xs uppercase tracking-wide text-indigo-600 font-bold mb-2">Total Revenue</p>
                            <p className="text-4xl font-bold text-slate-900">{formatCurrency(totalIncome)}</p>
                        </div>
                        <div className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
                            <p className="text-xs uppercase tracking-wide text-emerald-600 font-bold mb-2">Total Visitors</p>
                            <p className="text-4xl font-bold text-slate-900">{openPlay.totalPlayers}</p>
                        </div>
                        <div className="bg-white p-6 rounded-xl border border-slate-100 shadow-sm">
                            <p className="text-xs uppercase tracking-wide text-purple-600 font-bold mb-2">Rental Volume</p>
                            <p className="text-4xl font-bold text-slate-900">{rentals.totalRentals} <span className="text-lg text-slate-400 font-normal">bookings</span></p>
                        </div>
                    </div>

                    {/* Analysis Section */}
                    <div className="space-y-4">
                        <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide">Performance Insights</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="p-4 bg-white rounded-lg border border-slate-200">
                                <h4 className="font-semibold text-slate-800 mb-2">💰 Income Efficiency</h4>
                                <p className="text-sm text-slate-600 leading-relaxed">
                                    Open Play generated <strong>{formatCurrency(openPlay.totalIncome)}</strong> while Rentals contributed <strong>{formatCurrency(rentals.totalIncome)}</strong>.
                                    {rentals.totalIncome > openPlay.totalIncome ? " Rentals were the primary driver of revenue this period." : " Open Play sessions were the primary driver of revenue this period."}
                                </p>
                            </div>
                            <div className="p-4 bg-white rounded-lg border border-slate-200">
                                <h4 className="font-semibold text-slate-800 mb-2">🎾 Court Utilization</h4>
                                <p className="text-sm text-slate-600 leading-relaxed">
                                    Managed <strong>{rentals.totalRentals}</strong> rental bookings.
                                    {data.games?.topPlayerByWinRate ? ` Top performing player was ${data.games.topPlayerByWinRate.name} with a ${Math.round(data.games.topPlayerByWinRate.percent)}% win rate.` : " No competitive match data available for ranking."}
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
                <div className="p-6 bg-white border-t border-slate-100 text-center">
                    <p className="text-xs text-slate-400">Generated automatically by Dink Manager</p>
                </div>
            </div>
        </div>
    );
}

export default function DashboardV2Page() {
    const { bookingsV2 = {}, slotsV2 = {}, opSessions = [], settings, calendarCourts = [], players = [], markAllSlotsPaidV2, updateOpSession, updateBookingV2, fetchBookingsForRange } = useAppState(selectDashboardState);
    const navigate = useNavigate();

    // Data Loading: Fetch Last 30 Days + Current Month to support Charts and Range Views
    React.useEffect(() => {
        if (!fetchBookingsForRange) return;
        const today = new Date();

        // Start: 30 days ago (for charts)
        const start = new Date(today);
        start.setDate(today.getDate() - 32); // Buffer

        // End: End of current month (for "This Month" view)
        const end = new Date(today.getFullYear(), today.getMonth() + 1, 0);

        const sStr = start.toLocaleDateString('en-CA');
        const eStr = end.toLocaleDateString('en-CA');

        console.log(`Dashboard Fetching V2 Data: ${sStr} to ${eStr}`);
        fetchBookingsForRange(sStr, eStr);
    }, [fetchBookingsForRange]);

    const [range, setRange] = useState("day");
    const [modalOpen, setModalOpen] = useState(null); // 'revenue' | 'gameplay' | 'rental' | 'master' | 'unpaid'
    const [viewBookingId, setViewBookingId] = useState(null); // For BookingManagerModal

    // Settle Modal State
    const [settleModalOpen, setSettleModalOpen] = useState(false);
    const [reportModalOpen, setReportModalOpen] = useState(false);
    const [settleTarget, setSettleTarget] = useState(null); // { type: 'rental' | 'session_player', ids: [], sessionId?, playerId? }

    // Use Local Date for "Today" to align with User Perception vs UTC
    // This fixes the issue where early morning (local) looks like yesterday (UTC)
    const d = new Date();
    const localYMD = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const reportDate = localYMD;

    // Use reportDate string (YYYY-MM-DD) for consistency
    const reportData = useMemo(() => buildRangeReport(range, reportDate, opSessions, bookingsV2, slotsV2, settings, players), [range, reportDate, opSessions, bookingsV2, slotsV2, settings, players]);

    const formatLocalCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val);
    const incomeTotal = (reportData.openPlay.totalIncome || 0) + (reportData.rentals.totalIncome || 0);

    // 30-day history for Charts (independent of range toggle which affects Tiles)
    const history30 = useMemo(() => computeDailyMetricsLastNDays(opSessions, bookingsV2, slotsV2, 30, reportDate), [bookingsV2, slotsV2, opSessions, reportDate]);

    // Dynamic Sparklines based on real data
    const incomeSparkline = history30.slice(-7).map(d => d.total);
    // Visitors Sparkline for "Active Players" tile (Last 7 days)
    const visitorsSparkline = history30.slice(-7).map(d => d.visitorCount);
    // Rentals Sparkline (Calculated locally to ensure fresh data)
    const rentalsSparkline = useMemo(() => {
        const data = [];
        // Last 7 days including today
        for (let i = 6; i >= 0; i--) {
            const d = new Date(reportDate);
            d.setDate(d.getDate() - i);
            const ymd = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

            // Count unique bookings active on this day (V2)
            const unique = new Set();
            Object.values(slotsV2 || {}).forEach(s => {
                if (s && s.date === ymd && s.status !== 'CANCELLED') {
                    unique.add(s.bookingId);
                }
            });
            data.push(unique.size);
        }
        return data;
    }, [slotsV2, reportDate]);

    // Utilization for SELECTED RANGE
    const utilizationDays = range === 'day' ? 1 : range === 'week' ? 7 : 30;
    const utilizationSeries = useMemo(() => computeUtilizationForLastNDays(bookingsV2, slotsV2, calendarCourts.length || 4, settings, utilizationDays, reportDate), [bookingsV2, slotsV2, calendarCourts, settings, utilizationDays, reportDate]);

    // Real-time metrics
    const activeRentalCount = reportData.rentals.totalRentals;

    // Unpaid Data Derivation (Global, not range-limited)
    const unpaidSessions = useMemo(() => {
        return opSessions.filter(s =>
            String(s.status).toLowerCase() !== 'cancelled' &&
            s.players && s.players.some(p => (p.paymentStatus === 'not_paid' || p.paymentStatus === 'unpaid' || !p.paymentStatus))
        );
    }, [opSessions]);

    const unpaidRentals = useMemo(() => {
        const result = [];
        const ymd = (d) => {
            if (!d) return '';
            const dt = new Date(d);
            return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
        };

        Object.values(bookingsV2 || {}).forEach(b => {
            if (b.type === 'OPEN_PLAY_BLOCK') return; // Skip blocks

            const pSum = b.paymentSummary || {};
            const effectiveTotal = pSum.totalAmount ?? 0;
            const amountPaid = pSum.amountPaid || 0;

            // A booking has an outstanding balance if amountPaid < effectiveTotal
            const hasBalance = effectiveTotal > 0 && amountPaid < effectiveTotal;

            // Also check slot-level for backwards compatibility (legacy bookings without paymentSummary)
            const bSlots = Object.values(slotsV2).filter(s =>
                s.bookingId === b.id &&
                s.status !== 'CANCELLED' &&
                s.date // Ensure date exists
            );

            const hasUnpaidSlots = bSlots.some(s => !s.isPaid);

            // Show in unpaid list if: has a balance (discount-aware) OR has unpaid slots (legacy)
            if (!hasBalance && !hasUnpaidSlots) return;

                // Sort slots: By Date String then Start Time (numeric or string)
                bSlots.sort((x, y) => {
                    if (x.date !== y.date) return x.date.localeCompare(y.date);
                    // Compare Time: If number (minutes), compare. If string (ISO/Hash), compare string.
                    const tX = typeof x.startTime === 'number' ? x.startTime : (new Date(x.startTime).getTime() || 0);
                    const tY = typeof y.startTime === 'number' ? y.startTime : (new Date(y.startTime).getTime() || 0);
                    return tX - tY;
                });

                const start = bSlots[0];
                const end = bSlots[bSlots.length - 1];
                const courtIds = Array.from(new Set(bSlots.map(s => s.courtId))).sort().join(', ');

                // Formatter helper for Time only
                const formatTime = (val) => {
                    if (!val) return '';
                    if (typeof val === 'number') {
                        // Minutes from midnight
                        const h = Math.floor(val / 60);
                        const m = val % 60;
                        // Convert to AM/PM
                        const ampm = h >= 12 ? 'PM' : 'AM';
                        const h12 = h % 12 || 12;
                        return `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
                    }
                    // Fallback for ISO string
                    return new Date(val).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                };

                result.push({
                    ...b,
                    id: b.id,
                    rentalPrice: Math.max(0, effectiveTotal - amountPaid), // Outstanding balance (discount-aware)
                    renterName: b.renter?.name || b.title || "Unknown",
                    renterId: b.renter?.id,
                    renterContact: b.renter?.contact,
                    renterEmail: b.renter?.email,
                    date: start?.date || '', // Use direct YYYY-MM-DD string
                    // Display helpers for Modal
                    courtName: `Court ${courtIds}`,
                    courtId: courtIds, // fallback
                    startTime: formatTime(start?.startTime),
                    endTime: formatTime(end?.endTime)
                });
        });

        return result;
    }, [slotsV2, bookingsV2]);

    const unpaidStats = useMemo(() => {
        let count = 0;
        let amount = 0;

        unpaidSessions.forEach(s => {
            s.players.forEach(p => {
                if (!p.paymentStatus || p.paymentStatus === 'unpaid' || p.paymentStatus === 'not_paid') {
                    count++;
                    amount += (p.price || 0);
                }
            });
        });

        // For V2: use pre-computed rentalPrice which is discount-aware (effectiveTotal - amountPaid)
        unpaidRentals.forEach(b => {
            count++;
            amount += b.rentalPrice || 0;
        });

        return { count, amount };
    }, [unpaidSessions, unpaidRentals]);

    const handleRangeChange = (r) => setRange(r);

    // Handlers for Unpaid Actions
    const handleSettleRental = (rentalIds) => {
        const ids = Array.isArray(rentalIds) ? rentalIds : [rentalIds];

        // Settle Mode: We Open the Booking Manager for the first ID
        // (Batch settlement for multiple not supported in this modal yet, user asked for "slots view")
        if (ids.length > 0) {
            const id = ids[0];
            setViewBookingId(id);
            // We set settleTarget to TRUE (dummy) to indicate "Edit Mode" aka Settlement Mode
            setSettleTarget({ type: 'rental', ids });
        }
    };

    const handleSettleSessionPlayer = (sessionId, playerId) => {
        const session = opSessions.find(s => s.id === sessionId);
        const player = session?.players?.find(p => p.id === playerId);
        const amount = player?.price || 0;

        setSettleTarget({ type: 'session_player', sessionId, playerId, amount });
        setSettleModalOpen(true);
    };

    const onSettleConfirm = (method) => {
        if (!settleTarget) return;

        if (settleTarget.type === 'rental') {
            let settledTitle = "Rental Group";
            // Get title from first booking for the toast
            if (settleTarget.ids && settleTarget.ids.length > 0) {
                const firstId = settleTarget.ids[0];
                const booking = bookingsV2[firstId];
                if (booking) settledTitle = booking.title || booking.renter?.name || settledTitle;
            }

            settleTarget.ids.forEach(id => {
                // V2 Settle: Call markAllSlotsPaidV2
                if (markAllSlotsPaidV2) {
                    markAllSlotsPaidV2(id, method);
                } else {
                    console.error("markAllSlotsPaidV2 action missing");
                }
            });
            toast.success(`${settledTitle} has been successfully settled.`);

        } else if (settleTarget.type === 'session_player') {
            const { sessionId, playerId } = settleTarget;
            const session = opSessions.find(s => s.id === sessionId);
            if (session) {
                const updatedPlayers = session.players.map(p => {
                    if (p.id !== playerId) return p;
                    const isPaid = method !== 'unpaid';
                    const status = isPaid ? 'paid' : 'not_paid';
                    const paymentMethod = isPaid ? method : null;
                    const price = isPaid ? (p.price > 0 ? p.price : settings?.defaultOpFee || 250) : p.price;

                    return { ...p, paymentStatus: status, paymentMethod, price };
                });

                if (updateOpSession) {
                    updateOpSession(sessionId, { players: updatedPlayers });
                    const player = session.players.find(p => p.id === playerId);
                    const pName = player?.name || "Player";
                    toast.success(`${pName} has been successfully settled.`);
                }
            }
        }
        setSettleModalOpen(false);
        setSettleTarget(null);
    };

    // Placeholder for Session Settle - ideally we need playerID and sessionID
    // UnpaidDetailsModal will need to know how to call this.
    // For now, only rental settling is fully hooked up as requested in "Unpaid Rentals List".

    return (
        <div className="h-full overflow-y-auto bg-slate-50/50 p-6 font-sans">
            <Toaster position="top-center" reverseOrder={false} />
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Dashboard</h1>
                    <p className="text-slate-500 text-sm mt-1">Overview of your facility's performance.</p>
                </div>

                <div className="flex items-center gap-3 bg-white p-1.5 rounded-xl border border-slate-200 shadow-sm">
                    {['day', 'week', 'month'].map(r => (
                        <button
                            key={r}
                            onClick={() => handleRangeChange(r)}
                            className={`px-4 py-1.5 rounded-lg text-xs font-semibold transition-all ${range === r ? 'bg-slate-900 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}
                        >
                            {r === 'day' ? 'Today' : r === 'week' ? 'This Week' : 'This Month'}
                        </button>
                    ))}
                </div>

                <button
                    onClick={() => setReportModalOpen(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold rounded-lg shadow-sm transition-colors"
                >
                    <FileText className="w-4 h-4" />
                    <span>Generate Report</span>
                </button>
            </div>

            {/* Grid Layout: Top Row Tiles */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">

                <MetricTile
                    title={`Revenue (${range})`}
                    value={formatLocalCurrency(incomeTotal)}
                    icon="💰"
                    trend={{ value: "Live", direction: "neutral" }}
                    chartData={incomeSparkline}
                    colorClass="text-emerald-600"
                    onViewReport={() => setModalOpen('revenue')}
                />

                <MetricTile
                    title="Registered Players"
                    value={reportData.openPlay.totalPlayers}
                    subtext="Total Check-ins"
                    icon="👥"
                    colorClass="text-indigo-600"
                    chartData={visitorsSparkline} // Real data now
                    onViewReport={() => setModalOpen('gameplay')}
                />

                <MetricTile
                    title={`Rentals (${range})`}
                    value={activeRentalCount}
                    subtext="Rental Bookings"
                    icon="📅"
                    colorClass="text-purple-600"
                    trend={{ value: `${Math.round(reportData.rentals.totalIncome / 1000)}k`, direction: "neutral" }}
                    chartData={rentalsSparkline}
                    onViewReport={() => setModalOpen('rental')}
                />

                <MetricTile
                    title="Unpaid Balance"
                    value={formatLocalCurrency(unpaidStats.amount)}
                    subtext={`${unpaidStats.count} Pending Items`}
                    icon="⚠️"
                    colorClass="text-rose-600"
                    trend={{ value: "Action Needed", direction: "down" }}
                    onViewReport={() => setModalOpen('unpaid')}
                />


            </div>

            {/* Middle Grid: Quick Actions + Tables */}
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-8">
                {/* Middle Col: Today's Rentals List */}
                <div className="lg:col-span-3">
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide">Today's Rentals</h3>
                        <span className="text-xs text-slate-500 font-medium">{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}</span>
                    </div>

                    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden h-full max-h-[400px] overflow-y-auto">
                        {(() => {
                            // Logic to get today's rentals grouped (V2)
                            // Use 'en-CA' (YYYY-MM-DD) for consistent local date string
                            const localYMD = new Date().toLocaleDateString('en-CA');

                            const todaySlots = Object.values(slotsV2 || {}).filter(s => {
                                if (!s || s.status === 'CANCELLED') return false;

                                // Primary Match: s.date (set by Calendar to YYYY-MM-DD)
                                if (s.date && s.date === localYMD) return true;

                                // Fallback: Parse startTime
                                if (s.startTime) {
                                    const sd = new Date(s.startTime);
                                    const sYMD = sd.toLocaleDateString('en-CA');
                                    return sYMD === localYMD;
                                }
                                return false;
                            });
                            console.log(`[Dashboard] Today (${localYMD}) Slots:`, todaySlots.length);

                            // Group by Booking
                            const groups = {};
                            todaySlots.forEach(slot => {
                                const b = bookingsV2[slot.bookingId];
                                if (!b) return;

                                const key = b.id;
                                if (!groups[key]) {
                                    groups[key] = {
                                        id: key,
                                        title: b.title,
                                        renterName: b.renter?.name,
                                        renterContact: b.renter?.contact,
                                        renterEmail: b.renter?.email,
                                        paymentStatus: 'pending', // derived below
                                        courtIds: new Set(),
                                        slots: []
                                    };
                                }
                                groups[key].courtIds.add(slot.courtId);
                                groups[key].slots.push(slot);
                            });

                            // Derive status using paymentSummary (respects discounts)
                            Object.values(groups).forEach(g => {
                                const booking = bookingsV2[g.id];
                                const pSum = booking?.paymentSummary || {};
                                const effectiveTotal = pSum.totalAmount ?? g.slots.reduce((sum, s) => sum + (s.price || 0), 0);
                                const amountPaid = pSum.amountPaid || 0;

                                if (amountPaid >= effectiveTotal && effectiveTotal > 0) {
                                    g.paymentStatus = 'paid';
                                } else if (amountPaid > 0) {
                                    g.paymentStatus = 'partial';
                                } else {
                                    g.paymentStatus = 'unpaid';
                                }

                                // Sort slots by startTime (minutes)
                                g.slots.sort((a, b) => a.startTime - b.startTime);
                                g.startTime = g.slots[0].startTime;
                                g.endTime = g.slots[g.slots.length - 1].endTime;
                            });

                            const sortedGroups = Object.values(groups).sort((a, b) => a.startTime - b.startTime);

                            if (sortedGroups.length === 0) {
                                return <div className="p-8 text-center text-slate-400 text-sm">No rentals scheduled for today.</div>;
                            }

                            const formatTime = (minutes) => {
                                if (typeof minutes !== 'number') return '--:--';
                                const h = Math.floor(minutes / 60);
                                const m = minutes % 60;
                                const ampm = h >= 12 ? 'PM' : 'AM';
                                const h12 = h % 12 || 12;
                                return `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
                            };

                            return (
                                <div className="overflow-x-auto">
                                    <table className="w-full text-left text-xs">
                                        <thead className="bg-slate-50 border-b border-slate-100 text-slate-500 font-semibold sticky top-0">
                                            <tr>
                                                <th className="py-3 px-4 whitespace-nowrap">Time</th>
                                                <th className="py-3 px-4">Booking / Renter</th>
                                                <th className="py-3 px-4">Courts</th>
                                                <th className="py-3 px-4 text-right">Payment</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-slate-100">
                                            {sortedGroups.map(g => {
                                                const renterDisplay = g.renterName || "Pickle Renter";
                                                const contact = g.renterContact || g.renterEmail || "";

                                                // Status badge color
                                                let badgeClass = 'bg-amber-50 text-amber-700 border-amber-200';
                                                if (g.paymentStatus === 'paid') badgeClass = 'bg-emerald-50 text-emerald-700 border-emerald-200';
                                                if (g.paymentStatus === 'partial') badgeClass = 'bg-blue-50 text-blue-700 border-blue-200';

                                                return (
                                                    <tr key={g.id} className="hover:bg-slate-50 transition-colors">
                                                        <td className="py-3 px-4 font-mono text-slate-600 whitespace-nowrap">
                                                            {formatTime(g.startTime)} - {formatTime(g.endTime)}
                                                        </td>
                                                        <td className="py-3 px-4 min-w-[200px]">
                                                            <div className="font-semibold text-slate-900 text-sm">{g.title || "Rental"}</div>
                                                            <div className="text-[11px] text-slate-500 flex items-center gap-1">
                                                                <span>👤 {renterDisplay}</span>
                                                                {contact && <span className="opacity-50 hidden sm:inline">• {contact}</span>}
                                                            </div>
                                                        </td>
                                                        <td className="py-3 px-4 text-slate-600 whitespace-nowrap">
                                                            {Array.from(g.courtIds).sort().join(', ')}
                                                        </td>
                                                        <td className="py-3 px-4 text-right">
                                                            <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[10px] uppercase font-bold tracking-wide border ${badgeClass}`}>
                                                                {g.paymentStatus}
                                                            </span>
                                                        </td>
                                                    </tr>
                                                )
                                            })}
                                        </tbody>
                                    </table>
                                </div>

                            );
                        })()}
                    </div>
                </div>

                {/* Right Col: Today's Open Play */}
                <div className="lg:col-span-1">
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wide">Open Play</h3>
                    </div>
                    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden h-full max-h-[400px] overflow-y-auto">
                        {(() => {
                            const d = new Date();
                            const localYMD = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

                            const sessionsToday = opSessions.filter(s => {
                                // Simple date match
                                const start = new Date(s.startedAt);
                                const sYMD = `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, '0')}-${String(start.getDate()).padStart(2, '0')}`;
                                return sYMD === localYMD && s.status !== 'cancelled';
                            }).sort((a, b) => b.startedAt - a.startedAt); // Newest first

                            if (sessionsToday.length === 0) {
                                return <div className="p-8 text-center text-slate-400 text-sm">No open play sessions today.</div>;
                            }

                            return (
                                <div className="divide-y divide-slate-100">
                                    {sessionsToday.map(s => (
                                        <div key={s.id} className="p-4 hover:bg-slate-50 transition-colors">
                                            <div className="flex justify-between items-start mb-1">
                                                <span className="font-semibold text-slate-800 text-xs">Session #{s.id.slice(-4)}</span>
                                                <span className={`px-2 py-0.5 rounded-full text-[10px] uppercase font-bold tracking-wide border ${s.status === 'live' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-slate-50 text-slate-500 border-slate-100'}`}>
                                                    {s.status}
                                                </span>
                                            </div>
                                            <div className="flex justify-between items-end mt-2">
                                                <div className="text-xs text-slate-500">
                                                    <span className="block">👥 {s.players?.length || 0} Players</span>
                                                    <span className="block mt-0.5">💰 {formatLocalCurrency(s.players?.reduce((sum, p) => sum + (p.price || 0), 0) || 0)}</span>
                                                </div>
                                                <span className="text-[10px] text-slate-400">{new Date(s.startedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )
                        })()}
                    </div>
                </div>

            </div>

            {/* Modals */}
            <ReportGenerationModal isOpen={reportModalOpen} onClose={() => setReportModalOpen(false)} />
            <MasterReportModal isOpen={modalOpen === 'master'} onClose={() => setModalOpen(null)} data={reportData} range={range} />
            <RevenueDetailModal isOpen={modalOpen === 'revenue'} onClose={() => setModalOpen(null)} data={reportData} range={range} />
            <GameplayDetailModal isOpen={modalOpen === 'gameplay'} onClose={() => setModalOpen(null)} data={reportData} range={range} />
            <RentalDetailModal isOpen={modalOpen === 'rental'} onClose={() => setModalOpen(null)} data={reportData} range={range} />
            <UnpaidDetailsModal
                isOpen={modalOpen === 'unpaid'}
                onClose={() => setModalOpen(null)}
                unpaidSessions={unpaidSessions}
                unpaidRentals={unpaidRentals}
                onSettleRental={handleSettleRental}
                onSettleSessionPlayer={handleSettleSessionPlayer}
                onViewBooking={(id) => setViewBookingId(id)}
                defaultOpFee={settings?.defaultOpFee || 250}
            />
            <SettlePaymentModal
                isOpen={settleModalOpen}
                onClose={() => {
                    setSettleModalOpen(false);
                    setSettleTarget(null);
                }}
                onSettle={onSettleConfirm}
                title={settleTarget?.type === 'rental' ? 'Settle Rental Group' : 'Settle Player Payment'}
                amount={settleTarget?.amount}
            />

            {/* Read-Only View of Booking */}
            {viewBookingId && (
                <BookingManagerModal
                    isOpen={!!viewBookingId}
                    onClose={() => {
                        setViewBookingId(null);
                        setSettleTarget(null); // Clear settle target if any
                    }}
                    booking={bookingsV2[viewBookingId]}
                    slots={Object.values(slotsV2).filter(s => s.bookingId === viewBookingId && s.status !== 'CANCELLED')}
                    allSlots={Object.values(slotsV2)} // For conflict checking if they edit times
                    courts={calendarCourts}
                    readOnly={false} // Always Allow Edits (Transactions)
                    initialTab={settleTarget ? 'slots' : 'overview'} // Jump to slots if settling
                    onUpdateBooking={(id, data) => {
                        if (updateBookingV2) {
                            // The Modal returns { renter, payment, slots }.
                            // We should pass this to updateBooking.
                            updateBookingV2(id, data);
                            toast.success("Booking updated securely.");
                            setViewBookingId(null);
                            setSettleTarget(null);
                        } else {
                            console.error("updateBooking action missing");
                        }
                    }}
                />
            )}
        </div>
    );
}
