import React, { useEffect, useMemo, useState } from "react";
import toast from "react-hot-toast";
import PlayerRow from "./PlayerRow";
import { Link } from "react-router-dom";
import { MIN_WAIT_FOR_PRIORITY as WAIT_PRIORITY_MIN } from "../utils/autoQueue";
import { stringToColor } from "../utils/colorHash";

export default function PlayerTable({
  players,
  matches,
  onAddPlayer,
  onRemovePlayer,
  onClearAll,
  onSaveSessionAndClear,
  onUpdateLevel,
  onStopPlayer,
  onUpdateGender,
  onResumePlayer,
  onUpdatePaymentStatus,
  onMarkArrived,
  onMarkAllPaid,
  onMarkAllArrived,
  matchQueue,
  onAddToQueue,
  onRenamePlayer,
  onOpenReclub,
  disabled = false,
  duplicateNames = [], // 👈 new prop
  requestedMatches = [], // 👈 new prop
  partners = [], // 👈 new prop for tandem detection
}) {
  const [newPlayer, setNewPlayer] = useState("");
  const [newPlayerGender, setNewPlayerGender] = useState("M");
  const [error, setError] = useState("");
  const [sortTick, setSortTick] = useState(0);
  const [activeTab, setActiveTab] = useState("players");
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [bulkAction, setBulkAction] = useState(null); // 'arrived' | 'paid' | null
  const [searchTerm, setSearchTerm] = useState(""); // 👈 new search state

  useEffect(() => {
    const id = setInterval(() => setSortTick((tick) => tick + 1), 30000);
    return () => clearInterval(id);
  }, []);

  // Toast for duplicates
  const prevDupsRef = React.useRef(0);
  useEffect(() => {
    if (duplicateNames && duplicateNames.length > 0 && duplicateNames.length > prevDupsRef.current) {
      toast.error(`Found ${duplicateNames.length} duplicate name(s)! Highlighted in red.`, {
        duration: 5000,
        position: "top-center",
        id: "duplicate-name-toast", // Static ID to prevent stacking
      });
    }
    prevDupsRef.current = duplicateNames.length;
  }, [duplicateNames]);

  useEffect(() => {
    setSortTick((tick) => tick + 1);
  }, [players]);

  // Compute Recent Match Highlights
  const recentMatchMap = useMemo(() => {
    const map = new Map();
    const now = Date.now();
    const RECENT_THRESHOLD = 15 * 60 * 1000; // 15 mins

    // Matches are not guaranteed to be sorted, so we verify
    const sorted = [...matches].sort((a, b) => (b.endTime || 0) - (a.endTime || 0));

    sorted.forEach(m => {
      if (m.status === 'completed' && m.endTime && (now - m.endTime) < RECENT_THRESHOLD) {
        // Generate color for this match
        const color = stringToColor(m.id || `match-${m.endTime}`);
        // Apply to all players in lineup
        if (m.lineup) {
          m.lineup.forEach(p => {
            if (!map.has(p.id)) {
              map.set(p.id, color);
            }
          });
        }
      }
    });

    return map;
  }, [matches]);

  const tabs = useMemo(
    () => {
      // Calculate arrived count
      const arrivedCount = players.filter(p => p.arrivalTime > 0).length;

      return [
        { id: "players", label: `Players (${arrivedCount}/${players.length})` },
        { id: "payments", label: `Payments (${players.length})` },
      ];
    },
    [players]
  );

  const isQueued = (pid) => matchQueue?.some((item) => item?.playerIds?.includes(pid));

  // Compute partner info map for all players
  const partnerInfoMap = useMemo(() => {
    const map = new Map();
    partners.forEach(p => {
      if (!p.isActive) return;
      const p1 = players.find(x => x.id === p.player1Id);
      const p2 = players.find(x => x.id === p.player2Id);
      if (p1 && p2) {
        map.set(p.player1Id, {
          partnerId: p.player2Id,
          partnerName: p2.name,
          partnerStatus: p2.status,
          isActive: true
        });
        map.set(p.player2Id, {
          partnerId: p.player1Id,
          partnerName: p1.name,
          partnerStatus: p1.status,
          isActive: true
        });
      }
    });
    return map;
  }, [partners, players]);

  const sortedPlayers = useMemo(() => {
    const refreshKey = sortTick;

    const bucket = (player) => {
      if (player.status === "waiting") return 0;
      if (player.status === "queued") return 1;
      if (player.status === "playing") return 2;
      return 3;
    };

    const getWaitMinutes = (player) => {
      if (player.status !== "waiting" && player.status !== "queued") return 0;
      if (!player.waitStart) return 0;
      return Math.floor((Date.now() - player.waitStart) / 60000);
    };

    return [...players].sort((a, b) => {
      const aBucket = bucket(a);
      const bBucket = bucket(b);
      if (aBucket !== bBucket) return aBucket - bBucket;

      if (aBucket === 0 || aBucket === 1) {
        const aWait = getWaitMinutes(a) + refreshKey * 0;
        const bWait = getWaitMinutes(b) + refreshKey * 0;
        const aPriority = aWait >= WAIT_PRIORITY_MIN;
        const bPriority = bWait >= WAIT_PRIORITY_MIN;
        if (aPriority && !bPriority) return -1;
        if (bPriority && !aPriority) return 1;
        if (aPriority && bPriority) return bWait - aWait;
        if (a.matches !== b.matches) return a.matches - b.matches;
        return bWait - aWait;
      }

      if (aBucket === 2) {
        if (a.matches !== b.matches) return a.matches - b.matches;
        return a.name.localeCompare(b.name);
      }

      return a.name.localeCompare(b.name);
    });
  }, [players, sortTick]);

  // Search Filtering
  const displayedPlayers = useMemo(() => {
    if (!searchTerm.trim()) return sortedPlayers;
    const lower = searchTerm.toLowerCase();
    return sortedPlayers.filter(p => p.name.toLowerCase().includes(lower));
  }, [sortedPlayers, searchTerm]);

  const paymentPlayers = useMemo(() => {
    let list = players;
    if (searchTerm.trim()) {
      const lower = searchTerm.toLowerCase();
      list = list.filter(p => p.name.toLowerCase().includes(lower));
    }
    // Default sort for payments? Maybe alphabetical?
    return [...list].sort((a, b) => a.name.localeCompare(b.name));
  }, [players, searchTerm]);


  const handleSubmit = (event) => {
    event.preventDefault();
    if (!newPlayer.trim()) return;
    const upperName = newPlayer.trim().toUpperCase();
    if (players.some((p) => p.name.toUpperCase() === upperName)) {
      setError("Player already exists");
      return;
    }
    onAddPlayer(upperName, newPlayerGender, "High Intermediate");
    setNewPlayer("");
    setError("");
  };

  // Clear duplicates on rename if it fixes it?
  // Passed down logic could handle it, or we rely on the `duplicateNames` set.
  // When a player is renamed, if their OLD name was in valid list, we might need to re-check?
  // Actually, `importReclubParticipants` return value sets the `duplicateNames` state.
  // If user renames one of them, we rely on the parent (QueuePage) or we can clear specific name.
  // For simplicity, if we rename, we can remove that name from duplicates list.
  const handleRenameProxy = (id, newName) => {
    onRenamePlayer(id, newName);
  };


  return (
    <div className={`shadow-none rounded-xl p-0 h-full flex flex-col min-h-0 relative bg-transparent`}>
      <Link to="/leaderboards?tab=matches" className="mb-3 inline-flex min-h-[44px] items-center justify-center gap-2 rounded-xl border border-pickle-green/15 bg-pickle-green/5 px-4 text-sm font-semibold text-pickle-green hover:bg-pickle-green/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-pickle-tan">
        Record results <span className="text-xs font-normal">in Leaderboards →</span>
      </Link>
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2 p-1 bg-slate-100 rounded-lg">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={`px-3 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === tab.id
                ? "bg-pickle-green text-pickle-cream shadow-sm"
                : "text-slate-500 hover:text-pickle-green hover:bg-slate-200"
                }`}
              onClick={() => {
                setActiveTab(tab.id);
                setSearchTerm(""); // Clear search on tab switch
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>

        {activeTab === "players" && (
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setConfirmOpen(true)}
              className="border border-red-200 text-red-600 px-3 py-1 text-xs rounded-full hover:bg-red-50 hover:border-red-300 transition-colors"
            >
              Clear All
            </button>
            <button
              type="button"
              onClick={() => setSortTick((tick) => tick + 1)}
              className="text-xs px-3 py-1 border border-pickle-green/20 text-pickle-green rounded-full hover:bg-pickle-green/5 transition-colors"
            >
              Resort
            </button>
          </div>
        )}
      </div>

      {activeTab === "players" ? (
        <>
          <div className="mb-4 space-y-2">
            {/* Search Bar */}
            <div className="relative">
              <input
                type="text"
                placeholder="🔍 Search players..."
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-pickle-green/20 focus:border-pickle-green outline-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <form onSubmit={handleSubmit} className="flex flex-wrap gap-2 items-start">
              <div className="flex flex-col flex-1 min-w-[200px]">
                <input
                  type="text"
                  value={newPlayer}
                  onChange={(e) => {
                    setNewPlayer(e.target.value);
                    if (error) setError("");
                  }}
                  placeholder="Enter player name"
                  className={`border rounded-lg p-2 text-sm focus:ring-2 focus:ring-pickle-green/20 focus:border-pickle-green outline-none transition-all ${error ? "border-red-500" : "border-slate-200"
                    }`}
                />
                {error && <span className="text-red-500 text-xs mt-1">{error}</span>}
              </div>

              <select
                value={newPlayerGender}
                onChange={(e) => setNewPlayerGender(e.target.value)}
                className="border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-pickle-green/20 focus:border-pickle-green outline-none"
              >
                <option value="M">Male</option>
                <option value="F">Female</option>
              </select>

              <button
                type="submit"
                className="bg-pickle-green text-pickle-cream px-4 py-2 rounded-lg hover:bg-pickle-green/90 text-sm font-medium transition-colors shadow-sm"
              >
                + Add
              </button>
              <button
                type="button"
                onClick={() => onOpenReclub?.()}
                // Use pickle-tan for secondary heavy actions or external integrations
                className="bg-pickle-tan text-white px-4 py-2 rounded-lg hover:bg-[#8a723e] text-sm font-medium transition-colors shadow-sm"
              >
                Reclub Meet
              </button>
            </form>
          </div>

          <div className="flex-1 min-h-0 overflow-y-auto rounded-lg border border-pickle-green/10">
            <table className="w-full text-sm">
              <thead className="sticky top-0 z-10 bg-pickle-green/5 backdrop-blur-sm">
                <tr>
                  <th className="p-3 text-left text-xs font-bold text-pickle-green uppercase tracking-wider">Name</th>
                  <th className="p-3 text-xs font-bold text-pickle-green uppercase tracking-wider">Level</th>
                  <th className="p-3 text-xs font-bold text-pickle-green uppercase tracking-wider">Gender</th>
                  <th className="p-3 text-xs font-bold text-pickle-green uppercase tracking-wider">Status</th>
                  <th className="p-3 text-xs font-bold text-pickle-green uppercase tracking-wider">Wait</th>
                  <th className="p-3 text-xs font-bold text-pickle-green uppercase tracking-wider">Matches</th>
                  <th className="p-3 text-center text-xs font-bold text-pickle-green uppercase tracking-wider">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 bg-white">
                {displayedPlayers.map((player) => {
                  const isDup = duplicateNames.includes(player.name.toUpperCase());
                  const isReq = (requestedMatches || []).some(m => m.playerIds.includes(player.id));
                  return (
                    <PlayerRow
                      key={player.id}
                      player={player}
                      queued={isQueued(player.id)}
                      onRemovePlayer={onRemovePlayer}
                      onUpdateLevel={onUpdateLevel}
                      onUpdateGender={onUpdateGender}
                      onUpdatePaymentStatus={onUpdatePaymentStatus}
                      onStopPlayer={onStopPlayer}
                      onResumePlayer={onResumePlayer}
                      onAddToQueue={onAddToQueue}
                      onRenamePlayer={handleRenameProxy}
                      isDuplicate={isDup}
                      isRequested={isReq}
                      partnerInfo={partnerInfoMap.get(player.id)}
                      recentMatchColor={recentMatchMap.get(player.id)} // 👈 Pass color
                    />
                  );
                })}
              </tbody>
            </table>
          </div>
          {confirmOpen && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
              <div className="bg-white rounded-xl shadow-xl max-w-md w-full mx-4 p-6 border border-pickle-green/10">
                <h2 className="text-lg font-display text-pickle-green mb-2">Clear all players?</h2>
                <p className="text-xs text-slate-600 mb-4">
                  Are you sure you want to clear all the players from the list? You will not be able
                  to save the details from this session unless you save it now.
                </p>
                <div className="flex flex-col sm:flex-row gap-2 justify-end">
                  <button
                    type="button"
                    onClick={() => {
                      onSaveSessionAndClear?.();
                      setConfirmOpen(false);
                    }}
                    className="bg-pickle-green text-pickle-cream px-4 py-2 text-xs font-medium rounded-full hover:bg-pickle-green/90"
                  >
                    Save Session and Clear
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      onClearAll();
                      setConfirmOpen(false);
                    }}
                    className="border border-red-200 text-red-600 px-4 py-2 text-xs font-medium rounded-full hover:bg-red-50"
                  >
                    Clear Players
                  </button>
                  <button
                    type="button"
                    onClick={() => setConfirmOpen(false)}
                    className="text-xs px-4 py-2 rounded-full text-slate-500 hover:bg-slate-100"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}
        </>
      ) : (
        <div className="flex-1 min-h-0 overflow-y-auto rounded-lg border border-pickle-green/10 flex flex-col">
          {/* Bulk Actions Header */}
          <div className="p-2 border-b border-pickle-green/10 flex items-center justify-between gap-2 bg-slate-50">
            <div className="flex items-center gap-3">
              <input
                type="text"
                placeholder="🔍 Search payments..."
                className="border border-slate-200 rounded-lg px-2 py-1 text-xs focus:ring-1 focus:ring-pickle-green/20 focus:border-pickle-green outline-none min-w-[150px]"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <div className="flex gap-2 text-[10px] font-mono border-l pl-2 border-slate-200">
                <span className="bg-emerald-50 text-emerald-700 px-1.5 py-0.5 rounded border border-emerald-100">
                  Arrived: {players.filter(p => p.arrivalTime > 0).length}
                </span>
                <span className="bg-pickle-green/10 text-pickle-green px-1.5 py-0.5 rounded border border-pickle-green/20">
                  Paid: {players.filter(p => p.paymentStatus === 'paid').length}
                </span>
              </div>
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setBulkAction('arrived')}
                className="text-xs px-3 py-1.5 rounded-md bg-emerald-100 text-emerald-700 hover:bg-emerald-200 font-medium transition-colors"
              >
                All Arrived
              </button>
              <button
                type="button"
                onClick={() => setBulkAction('paid')}
                className="text-xs px-3 py-1.5 rounded-md bg-pickle-green text-white hover:bg-pickle-green/90 font-medium transition-colors shadow-sm"
              >
                All Paid
              </button>
            </div>
          </div>
          <table className="w-full text-sm">
            <thead className="sticky top-0 z-10 bg-pickle-green/5 backdrop-blur-sm">
              <tr>
                <th className="p-3 text-left text-xs font-bold text-pickle-green uppercase tracking-wider">Name</th>
                <th className="p-3 text-center text-xs font-bold text-pickle-green uppercase tracking-wider">Payment</th>
                <th className="p-3 text-center text-xs font-bold text-pickle-green uppercase tracking-wider">Arrival</th>
                <th className="p-3 text-center text-xs font-bold text-pickle-green uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 bg-white">
              {paymentPlayers.map((player) => (
                <tr key={player.id} className="hover:bg-pickle-green/5 transition-colors">
                  <td className="p-3 text-left font-medium text-slate-700">{player.name}</td>
                  <td className="p-3 text-center">
                    <div className="flex flex-col items-center gap-2">
                      {/* Status Buttons */}
                      <div className="flex items-center bg-slate-100 rounded-lg p-0.5">
                        <button
                          type="button"
                          onClick={() => onUpdatePaymentStatus(player.id, "unpaid", null)}
                          className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${player.paymentStatus === "unpaid" || !player.paymentStatus
                            ? "bg-white text-rose-600 shadow-sm"
                            : "text-slate-400 hover:text-slate-600"
                            }`}
                        >
                          Unpaid
                        </button>
                        <button
                          type="button"
                          onClick={() => onUpdatePaymentStatus(player.id, "paid", player.paymentMethod || "cash")}
                          className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${player.paymentStatus === "paid"
                            ? "bg-pickle-green text-white shadow-sm"
                            : "text-slate-400 hover:text-slate-600"
                            }`}
                        >
                          Paid
                        </button>
                      </div>

                      {/* MOP Select */}
                      <select
                        value={player.paymentMethod || ""}
                        onChange={(e) => onUpdatePaymentStatus(player.id, player.paymentStatus, e.target.value)}
                        className="border border-slate-200 rounded-lg px-2 py-1 text-xs bg-white w-full max-w-[120px] focus:border-pickle-green outline-none"
                      >
                        <option value="" disabled>Select MOP</option>
                        <option value="cash">Cash</option>
                        <option value="gcash">GCash</option>
                        <option value="gotyme">GoTyme</option>
                        <option value="free">Free</option>
                      </select>
                    </div>
                  </td>
                  <td className="p-3 text-center text-xs text-slate-500 font-mono">
                    {player.arrivalTime
                      ? new Date(player.arrivalTime).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                      })
                      : "—"}
                  </td>
                  <td className="p-3 text-center">
                    {player.status === "stopped" ? (
                      <button
                        type="button"
                        className="text-xs px-3 py-1 rounded-full bg-emerald-600 text-white hover:bg-emerald-700 shadow-sm"
                        onClick={() => onMarkArrived(player.id)}
                      >
                        Tag Arrived
                      </button>
                    ) : (
                      <span className="text-xs text-slate-400 italic">Already in play</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {/* Confirmation Modal Logic */}
      {bulkAction && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-xl max-w-sm w-full mx-4 p-6 border border-pickle-green/10">
            <h2 className="text-lg font-display text-pickle-green mb-2">
              {bulkAction === 'arrived' ? "Mark all as Arrived?" : "Mark all as Paid?"}
            </h2>
            <p className="text-xs text-slate-600 mb-6">
              {bulkAction === 'arrived'
                ? "This will set the status of all stopped players to 'Waiting' and update their arrival time to now. Players currently in matches or queued will be unaffected."
                : "This will mark all Unpaid players as Paid via Cash. Players with existing payment methods will not be changed."}
            </p>
            <div className="flex justify-end gap-2">
              <button
                onClick={() => setBulkAction(null)}
                className="px-4 py-2 rounded-full text-slate-500 hover:bg-slate-100 text-xs font-medium"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  if (bulkAction === 'arrived') onMarkAllArrived();
                  else if (bulkAction === 'paid') onMarkAllPaid();
                  setBulkAction(null);
                }}
                className="bg-pickle-green text-white px-4 py-2 rounded-full hover:bg-pickle-green/90 text-xs font-medium shadow-sm transition-transform active:scale-95"
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
