import React from "react";

const PHASE_STYLES = {
  setup: "bg-slate-100 text-slate-600",
  group_stage: "bg-blue-100 text-blue-700",
  playoffs: "bg-amber-100 text-amber-700",
  completed: "bg-green-100 text-green-700",
};

const PHASE_LABELS = {
  setup: "Setup",
  group_stage: "Group Stage",
  playoffs: "Playoffs",
  completed: "Completed",
};

export default function PhaseBadge({ phase, className = "" }) {
  const style = PHASE_STYLES[phase] || PHASE_STYLES.setup;
  const label = PHASE_LABELS[phase] || phase;
  return (
    <span
      className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold uppercase tracking-wide ${style} ${className}`}
    >
      {label}
    </span>
  );
}
