import React, { useMemo } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useAppState } from '../../app/providers';
import { selectDashboardState } from '../../state/selectors';
import { computeDailyMetricsInRange, buildPerPlayerMatchStats, buildPerPlayerWaitBeforeMatch } from '../dashboard/utils/reports';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
    PieChart, Pie, Cell, Legend, LineChart, Line
} from 'recharts';
import { ArrowLeft, Printer, Calendar as CalendarIcon, DollarSign, Users, Activity, Trophy, Clock, Timer, Gamepad2 } from 'lucide-react';

const COLORS = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];
const PIE_COLORS = { cash: '#10b981', gcash: '#3b82f6', gotyme: '#f59e0b', unpaid: '#ef4444', free: '#94a3b8', cancelled: '#cbd5e1' };

const StatBadge = ({ label, value, sub }) => (
    <div className="bg-white border border-slate-200 rounded-xl p-4 flex flex-col justify-center items-center text-center shadow-sm">
        <p className="text-xs font-bold text-slate-400 uppercase mb-1">{label}</p>
        <p className="text-2xl font-extrabold text-slate-900">{value}</p>
        {sub && <p className="text-xs text-indigo-600 font-medium">{sub}</p>}
    </div>
);

// --- Helper Components for Layout ---
const SectionHeader = ({ icon: Icon, title, subtitle }) => (
    <div className="flex items-start gap-3 mb-6 border-b border-pickle-green/10 pb-4 print:break-inside-avoid">
        <div className="p-2 bg-pickle-green/10 rounded-lg text-pickle-green print:bg-white print:border print:border-pickle-green/20">
            <Icon className="w-6 h-6" />
        </div>
        <div>
            <h2 className="text-xl font-bold text-pickle-green font-body">{title}</h2>
            <p className="text-sm text-pickle-green/60">{subtitle}</p>
        </div>
    </div>
);

const InsightCard = ({ title, value, insight, trend }) => (
    <div className="bg-slate-50 p-5 rounded-xl border border-slate-100 print:border-slate-200 print:bg-white">
        <p className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-1">{title}</p>
        <p className="text-3xl font-bold text-slate-900 mb-2">{value}</p>
        <p className="text-sm text-slate-600 leading-snug border-t border-slate-200 pt-2 mt-2">
            💡 {insight}
        </p>
    </div>
);

export default function ReportPrintPage() {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const { bookings = [], bookingsV2 = {}, slotsV2 = {}, opSessions = [], players = [] } = useAppState(selectDashboardState);

    // Extract Params
    const mode = searchParams.get('mode') || 'day';
    const singleDate = searchParams.get('date');
    const startDate = searchParams.get('start');
    const endDate = searchParams.get('end');
    const month = searchParams.get('month');

    // Date Range Logic
    const rangeInfo = useMemo(() => {
        if (mode === 'day') {
            const dLocal = new Date();
            const localYMD = `${dLocal.getFullYear()}-${String(dLocal.getMonth() + 1).padStart(2, '0')}-${String(dLocal.getDate()).padStart(2, '0')}`;
            const d = singleDate || localYMD;
            return { label: `Daily Report: ${d}`, start: d, end: d };
        }
        if (mode === 'month') {
            const m = month || new Date().toISOString().slice(0, 7);
            const [y, mo] = m.split('-');
            const firstDay = `${m}-01`;
            const lastDay = new Date(y, mo, 0).toISOString().slice(0, 10);
            return { label: `Monthly Report: ${new Date(firstDay).toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}`, start: firstDay, end: lastDay };
        }
        return { label: `Custom Range: ${startDate} to ${endDate}`, start: startDate, end: endDate };
    }, [mode, singleDate, startDate, endDate, month]);

    // --- Metrics Calculation ---
    const metrics = useMemo(() => {
        if (!rangeInfo.start || !rangeInfo.end) return null;

        const dailySeries = computeDailyMetricsInRange(opSessions, bookingsV2, slotsV2, rangeInfo.start, rangeInfo.end);

        // Define helper early
        const toYMDLocal = (date) => {
            const d = new Date(date);
            if (isNaN(d.getTime())) return "";
            return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        };

        // Aggregates
        const totalIncome = dailySeries.reduce((sum, d) => sum + d.total, 0);
        const openPlayIncome = dailySeries.reduce((sum, d) => sum + d.openPlayIncome, 0);
        const rentalIncome = dailySeries.reduce((sum, d) => sum + d.rentalIncome, 0);
        const totalVisitors = dailySeries.reduce((sum, d) => sum + d.visitorCount, 0);
        const totalRentals = dailySeries.reduce((sum, d) => sum + d.rentalCount, 0);

        // Busiest Day Logic
        let busiestDay = dailySeries[0];
        let quietestDay = dailySeries[0];
        dailySeries.forEach(d => {
            if (d.visitorCount > (busiestDay?.visitorCount || 0)) busiestDay = d;
            if (d.visitorCount < (quietestDay?.visitorCount || Infinity)) quietestDay = d;
        });

        // Payment Mix
        // Filter source data for details
        const sessionsInRange = opSessions.filter(s => {
            const sYMD = toYMDLocal(s.startedAt || s.endedAt);
            return sYMD >= rangeInfo.start && sYMD <= rangeInfo.end;
        });

        // V2 Rentals In Range (Slots)
        // We'll reconstruct "Rental Objects" for the list view, or simply iterate slots for stats
        // For the "Rental Volume" list, we likely want bookings.
        // Let's gather slots in range first.

        const slotsInRange = [];
        const uniqueResultIds = new Set();
        Object.values(slotsV2 || {}).forEach(s => {
            if (s && s.status !== 'CANCELLED') {
                // Use s.date (YYYY-MM-DD string) as primary, fallback to parsing startTime
                const sYMD = s.date || toYMDLocal(s.startTime);
                // Simple YMD range check
                if (sYMD >= rangeInfo.start && sYMD <= rangeInfo.end) {
                    slotsInRange.push(s);
                    uniqueResultIds.add(s.bookingId);
                }
            }
        });
        const rentalsInRange = Array.from(uniqueResultIds).map(id => bookingsV2[id]).filter(Boolean);

        // --- Payment Mix (Open Play Specific) ---
        const opPaymentCounts = { cash: 0, gcash: 0, gotyme: 0, unpaid: 0, free: 0, cancelled: 0 };
        sessionsInRange.forEach(s => {
            (s.players || []).forEach(p => {
                const status = String(p.paymentStatus || 'not_paid').toLowerCase();
                const method = String(p.paymentMethod || '').toLowerCase();

                if (status === 'cancelled') { opPaymentCounts.cancelled++; return; }

                if (status === 'unpaid' || status === 'not_paid' || (!status && !method)) {
                    opPaymentCounts.unpaid++;
                } else {
                    // Paid Logic aligned with reports.js
                    if (method === 'free' || status === 'free') opPaymentCounts.free++;
                    else if (method.includes('gotyme')) opPaymentCounts.gotyme++;
                    else if (method.includes('gcash')) opPaymentCounts.gcash++;
                    else opPaymentCounts.cash++; // Default
                }
            });
        });
        const opPaymentData = Object.entries(opPaymentCounts)
            .filter(([_, val]) => val > 0)
            .map(([name, value]) => ({ name, value }))
            .sort((a, b) => b.value - a.value);

        // --- Gameplay Stats ---
        // 1. Flatten Matches
        const allMatches = sessionsInRange.flatMap(s => s.matches || []);

        // 2. Durations
        const durations = allMatches.map(m => m.durationMs ? m.durationMs / 60000 : 0).filter(d => d > 0);
        const avgMatchDuration = durations.length ? durations.reduce((a, b) => a + b, 0) / durations.length : 0;
        const shortestMatch = durations.length ? Math.min(...durations) : 0;
        const longestMatch = durations.length ? Math.max(...durations) : 0;

        // 3. Player Stats (Matches & Win Rate)
        // Ensure buildPerPlayerMatchStats is robust even if matches are empty
        const matchStats = buildPerPlayerMatchStats(allMatches);
        const playerMatchCounts = {}; // {pid: {wins, losses, total}}
        matchStats.forEach(stat => {
            if (!playerMatchCounts[stat.playerId]) playerMatchCounts[stat.playerId] = { wins: 0, total: 0, id: stat.playerId };
            playerMatchCounts[stat.playerId].total++;
            if (stat.result === 'win') playerMatchCounts[stat.playerId].wins++;
        });

        const activePlayers = Object.values(playerMatchCounts);
        const realAvgGames = activePlayers.length ? activePlayers.reduce((sum, p) => sum + p.total, 0) / activePlayers.length : 0;

        const highestGamesPlayer = activePlayers.sort((a, b) => b.total - a.total)[0] || null;
        const topWinRatePlayer = activePlayers.filter(p => p.total >= 3).sort((a, b) => (b.wins / b.total) - (a.wins / a.total))[0] || null;

        // 4. Wait Times
        const waitMap = buildPerPlayerWaitBeforeMatch(allMatches); // Map<pid, Map<mid, ms>>
        let totalWaitMs = 0;
        let waitCount = 0;
        let maxWaitMs = 0;

        waitMap.forEach((matchWaits) => {
            matchWaits.forEach((ms) => {
                totalWaitMs += ms;
                if (ms > 0) { // Only count positive waits
                    waitCount++;
                    if (ms > maxWaitMs) maxWaitMs = ms;
                }
            });
        });
        const avgWaitMin = waitCount ? (totalWaitMs / waitCount / 60000) : 0;
        const maxWaitMin = maxWaitMs / 60000;

        // 5. Activity List (Hydrated)
        const topPlayers = activePlayers
            .map(p => {
                const foundS = sessionsInRange.find(s => s.players && s.players.find(pl => pl.id === p.id));
                const name = foundS?.players.find(pl => pl.id === p.id)?.name || 'Unknown';
                return { ...p, name, visits: p.total };
            })
            .sort((a, b) => b.visits - a.visits)
            .slice(0, 5);

        // --- Rental Specific Metrics (V2) ---
        const courtStats = {}; // { 1: { revenue: 0, hours: 0 } }
        let totalRentalHours = 0;

        // Build court stats: hours by court, revenue distributed from booking-level amountPaid
        // First pass: accumulate hours per court per booking
        const bookingCourtHours = {}; // bookingId -> { courtId: hours }
        const countedBookings = new Set();

        slotsInRange.forEach(slot => {
            const cid = slot.courtId;
            const name = `Court ${cid}`;
            if (!courtStats[cid]) courtStats[cid] = { name, revenue: 0, hours: 0 };

            // Use minutes-from-midnight format
            let duration = 0;
            if (typeof slot.startTime === 'number' && typeof slot.endTime === 'number') {
                duration = Math.max(0, (slot.endTime - slot.startTime) / 60);
            } else {
                const start = new Date(slot.startTime);
                const end = new Date(slot.endTime);
                duration = Math.max(0, (end - start) / (1000 * 60 * 60));
            }
            courtStats[cid].hours += duration;
            totalRentalHours += duration;

            if (!bookingCourtHours[slot.bookingId]) bookingCourtHours[slot.bookingId] = {};
            bookingCourtHours[slot.bookingId][cid] = (bookingCourtHours[slot.bookingId][cid] || 0) + duration;
        });

        // Second pass: distribute each booking's amountPaid across courts proportionally by hours
        slotsInRange.forEach(slot => {
            if (countedBookings.has(slot.bookingId)) return;
            countedBookings.add(slot.bookingId);

            const booking = bookingsV2[slot.bookingId];
            const pSum = booking?.paymentSummary || {};
            const paid = pSum.amountPaid || 0;
            if (paid <= 0) return;

            const courtHours = bookingCourtHours[slot.bookingId] || {};
            const totalHoursForBooking = Object.values(courtHours).reduce((s, h) => s + h, 0);
            if (totalHoursForBooking <= 0) return;

            Object.entries(courtHours).forEach(([cid, hours]) => {
                if (courtStats[cid]) {
                    courtStats[cid].revenue += paid * (hours / totalHoursForBooking);
                }
            });
        });

        const courtData = Object.values(courtStats).sort((a, b) => a.name.localeCompare(b.name));
        const startD = new Date(rangeInfo.start);
        const endD = new Date(rangeInfo.end);
        const daysInRange = Math.max(1, (endD - startD) / (1000 * 60 * 60 * 24));
        const averageDailyHours = totalRentalHours / daysInRange;

        return {
            dailySeries,
            totalIncome, openPlayIncome, rentalIncome,
            totalVisitors, totalRentals,
            busiestDay, quietestDay,
            opPaymentData, // Renamed for clarity in JSX
            rentalsInRange,
            topPlayers,
            courtData,
            totalRentalHours,
            averageDailyHours,
            // Gameplay
            avgMatchDuration, shortestMatch, longestMatch,
            avgWaitMin, maxWaitMin,
            realAvgGames, highestGamesPlayer, topWinRatePlayer
        };
    }, [opSessions, bookingsV2, slotsV2, rangeInfo]);

    if (!metrics) return <div className="flex h-screen items-center justify-center font-bold text-slate-400">Loading Report...</div>;

    const formatCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

    // --- Insights Generators ---
    const revenueInsight = metrics.openPlayIncome > metrics.rentalIncome
        ? `Open Play contributes ${Math.round((metrics.openPlayIncome / metrics.totalIncome) * 100)}% of revenue, outperforming rentals.`
        : `Rentals are the primary revenue driver, contributing ${Math.round((metrics.rentalIncome / metrics.totalIncome) * 100)}% of total income.`;

    const trafficInsight = metrics.busiestDay
        ? `Peak traffic was on ${metrics.busiestDay.date} with ${metrics.busiestDay.visitorCount} visitors.`
        : `Traffic has been consistent throughout the period.`;

    const rentalInsight = metrics.totalRentals > 0
        ? `A total of ${metrics.totalRentals} bookings were managed, generating ${formatCurrency(metrics.rentalIncome)}.`
        : "No rental bookings were recorded in this period.";

    return (
        <div className="h-screen overflow-y-auto bg-slate-50 print:bg-white p-6 md:p-12 font-sans text-slate-900 print:h-auto print:overflow-visible print:p-0">
            {/* Nav */}
            <div className="max-w-5xl mx-auto mb-8 flex justify-between items-center print:hidden">
                <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-slate-600 hover:text-slate-900 font-bold"><ArrowLeft className="w-5 h-5" /> Back</button>
                <button onClick={() => window.print()} className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-bold shadow-sm"><Printer className="w-5 h-5" /> Print Report</button>
            </div>

            <div className="max-w-5xl mx-auto bg-white print:shadow-none shadow-xl rounded-2xl overflow-hidden print:rounded-none print:w-full print:max-w-none">

                {/* 0. Header & Summary */}
                <div className="bg-pickle-cream text-pickle-green px-10 py-8 print:bg-pickle-cream print:text-pickle-green border-b-4 border-pickle-green/20">
                    <div className="flex justify-between items-start mb-6">
                        <div>
                            <h1 className="text-4xl font-extrabold mb-2 tracking-tight font-body">Facility Performance Report</h1>
                            <p className="text-pickle-green/80 font-medium flex items-center gap-2 text-lg">
                                <CalendarIcon className="w-5 h-5" /> {rangeInfo.label}
                            </p>
                        </div>
                        <div className="text-right hidden print:block">
                            <h2 className="text-2xl font-bold text-pickle-green font-display">Pickle Studio</h2>
                            <p className="text-sm text-pickle-green/60">Generated {new Date().toLocaleDateString()}</p>
                        </div>
                    </div>
                </div>

                <div className="p-10 space-y-12">
                    {/* Executive Summary Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <InsightCard title="Total Revenue" value={formatCurrency(metrics.totalIncome)} insight={revenueInsight} />
                        <InsightCard title="Total Visitors" value={metrics.totalVisitors} insight={trafficInsight} />
                        <InsightCard title="Rental Volume" value={metrics.totalRentals} insight={rentalInsight} />
                    </div>

                    <hr className="border-slate-100" />

                    {/* 1. Revenue Section */}
                    <section className="print:break-inside-avoid">
                        <SectionHeader icon={DollarSign} title="Financial Performance" subtitle="Revenue breakdown by source and method." />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
                            <div className="h-64 bg-white border border-slate-100 rounded-xl p-4">
                                <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Daily Revenue Trend</h4>
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={metrics.dailySeries}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                        <XAxis dataKey="date" tickFormatter={d => d.slice(5)} fontSize={10} />
                                        <YAxis fontSize={10} tickFormatter={v => `₱${v / 1000}k`} />
                                        <RechartsTooltip formatter={(v) => formatCurrency(v)} />
                                        <Bar dataKey="openPlayIncome" stackId="a" fill="#4f46e5" name="Open Play" />
                                        <Bar dataKey="rentalIncome" stackId="a" fill="#10b981" name="Rentals" />
                                        <Legend />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                            <div className="h-64 bg-white border border-slate-100 rounded-xl p-4">
                                <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Revenue by Source</h4>
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie data={[{ name: 'Open Play', value: metrics.openPlayIncome }, { name: 'Rentals', value: metrics.rentalIncome }]} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                                            {COLORS.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                                        </Pie>
                                        <RechartsTooltip formatter={(v) => formatCurrency(v)} />
                                        <Legend />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </section>

                    {/* 2. Visitor Section */}
                    <section className="print:break-inside-avoid">
                        <SectionHeader icon={Users} title="Visitor Analysis" subtitle="Footfall traffic and player engagement." />
                        <div className="h-64 bg-white border border-slate-100 rounded-xl p-4 mb-6">
                            <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Daily Visitor Traffic</h4>
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={metrics.dailySeries}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                    <XAxis dataKey="date" tickFormatter={d => d.slice(5)} fontSize={10} />
                                    <YAxis fontSize={10} />
                                    <RechartsTooltip />
                                    <Bar dataKey="visitorCount" fill="#f59e0b" name="Visitors" radius={[4, 4, 0, 0]} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>
                    </section>

                    {/* 3. Open Play Operations */}
                    <section className="print:break-inside-avoid">
                        <SectionHeader icon={Gamepad2} title="Open Play Operations" subtitle="Deep dive into player activity, revenue, and efficiency." />

                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                            {/* Col 1: Revenue & Mix */}
                            <div className="bg-white border border-slate-100 rounded-xl p-6 lg:col-span-1">
                                <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Financials</h4>
                                <div className="mb-6">
                                    <p className="text-sm text-slate-500 mb-1">Total Open Play Revenue</p>
                                    <p className="text-3xl font-extrabold text-indigo-600">{formatCurrency(metrics.openPlayIncome)}</p>
                                </div>
                                <div className="h-40">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <PieChart>
                                            <Pie
                                                data={metrics.opPaymentData}
                                                innerRadius={40}
                                                outerRadius={60}
                                                paddingAngle={2}
                                                dataKey="value"
                                            >
                                                {metrics.opPaymentData.map((entry, index) => (
                                                    <Cell key={`cell-${index}`} fill={PIE_COLORS[entry.name.toLowerCase()] || '#cbd5e1'} />
                                                ))}
                                            </Pie>
                                            <RechartsTooltip />
                                            <Legend verticalAlign="middle" align="right" layout="vertical" iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                                        </PieChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>

                            {/* Col 2: Match Stats (Center) */}
                            <div className="lg:col-span-2 space-y-4">
                                <h4 className="text-xs font-bold text-slate-500 uppercase">Match Summary</h4>
                                <div className="grid grid-cols-3 gap-4">
                                    <StatBadge label="Avg Match" value={`${metrics.avgMatchDuration.toFixed(0)} min`} />
                                    <StatBadge label="Shortest" value={`${metrics.shortestMatch.toFixed(0)} min`} />
                                    <StatBadge label="Longest" value={`${metrics.longestMatch.toFixed(0)} min`} />
                                </div>

                                <h4 className="text-xs font-bold text-slate-500 uppercase mt-2">Player Experience</h4>
                                <div className="grid grid-cols-2 gap-4">
                                    <StatBadge label="Avg Wait" value={`${metrics.avgWaitMin.toFixed(1)} min`} />
                                    <StatBadge label="Avg Games / Player" value={metrics.realAvgGames.toFixed(1)} />
                                </div>
                            </div>
                        </div>

                        {/* Top Performers Grid */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                            <div className="bg-slate-50 rounded-xl border border-slate-100 p-5 flex items-center justify-between">
                                <div>
                                    <p className="text-xs font-bold text-slate-500 uppercase">Highest Games Played</p>
                                    {metrics.highestGamesPlayer ? (
                                        <div className="mt-2">
                                            <p className="text-xl font-bold text-slate-900">{metrics.highestGamesPlayer.total} Matches</p>
                                            <p className="text-sm text-slate-600">Player ID: {metrics.highestGamesPlayer.id}</p>
                                        </div>
                                    ) : <p className="text-slate-400 text-sm mt-2">No data</p>}
                                </div>
                                <Trophy className="w-8 h-8 text-amber-500 opacity-80" />
                            </div>

                            <div className="bg-slate-50 rounded-xl border border-slate-100 p-5 flex items-center justify-between">
                                <div>
                                    <p className="text-xs font-bold text-slate-500 uppercase">Top Winner (Win Rate)</p>
                                    {metrics.topWinRatePlayer ? (
                                        <div className="mt-2">
                                            <p className="text-xl font-bold text-slate-900">{Math.round((metrics.topWinRatePlayer.wins / metrics.topWinRatePlayer.total) * 100)}% Win Rate</p>
                                            <p className="text-sm text-slate-600">
                                                {metrics.topWinRatePlayer.wins} Wins / {metrics.topWinRatePlayer.total} Games
                                            </p>
                                        </div>
                                    ) : <p className="text-slate-400 text-sm mt-2">No qualified players (min 3 games)</p>}
                                </div>
                                <Activity className="w-8 h-8 text-emerald-500 opacity-80" />
                            </div>
                        </div>

                        {/* Leaderboard List */}
                        <div className="bg-white rounded-xl border border-slate-100 p-6">
                            <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Most Active Players Leaderboard</h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-2">
                                {metrics.topPlayers.length > 0 ? metrics.topPlayers.map((p, i) => (
                                    <div key={p.id} className="flex justify-between items-center text-sm py-2 border-b border-slate-50 last:border-0 hover:bg-slate-50 rounded px-2">
                                        <div className="flex items-center gap-3">
                                            <span className="font-bold text-indigo-100 bg-indigo-600 w-6 h-6 flex items-center justify-center rounded-full text-xs">{i + 1}</span>
                                            <span className="font-bold text-slate-700">{p.name || 'Unknown Player'}</span>
                                        </div>
                                        <div className="text-right">
                                            <span className="font-bold text-slate-900">{p.visits} Matches</span>
                                        </div>
                                    </div>
                                )) : <p className="text-slate-400 text-sm">No player activity recorded.</p>}
                            </div>
                        </div>
                    </section>

                    {/* 4. Rental Section */}
                    <section className="print:break-inside-avoid">
                        <SectionHeader icon={Activity} title="Rental Operations" subtitle="Court utilization and revenue." />

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6">
                            {/* Court Usage Chart */}
                            <div className="h-64 bg-white border border-slate-100 rounded-xl p-4">
                                <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Hours Booked by Court</h4>
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={metrics.courtData} layout="vertical">
                                        <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                                        <XAxis type="number" fontSize={10} />
                                        <YAxis dataKey="name" type="category" width={60} fontSize={10} />
                                        <RechartsTooltip />
                                        <Bar dataKey="hours" fill="#4f46e5" name="Hours Booked" radius={[0, 4, 4, 0]} barSize={20} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>

                            {/* Rental Stats Summary */}
                            <div className="bg-slate-50 rounded-xl border border-slate-100 p-6">
                                <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 mb-6">Performance Metrics</h4>
                                <div className="space-y-6">
                                    <div className="flex justify-between items-center border-b border-slate-200 pb-3">
                                        <span className="text-slate-600 text-sm">Total Rental Revenue</span>
                                        <span className="text-lg font-bold text-slate-900">{formatCurrency(metrics.rentalIncome)}</span>
                                    </div>
                                    <div className="flex justify-between items-center border-b border-slate-200 pb-3">
                                        <span className="text-slate-600 text-sm">Total Hours Booked</span>
                                        <span className="text-lg font-bold text-slate-900">{metrics.totalRentalHours.toFixed(1)} hrs</span>
                                    </div>
                                    <div className="flex justify-between items-center border-b border-slate-200 pb-3">
                                        <span className="text-slate-600 text-sm">Avg. Daily Usage</span>
                                        <span className="text-lg font-bold text-slate-900">{metrics.averageDailyHours.toFixed(1)} hrs/day</span>
                                    </div>
                                </div>
                                <div className="mt-6">
                                    <h5 className="text-xs font-bold text-slate-500 uppercase mb-3">Revenue By Court</h5>
                                    {metrics.courtData.map(c => (
                                        <div key={c.name} className="flex justify-between items-center text-sm py-1">
                                            <span className="text-slate-600">{c.name}</span>
                                            <span className="font-medium text-slate-900">{formatCurrency(c.revenue)}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </section>

                    {/* Footer */}
                    <div className="pt-8 border-t border-slate-200 text-center">
                        <p className="text-slate-400 text-xs">Generated by Dink Manager • {new Date().toLocaleString()}</p>
                    </div>
                </div>
            </div>
        </div>
    );
}
