import React from "react";

const RANK_STYLES = {
  1: "bg-pickle-gold text-pickle-brown",
  2: "bg-slate-200 text-slate-700",
  3: "bg-amber-700/20 text-amber-900",
};

export default function SessionLeaderboard({ leaderboard = [], hasSession = false }) {
  if (!hasSession) {
    return (
      <div className="flex items-center justify-center text-lg text-pickle-green/40 font-oswald uppercase tracking-widest border-2 border-dashed border-pickle-green/20 rounded-2xl p-5 text-center">
        No active session
      </div>
    );
  }

  if (leaderboard.length === 0) {
    return (
      <div className="flex items-center justify-center text-base text-pickle-brown/50 font-oswald uppercase tracking-wide border-2 border-dashed border-pickle-brown/15 rounded-2xl p-5 text-center leading-snug">
        Play 2+ matches to rank
      </div>
    );
  }

  return (
    <ul className="flex flex-col gap-2">
      {leaderboard.map((entry) => (
        <li
          key={entry.id}
          className="flex items-center gap-3 bg-pickle-cream rounded-xl px-3 py-2.5 shadow-md border-2 border-white"
        >
          <span
            className={`flex-shrink-0 w-9 h-9 rounded-full flex items-center justify-center font-oswald font-bold text-lg ${RANK_STYLES[entry.rank] || "bg-slate-100 text-slate-600"}`}
          >
            {entry.rank}
          </span>
          <div className="flex-1 min-w-0">
            <p className="font-oswald text-xl text-pickle-brown font-bold uppercase truncate leading-tight">
              {entry.name}
            </p>
            <p className="font-oswald text-base text-pickle-brown/60 font-bold">
              {Math.round(entry.winRate)}% ({entry.wins}/{entry.total})
            </p>
          </div>
        </li>
      ))}
    </ul>
  );
}
