import React from "react";
import { Trash2 } from "lucide-react";
import PhaseBadge from "./PhaseBadge";

const FORMAT_LABELS = {
  single_elimination: "Single Elim",
  double_elimination: "Double Elim",
  round_robin_only: "Round Robin",
};

function formatDate(d) {
  if (!d) return "—";
  const date = new Date(d + "T00:00:00");
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function TournamentCard({ tournament, partnerCount, matchCount, completedCount, onClick, onDelete }) {
  return (
    <div
      className="bg-white border border-slate-200 rounded-2xl shadow-sm hover:shadow-md transition-shadow cursor-pointer flex flex-col"
      onClick={onClick}
    >
      <div className="p-4 flex-1">
        <div className="flex items-start justify-between gap-2 mb-3">
          <h3 className="font-semibold text-pickle-green text-lg leading-tight line-clamp-2">
            {tournament.name}
          </h3>
          <button
            onClick={(e) => { e.stopPropagation(); onDelete(); }}
            className="shrink-0 p-1.5 rounded-lg text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors"
            title="Delete tournament"
          >
            <Trash2 size={14} />
          </button>
        </div>

        <div className="flex items-center gap-2 flex-wrap mb-3">
          <PhaseBadge phase={tournament.phase} />
          <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-600">
            {FORMAT_LABELS[tournament.format] || tournament.format}
          </span>
        </div>

        {(tournament.start_date || tournament.end_date) && (
          <p className="text-xs text-slate-500 mb-3">
            {formatDate(tournament.start_date)} — {formatDate(tournament.end_date)}
          </p>
        )}

        <div className="grid grid-cols-3 gap-2 text-center">
          <div className="bg-slate-50 rounded-lg py-2">
            <div className="text-lg font-bold text-pickle-green">{partnerCount ?? 0}</div>
            <div className="text-xs text-slate-500">Partners</div>
          </div>
          <div className="bg-slate-50 rounded-lg py-2">
            <div className="text-lg font-bold text-pickle-green">{matchCount ?? 0}</div>
            <div className="text-xs text-slate-500">Matches</div>
          </div>
          <div className="bg-slate-50 rounded-lg py-2">
            <div className="text-lg font-bold text-pickle-green">{completedCount ?? 0}</div>
            <div className="text-xs text-slate-500">Done</div>
          </div>
        </div>
      </div>
    </div>
  );
}
