import React, { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { ChevronLeft } from "lucide-react";
import { useTournamentState } from "./providers/TournamentStateProvider";
import PhaseBadge from "./components/PhaseBadge";

// Tab components — imported lazily as they're built out
import OverviewTab from "./components/OverviewTab";
import PartnersTab from "./components/PartnersTab";
import DivisionsGroupsTab from "./components/DivisionsGroupsTab";
import BracketingTab from "./components/BracketingTab";
import ScheduleTab from "./components/ScheduleTab";
import StandingsTab from "./components/StandingsTab";
import SettingsTab from "./components/SettingsTab";
import CourtsTab from "./components/CourtsTab";
import RemoteTab from "./components/RemoteTab";

const TABS = [
  { key: "overview", label: "Overview" },
  { key: "partners", label: "Partners" },
  { key: "divisions", label: "Divisions & Groups" },
  { key: "bracketing", label: "Bracketing" },
  { key: "schedule", label: "Schedule" },
  { key: "courts", label: "Courts" },
  { key: "standings", label: "Standings" },
  { key: "remote", label: "Remote" },
  { key: "settings", label: "Settings" },
];

export default function TournamentDetailPage() {
  const { tournamentId } = useParams();
  const navigate = useNavigate();
  const { tournaments } = useTournamentState();
  const [activeTab, setActiveTab] = useState("overview");

  const tournament = tournaments[tournamentId];

  if (!tournament) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center gap-4 text-center p-6">
        <p className="text-slate-500">Tournament not found.</p>
        <button
          onClick={() => navigate("/tournament")}
          className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90"
        >
          Back to Tournaments
        </button>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {/* Page header */}
      <div className="shrink-0 px-4 md:px-6 py-3 border-b border-pickle-green/10 bg-white flex items-center gap-3 flex-wrap">
        <button
          onClick={() => navigate("/tournament")}
          className="flex items-center gap-1 text-sm text-slate-400 hover:text-pickle-green transition-colors"
        >
          <ChevronLeft size={16} />
          Tournaments
        </button>
        <span className="text-slate-200">/</span>
        <h1 className="font-display text-xl md:text-2xl text-pickle-green">{tournament.name}</h1>
        <PhaseBadge phase={tournament.phase} />
      </div>

      {/* Tab bar */}
      <div className="shrink-0 border-b border-pickle-green/10 bg-white overflow-x-auto">
        <div className="flex px-4 md:px-6 min-w-max">
          {TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`px-4 py-3.5 text-sm font-semibold border-b-2 transition-colors whitespace-nowrap ${
                activeTab === tab.key
                  ? "border-pickle-green text-pickle-green"
                  : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Tab content */}
      <div className="flex-1 overflow-y-auto">
        {activeTab === "overview" && <OverviewTab tournament={tournament} />}
        {activeTab === "partners" && <PartnersTab tournament={tournament} />}
        {activeTab === "divisions" && <DivisionsGroupsTab tournament={tournament} />}
        {activeTab === "bracketing" && <BracketingTab tournament={tournament} />}
        {activeTab === "schedule" && <ScheduleTab tournament={tournament} />}
        {activeTab === "courts" && <CourtsTab tournament={tournament} />}
        {activeTab === "standings" && <StandingsTab tournament={tournament} />}
        {activeTab === "remote" && <RemoteTab tournament={tournament} />}
        {activeTab === "settings" && <SettingsTab tournament={tournament} />}
      </div>
    </div>
  );
}
