import React from "react";

const COLUMNS = [
  { key: "rank", label: "#" },
  { key: "name", label: "Player" },
  { key: "matches", label: "Matches" },
  { key: "winRate", label: "Win Rate" },
  { key: "wins", label: "Win" },
  { key: "losses", label: "Lose" },
  { key: "points", label: "PD" },
  { key: "level", label: "Level" },
];

const formatPoints = (value) => {
  const n = Number(value) || 0;
  if (n > 0) return `+${n}`;
  return String(n);
};

export default function PlayerLeaderboardTable({
  rows = [],
  variant = "admin",
  emptyLabel = "No players yet.",
}) {
  const isDisplay = variant === "display";
  const tableClass = isDisplay
    ? "w-full text-left border-collapse"
    : "w-full text-left text-sm";
  const headClass = isDisplay
    ? "text-[11px] uppercase tracking-[0.18em] text-white/45 font-oswald font-bold"
    : "text-[11px] uppercase tracking-wider text-slate-500 font-semibold";
  const rowClass = (idx) =>
    isDisplay
      ? idx === 0
        ? "bg-white/[0.07] text-white"
        : "text-white/90"
      : idx % 2 === 0
        ? "bg-white"
        : "bg-slate-50/80";

  if (!rows.length) {
    return (
      <p className={isDisplay ? "text-center text-white/40 py-16 text-sm uppercase tracking-widest" : "text-sm text-slate-500 py-10 text-center"}>
        {emptyLabel}
      </p>
    );
  }

  return (
    <div className="h-full overflow-auto custom-scrollbar">
      <table className={tableClass}>
        <thead>
          <tr className={isDisplay ? "border-b border-white/10" : "border-b border-slate-200"}>
            {COLUMNS.map((col) => (
              <th
                key={col.key}
                className={`${headClass} py-3 ${col.key === "name" ? "px-3 text-left" : "px-2 text-center"} ${col.key === "rank" ? "w-12" : ""}`}
              >
                {col.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => (
            <tr key={row.id} className={`${rowClass(idx)} ${isDisplay ? "border-b border-white/5" : "border-b border-slate-100"}`}>
              <td className={`py-2.5 px-2 text-center font-oswald font-bold ${isDisplay ? "text-pickle-gold text-lg" : "text-slate-400"}`}>
                {idx + 1}
              </td>
              <td className={`py-2.5 px-3 font-semibold ${isDisplay ? "text-xl md:text-2xl tracking-wide" : "text-slate-900"}`}>
                {row.name}
              </td>
              <td className={`py-2.5 px-2 text-center tabular-nums ${isDisplay ? "text-lg" : ""}`}>{row.matches}</td>
              <td className={`py-2.5 px-2 text-center tabular-nums font-bold ${isDisplay ? "text-lg text-pickle-gold" : "text-pickle-green"}`}>
                {row.winRate}%
              </td>
              <td className={`py-2.5 px-2 text-center tabular-nums ${isDisplay ? "text-lg" : ""}`}>{row.wins}</td>
              <td className={`py-2.5 px-2 text-center tabular-nums ${isDisplay ? "text-lg" : ""}`}>{row.losses}</td>
              <td className={`py-2.5 px-2 text-center tabular-nums font-semibold ${isDisplay ? "text-lg" : ""}`}>
                {formatPoints(row.points)}
              </td>
              <td className={`py-2.5 px-2 text-center ${isDisplay ? "text-sm uppercase tracking-widest text-white/70" : "text-slate-600"}`}>
                {row.level || "—"}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
