import React, { useCallback, useEffect, useMemo, useState } from "react";
import { CourtList, MatchQueue, PlayersModal } from "../queue";
import { loadState, decodeRawState } from "../../state/storage";
import config from "../../config";
import PlayerLeaderboardOverlay from "../leaderboard/components/PlayerLeaderboardOverlay";
import PlayerLeaderboardTop5Overlay from "../leaderboard/components/PlayerLeaderboardTop5Overlay";
import {
	buildPlayerLeaderboard,
	clearLeaderboardDisplay,
	LEADERBOARD_DISPLAY_EVENT,
	LEADERBOARD_DISPLAY_MODE,
	LEADERBOARD_DISPLAY_STORAGE_KEY,
	readLeaderboardDisplay,
	sliceLeaderboardTop,
} from "../leaderboard/utils/playerLeaderboard";
import SessionLeaderboard from "./components/SessionLeaderboard";
import { computeSessionLeaderboard } from "./utils/sessionLeaderboard";

export default function DisplayPage() {
	const [courts, setCourts] = useState([]);
	const [players, setPlayers] = useState([]);
	const [matchQueue, setMatchQueue] = useState([]);
	const [matches, setMatches] = useState([]);
	const [currentOpSession, setCurrentOpSession] = useState(null);
	const [openCourtId, setOpenCourtId] = useState(null);
	const [leaderboardUntil, setLeaderboardUntil] = useState(0);
	const [leaderboardMode, setLeaderboardMode] = useState(LEADERBOARD_DISPLAY_MODE.FULL);
	const hideLeaderboard = useCallback(() => {
		clearLeaderboardDisplay();
		setLeaderboardUntil(0);
	}, []);
	const closeDisplayModal = useCallback(() => {
		if (openCourtId && typeof window !== "undefined" && "BroadcastChannel" in window) {
			const bc = new BroadcastChannel("dink_manager");
			bc.postMessage({ type: "CLOSE_MODAL", courtId: openCourtId });
			bc.close();
		}
		setOpenCourtId(null);
	}, [openCourtId]);

	// Auto-close modal after 20 seconds
	useEffect(() => {
		if (!openCourtId) return;
		const timer = setTimeout(() => {
			closeDisplayModal();
		}, 60000);
		return () => clearTimeout(timer);
	}, [openCourtId, closeDisplayModal]);

	useEffect(() => {
		const saved = loadState();
		setCourts(saved?.courts || config.getDefaultCourts());
		setPlayers(saved?.players || []);
		setMatchQueue(saved?.matchQueue || []);
		setMatches(saved?.matches || []);
		setCurrentOpSession(saved?.currentOpSession || null);
		const savedDisplay = readLeaderboardDisplay();
		if (savedDisplay.until > Date.now()) {
			setLeaderboardUntil(savedDisplay.until);
			setLeaderboardMode(savedDisplay.mode);
		}
	}, []);

	useEffect(() => {
		const prevZoom = document.body.style.zoom;
		// document.body.style.zoom = "120%"; // Removed zoom for better responsiveness handle
		// document.body.style.overflowX = "hidden";
		return () => {
			document.body.style.zoom = prevZoom || "100%";
			document.body.style.overflowX = "auto";
		};
	}, []);

	useEffect(() => {
		const onStorage = (e) => {
			if (e.key === LEADERBOARD_DISPLAY_STORAGE_KEY) {
				const next = readLeaderboardDisplay();
				setLeaderboardUntil(next.until > Date.now() ? next.until : 0);
				setLeaderboardMode(next.mode);
			}
			if (e.key === "picklestudioAppState" && e.newValue) {
				const next = decodeRawState(e.newValue);
				if (next) {
					setCourts(next.courts || []);
					setPlayers(next.players || []);
					setMatchQueue(next.matchQueue || []);
					setMatches(next.matches || []);
					setCurrentOpSession(next.currentOpSession || null);
				}
			}
		};
		window.addEventListener("storage", onStorage);

		let bc;
		if ("BroadcastChannel" in window) {
			bc = new BroadcastChannel("dink_manager");
			bc.onmessage = (msg) => {
				const { type, courtId, payload } = msg?.data || {};
				if (type === LEADERBOARD_DISPLAY_EVENT) {
					const until = Number(msg?.data?.until);
					setLeaderboardUntil(Number.isFinite(until) && until > Date.now() ? until : 0);
					setLeaderboardMode(msg?.data?.mode === LEADERBOARD_DISPLAY_MODE.TOP5
						? LEADERBOARD_DISPLAY_MODE.TOP5 : LEADERBOARD_DISPLAY_MODE.FULL);
				}
				if (type === "OPEN_MODAL") setOpenCourtId(courtId || null);
				if (type === "CLOSE_MODAL") setOpenCourtId(null);
				if (type === "STATE_UPDATE" && payload) {
					setCourts(payload.courts || []);
					setPlayers(payload.players || []);
					setMatchQueue(payload.matchQueue || []);
					setMatches(payload.matches || []);
					setCurrentOpSession(payload.currentOpSession || null);
				}
			};
		}

		return () => {
			window.removeEventListener("storage", onStorage);
			if (bc) bc.close();
		};
	}, []);

	const selectedCourt = courts.find((c) => c.id === openCourtId) || null;
	const selectedPlayers = selectedCourt
		? players
			.filter((p) => selectedCourt.players.includes(p.id))
			.map((p) => ({
				...p,
				team: selectedCourt.teamGreen?.includes(p.id)
					? "green"
					: selectedCourt.teamBlue?.includes(p.id)
						? "blue"
						: null,
			}))
		: [];

	const leaderboard = useMemo(
		() => computeSessionLeaderboard(matches, players, currentOpSession?.startedAt ?? 0, 3),
		[matches, players, currentOpSession?.startedAt]
	);

	const leaderboardRows = useMemo(() => buildPlayerLeaderboard(players, matches), [players, matches]);

	return (
		<div className="min-h-screen bg-pickle-dgreen p-4 overflow-hidden flex flex-col">
			{/* Header */}
			<header className="flex items-center gap-6 mb-6 px-4">
				<img src={config.assetPath("logo.jpg")} alt="Pickle Studio" className="w-24 h-24 object-contain rounded-full shadow-md border-2 border-white" />
				<div className="flex flex-col leading-tight justify-center">
					<span className="text-6xl text-white font-display drop-shadow-sm">
						Pickle <span className="font-body font-bold text-3xl tracking-widest uppercase text-pickle-cream ml-2">Studio</span>
					</span>
				</div>
			</header>

			<div className="flex-1 grid grid-cols-12 gap-8 min-h-0">
				{/* 1) Match Queue Column (Left ~25%) */}
				<div className="col-span-3 flex flex-col bg-white rounded-[2rem] overflow-hidden border-4 border-white shadow-2xl min-h-0 p-3 gap-4">
					<div className="text-center shrink-0 pt-1">
						<h2 className="text-3xl font-oswald font-bold text-pickle-dgreen uppercase tracking-tight">Match Queue</h2>
					</div>

					{/* Top: next up match — grows to fill available space */}
					<div className="flex-1 min-h-0 flex flex-col rounded-2xl border border-pickle-green/15 bg-slate-50/80 p-3">
						<h3 className="text-sm font-anton text-pickle-brown uppercase tracking-widest text-center mb-2 shrink-0">Queued Match</h3>
						<div className="flex-1 min-h-0 custom-scrollbar">
							<MatchQueue
								courts={courts}
								players={players}
								queue={matchQueue || []}
								readOnly
								onAddQueue={() => { }}
								onRemoveQueue={() => { }}
								onRemoveFromQueue={() => { }}
								onSendQueueToCourt={() => { }}
								onAutoBuild={() => { }}
								variant="display"
							/>
						</div>
					</div>

					{/* Bottom: session leaderboard — content height only */}
					<div className="shrink-0 flex flex-col rounded-2xl border border-pickle-brown/15 bg-slate-50/80 p-3">
						<h3 className="text-sm font-anton text-pickle-brown uppercase tracking-widest text-center mb-2 shrink-0">Session Leaderboard</h3>
						<div className="custom-scrollbar">
							<SessionLeaderboard
								leaderboard={leaderboard}
								hasSession={!!currentOpSession}
							/>
						</div>
					</div>
				</div>

				{/* 2) Live Courts Grid (Right ~75%) */}
				<div className="col-span-9 flex flex-col h-full pl-4">
					<div className="flex items-center gap-4 mb-4">
						<h2 className="text-6xl font-prata text-pickle-cream drop-shadow-md tracking-wide">LIVE COURTS</h2>
						<span className="text-5xl drop-shadow-sm filter invert" role="img" aria-label="player">🏓</span>
					</div>
					<div className="flex-1 grid grid-cols-2 grid-rows-2 gap-6">
						<CourtList
							courts={courts}
							players={players}
							onAssign={() => { }}
							onRemove={() => { }}
							onUnlockCourt={() => { }}
							onRemoveCourt={() => { }}
							onUpdateCourtName={() => { }}
							onSetTeams={() => { }}
							onCompleteMatch={() => { }}
							readOnly
							compact
							className="contents" // Use contents to let children fall into the parent grid
							variant="display" // 👈 Isolated Variant
						/>
					</div>
				</div>

				<PlayersModal
					open={openCourtId != null}
					onClose={closeDisplayModal}
					courtName={selectedCourt?.name || ""}
					players={selectedPlayers}
					isReadOnly
					variant="display" // 👈 Isolated Variant
				/>
			</div>
			{leaderboardUntil > Date.now() && leaderboardMode === LEADERBOARD_DISPLAY_MODE.TOP5 && (
				<PlayerLeaderboardTop5Overlay rows={sliceLeaderboardTop(leaderboardRows, 5)} until={leaderboardUntil} onClose={hideLeaderboard} />
			)}
			{leaderboardUntil > Date.now() && leaderboardMode !== LEADERBOARD_DISPLAY_MODE.TOP5 && (
				<PlayerLeaderboardOverlay rows={leaderboardRows} until={leaderboardUntil} onClose={hideLeaderboard} />
			)}
		</div>
	);
}
