import React, { useState, useEffect, useMemo } from "react";
import DisplayTournamentInfo from "./DisplayTournamentInfo";
import DisplayCurrentMatch from "./DisplayCurrentMatch";
import DisplayLiveCourts from "./DisplayLiveCourts";
import DisplayStandings from "./DisplayStandings";
import DisplayUpcoming from "./DisplayUpcoming";
import DisplayResults from "./DisplayResults";
import DisplaySponsorSlideshow from "./DisplaySponsorSlideshow";

const SLIDE_VIEWS = [
  "tournament_info",
  "current_match",
  "live_courts",
  "standings",
  "upcoming",
  "results",
];

export default function DisplaySlideshow({
  tournament, divisions, groups, partners, matches,
  onSlideChange,
}) {
  const interval = (tournament?.display_settings?.slideshow_interval || 15) * 1000;
  const sponsors = (tournament?.sponsors || []).filter((s) => s.enabled);

  // Build the cycle: interleave sponsor slide after every 3 match views if sponsors exist
  const cycle = useMemo(() => {
    const views = [];
    SLIDE_VIEWS.forEach((v, i) => {
      views.push({ type: "view", key: v });
      if (sponsors.length > 0 && (i + 1) % 3 === 0) {
        views.push({ type: "sponsor" });
      }
    });
    return views;
  }, [sponsors.length]);

  const [slideIdx, setSlideIdx] = useState(0);

  useEffect(() => {
    const t = setInterval(() => {
      setSlideIdx((i) => {
        const next = (i + 1) % cycle.length;
        return next;
      });
    }, interval);
    return () => clearInterval(t);
  }, [cycle.length, interval]);

  useEffect(() => {
    if (onSlideChange) onSlideChange(slideIdx, cycle.length);
  }, [slideIdx, cycle.length, onSlideChange]);

  const current = cycle[slideIdx % cycle.length] || cycle[0];

  const sharedProps = { tournament, divisions, groups, partners, matches };

  if (current.type === "sponsor") {
    return <DisplaySponsorSlideshow tournament={tournament} />;
  }

  switch (current.key) {
    case "tournament_info": return <DisplayTournamentInfo {...sharedProps} />;
    case "current_match": return <DisplayCurrentMatch {...sharedProps} />;
    case "live_courts": return <DisplayLiveCourts {...sharedProps} />;
    case "standings": return <DisplayStandings {...sharedProps} />;
    case "upcoming": return <DisplayUpcoming {...sharedProps} />;
    case "results": return <DisplayResults {...sharedProps} />;
    default: return <DisplayTournamentInfo {...sharedProps} />;
  }
}
