import React, { useState, useEffect } from "react";
import { ChevronDown, ChevronUp } from "lucide-react";

const defaults = {
  team_name: "",
  player_1_name: "",
  player_2_name: "",
  division_id: "",
  group_id: "",
  seed: "",
  // Extended player details
  player_1_dob: "",
  player_2_dob: "",
  player_1_gender: "",
  player_2_gender: "",
  player_1_phone: "",
  player_2_phone: "",
  player_1_rating: "",
  player_2_rating: "",
};

const GENDER_OPTIONS = ["", "Male", "Female", "Non-binary"];

/** Compute age from YYYY-MM-DD string. Returns null if invalid. */
function computeAge(dob) {
  if (!dob) return null;
  const birth = new Date(dob + "T00:00:00");
  if (isNaN(birth)) return null;
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const m = today.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
  return age;
}

export default function PartnerFormModal({ partner, divisions, groupsByDivision, onSave, onClose }) {
  const [form, setForm] = useState({
    ...defaults,
    ...(partner || {}),
    seed: partner?.seed ?? "",
    group_id: partner?.group_id ?? "",
  });
  const [detailsOpen, setDetailsOpen] = useState(false);

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const set = (key, val) => setForm((prev) => ({ ...prev, [key]: val }));

  const availableGroups = form.division_id ? (groupsByDivision[form.division_id] || []) : [];

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.team_name.trim() || !form.player_1_name.trim() || !form.player_2_name.trim() || !form.division_id) return;
    onSave({
      ...form,
      group_id: form.group_id || null,
      seed: form.seed !== "" ? Number(form.seed) : null,
      player_1_dob: form.player_1_dob || null,
      player_2_dob: form.player_2_dob || null,
      player_1_gender: form.player_1_gender || null,
      player_2_gender: form.player_2_gender || null,
      player_1_phone: form.player_1_phone || null,
      player_2_phone: form.player_2_phone || null,
      player_1_rating: form.player_1_rating !== "" ? Number(form.player_1_rating) : null,
      player_2_rating: form.player_2_rating !== "" ? Number(form.player_2_rating) : null,
    });
  };

  const age1 = computeAge(form.player_1_dob);
  const age2 = computeAge(form.player_2_dob);

  const inputCls = "w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30";

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <form
        onSubmit={handleSubmit}
        className="relative bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col max-h-[90vh] overflow-y-auto"
      >
        <div className="p-6 border-b border-slate-100">
          <h2 className="text-xl font-bold text-slate-900">
            {partner ? "Edit Partner" : "Add Partner Pair"}
          </h2>
        </div>

        <div className="p-6 flex flex-col gap-4">
          {/* Team Name */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-1">Team Name *</label>
            <input
              className={inputCls}
              value={form.team_name}
              onChange={(e) => set("team_name", e.target.value)}
              placeholder="e.g. The Dinkers"
              required
            />
          </div>

          {/* Player names */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Player 1 *</label>
              <input
                className={inputCls}
                value={form.player_1_name}
                onChange={(e) => set("player_1_name", e.target.value)}
                placeholder="Full name"
                required
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Player 2 *</label>
              <input
                className={inputCls}
                value={form.player_2_name}
                onChange={(e) => set("player_2_name", e.target.value)}
                placeholder="Full name"
                required
              />
            </div>
          </div>

          {/* Division */}
          <div>
            <label className="block text-xs font-semibold text-slate-600 mb-1">Division *</label>
            <select
              className={inputCls}
              value={form.division_id}
              onChange={(e) => { set("division_id", e.target.value); set("group_id", ""); }}
              required
            >
              <option value="">Select a division…</option>
              {divisions.map((d) => (
                <option key={d.id} value={d.id}>{d.name}</option>
              ))}
            </select>
          </div>

          {/* Group + Seed */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Group</label>
              <select
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.group_id}
                onChange={(e) => set("group_id", e.target.value)}
                disabled={!form.division_id || availableGroups.length === 0}
              >
                <option value="">Unassigned</option>
                {availableGroups.map((g) => (
                  <option key={g.id} value={g.id}>{g.name}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1">Seed (optional)</label>
              <input
                type="number"
                min="1"
                className={inputCls}
                value={form.seed}
                onChange={(e) => set("seed", e.target.value)}
                placeholder="e.g. 1"
              />
            </div>
          </div>

          {/* ── Collapsible Player Details ── */}
          <div className="border border-slate-200 rounded-xl overflow-hidden">
            <button
              type="button"
              onClick={() => setDetailsOpen((v) => !v)}
              className="w-full flex items-center justify-between px-4 py-3 bg-slate-50 hover:bg-slate-100 transition-colors text-xs font-semibold text-slate-600"
            >
              <span>Player Details (age, gender, contact, rating)</span>
              {detailsOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </button>

            {detailsOpen && (
              <div className="p-4 grid grid-cols-2 gap-x-4 gap-y-3">
                {/* DOB */}
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">
                    P1 Date of Birth {age1 != null && <span className="text-pickle-green font-bold ml-1">Age {age1}</span>}
                  </label>
                  <input
                    type="date"
                    className={inputCls}
                    value={form.player_1_dob || ""}
                    onChange={(e) => set("player_1_dob", e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">
                    P2 Date of Birth {age2 != null && <span className="text-pickle-green font-bold ml-1">Age {age2}</span>}
                  </label>
                  <input
                    type="date"
                    className={inputCls}
                    value={form.player_2_dob || ""}
                    onChange={(e) => set("player_2_dob", e.target.value)}
                  />
                </div>

                {/* Gender */}
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P1 Gender</label>
                  <select className={inputCls} value={form.player_1_gender || ""} onChange={(e) => set("player_1_gender", e.target.value)}>
                    {GENDER_OPTIONS.map((g) => <option key={g} value={g}>{g || "Not specified"}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P2 Gender</label>
                  <select className={inputCls} value={form.player_2_gender || ""} onChange={(e) => set("player_2_gender", e.target.value)}>
                    {GENDER_OPTIONS.map((g) => <option key={g} value={g}>{g || "Not specified"}</option>)}
                  </select>
                </div>

                {/* Phone */}
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P1 Phone</label>
                  <input
                    type="tel"
                    className={inputCls}
                    value={form.player_1_phone || ""}
                    onChange={(e) => set("player_1_phone", e.target.value)}
                    placeholder="+1 555-0100"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P2 Phone</label>
                  <input
                    type="tel"
                    className={inputCls}
                    value={form.player_2_phone || ""}
                    onChange={(e) => set("player_2_phone", e.target.value)}
                    placeholder="+1 555-0101"
                  />
                </div>

                {/* Rating */}
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P1 Rating (DUPR)</label>
                  <input
                    type="number"
                    min="0"
                    max="8"
                    step="0.01"
                    className={inputCls}
                    value={form.player_1_rating || ""}
                    onChange={(e) => set("player_1_rating", e.target.value)}
                    placeholder="e.g. 4.25"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-semibold text-slate-500 mb-1 uppercase tracking-wide">P2 Rating (DUPR)</label>
                  <input
                    type="number"
                    min="0"
                    max="8"
                    step="0.01"
                    className={inputCls}
                    value={form.player_2_rating || ""}
                    onChange={(e) => set("player_2_rating", e.target.value)}
                    placeholder="e.g. 3.80"
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button type="button" onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">
            Cancel
          </button>
          <button type="submit" className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm">
            {partner ? "Save Changes" : "Add Partner"}
          </button>
        </div>
      </form>
    </div>
  );
}
