import React, { useEffect, useState } from 'react';
import { X, ArrowLeft } from 'lucide-react';
import { useAppState } from '../../../app/providers';
import config from '../../../config';

const DEFAULT_QR_FILENAME = 'payment-qr.png';

// ─── Pure display helpers ─────────────────────────────────────────────────────

function Brand() {
    return (
        <div className="flex justify-center mb-3">
            <div className="flex flex-col items-center leading-none">
                <span className="text-2xl sm:text-3xl text-[#3A4D39]" style={{ fontFamily: 'Lobster, cursive' }}>
                    Pickle{' '}
                    <span className="font-bold text-sm sm:text-base tracking-widest uppercase text-[#A18F53] ml-1" style={{ fontFamily: 'Outfit, sans-serif' }}>
                        Studio
                    </span>
                </span>
                <span className="text-[8px] text-[#3A4D39]/60 uppercase tracking-[0.25em] font-medium mt-0.5" style={{ fontFamily: 'Outfit, sans-serif' }}>
                    Premium Court Experience
                </span>
            </div>
        </div>
    );
}

function FinancialBlock({ discountPct, subtotal, total, discountAmount, paid, balance, compact = false }) {
    return (
        <div className={`bg-slate-50 rounded-lg px-3 ${compact ? 'py-1.5 space-y-0.5' : 'py-2.5 space-y-1'} print:bg-transparent print:p-0 print:border-t-2 print:border-slate-900 print:rounded-none`}>
            {discountPct > 0 && (
                <>
                    <div className="flex justify-between items-center">
                        <span className="text-xs text-slate-500">Subtotal</span>
                        <span className="text-xs text-slate-600">₱{(subtotal ?? total + discountAmount).toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-xs text-emerald-600 font-medium">Discount ({discountPct}%)</span>
                        <span className="text-xs font-semibold text-emerald-600">-₱{discountAmount.toLocaleString()}</span>
                    </div>
                </>
            )}
            <div className={`flex justify-between items-center ${discountPct > 0 ? 'border-t border-slate-200 pt-1' : ''}`}>
                <span className="text-xs text-slate-600">Amount Paid</span>
                <span className="text-xs font-semibold text-slate-900">₱{paid.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center">
                <span className="text-xs text-slate-600">Total Due</span>
                <span className="text-xs font-semibold text-slate-900">₱{total.toLocaleString()}</span>
            </div>
            <div className={`flex justify-between items-center border-t border-slate-200 ${compact ? 'pt-1' : 'pt-1.5 mt-0.5'} print:border-slate-900`}>
                <span className={`${compact ? 'text-xs' : 'text-sm'} font-bold text-slate-700`}>Current Balance</span>
                <span className={`${compact ? 'text-xs' : 'text-sm'} font-bold ${balance > 0 ? 'text-rose-600' : 'text-emerald-600'} print:text-black`}>
                    ₱{balance.toLocaleString()}
                </span>
            </div>
        </div>
    );
}

function BookingDetails({
    rentalDate, renter, dateCreated, dateFullyPaid, balance,
    startTime, endTime, courtSummary, paymentLabel,
}) {
    return (
        <div className="space-y-2 border-t border-b border-slate-200 py-3 mb-3">
            <div className="grid grid-cols-2 gap-x-2">
                <div>
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Rental Date</p>
                    <p className="text-xs font-semibold text-slate-900">{rentalDate}</p>
                </div>
                <div className="text-right">
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Renter Name</p>
                    <p className="text-xs font-semibold text-slate-900 truncate">{renter?.name || 'N/A'}</p>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-x-2 pt-1.5 border-t border-slate-100">
                <div>
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Date Created</p>
                    <p className="text-[11px] font-medium text-slate-700">{dateCreated}</p>
                </div>
                <div className="text-right">
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Date Fully Paid</p>
                    <p className={`text-[11px] font-medium ${balance <= 0 ? 'text-emerald-600' : 'text-slate-400 italic'}`}>
                        {balance <= 0 ? dateFullyPaid : '—'}
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-x-2 pt-1.5 border-t border-slate-100">
                <div>
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Start Time</p>
                    <p className="text-xs font-semibold text-slate-900">{startTime}</p>
                </div>
                <div className="text-right">
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">End Time</p>
                    <p className="text-xs font-semibold text-slate-900">{endTime}</p>
                </div>
            </div>

            <div className="pt-2 border-t border-slate-100">
                <p className="text-[9px] font-bold text-slate-400 uppercase mb-1.5 text-center">Courts Rented &amp; Hours</p>
                <div className="flex flex-wrap justify-center gap-2">
                    {courtSummary.map(({ courtId, hours }) => (
                        <div key={courtId} className="flex items-center gap-1 bg-slate-100 rounded px-2.5 py-1">
                            <span className="text-[11px] text-slate-600">Court {courtId} :</span>
                            <span className="text-[11px] font-semibold text-slate-900">{hours.toFixed(1)}h</span>
                        </div>
                    ))}
                    {courtSummary.length === 0 && (
                        <p className="text-xs text-slate-400 italic text-center w-full">No slots</p>
                    )}
                </div>
            </div>

            <div className="pt-1.5 border-t border-slate-100">
                <p className="text-[9px] font-bold text-slate-400 uppercase mb-0.5">Payment Method</p>
                <p className="text-xs font-semibold text-slate-900 uppercase">{paymentLabel}</p>
            </div>
        </div>
    );
}

// ─── Main component ───────────────────────────────────────────────────────────

export default function InvoiceModal({
    isOpen,
    onClose,
    booking,
    slots = [],
    subtotal,
    total,
    discountPct = 0,
    discountAmount = 0,
    paid,
    balance,
    renter,
    paymentMethod,
}) {
    const { settings } = useAppState((s) => ({ settings: s.settings }));
    const [showQr, setShowQr] = useState(false);

    useEffect(() => {
        if (!isOpen) return;
        const onKey = (e) => e.key === 'Escape' && onClose();
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [isOpen, onClose]);

    useEffect(() => {
        if (!isOpen) setShowQr(false);
    }, [isOpen]);

    if (!isOpen) return null;

    const paymentName = settings?.invoicePaymentName || 'Von Bryan Yu';
    const paymentMobile = settings?.invoicePaymentMobile || '+63 962 797 5181';
    const qrImageSrc =
        (settings?.invoicePaymentQrUrl || '').trim() ||
        config.assetPath(DEFAULT_QR_FILENAME);

    const formatTime = (minutes) => {
        const h = Math.floor(minutes / 60);
        const m = minutes % 60;
        const ampm = h >= 12 ? 'PM' : 'AM';
        const displayH = h % 12 || 12;
        return `${displayH}:${m.toString().padStart(2, '0')} ${ampm}`;
    };

    const rentalDate = slots.length > 0 ? slots[0].date : new Date().toLocaleDateString('en-CA');
    const sortedSlots = [...slots].sort((a, b) => a.startTime - b.startTime);
    const startTime = sortedSlots.length > 0 ? formatTime(sortedSlots[0].startTime) : 'N/A';
    const endTime = sortedSlots.length > 0 ? formatTime(sortedSlots[sortedSlots.length - 1].endTime) : 'N/A';

    const dateCreated = booking.createdAt
        ? new Date(booking.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
        : 'N/A';

    const dateFullyPaid = (() => {
        if (balance > 0) return 'Unpaid';
        if (!booking.auditLogs || booking.auditLogs.length === 0) return dateCreated;
        const payments = booking.auditLogs
            .filter(l => l.action === 'PAYMENT_ADDED' || l.action === 'PAYMENT_REFUNDED')
            .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
        return payments.length > 0
            ? new Date(payments[0].timestamp).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
            : dateCreated;
    })();

    const courtSummary = Object.entries(
        slots.reduce((acc, slot) => {
            const dur = (slot.endTime - slot.startTime) / 60;
            acc[slot.courtId] = (acc[slot.courtId] || 0) + dur;
            return acc;
        }, {})
    ).map(([courtId, hours]) => ({ courtId, hours }));

    const paymentLabel =
        ['GCASH', 'GCash', 'gcash'].includes(paymentMethod) ? 'GCash' :
        ['GOTYME', 'GoTyme', 'gotyme'].includes(paymentMethod) ? 'GoTyme' : 'Cash';

    const bookingProps = { rentalDate, renter, dateCreated, dateFullyPaid, balance, startTime, endTime, courtSummary, paymentLabel };
    const financialProps = { discountPct, subtotal, total, discountAmount, paid, balance };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 print:p-0 print:bg-white print:static">
            <div
                className="bg-white w-full max-w-lg rounded-xl shadow-2xl flex flex-col print:shadow-none print:w-full print:max-w-none print:rounded-none"
                style={{ maxHeight: '95dvh' }}
            >
                {/* Sticky header */}
                <div className="flex items-center justify-between border-b border-slate-200 px-4 py-2.5 bg-slate-50 print:hidden flex-shrink-0 rounded-t-xl">
                    <h2 className="text-sm font-bold text-slate-900">Invoice Summary</h2>
                    <button onClick={onClose} className="p-1.5 text-slate-400 hover:bg-slate-200 hover:text-slate-600 rounded-full transition-colors">
                        <X className="h-4 w-4" />
                    </button>
                </div>

                {/* Scrollable body */}
                <div className="overflow-y-auto flex-1 print:overflow-visible">
                    <div className="px-4 py-3 print:p-0">

                        <Brand />

                        {/* ── Paid invoice ── */}
                        {balance <= 0 && (
                            <>
                                <BookingDetails {...bookingProps} />
                                <FinancialBlock {...financialProps} />
                                <div className="mt-2.5 text-center text-[11px] font-medium text-emerald-800 bg-emerald-50/50 py-2 rounded-lg border border-emerald-100 print:bg-transparent print:border-none print:text-slate-600 print:font-normal print:italic print:p-0 print:mt-6">
                                    Kindly present this invoice to the reception staff upon check-in.
                                </div>
                            </>
                        )}

                        {/* ── Unpaid invoice — single column (QR hidden) ── */}
                        {balance > 0 && !showQr && (
                            <>
                                <BookingDetails {...bookingProps} />
                                <FinancialBlock {...financialProps} />
                                <div className="mt-2.5 text-center text-[11px] font-medium text-amber-900 bg-amber-50 py-2 rounded-lg border border-amber-100 print:bg-transparent print:border-none print:text-slate-600 print:font-normal print:p-0 print:mt-6">
                                    Kindly settle Court Fee to hold your booking.
                                    <br />
                                    <span className="font-bold">{paymentMobile} Gcash</span>
                                    <br />
                                    {paymentName}
                                </div>
                                <button
                                    onClick={() => setShowQr(true)}
                                    className="mt-2 w-full py-2 text-xs font-bold text-white bg-pickle-green rounded-lg hover:bg-pickle-green/90 transition-all active:scale-95"
                                >
                                    Show QR for Payment
                                </button>
                            </>
                        )}

                        {/* ── Unpaid invoice — split view (QR visible) ── */}
                        {balance > 0 && showQr && (
                            <>
                                <div className="grid grid-cols-2 gap-3 items-start">
                                    {/* Left: condensed booking info + financials */}
                                    <div className="space-y-2">
                                        <div className="border border-slate-100 rounded-lg p-2 space-y-1.5 text-xs">
                                            <div>
                                                <p className="text-[8px] font-bold text-slate-400 uppercase">Renter</p>
                                                <p className="font-semibold text-slate-900 truncate">{renter?.name || 'N/A'}</p>
                                            </div>
                                            <div className="border-t border-slate-100 pt-1.5">
                                                <p className="text-[8px] font-bold text-slate-400 uppercase">Date</p>
                                                <p className="font-semibold text-slate-900">{rentalDate}</p>
                                            </div>
                                            <div className="border-t border-slate-100 pt-1.5">
                                                <p className="text-[8px] font-bold text-slate-400 uppercase">Time</p>
                                                <p className="font-semibold text-slate-900">{startTime} – {endTime}</p>
                                            </div>
                                            {courtSummary.map(({ courtId, hours }) => (
                                                <div key={courtId} className="border-t border-slate-100 pt-1.5">
                                                    <p className="text-[8px] font-bold text-slate-400 uppercase">Court {courtId}</p>
                                                    <p className="font-semibold text-slate-900">{hours.toFixed(1)}h</p>
                                                </div>
                                            ))}
                                        </div>
                                        <div className="border border-slate-100 rounded-lg p-2">
                                            <FinancialBlock {...financialProps} compact />
                                        </div>
                                    </div>

                                    {/* Right: QR + payment info */}
                                    <div className="flex flex-col items-center gap-2">
                                        <div className="text-center text-[10px] font-semibold text-amber-800 bg-amber-50 px-2 py-1.5 rounded-lg border border-amber-100 w-full">
                                            Scan to pay via GCash
                                        </div>
                                        <img
                                            src={qrImageSrc}
                                            alt="Payment QR code"
                                            className="w-full h-auto rounded-lg border border-slate-100"
                                        />
                                        <div className="text-center">
                                            <p className="text-[10px] font-bold text-slate-800">{paymentName}</p>
                                            <p className="text-[9px] text-slate-500">{paymentMobile}</p>
                                        </div>
                                    </div>
                                </div>

                                <button
                                    onClick={() => setShowQr(false)}
                                    className="mt-3 w-full py-1.5 text-[11px] font-medium text-slate-500 bg-slate-100 rounded-lg hover:bg-slate-200 transition-all flex items-center justify-center gap-1"
                                >
                                    <ArrowLeft className="h-3 w-3" />
                                    Back to full invoice
                                </button>
                            </>
                        )}

                        {/* Print-only footer */}
                        <div className="hidden print:block mt-12 text-center">
                            <p className="text-xs text-slate-400">Generated by Dink Manager</p>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    );
}
