import { resolveMatchResult } from "../../../state/matchResults";
export function getSessionMatches(matches, sessionStartMs) {
  return (matches || []).filter(
    (m) => m?.status === "completed" && (m.startTime ?? 0) >= sessionStartMs
  );
}

export function computeSessionLeaderboard(matches, players, sessionStartMs, limit = 3) {
  if (!sessionStartMs) return [];

  const sessionMatches = getSessionMatches(matches, sessionStartMs);
  const playerStats = {};

  sessionMatches.forEach((m) => {
    const { winner } = resolveMatchResult(m);
    if (!winner) return;

    const processTeam = (teamIds, isWinner) => {
      (teamIds || []).forEach((id) => {
        if (!playerStats[id]) playerStats[id] = { wins: 0, total: 0 };
        playerStats[id].total += 1;
        if (isWinner) playerStats[id].wins += 1;
      });
    };

    processTeam(m.teams?.green, winner === "green");
    processTeam(m.teams?.blue, winner === "blue");
  });

  const ranked = Object.entries(playerStats)
    .filter(([, stats]) => stats.total >= 2)
    .map(([id, stats]) => {
      const player = (players || []).find((p) => String(p.id) === String(id));
      const name = player?.name || `P${id}`;
      const winRate = stats.total > 0 ? (stats.wins / stats.total) * 100 : 0;
      return { id, name, wins: stats.wins, total: stats.total, winRate };
    })
    .sort((a, b) => {
      if (b.winRate !== a.winRate) return b.winRate - a.winRate;
      if (b.total !== a.total) return b.total - a.total;
      return a.name.localeCompare(b.name);
    })
    .slice(0, limit)
    .map((entry, index) => ({ ...entry, rank: index + 1 }));

  return ranked;
}
