import React, { useMemo } from "react";
import BracketMatchCard from "./BracketMatchCard";

/**
 * Pure CSS/flexbox bracket view — no SVG, no library.
 * Columns = rounds, rows = match slots with connector lines.
 *
 * Props:
 *   matches      - Array of playoff match objects for one division
 *   partners     - Object keyed by partner id (or array — both handled)
 *   onScore      - (match) => void — opens score entry
 */
export default function BracketView({ matches, partners, onScore, onEdit }) {
  const partnerMap = useMemo(() => {
    if (!partners) return {};
    if (Array.isArray(partners)) {
      return Object.fromEntries(partners.map((p) => [p.id, p]));
    }
    return partners;
  }, [partners]);

  const rounds = useMemo(() => {
    const roundMap = {};
    for (const m of matches) {
      if (!m.round) continue;
      if (!roundMap[m.round]) roundMap[m.round] = [];
      roundMap[m.round].push(m);
    }
    // Sort each round by bracket_position
    Object.keys(roundMap).forEach((r) => {
      roundMap[r].sort((a, b) => (a.bracket_position || 0) - (b.bracket_position || 0));
    });
    return roundMap;
  }, [matches]);

  const roundNumbers = Object.keys(rounds)
    .map(Number)
    .sort((a, b) => a - b);

  if (roundNumbers.length === 0) {
    return (
      <div className="py-12 text-center text-sm text-slate-400">
        No bracket matches generated yet.
      </div>
    );
  }

  const getRoundLabel = (round, totalRounds) => {
    const remaining = totalRounds - round + 1;
    if (remaining === 1) return "Final";
    if (remaining === 2) return "Semifinals";
    if (remaining === 3) return "Quarterfinals";
    return `Round ${round}`;
  };

  const totalRounds = roundNumbers[roundNumbers.length - 1];

  return (
    <div className="relative">
      {/* Right-edge gradient — visual cue that the bracket scrolls horizontally on small screens */}
      <div
        className="pointer-events-none absolute right-0 inset-y-0 w-10 bg-gradient-to-l from-white to-transparent z-10 md:hidden"
        aria-hidden="true"
      />
      <p className="text-[10px] text-slate-400 text-right pr-2 mb-1 md:hidden">
        Scroll →
      </p>
      <div className="overflow-x-auto">
      <div className="flex items-start gap-0 min-w-max py-4 px-4">
        {roundNumbers.map((round, roundIdx) => {
          const roundMatches = rounds[round];
          const matchesInRound = roundMatches.length;
          // Calculate spacing: matches in round 1 are tightest; later rounds have more vertical spacing
          const spacingClass = matchesInRound > 4
            ? "gap-2"
            : matchesInRound > 2
            ? "gap-6"
            : matchesInRound > 1
            ? "gap-12"
            : "gap-0";

          return (
            <div key={round} className="flex items-stretch">
              {/* Round column */}
              <div className="flex flex-col" style={{ minWidth: "180px" }}>
                {/* Round label */}
                <div className="text-center text-[10px] font-semibold text-slate-400 uppercase tracking-wide mb-2 px-2">
                  {getRoundLabel(round, totalRounds)}
                </div>

                {/* Matches */}
                <div className={`flex flex-col flex-1 ${spacingClass} justify-around`}>
                  {roundMatches.map((match) => (
                    <div key={match.id} className="relative flex items-center">
                      {/* Connector from previous round */}
                      {roundIdx > 0 && (
                        <div
                          className="absolute left-0 top-1/2 -translate-y-1/2 w-3 border-t-2 border-slate-200"
                          style={{ left: "-12px" }}
                        />
                      )}

                      <div className="w-full px-1">
                        <BracketMatchCard
                          match={match}
                          partnerA={match.partner_a_id ? partnerMap[match.partner_a_id] : null}
                          partnerB={match.partner_b_id ? partnerMap[match.partner_b_id] : null}
                          onScore={onScore}
                          onEdit={onEdit}
                          isCompact={matchesInRound > 4}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Connector lines between rounds (right side of current round, left side of next) */}
              {roundIdx < roundNumbers.length - 1 && (
                <ConnectorColumn
                  matchCount={matchesInRound}
                  spacingClass={spacingClass}
                />
              )}
            </div>
          );
        })}
      </div>
      </div>
    </div>
  );
}

/**
 * Draws bracket connector lines between two rounds.
 * For N matches in current round, there are N/2 pairs → N/2 connectors.
 */
function ConnectorColumn({ matchCount }) {
  const pairCount = Math.max(1, Math.floor(matchCount / 2));

  return (
    <div
      className="flex flex-col justify-around"
      style={{ width: "24px", minWidth: "24px" }}
    >
      {Array.from({ length: pairCount }).map((_, i) => (
        <div key={i} className="flex-1 flex flex-col justify-center" style={{ minHeight: "40px" }}>
          {/* Top half: right border down */}
          <div className="flex-1 border-r-2 border-slate-200" />
          {/* Middle: horizontal bridge */}
          <div className="border-t-2 border-slate-200 w-full" style={{ height: "0px" }} />
          {/* Bottom half: right border up */}
          <div className="flex-1 border-r-2 border-slate-200" />
        </div>
      ))}
    </div>
  );
}
