// One interpretation of results for storage, operator screens, reports and TV.
export const playerIdKey = (id) => String(id ?? "");

export function parseMatchScore(value) {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!/^\d+$/.test(trimmed)) return null;
    value = Number(trimmed);
  }
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : null;
}

export function computeWinner(score) {
  const green = parseMatchScore(score?.green);
  const blue = parseMatchScore(score?.blue);
  if (green === null || blue === null) return null;
  return green === blue ? "tie" : green > blue ? "green" : "blue";
}

export function getMatchParticipants(match, roster = []) {
  const byId = new Map(roster.map((player) => [playerIdKey(player.id), player]));
  const lineup = Array.isArray(match?.lineup) ? match.lineup : [];
  // Prefer recorded participants. Never add unrelated players from today's roster.
  const entries = lineup.length ? lineup : Array.from(new Set(
    [...(match?.teams?.green || []), ...(match?.teams?.blue || [])].map(playerIdKey)
  )).map((id) => ({ id }));
  return entries.filter((entry) => entry?.id != null).map((entry) => ({
    id: entry.id,
    name: entry.name || byId.get(playerIdKey(entry.id))?.name || `Player ${entry.id}`,
  }));
}

export function resolveMatchResult(match) {
  const score = {
    green: parseMatchScore(match?.score?.green),
    blue: parseMatchScore(match?.score?.blue),
  };
  const green = Array.isArray(match?.teams?.green) ? match.teams.green : [];
  const blue = Array.isArray(match?.teams?.blue) ? match.teams.blue : [];
  const ids = [...green, ...blue].map(playerIdKey);
  const lineupIds = (match?.lineup || []).map((player) => playerIdKey(player.id));
  const validTeams = green.length > 0 && blue.length > 0 && ids.every(Boolean)
    && new Set(ids).size === ids.length
    && (!lineupIds.length || (ids.length === lineupIds.length && ids.every((id) => lineupIds.includes(id))));
  const winner = match?.status === "completed" && validTeams ? computeWinner(score) : null;
  return { score, winner, recorded: winner !== null };
}

export function normalizeMatchResult(match) {
  const { score, winner } = resolveMatchResult(match);
  return { ...match, score, winner };
}

export function createRecordedMatch(match, input, roster = [], now = Date.now()) {
  if (!match || match.status !== "completed") throw new Error("Only completed matches can be scored.");
  const participants = getMatchParticipants(match, roster);
  const ids = participants.map((player) => playerIdKey(player.id));
  if (ids.length !== 4 || new Set(ids).size !== 4) {
    throw new Error("This match needs four distinct recorded players before a result can be saved.");
  }
  const winnerIds = (input.winnerIds || []).map(playerIdKey);
  if (winnerIds.length !== 2 || new Set(winnerIds).size !== 2 || winnerIds.some((id) => !ids.includes(id))) {
    throw new Error("Select exactly two winners from this match.");
  }
  const winnerScore = parseMatchScore(input.winnerScore);
  const loserScore = parseMatchScore(input.loserScore);
  if (winnerScore === null || loserScore === null) throw new Error("Enter both scores as whole numbers, zero or higher.");
  if (winnerScore <= loserScore) throw new Error("The winning score must be higher than the losing score.");
  return {
    ...match,
    lineup: participants,
    teams: {
      green: participants.filter((p) => winnerIds.includes(playerIdKey(p.id))).map((p) => p.id),
      blue: participants.filter((p) => !winnerIds.includes(playerIdKey(p.id))).map((p) => p.id),
    },
    score: { green: winnerScore, blue: loserScore },
    winner: "green",
    updatedAt: now,
  };
}

export function computePlayerStats(matches = []) {
  const stats = new Map();
  matches.forEach((match) => {
    if (match?.status !== "completed") return;
    const participants = new Set(getMatchParticipants(match).map((p) => playerIdKey(p.id)));
    const result = resolveMatchResult(match);
    const green = new Set((match.teams?.green || []).map(playerIdKey));
    const margin = result.recorded ? Math.abs(result.score.green - result.score.blue) : 0;
    participants.forEach((id) => {
      const current = stats.get(id) || { pointDiff: 0, matches: 0, totalMatchTimeMs: 0 };
      const won = result.winner === (green.has(id) ? "green" : "blue");
      stats.set(id, {
        pointDiff: current.pointDiff + (result.winner && result.winner !== "tie" ? (won ? margin : -margin) : 0),
        matches: current.matches + 1,
        totalMatchTimeMs: current.totalMatchTimeMs + Math.max(0, Number(match.durationMs) || 0),
      });
    });
  });
  return stats;
}

export function withPlayerMatchStats(players, matches) {
  const stats = computePlayerStats(matches);
  return players.map((player) => {
    const entry = stats.get(playerIdKey(player.id)) || { pointDiff: 0, matches: 0, totalMatchTimeMs: 0 };
    const next = {
      pointDifferential: entry.pointDiff,
      matches: entry.matches,
      totalMatchTimeMs: entry.totalMatchTimeMs,
      averageMatchDurationMs: entry.matches ? Math.round(entry.totalMatchTimeMs / entry.matches) : 0,
    };
    return Object.keys(next).every((key) => next[key] === player[key]) ? player : { ...player, ...next };
  });
}
