import React from "react";

// ── Helpers ───────────────────────────────────────────────────────────────────
function playerNames(partner) {
  if (!partner) return null;
  const p1 = partner.player_1_name?.trim();
  const p2 = partner.player_2_name?.trim();
  if (p1 && p2) return `${p1}  ·  ${p2}`;
  return p1 || p2 || null;
}

// ── VS Full-Screen Layout ─────────────────────────────────────────────────────
function VSMatchDisplay({ match, teamA, teamB, div }) {
  const liveScore = match.live_score;
  const completedScores = match.scores?.length ? match.scores : null;

  const scoreA = liveScore?.partner_a ?? null;
  const scoreB = liveScore?.partner_b ?? null;
  const aWinning = scoreA !== null && scoreB !== null && scoreA > scoreB;
  const bWinning = scoreB !== null && scoreA !== null && scoreB > scoreA;

  return (
    <div className="flex-1 flex flex-col items-center justify-between py-8 px-10 overflow-hidden">
      {/* Top meta row */}
      <div className="flex items-center gap-4 text-center">
        {match.court && (
          <span className="font-oswald font-bold text-pickle-cream/70 text-2xl uppercase tracking-[0.2em]">
            {match.court}
          </span>
        )}
        {match.court && div && <span className="text-white/20 text-xl">·</span>}
        {div && (
          <span className="font-body text-pickle-cream/40 text-xl">{div.name}</span>
        )}
        {match.round != null && (
          <>
            <span className="text-white/20 text-xl">·</span>
            <span className="font-oswald font-bold text-pickle-cream/40 text-xl uppercase tracking-wider">Round {match.round}</span>
          </>
        )}
      </div>

      {/* Main VS area */}
      <div className="flex-1 flex items-center justify-center w-full gap-0 max-w-[1400px]">
        {/* Team A side */}
        <div className="flex-1 flex flex-col items-center justify-center gap-6 text-center px-6">
          {/* Score */}
          {scoreA !== null ? (
            <div className={`font-oswald font-bold leading-none tabular-nums transition-colors ${
              aWinning ? "text-pickle-gold" : "text-white/70"
            }`} style={{ fontSize: "clamp(5rem, 14vw, 12rem)" }}>
              {scoreA}
            </div>
          ) : (
            <div className="text-white/10 font-oswald font-bold text-8xl">—</div>
          )}

          {/* Team name + player names */}
          <div className="flex flex-col items-center gap-2">
            <div className={`font-oswald font-bold leading-tight text-center px-4 transition-colors ${
              aWinning ? "text-white" : "text-white/85"
            }`} style={{ fontSize: "clamp(2rem, 4.5vw, 4rem)" }}>
              {teamA?.team_name || "TBD"}
            </div>
            {playerNames(teamA) && (
              <div className="font-body text-pickle-cream/50 text-center px-6 leading-snug"
                style={{ fontSize: "clamp(0.95rem, 1.8vw, 1.5rem)" }}>
                {playerNames(teamA)}
              </div>
            )}
          </div>
        </div>

        {/* Center VS column */}
        <div className="flex flex-col items-center gap-5 shrink-0 px-4">
          {/* Dashed circle VS badge */}
          <div className="relative flex items-center justify-center"
            style={{ width: "clamp(80px, 10vw, 130px)", height: "clamp(80px, 10vw, 130px)" }}>
            {/* Outer dashed ring */}
            <svg className="absolute inset-0 w-full h-full" viewBox="0 0 100 100">
              <circle
                cx="50" cy="50" r="46"
                fill="none"
                stroke="rgba(248,223,186,0.20)"
                strokeWidth="2.5"
                strokeDasharray="6 5"
                strokeLinecap="round"
              />
            </svg>
            <span className="font-oswald font-bold text-white/60 z-10"
              style={{ fontSize: "clamp(1.1rem, 2.5vw, 2rem)" }}>
              VS
            </span>
          </div>
        </div>

        {/* Team B side */}
        <div className="flex-1 flex flex-col items-center justify-center gap-6 text-center px-6">
          {/* Score */}
          {scoreB !== null ? (
            <div className={`font-oswald font-bold leading-none tabular-nums transition-colors ${
              bWinning ? "text-pickle-gold" : "text-white/70"
            }`} style={{ fontSize: "clamp(5rem, 14vw, 12rem)" }}>
              {scoreB}
            </div>
          ) : (
            <div className="text-white/10 font-oswald font-bold text-8xl">—</div>
          )}

          {/* Team name + player names */}
          <div className="flex flex-col items-center gap-2">
            <div className={`font-oswald font-bold leading-tight text-center px-4 transition-colors ${
              bWinning ? "text-white" : "text-white/85"
            }`} style={{ fontSize: "clamp(2rem, 4.5vw, 4rem)" }}>
              {teamB?.team_name || "TBD"}
            </div>
            {playerNames(teamB) && (
              <div className="font-body text-pickle-cream/50 text-center px-6 leading-snug"
                style={{ fontSize: "clamp(0.95rem, 1.8vw, 1.5rem)" }}>
                {playerNames(teamB)}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Bottom: completed game scores + status */}
      <div className="flex items-center gap-6">
        {completedScores && (
          <div className="flex items-center gap-3">
            <span className="text-pickle-cream/30 font-body text-base uppercase tracking-wider">Games</span>
            {completedScores.map((g, i) => (
              <span key={i} className="font-oswald font-bold text-pickle-gold text-xl">
                {g.partner_a}–{g.partner_b}
              </span>
            ))}
          </div>
        )}
        {match.status === "in_progress" && (
          <div className="flex items-center gap-2">
            <span className="w-2.5 h-2.5 rounded-full bg-green-400 animate-pulse" />
            <span className="font-oswald font-bold text-green-300 text-lg uppercase tracking-widest">Live</span>
          </div>
        )}
        {match.status === "scheduled" && match.scheduled_time && (
          <span className="font-oswald font-bold text-pickle-cream/50 text-xl">{match.scheduled_time}</span>
        )}
      </div>
    </div>
  );
}

// ── Multi-match compact grid (fallback when multiple live, no featured) ────────
function MultiMatchGrid({ liveMatches, partnerMap, divMap }) {
  const gridCols =
    liveMatches.length === 1
      ? "grid-cols-1 max-w-3xl mx-auto w-full"
      : liveMatches.length <= 4
      ? "grid-cols-2"
      : "grid-cols-3";

  return (
    <div className="flex-1 p-6 flex flex-col overflow-auto">
      <div className="text-pickle-cream/40 font-oswald font-bold text-xl uppercase tracking-widest text-center mb-4">
        Now Playing — {liveMatches.length} Matches
      </div>
      <div className={`grid gap-6 flex-1 ${gridCols}`}>
        {liveMatches.map((m) => {
          const teamA = partnerMap[m.partner_a_id];
          const teamB = partnerMap[m.partner_b_id];
          const div = divMap[m.division_id];
          const aWon = m.winner_id === m.partner_a_id;
          const bWon = m.winner_id === m.partner_b_id;
          const liveScore = m.live_score;
          return (
            <div
              key={m.id}
              className="bg-white/10 border-2 border-white/20 rounded-3xl p-8 flex flex-col gap-4"
            >
              <div className="flex items-center justify-between">
                <span className="text-pickle-cream/60 font-oswald font-bold text-2xl uppercase tracking-wide">
                  {m.court || "Court"}
                </span>
                {div && <span className="text-pickle-cream/40 font-body text-lg">{div.name}</span>}
              </div>
              <div className="flex-1 flex flex-col justify-center gap-4">
                <div className="flex items-center justify-between gap-4">
                  <div className={`flex-1 min-w-0 ${aWon ? "text-pickle-gold" : "text-white"}`}>
                    <div className="font-oswald font-bold text-4xl leading-tight truncate">{teamA?.team_name || "TBD"}</div>
                    {playerNames(teamA) && <div className="font-body text-pickle-cream/45 text-lg mt-1 truncate">{playerNames(teamA)}</div>}
                  </div>
                  {liveScore && (
                    <span className={`font-oswald font-bold text-4xl tabular-nums shrink-0 ${liveScore.partner_a > liveScore.partner_b ? "text-pickle-gold" : "text-white/60"}`}>
                      {liveScore.partner_a ?? 0}
                    </span>
                  )}
                </div>
                <div className="text-white/30 font-body text-xl text-center">vs</div>
                <div className="flex items-center justify-between gap-4">
                  <div className={`flex-1 min-w-0 ${bWon ? "text-pickle-gold" : "text-white"}`}>
                    <div className="font-oswald font-bold text-4xl leading-tight truncate">{teamB?.team_name || "TBD"}</div>
                    {playerNames(teamB) && <div className="font-body text-pickle-cream/45 text-lg mt-1 truncate">{playerNames(teamB)}</div>}
                  </div>
                  {liveScore && (
                    <span className={`font-oswald font-bold text-4xl tabular-nums shrink-0 ${liveScore.partner_b > liveScore.partner_a ? "text-pickle-gold" : "text-white/60"}`}>
                      {liveScore.partner_b ?? 0}
                    </span>
                  )}
                </div>
              </div>
              <div className="border-t border-white/10 pt-4 flex items-center justify-center">
                {m.scores?.length ? (
                  <div className="text-pickle-gold font-oswald font-bold text-2xl">
                    {m.scores.map((g, i) => (
                      <span key={i}>{i > 0 && <span className="text-white/30 mx-2">·</span>}{g.partner_a}–{g.partner_b}</span>
                    ))}
                  </div>
                ) : (
                  <span className="text-white/20 font-oswald font-bold text-2xl">—</span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Main export ───────────────────────────────────────────────────────────────
export default function DisplayCurrentMatch({ tournament, divisions, matches, partners, featuredMatchId }) {
  const divMap = Object.fromEntries(divisions.map((d) => [d.id, d]));
  const partnerMap = Object.fromEntries(partners.map((p) => [p.id, p]));

  const liveMatches = matches
    .filter((m) => m.tournament_id === tournament.id && m.status === "in_progress")
    .sort((a, b) => (a.court || "").localeCompare(b.court || ""));

  // Featured match: either the pinned one, or the first live match
  const featuredMatch = featuredMatchId
    ? matches.find((m) => m.id === featuredMatchId) || liveMatches[0]
    : liveMatches.length === 1
    ? liveMatches[0]
    : null;

  // Nothing live and no featured
  if (liveMatches.length === 0 && !featuredMatch) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center gap-6 text-center px-8">
        <div className="relative flex items-center justify-center w-48 h-48">
          <svg className="absolute inset-0 w-full h-full opacity-20" viewBox="0 0 100 100">
            <circle cx="50" cy="50" r="46" fill="none" stroke="rgba(248,223,186,0.5)" strokeWidth="2" strokeDasharray="6 5" />
          </svg>
          <span className="font-oswald font-bold text-white/20 text-4xl z-10">VS</span>
        </div>
        <div className="text-pickle-cream/40 font-oswald font-bold text-5xl uppercase tracking-widest">
          No Matches In Progress
        </div>
        <div className="text-pickle-cream/20 font-body text-2xl">
          Matches will appear here when they start.
        </div>
      </div>
    );
  }

  // Show full VS layout for featured or single live match
  if (featuredMatch) {
    const teamA = partnerMap[featuredMatch.partner_a_id];
    const teamB = partnerMap[featuredMatch.partner_b_id];
    const div = divMap[featuredMatch.division_id];
    return (
      <VSMatchDisplay
        match={featuredMatch}
        teamA={teamA}
        teamB={teamB}
        div={div}
      />
    );
  }

  // Multiple live matches, no featured → compact grid
  return <MultiMatchGrid liveMatches={liveMatches} partnerMap={partnerMap} divMap={divMap} />;
}
