import React from "react";
import { Calendar, MapPin, Users } from "lucide-react";

function formatDate(d) {
  if (!d) return "—";
  const parts = d.split("-");
  const dt = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
  return dt.toLocaleDateString([], { month: "long", day: "numeric", year: "numeric" });
}

export default function DisplayTournamentInfo({ tournament, divisions, groups, partners }) {
  const divisionList = divisions.filter((d) => d.tournament_id === tournament.id);

  return (
    <div className="flex-1 flex flex-col items-center justify-center gap-10 px-12 py-8 text-center">
      {/* Tournament name */}
      <div>
        <div className="font-display text-8xl md:text-[7rem] text-pickle-cream mb-4 drop-shadow-lg leading-tight">
          {tournament.name}
        </div>
        {(tournament.start_date || tournament.end_date) && (
          <div className="flex items-center justify-center gap-3 text-pickle-cream/70 text-2xl font-body">
            <Calendar size={26} />
            <span>
              {formatDate(tournament.start_date)}
              {tournament.end_date && tournament.end_date !== tournament.start_date && (
                <> — {formatDate(tournament.end_date)}</>
              )}
            </span>
          </div>
        )}
      </div>

      {/* Divisions grid */}
      {divisionList.length > 0 && (
        <div className="w-full max-w-3xl">
          <h2 className="text-pickle-cream/40 text-lg font-oswald uppercase tracking-widest mb-5">Divisions</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {divisionList.map((div) => {
              const divPartners = partners.filter((p) => p.division_id === div.id && !p.withdrawn);
              const divGroups = groups.filter((g) => g.division_id === div.id);
              return (
                <div key={div.id} className="bg-white/10 rounded-3xl px-7 py-5 text-left">
                  <div className="text-white font-oswald text-3xl mb-2">{div.name}</div>
                  <div className="flex gap-5 text-pickle-cream/60 text-xl font-body">
                    <span className="flex items-center gap-2">
                      <Users size={18} />
                      {divPartners.length} teams
                    </span>
                    <span>
                      {divGroups.length} {divGroups.length === 1 ? "group" : "groups"}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Courts */}
      {tournament.courts?.length > 0 && (
        <div className="flex items-center gap-3 text-pickle-cream/50 text-xl font-body">
          <MapPin size={20} />
          <span>{tournament.courts.join(" · ")}</span>
        </div>
      )}
    </div>
  );
}
