import base from "./config";

// Single active config with shared helpers
const config = {
  ...base,
  assetPath(relative) {
    const r = String(relative || "").replace(/^\/+/, "");
    const publicUrl = (process.env.PUBLIC_URL || "").replace(/\/$/, "");
    const rawBase = base.assetsBase || "/assets";
    const basePath = (rawBase.endsWith("/")) ? rawBase.slice(0, -1) : rawBase;
    const normalizedBase = basePath.startsWith("/") ? basePath : `/${basePath}`;
    // When homepage is set to "." (CRA), PUBLIC_URL is "." producing relative paths like "./assets/..."
    return `${publicUrl}${normalizedBase}/${r}`;
  },
  getDefaultCourts() {
    const names = base.courts?.defaultNames || ["Court 1", "Court 2", "Court 3"];
    return names.map((name, idx) => ({ id: idx + 1, name, players: [] }));
  },
};

export default config;
