import { generateId } from "./ids";

/**
 * Returns the smallest power of 2 >= n.
 */
export function nextPowerOfTwo(n) {
  let p = 1;
  while (p < n) p *= 2;
  return p;
}

/**
 * generateSingleEliminationBracket(seededPartners, meta)
 * meta: { tournament_id, division_id }
 *
 * Returns flat Match[] for single elimination.
 * - Seeds partners 1..N into a bracket of size 2^k
 * - Highest seeds get first-round BYEs
 * - Later-round matches have null partner IDs (TBD)
 * - BYE matches are auto-completed
 */
export function generateSingleEliminationBracket(seededPartners, meta = {}) {
  const n = seededPartners.length;
  if (n < 2) return [];

  const size = nextPowerOfTwo(n);
  const totalRounds = Math.log2(size);

  // Create seeded slots: index 0 = seed 1, etc.
  // For a bracket of size `size`, we need to place partners in seeded positions
  // Standard bracket seeding: 1v(size), 2v(size-1), etc. in a balanced way
  const slots = buildSeededSlots(size);

  // Map slot index to partner (null = BYE)
  const slotPartners = slots.map((seed) =>
    seed <= n ? seededPartners[seed - 1] : null
  );

  const matches = [];

  // Round 1: pair adjacent slots
  for (let i = 0; i < size; i += 2) {
    const partnerA = slotPartners[i];
    const partnerB = slotPartners[i + 1];
    const position = i / 2 + 1;

    const isBye = !partnerA || !partnerB;
    const winner = isBye ? (partnerA || partnerB) : null;

    const match = {
      id: generateId(),
      tournament_id: meta.tournament_id || null,
      division_id: meta.division_id || null,
      group_id: null,
      phase: "playoff",
      round: 1,
      bracket_type: "winners",
      bracket_position: position,
      partner_a_id: partnerA?.id || null,
      partner_b_id: partnerB?.id || null,
      winner_id: isBye ? winner?.id || null : null,
      scores: [],
      scheduled_date: null,
      scheduled_time: null,
      court: null,
      status: isBye ? "bye" : "scheduled",
      created_at: new Date().toISOString(),
      completed_at: isBye ? new Date().toISOString() : null,
    };
    matches.push(match);
  }

  // Generate placeholder matches for rounds 2..totalRounds
  for (let round = 2; round <= totalRounds; round++) {
    const matchesInRound = size / Math.pow(2, round);
    for (let pos = 1; pos <= matchesInRound; pos++) {
      matches.push({
        id: generateId(),
        tournament_id: meta.tournament_id || null,
        division_id: meta.division_id || null,
        group_id: null,
        phase: "playoff",
        round,
        bracket_type: "winners",
        bracket_position: pos,
        partner_a_id: null,
        partner_b_id: null,
        winner_id: null,
        scores: [],
        scheduled_date: null,
        scheduled_time: null,
        court: null,
        status: "scheduled",
        created_at: new Date().toISOString(),
        completed_at: null,
      });
    }
  }

  // Auto-advance BYE winners into round 2
  const round1Matches = matches.filter((m) => m.round === 1 && m.status === "bye");
  for (const byeMatch of round1Matches) {
    if (!byeMatch.winner_id) continue;
    const nextRoundMatch = matches.find(
      (m) =>
        m.round === 2 &&
        m.bracket_position === Math.ceil(byeMatch.bracket_position / 2)
    );
    if (nextRoundMatch) {
      if (byeMatch.bracket_position % 2 === 1) {
        nextRoundMatch.partner_a_id = byeMatch.winner_id;
      } else {
        nextRoundMatch.partner_b_id = byeMatch.winner_id;
      }
    }
  }

  return matches;
}

/**
 * advanceWinnerInBracket(completedMatchId, winnerId, allMatchesArray)
 * Returns the updated allMatchesArray (new array reference) after routing winner.
 */
export function advanceWinnerInBracket(completedMatchId, winnerId, allMatchesArray) {
  const completedMatch = allMatchesArray.find((m) => m.id === completedMatchId);
  if (!completedMatch || completedMatch.phase !== "playoff") return allMatchesArray;

  const nextRound = completedMatch.round + 1;
  const nextPosition = Math.ceil(completedMatch.bracket_position / 2);

  return allMatchesArray.map((m) => {
    if (
      m.phase === "playoff" &&
      m.round === nextRound &&
      m.bracket_position === nextPosition &&
      m.tournament_id === completedMatch.tournament_id &&
      m.division_id === completedMatch.division_id
    ) {
      // Odd bracket_position fills partner_a, even fills partner_b
      if (completedMatch.bracket_position % 2 === 1) {
        return { ...m, partner_a_id: winnerId };
      } else {
        return { ...m, partner_b_id: winnerId };
      }
    }
    return m;
  });
}

// ---------------------------------------------------------------------------
// Seeded bracket slot builder
// Produces ordered slot seeds for a standard seeded bracket.
// E.g. for size 8: slots [1,8,5,4,3,6,7,2] → R1 matchups: 1v8, 5v4, 3v6, 7v2
// ---------------------------------------------------------------------------
function buildSeededSlots(size) {
  let slots = [1, 2];
  while (slots.length < size) {
    const nextSize = slots.length * 2;
    const newSlots = [];
    for (const s of slots) {
      newSlots.push(s);
      newSlots.push(nextSize + 1 - s);
    }
    slots = newSlots;
  }
  return slots;
}
