import React, { useState, useMemo } from "react";
import { Pencil, ClipboardList, Play, ArrowLeftRight } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import ScoreEntryModal from "./ScoreEntryModal";
import toast from "react-hot-toast";

function fmt12(time24) {
  if (!time24) return null;
  const [h, m] = time24.split(":").map(Number);
  const ampm = h >= 12 ? "PM" : "AM";
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${ampm}`;
}

function fmtDate(dateStr) {
  if (!dateStr) return null;
  const [y, mo, d] = dateStr.split("-").map(Number);
  return new Date(y, mo - 1, d).toLocaleDateString([], { month: "short", day: "numeric" });
}

const STATUS_LABELS = {
  scheduled: "Scheduled",
  in_progress: "In Progress",
  completed: "Completed",
  cancelled: "Cancelled",
  bye: "Bye",
};

const STATUS_STYLES = {
  scheduled: "bg-slate-100 text-slate-600",
  in_progress: "bg-blue-100 text-blue-700",
  completed: "bg-green-100 text-green-700",
  cancelled: "bg-red-100 text-red-600",
  bye: "bg-amber-100 text-amber-700",
};

function StatusBadge({ status }) {
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_STYLES[status] || STATUS_STYLES.scheduled}`}>
      {STATUS_LABELS[status] || status}
    </span>
  );
}

export default function ScheduleTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getMatchesForTournament,
    partners,
    updateMatchStatus,
    updateMatchSchedule,
    updateMatchPartners,
    recordMatchResult,
    autoScheduleUnscheduled,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allMatches = getMatchesForTournament(tournament.id);

  const [filterDivision, setFilterDivision] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [scoreMatch, setScoreMatch] = useState(null);
  const [editMatch, setEditMatch] = useState(null);
  const [editForm, setEditForm] = useState({});
  // Swap state: swapSource = the match we want to swap teams FROM
  const [swapSource, setSwapSource] = useState(null);

  const getPartner = (pid) => pid ? partners[pid] : null;

  const unscheduledCount = useMemo(
    () => allMatches.filter((m) => !m.scheduled_date && m.status === "scheduled").length,
    [allMatches]
  );

  const filtered = useMemo(() => {
    return allMatches
      .filter((m) => {
        if (filterDivision && m.division_id !== filterDivision) return false;
        if (filterStatus && m.status !== filterStatus) return false;
        return true;
      })
      .sort((a, b) => {
        const dateA = a.scheduled_date || "9999";
        const dateB = b.scheduled_date || "9999";
        if (dateA !== dateB) return dateA.localeCompare(dateB);
        return (a.scheduled_time || "").localeCompare(b.scheduled_time || "");
      });
  }, [allMatches, filterDivision, filterStatus]);

  // For swap modal: other group-stage matches in same division that are swappable
  const swapCandidates = useMemo(() => {
    if (!swapSource) return [];
    return allMatches.filter(
      (m) =>
        m.id !== swapSource.id &&
        m.phase === "group_stage" &&
        m.division_id === swapSource.division_id &&
        m.status !== "completed" &&
        m.status !== "bye"
    );
  }, [allMatches, swapSource]);

  const getDivisionName = (did) => divisions.find((d) => d.id === did)?.name || "—";

  const handleMarkInProgress = (match) => {
    updateMatchStatus(match.id, "in_progress");
    toast.success("Match marked as in progress.");
  };

  const handleSaveSchedule = (e) => {
    e.preventDefault();
    updateMatchSchedule(editMatch.id, editForm);
    setEditMatch(null);
    toast.success("Schedule updated.");
  };

  const handleSaveResult = (scores) => {
    recordMatchResult(scoreMatch.id, scores, tournament.id);
    setScoreMatch(null);
    toast.success("Result recorded.");
  };

  const handleSwap = (targetMatch) => {
    // Swap partner_a_id and partner_b_id between swapSource and targetMatch
    updateMatchPartners(swapSource.id, {
      partner_a_id: targetMatch.partner_a_id,
      partner_b_id: targetMatch.partner_b_id,
    });
    updateMatchPartners(targetMatch.id, {
      partner_a_id: swapSource.partner_a_id,
      partner_b_id: swapSource.partner_b_id,
    });
    setSwapSource(null);
    toast.success("Teams swapped successfully.");
  };

  if (tournament.phase === "setup") {
    return (
      <div className="p-6 text-center text-slate-400 text-sm">
        Start the tournament to generate the match schedule.
      </div>
    );
  }

  // Show swap button only in group_stage phase (not playoffs — bracket integrity)
  const canSwap = tournament.phase === "group_stage";

  return (
    <div className="p-4 md:p-6 space-y-4">
      <SurfaceCard title={`Schedule (${filtered.length} matches)`}>
        {/* Division tabs */}
        <div className="flex overflow-x-auto border-b border-slate-100">
          <button
            onClick={() => setFilterDivision("")}
            className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
              filterDivision === ""
                ? "border-pickle-green text-pickle-green"
                : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
            }`}
          >
            All
          </button>
          {divisions.map((d) => (
            <button
              key={d.id}
              onClick={() => setFilterDivision(d.id)}
              className={`px-4 py-2.5 text-xs font-semibold border-b-2 whitespace-nowrap transition-colors shrink-0 ${
                filterDivision === d.id
                  ? "border-pickle-green text-pickle-green"
                  : "border-transparent text-slate-500 hover:text-pickle-green hover:border-pickle-green/30"
              }`}
            >
              {d.name}
            </button>
          ))}
        </div>

        {/* Status filter + actions */}
        <div className="px-4 pt-3 pb-2 flex flex-wrap gap-2">
          <select
            className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs focus:outline-none"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
          >
            <option value="">All Statuses</option>
            {Object.entries(STATUS_LABELS).map(([k, v]) => (
              <option key={k} value={k}>{v}</option>
            ))}
          </select>
          {unscheduledCount > 0 && (
            <button
              onClick={() => autoScheduleUnscheduled(tournament.id)}
              className="flex items-center gap-1 px-2.5 py-1.5 rounded-lg text-xs font-medium text-pickle-green border border-pickle-green/30 hover:bg-pickle-green/5 transition-colors"
              title="Assign all unscheduled matches to courts and times automatically"
            >
              Auto-Schedule ({unscheduledCount})
            </button>
          )}
          {canSwap && (
            <span className="ml-auto text-xs text-slate-400 self-center">
              <ArrowLeftRight size={11} className="inline mr-1" />
              Click swap to reassign teams between two matches
            </span>
          )}
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead className="bg-slate-50 text-xs uppercase text-slate-500">
              <tr>
                <th className="text-left px-4 py-2 font-semibold">Date / Time</th>
                <th className="text-left px-3 py-2 font-semibold">Court</th>
                <th className="text-left px-3 py-2 font-semibold">Division</th>
                <th className="text-left px-3 py-2 font-semibold">Match</th>
                <th className="text-left px-3 py-2 font-semibold">Status</th>
                <th className="px-3 py-2" />
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={6} className="text-center py-8 text-slate-400">No matches found.</td>
                </tr>
              )}
              {filtered.map((m) => {
                const pA = getPartner(m.partner_a_id);
                const pB = getPartner(m.partner_b_id);
                const isSwappable = canSwap && m.phase === "group_stage" && m.status !== "completed" && m.status !== "bye";
                const isSwapSource = swapSource?.id === m.id;
                return (
                  <tr
                    key={m.id}
                    className={`hover:bg-slate-50 ${isSwapSource ? "bg-amber-50 ring-1 ring-amber-300" : ""}`}
                  >
                    <td className="px-4 py-3">
                      {m.scheduled_date ? (
                        <div className="space-y-0.5">
                          <div className="font-bold text-pickle-green text-sm tabular-nums">
                            {fmt12(m.scheduled_time) || <span className="text-slate-400 font-normal text-xs">No time</span>}
                          </div>
                          <div className="text-xs text-slate-400">{fmtDate(m.scheduled_date)}</div>
                        </div>
                      ) : (
                        <span className="text-amber-500 text-xs font-semibold">Unscheduled</span>
                      )}
                    </td>
                    <td className="px-3 py-3 text-slate-600">{m.court || "—"}</td>
                    <td className="px-3 py-3 text-slate-500">{getDivisionName(m.division_id)}</td>
                    <td className="px-3 py-3 font-semibold text-slate-800">
                      <span className="truncate max-w-[140px] block">
                        {pA?.team_name || "TBD"} <span className="text-slate-400 font-normal">vs</span> {pB?.team_name || "TBD"}
                      </span>
                    </td>
                    <td className="px-3 py-3"><StatusBadge status={m.status} /></td>
                    <td className="px-3 py-3">
                      <div className="flex items-center gap-1 justify-end">
                        {m.status === "scheduled" && (
                          <button
                            onClick={() => handleMarkInProgress(m)}
                            className="p-1 rounded text-slate-400 hover:text-blue-500 hover:bg-blue-50"
                            title="Mark In Progress"
                          >
                            <Play size={12} />
                          </button>
                        )}
                        {(m.status === "in_progress" || m.status === "scheduled" || m.status === "completed") && m.status !== "bye" && (
                          <button
                            onClick={() => setScoreMatch(m)}
                            className="p-1 rounded text-slate-400 hover:text-pickle-green hover:bg-pickle-green/10"
                            title="Record Scores"
                          >
                            <ClipboardList size={12} />
                          </button>
                        )}
                        {m.status !== "completed" && m.status !== "bye" && (
                          <button
                            onClick={() => { setEditMatch(m); setEditForm({ date: m.scheduled_date || "", time: m.scheduled_time || "", court: m.court || "" }); }}
                            className="p-1 rounded text-slate-400 hover:text-slate-600 hover:bg-slate-100"
                            title="Edit Schedule"
                          >
                            <Pencil size={12} />
                          </button>
                        )}
                        {isSwappable && (
                          <button
                            onClick={() => setSwapSource(isSwapSource ? null : m)}
                            className={`p-1 rounded transition-colors ${
                              isSwapSource
                                ? "text-amber-600 bg-amber-100"
                                : "text-slate-400 hover:text-amber-500 hover:bg-amber-50"
                            }`}
                            title={isSwapSource ? "Cancel swap" : "Swap teams with another match"}
                          >
                            <ArrowLeftRight size={12} />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </SurfaceCard>

      {/* Score entry modal */}
      {scoreMatch && (
        <ScoreEntryModal
          match={scoreMatch}
          partnerA={getPartner(scoreMatch.partner_a_id)}
          partnerB={getPartner(scoreMatch.partner_b_id)}
          tournament={tournament}
          onSave={handleSaveResult}
          onClose={() => setScoreMatch(null)}
        />
      )}

      {/* Edit schedule modal */}
      {editMatch && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setEditMatch(null)} />
          <form
            onSubmit={handleSaveSchedule}
            className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col"
          >
            <div className="p-6 border-b border-slate-100">
              <h2 className="text-lg font-bold text-slate-900">Edit Schedule</h2>
            </div>
            <div className="p-6 flex flex-col gap-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Date</label>
                <input type="date" className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none" value={editForm.date} onChange={(e) => setEditForm((f) => ({ ...f, date: e.target.value }))} />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Time</label>
                <input type="time" className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none" value={editForm.time} onChange={(e) => setEditForm((f) => ({ ...f, time: e.target.value }))} />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Court</label>
                <input type="text" className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none" value={editForm.court} onChange={(e) => setEditForm((f) => ({ ...f, court: e.target.value }))} placeholder="e.g. Court 1" />
              </div>
            </div>
            <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
              <button type="button" onClick={() => setEditMatch(null)} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">Cancel</button>
              <button type="submit" className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm">Save</button>
            </div>
          </form>
        </div>
      )}

      {/* Swap teams modal */}
      {swapSource && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={() => setSwapSource(null)} />
          <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col max-h-[80vh]">
            <div className="p-6 border-b border-slate-100">
              <h2 className="text-lg font-bold text-slate-900">Swap Teams</h2>
              <p className="text-xs text-slate-500 mt-1">
                Swapping <span className="font-semibold text-slate-700">
                  {getPartner(swapSource.partner_a_id)?.team_name || "TBD"} vs {getPartner(swapSource.partner_b_id)?.team_name || "TBD"}
                </span>
              </p>
              <p className="text-xs text-slate-400 mt-0.5">Select a match to swap teams with:</p>
            </div>

            <div className="overflow-y-auto flex-1">
              {swapCandidates.length === 0 ? (
                <div className="px-6 py-8 text-center text-sm text-slate-400">
                  No other swappable matches in this division.
                </div>
              ) : (
                <ul className="divide-y divide-slate-100">
                  {swapCandidates.map((m) => {
                    const pA = getPartner(m.partner_a_id);
                    const pB = getPartner(m.partner_b_id);
                    return (
                      <li key={m.id}>
                        <button
                          onClick={() => handleSwap(m)}
                          className="w-full text-left px-6 py-3 hover:bg-amber-50 transition-colors flex items-center gap-3"
                        >
                          <ArrowLeftRight size={14} className="text-amber-400 shrink-0" />
                          <div className="flex-1 min-w-0">
                            <div className="text-sm font-medium text-slate-700 truncate">
                              {pA?.team_name || "TBD"} <span className="text-slate-400">vs</span> {pB?.team_name || "TBD"}
                            </div>
                            <div className="text-xs text-slate-400">
                              {m.scheduled_date || "Unscheduled"} {m.scheduled_time || ""} {m.court ? `· ${m.court}` : ""}
                            </div>
                          </div>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>

            <div className="p-4 border-t border-slate-100 flex justify-end">
              <button
                onClick={() => setSwapSource(null)}
                className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
