import React, { useMemo, useState } from "react";
import { Users, LayoutGrid, Trophy, CheckCircle, Medal, Flag, X } from "lucide-react";
import { useTournamentState } from "../providers/TournamentStateProvider";
import SurfaceCard from "../../../common/components/SurfaceCard";
import { calculateGroupStandings } from "../utils/standings";

function StatCard({ icon: Icon, label, value, color = "text-pickle-green" }) {
  return (
    <div className="bg-white border border-slate-200 rounded-xl p-5 flex items-center gap-4 shadow-sm">
      <div className={`p-2.5 rounded-xl bg-slate-50 ${color}`}>
        <Icon size={24} />
      </div>
      <div>
        <div className="text-3xl font-bold text-pickle-green leading-none">{value}</div>
        <div className="text-xs font-medium text-slate-500 mt-0.5">{label}</div>
      </div>
    </div>
  );
}

function DivisionSummaryRow({ division, allGroups, allPartners, allMatches }) {
  const divGroups = allGroups.filter((g) => g.division_id === division.id);
  const divPartners = allPartners.filter((p) => p.division_id === division.id);
  const divCompletedMatches = allMatches.filter(
    (m) => m.division_id === division.id && (m.status === "completed" || m.status === "bye")
  );

  const pointsMap = {};
  divPartners.forEach((p) => { pointsMap[p.id] = 0; });
  divCompletedMatches.forEach((m) => {
    if (m.winner_id && pointsMap[m.winner_id] !== undefined) {
      pointsMap[m.winner_id] = (pointsMap[m.winner_id] || 0) + 3;
    }
    [m.partner_a_id, m.partner_b_id].forEach((pid) => {
      if (pid && pid !== m.winner_id && pointsMap[pid] !== undefined) {
        pointsMap[pid] = (pointsMap[pid] || 0) + 1;
      }
    });
  });

  const leader = divPartners.length > 0
    ? divPartners.reduce((best, p) =>
        (pointsMap[p.id] || 0) > (pointsMap[best?.id] || -1) ? p : best, null)
    : null;

  const GENDER_LABELS = { mixed: "Mixed", men: "Men", women: "Women" };

  return (
    <div className="flex items-center justify-between py-4 border-b border-slate-100 last:border-0 gap-4">
      <div className="min-w-0">
        <div className="font-semibold text-slate-800 text-sm truncate">{division.name}</div>
        <div className="text-xs text-slate-400 mt-0.5">
          {division.age_bracket} · {GENDER_LABELS[division.gender_category] || division.gender_category}
        </div>
      </div>
      <div className="flex items-center gap-4 text-xs text-slate-500 shrink-0 flex-wrap justify-end">
        <span>{divPartners.length} partners</span>
        <span>{divGroups.length} groups</span>
        {leader && divCompletedMatches.length > 0 && (pointsMap[leader.id] || 0) > 0 && (
          <span className="text-pickle-green font-medium truncate max-w-[120px]">
            🏅 {leader.team_name}
          </span>
        )}
      </div>
    </div>
  );
}

// ── Determine a division's champion + podium from any bracket/standings format ──
function getDivisionChampionInfo(division, divGroups, allPartners, allMatches) {
  const isSE = division.format === "single_elimination";
  const isRR = division.format === "round_robin";
  const groupCount = divGroups.length;
  const advCount = division.advance_count ?? 2;
  const findPartner = (id) => (id ? allPartners.find((p) => p.id === id) : null);

  // Case 1: Has a playoff bracket — find the final match winner
  const playoffMatches = allMatches.filter(
    (m) => m.phase === "playoff" && m.division_id === division.id
  );
  if (playoffMatches.length > 0) {
    const maxRound = Math.max(...playoffMatches.map((m) => m.round || 0));
    if (maxRound < 1) return null;
    const finalMatch = playoffMatches.find((m) => m.round === maxRound && m.status === "completed");
    if (!finalMatch?.winner_id) return null;
    const champion = findPartner(finalMatch.winner_id);
    const runnerUp = findPartner(
      finalMatch.partner_a_id === finalMatch.winner_id
        ? finalMatch.partner_b_id
        : finalMatch.partner_a_id
    );
    const sfMatches = maxRound > 1
      ? playoffMatches.filter((m) => m.round === maxRound - 1 && m.status === "completed")
      : [];
    const semis = sfMatches.flatMap((m) => {
      if (!m.winner_id) return [];
      const loserId = m.partner_a_id === m.winner_id ? m.partner_b_id : m.partner_a_id;
      return loserId ? [findPartner(loserId)].filter(Boolean) : [];
    });
    return { champion, runnerUp, semis };
  }

  // Case 2: SE + 1 group — the group bracket IS the final
  if (isSE && groupCount === 1) {
    const seMs = allMatches.filter(
      (m) =>
        m.phase === "group_stage" &&
        m.division_id === division.id &&
        m.round != null
    );
    if (!seMs.length) return null;
    const maxRound = Math.max(...seMs.map((m) => m.round || 0));
    const finalMatch = seMs.find((m) => m.round === maxRound && m.status === "completed");
    if (!finalMatch?.winner_id) return null;
    const champion = findPartner(finalMatch.winner_id);
    const runnerUp = findPartner(
      finalMatch.partner_a_id === finalMatch.winner_id
        ? finalMatch.partner_b_id
        : finalMatch.partner_a_id
    );
    const sfMatches = maxRound > 1
      ? seMs.filter((m) => m.round === maxRound - 1 && m.status === "completed")
      : [];
    const semis = sfMatches.flatMap((m) => {
      if (!m.winner_id) return [];
      const loserId = m.partner_a_id === m.winner_id ? m.partner_b_id : m.partner_a_id;
      return loserId ? [findPartner(loserId)].filter(Boolean) : [];
    });
    return { champion, runnerUp, semis };
  }

  // Case 3: RR + 1 group + 1 advance → standings leader is champion
  if (isRR && groupCount === 1 && advCount <= 1) {
    const group = divGroups[0];
    if (!group) return null;
    const standings = calculateGroupStandings(group.id, allPartners, allMatches);
    if (!standings.length || standings[0].wins === 0) return null;
    return {
      champion: standings[0].partner,
      runnerUp: standings[1]?.partner || null,
      semis: [],
    };
  }

  return null;
}

// ── Podium section — shows results for any division that has a winner ─────────
function PodiumSection({ divisions, allGroups, allPartners, allMatches }) {
  const podiums = useMemo(() => {
    return divisions
      .map((div) => {
        const divGroups = allGroups.filter((g) => g.division_id === div.id);
        const info = getDivisionChampionInfo(div, divGroups, allPartners, allMatches);
        if (!info?.champion) return null;
        return { division: div, ...info };
      })
      .filter(Boolean);
  }, [divisions, allGroups, allPartners, allMatches]);

  if (podiums.length === 0) return null;

  return (
    <div className="space-y-4">
      <h2 className="text-sm font-bold text-slate-600 uppercase tracking-wide flex items-center gap-2">
        <Medal size={15} /> Podium Results
      </h2>
      {podiums.map(({ division, champion, runnerUp, semis }) => (
        <SurfaceCard key={division.id} title={division.name}>
          <div className="px-5 pb-5 grid grid-cols-2 md:grid-cols-4 gap-3 mt-1">
            {champion && (
              <div className="col-span-2 md:col-span-1 flex items-center gap-3 p-4 bg-amber-50 border border-amber-200 rounded-xl">
                <span className="text-3xl leading-none">🏆</span>
                <div className="min-w-0">
                  <div className="text-[10px] font-bold text-amber-600 uppercase tracking-wide">Champion</div>
                  <div className="font-bold text-slate-900 text-sm truncate">{champion.team_name}</div>
                  <div className="text-xs text-slate-500 truncate">
                    {champion.player_1_name}{champion.player_2_name ? ` & ${champion.player_2_name}` : ""}
                  </div>
                </div>
              </div>
            )}
            {runnerUp && (
              <div className="flex items-center gap-3 p-4 bg-slate-50 border border-slate-200 rounded-xl">
                <span className="text-2xl leading-none">🥈</span>
                <div className="min-w-0">
                  <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Runner-Up</div>
                  <div className="font-semibold text-slate-800 text-sm truncate">{runnerUp.team_name}</div>
                </div>
              </div>
            )}
            {semis.map((s, i) => (
              <div key={s?.id || i} className="flex items-center gap-3 p-4 bg-slate-50 border border-slate-200 rounded-xl">
                <span className="text-xl leading-none">🥉</span>
                <div className="min-w-0">
                  <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wide">Semi-Final</div>
                  <div className="font-medium text-slate-700 text-sm truncate">{s?.team_name || "—"}</div>
                </div>
              </div>
            ))}
          </div>
        </SurfaceCard>
      ))}
    </div>
  );
}

// ── Complete Tournament confirmation modal ────────────────────────────────────
function CompleteModal({ divisions, allGroups, allPartners, allMatches, onConfirm, onCancel }) {
  const winners = useMemo(() => {
    return divisions.map((div) => {
      const divGroups = allGroups.filter((g) => g.division_id === div.id);
      const info = getDivisionChampionInfo(div, divGroups, allPartners, allMatches);
      return { division: div, winner: info?.champion || null };
    });
  }, [divisions, allGroups, allPartners, allMatches]);

  const hasAnyWinner = winners.some((w) => w.winner);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onCancel} />
      <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col">
        {/* Header */}
        <div className="p-6 border-b border-slate-100 flex items-start justify-between">
          <div className="flex items-center gap-2">
            <Flag size={20} className="text-pickle-green" />
            <h2 className="text-lg font-bold text-slate-900">Complete Tournament</h2>
          </div>
          <button onClick={onCancel} className="p-1 rounded text-slate-400 hover:text-slate-600">
            <X size={16} />
          </button>
        </div>

        {/* Division winners list */}
        <div className="p-6 space-y-3 max-h-[55vh] overflow-y-auto">
          <p className="text-xs text-slate-500 mb-1">
            {hasAnyWinner
              ? "Division winners determined so far:"
              : "No division winners have been determined yet. You can still mark the tournament as complete."}
          </p>
          {winners.map(({ division, winner }) => (
            <div
              key={division.id}
              className={`flex items-center justify-between gap-3 p-3.5 rounded-xl border transition-colors ${
                winner
                  ? "bg-amber-50 border-amber-200"
                  : "bg-slate-50 border-slate-200"
              }`}
            >
              <div className="min-w-0">
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">{division.name}</div>
                {winner ? (
                  <>
                    <div className="font-bold text-slate-900 text-sm mt-0.5">
                      🏆 {winner.team_name}
                    </div>
                    <div className="text-xs text-slate-500">
                      {winner.player_1_name}
                      {winner.player_2_name ? ` & ${winner.player_2_name}` : ""}
                    </div>
                  </>
                ) : (
                  <div className="text-xs text-slate-400 italic mt-0.5">No winner determined</div>
                )}
              </div>
              {winner && (
                <span className="text-2xl shrink-0">🏆</span>
              )}
            </div>
          ))}
        </div>

        {/* Actions */}
        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button
            onClick={onCancel}
            className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="px-5 py-2 rounded-lg text-sm font-bold text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm flex items-center gap-1.5"
          >
            <Flag size={13} /> Mark as Completed
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Main tab ──────────────────────────────────────────────────────────────────
export default function OverviewTab({ tournament }) {
  const {
    getDivisionsForTournament,
    getGroupsForDivision,
    getPartnersForTournament,
    getMatchesForTournament,
    startTournament,
    updateTournament,
  } = useTournamentState();

  const divisions = getDivisionsForTournament(tournament.id);
  const allGroups = divisions.flatMap((d) => getGroupsForDivision(d.id));
  const allPartners = getPartnersForTournament(tournament.id);
  const allMatches = getMatchesForTournament(tournament.id);
  const completedMatches = allMatches.filter(
    (m) => m.status === "completed" || m.status === "bye"
  );

  const [showCompleteModal, setShowCompleteModal] = useState(false);

  const canStart = tournament.phase === "setup";
  const canComplete =
    tournament.phase !== "setup" && tournament.phase !== "completed";

  // Count incomplete group-stage matches for the info banner
  const incompleteGroupMatches = allMatches.filter(
    (m) => m.phase === "group_stage" && !["completed", "bye", "cancelled"].includes(m.status)
  ).length;

  const handleConfirmComplete = () => {
    updateTournament(tournament.id, { phase: "completed" });
    setShowCompleteModal(false);
  };

  return (
    <div className="p-4 md:p-6 space-y-6">
      {/* Phase action banner — Start */}
      {canStart && (
        <div className="bg-pickle-green/5 border border-pickle-green/20 rounded-xl p-4 flex items-center justify-between gap-4 flex-wrap">
          <div>
            <p className="text-sm font-semibold text-pickle-green">Ready to start the tournament?</p>
            <p className="text-xs text-slate-500 mt-0.5">
              Assign partners to groups, generate matches in the Divisions tab, then start when ready.
            </p>
          </div>
          <button
            onClick={() => startTournament && startTournament(tournament.id)}
            className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm transition-colors"
          >
            Start Tournament
          </button>
        </div>
      )}

      {/* Group stage progress banner */}
      {tournament.phase === "group_stage" && incompleteGroupMatches > 0 && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 flex items-center justify-between gap-4 flex-wrap">
          <div>
            <p className="text-sm font-semibold text-amber-700">Group stage in progress</p>
            <p className="text-xs text-amber-600 mt-0.5">
              {incompleteGroupMatches} match{incompleteGroupMatches !== 1 ? "es" : ""} remaining. Go to{" "}
              <strong>Bracketing</strong> to advance each division to playoffs.
            </p>
          </div>
        </div>
      )}

      {/* Completed banner */}
      {tournament.phase === "completed" && (
        <div className="bg-green-50 border border-green-200 rounded-xl p-4 flex items-center gap-3">
          <CheckCircle size={20} className="text-green-500 shrink-0" />
          <div>
            <p className="text-sm font-semibold text-green-700">Tournament Completed!</p>
            <p className="text-xs text-green-600 mt-0.5">Final results are shown below.</p>
          </div>
        </div>
      )}

      {/* Stats grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard icon={Users} label="Partners" value={allPartners.length} />
        <StatCard icon={LayoutGrid} label="Groups" value={allGroups.length} />
        <StatCard icon={Trophy} label="Matches" value={allMatches.length} />
        <StatCard
          icon={CheckCircle}
          label="Completed"
          value={completedMatches.length}
          color="text-green-600"
        />
      </div>

      {/* Division summary */}
      {divisions.length > 0 && (
        <SurfaceCard
          title="Divisions"
          actions={
            canComplete ? (
              <button
                onClick={() => setShowCompleteModal(true)}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm transition-colors"
              >
                <Flag size={11} /> Complete Tournament
              </button>
            ) : null
          }
        >
          <div className="px-5 pb-3">
            {divisions.map((d) => (
              <DivisionSummaryRow
                key={d.id}
                division={d}
                allGroups={allGroups}
                allPartners={allPartners}
                allMatches={allMatches}
              />
            ))}
          </div>
        </SurfaceCard>
      )}

      {divisions.length === 0 && (
        <div className="text-center py-10 text-slate-400 text-sm">
          No divisions yet. Go to the <strong>Divisions &amp; Groups</strong> tab to get started.
        </div>
      )}

      {/* Podium — shown whenever any division has a winner */}
      <PodiumSection
        divisions={divisions}
        allGroups={allGroups}
        allPartners={allPartners}
        allMatches={allMatches}
      />

      {/* Complete Tournament modal */}
      {showCompleteModal && (
        <CompleteModal
          divisions={divisions}
          allGroups={allGroups}
          allPartners={allPartners}
          allMatches={allMatches}
          onConfirm={handleConfirmComplete}
          onCancel={() => setShowCompleteModal(false)}
        />
      )}
    </div>
  );
}
