import React from "react";

export default function RentalDetailModal({ isOpen, onClose, data, range }) {
    if (!isOpen || !data) return null;

    const { rentals } = data;
    const { totalRentals, totalIncome, byCourt } = rentals;
    const courtNames = Object.keys(byCourt || {});
    const totalHours = Object.values(byCourt || {}).reduce((a, b) => a + b, 0);

    // Simple formatting helper
    const formatS = (n) => n === 1 ? '' : 's';
    const hoursDisplay = (h) => Number.isInteger(h) ? h : h.toFixed(1);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-lg w-full overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-5 border-b border-gray-100 flex justify-between items-center bg-white sticky top-0">
                    <div>
                        <h2 className="text-lg font-bold text-slate-900">Rental Activity</h2>
                        <p className="text-xs text-slate-500 uppercase tracking-wide">{range} Report</p>
                    </div>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors">✕</button>
                </div>

                <div className="p-6 overflow-y-auto">
                    <div className="grid grid-cols-2 gap-4 mb-8">
                        <div className="p-4 bg-purple-50 rounded-xl border border-purple-100">
                            <p className="text-xs uppercase tracking-wide text-purple-600 font-semibold">Total Revenue</p>
                            <p className="text-2xl font-bold text-purple-900 mt-1">₱{totalIncome.toLocaleString()}</p>
                        </div>
                        <div className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                            <p className="text-xs uppercase tracking-wide text-slate-600 font-semibold">Volume</p>
                            <div className="flex flex-col mt-1">
                                <span className="text-2xl font-bold text-slate-900">{totalRentals} <span className="text-sm font-normal text-slate-500">bookings</span></span>
                            </div>
                        </div>
                    </div>

                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Payment Breakdown</h3>
                    <div className="space-y-2 mb-8">
                        {/* We can use the payments.rentals breakdown if available in data, or reconstruct */}
                        {/* data.payments.rentals is an array of items. Let's aggregate if not already done. */}
                        {(() => {
                            // Struct is from aggregatePayments: { cash: {count, amount}, gcash:..., notPaid:... }
                            const p = data.payments?.rentals || {};

                            // Sum up Paid vs Unpaid
                            const paidAmount = (p.cash?.amount || 0) + (p.gcash?.amount || 0) + (p.gotyme?.amount || 0);
                            const unpaidAmount = (p.notPaid?.amount || 0) + (p.cancelled?.amount || 0);

                            const format = (v) => `₱${(v || 0).toLocaleString()}`;

                            return (
                                <div className="grid grid-cols-2 gap-2 text-sm max-w-sm">
                                    <div className="flex justify-between p-3 bg-emerald-50 rounded-lg border border-emerald-100">
                                        <span className="text-emerald-700 font-medium">Paid</span>
                                        <span className="font-bold text-emerald-900">{format(paidAmount)}</span>
                                    </div>
                                    <div className="flex justify-between p-3 bg-amber-50 rounded-lg border border-amber-100">
                                        <span className="text-amber-700 font-medium">Unpaid</span>
                                        <span className="font-bold text-amber-900">{format(unpaidAmount)}</span>
                                    </div>
                                </div>
                            );
                        })()}
                    </div>

                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Utilization by Court</h3>
                    <div className="space-y-4">
                        {courtNames.length > 0 ? courtNames.sort().map((name) => {
                            const h = byCourt[name];
                            const pct = totalHours ? (h / totalHours) * 100 : 0;
                            return (
                                <div key={name}>
                                    <div className="flex justify-between text-sm mb-1">
                                        <span className="font-medium text-slate-700">{name}</span>
                                        <span className="font-bold text-slate-900">{hoursDisplay(h)} hr{formatS(h)}</span>
                                    </div>
                                    <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                                        <div className="bg-purple-500 h-full rounded-full" style={{ width: `${pct}%` }}></div>
                                    </div>
                                </div>
                            );
                        }) : (
                            <div className="p-4 text-center text-sm text-slate-400 bg-slate-50 rounded-lg border border-dashed border-slate-200">
                                No rental activity recorded for this period.
                            </div>
                        )}
                    </div>

                    <div className="mt-6 pt-4 border-t border-slate-100 text-right">
                        <p className="text-xs text-slate-400">Total Utilization: {hoursDisplay(totalHours)} hours</p>
                    </div>
                </div>
            </div>
        </div>
    );
}
