import React, { useState, useEffect } from "react";
import { validateScores } from "../utils/matchValidation";

function GameRow({ gameNumber, scores, onChange, readOnly }) {
  return (
    <div className="flex items-center gap-3">
      <span className="text-xs text-slate-400 w-12 text-right">Game {gameNumber}</span>
      <input
        type="number"
        min="0"
        className="w-16 border border-slate-200 rounded-lg px-2 py-1.5 text-sm text-center focus:outline-none focus:ring-2 focus:ring-pickle-green/30 disabled:bg-slate-50"
        value={scores.partner_a ?? ""}
        onChange={(e) => onChange({ ...scores, partner_a: e.target.value === "" ? "" : Number(e.target.value) })}
        disabled={readOnly}
        placeholder="0"
      />
      <span className="text-slate-400 font-medium">vs</span>
      <input
        type="number"
        min="0"
        className="w-16 border border-slate-200 rounded-lg px-2 py-1.5 text-sm text-center focus:outline-none focus:ring-2 focus:ring-pickle-green/30 disabled:bg-slate-50"
        value={scores.partner_b ?? ""}
        onChange={(e) => onChange({ ...scores, partner_b: e.target.value === "" ? "" : Number(e.target.value) })}
        disabled={readOnly}
        placeholder="0"
      />
    </div>
  );
}

export default function ScoreEntryModal({ match, partnerA, partnerB, tournament, onSave, onClose, prefillScores }) {
  const bestOf = tournament?.best_of || 1;
  const maxGames = bestOf;
  const gamesNeeded = Math.ceil(bestOf / 2);

  const defaultScores = match.scores?.length > 0
    ? match.scores.map((s) => ({ game: s.game, partner_a: s.partner_a, partner_b: s.partner_b }))
    : [{ game: 1, partner_a: "", partner_b: "" }];

  const [gameScores, setGameScores] = useState(prefillScores ?? defaultScores);
  const readOnly = match.status === "completed";

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const updateGame = (index, scores) => {
    const updated = [...gameScores];
    updated[index] = { ...updated[index], ...scores };
    setGameScores(updated);
  };

  const addGame = () => {
    if (gameScores.length >= maxGames) return;
    setGameScores((prev) => [...prev, { game: prev.length + 1, partner_a: "", partner_b: "" }]);
  };

  const removeGame = (index) => {
    if (gameScores.length <= 1) return;
    setGameScores((prev) => prev.filter((_, i) => i !== index).map((s, i) => ({ ...s, game: i + 1 })));
  };

  const scoresToValidate = gameScores.map((s) => ({
    game: s.game,
    partner_a: Number(s.partner_a || 0),
    partner_b: Number(s.partner_b || 0),
  }));

  const settings = {
    points_to_win: tournament?.points_to_win || 11,
    win_by: tournament?.win_by || 2,
    best_of: bestOf,
  };

  const { valid, winner, error } = validateScores(scoresToValidate, settings);

  const winnerName =
    winner === "a" ? partnerA?.team_name : winner === "b" ? partnerB?.team_name : null;

  const handleSave = () => {
    if (!valid) return;
    onSave(scoresToValidate);
  };

  const roundLabel =
    match.phase === "playoff"
      ? `Playoff Round ${match.round}`
      : `Group Stage · Round ${match.round}`;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-sm flex flex-col">
        <div className="p-6 border-b border-slate-100">
          <p className="text-xs text-slate-400 mb-1">{roundLabel}</p>
          <div className="flex items-center gap-2 text-sm font-semibold text-slate-800">
            <span className="truncate">{partnerA?.team_name || "TBD"}</span>
            <span className="text-slate-400 shrink-0">vs</span>
            <span className="truncate">{partnerB?.team_name || "TBD"}</span>
          </div>
          {match.court && (
            <p className="text-xs text-slate-400 mt-1">{match.court}</p>
          )}
        </div>

        <div className="p-6 flex flex-col gap-3">
          <div className="flex items-center justify-between mb-1">
            <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide">Scores</p>
            <div className="flex items-center gap-2 text-xs text-slate-400">
              <span className="font-medium text-pickle-green truncate max-w-[80px]">{partnerA?.team_name}</span>
              <span>vs</span>
              <span className="font-medium text-pickle-green truncate max-w-[80px]">{partnerB?.team_name}</span>
            </div>
          </div>

          {gameScores.map((s, i) => (
            <div key={i} className="flex items-center gap-2">
              <div className="flex-1">
                <GameRow
                  gameNumber={i + 1}
                  scores={s}
                  onChange={(val) => updateGame(i, val)}
                  readOnly={readOnly}
                />
              </div>
              {!readOnly && gameScores.length > 1 && (
                <button
                  onClick={() => removeGame(i)}
                  className="text-slate-300 hover:text-red-400 text-xs px-1"
                >
                  ×
                </button>
              )}
            </div>
          ))}

          {!readOnly && gameScores.length < maxGames && (
            <button
              onClick={addGame}
              className="text-xs text-pickle-green hover:underline self-start"
            >
              + Add Game {gameScores.length + 1}
            </button>
          )}

          {/* Winner preview */}
          {winnerName && (
            <div className="bg-green-50 border border-green-200 rounded-lg px-3 py-2 text-sm font-semibold text-green-700 text-center">
              🏆 Winner: {winnerName}
            </div>
          )}
          {!valid && !winnerName && scoresToValidate.some((s) => s.partner_a > 0 || s.partner_b > 0) && error && (
            <p className="text-xs text-red-500 text-center">{error}</p>
          )}
        </div>

        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100">
            {readOnly ? "Close" : "Cancel"}
          </button>
          {!readOnly && (
            <button
              onClick={handleSave}
              disabled={!valid}
              className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
            >
              Save Result
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
