import React, { useMemo } from "react";
import BracketView from "../BracketView";

export default function DisplayBracket({ tournament, divisions, matches, partners, filterDivisionId }) {
  const partnerMap = useMemo(() => Object.fromEntries(partners.map((p) => [p.id, p])), [partners]);

  const playoffDivisions = divisions.filter((d) => {
    if (filterDivisionId && d.id !== filterDivisionId) return false;
    const divMatches = matches.filter((m) => m.division_id === d.id && m.phase === "playoff");
    return divMatches.length > 0;
  });

  if (playoffDivisions.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center text-center">
        <div>
          <div className="text-pickle-cream/30 font-oswald text-3xl uppercase tracking-widest mb-2">Playoffs Not Started</div>
          <div className="text-pickle-cream/20 font-body text-base">Playoff brackets will appear here when playoffs begin.</div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 p-6 overflow-auto">
      {playoffDivisions.map((div) => {
        const divMatches = matches.filter((m) => m.division_id === div.id && m.phase === "playoff");
        return (
          <div key={div.id} className="mb-8">
            <h2 className="font-oswald text-pickle-cream text-2xl mb-4 uppercase tracking-wide">{div.name}</h2>
            <div className="bg-white rounded-2xl p-4 overflow-x-auto">
              <BracketView matches={divMatches} partners={partnerMap} onEdit={null} />
            </div>
          </div>
        );
      })}
    </div>
  );
}
