import React, { useEffect, useState } from "react";
import config from "../../../config";
import PlayerLeaderboardTable from "./PlayerLeaderboardTable";

export default function PlayerLeaderboardOverlay({ rows, until, onClose }) {
  const [remaining, setRemaining] = useState(() => Math.max(0, Math.ceil((until - Date.now()) / 1000)));

  useEffect(() => {
    let closed = false;
    const tick = () => {
      const next = Math.max(0, Math.ceil((until - Date.now()) / 1000));
      setRemaining(next);
      if (next <= 0 && !closed) {
        closed = true;
        onClose?.();
      }
    };
    tick();
    const id = setInterval(tick, 250);
    return () => clearInterval(id);
  }, [until, onClose]);

  return (
    <div className="fixed inset-0 z-[80] bg-[#3E430F] flex flex-col p-6 md:p-10">
      <header className="flex items-center justify-between mb-6 shrink-0">
        <div className="flex items-center gap-4">
          <img
            src={config.assetPath("logo.jpg")}
            alt={config.displayName}
            className="h-16 md:h-20 w-auto object-contain"
          />
          <div>
            <p className="text-[10px] uppercase tracking-[0.28em] text-[#F8DFBA] font-semibold">Premium Court Experience</p>
            <h2 className="text-white text-2xl md:text-3xl font-bold tracking-wide">Leaderboards</h2>
          </div>
        </div>
        <div className="text-right">
          <p className="text-[10px] uppercase tracking-[0.2em] text-white/40">Closes in</p>
          <p className="text-3xl font-oswald font-bold text-[#9C824A] tabular-nums">
            {Math.floor(remaining / 60)}:{String(remaining % 60).padStart(2, "0")}
          </p>
        </div>
      </header>
      <div className="flex-1 min-h-0 bg-[#3A4D39] rounded-2xl border border-[#9C824A]/30 p-4 md:p-6 overflow-hidden">
        <PlayerLeaderboardTable
          rows={rows}
          variant="display"
          emptyLabel="No players yet."
        />
      </div>
    </div>
  );
}
