import React, { useMemo, useState } from "react";
import { useAppState } from "../../app/providers";
import { selectCalendarState } from "../../state/selectors";
import { SurfaceCard, ConfirmationModal } from "../../common/components";

function formatHourLabel(h) {
  const suffix = h >= 12 ? "PM" : "AM";
  const hour12 = ((h + 11) % 12) + 1;
  return `${hour12}:00 ${suffix}`;
}

function getYMD(date) {
  return date.toISOString().slice(0, 10);
}

function startOfMonth(date) {
  const d = new Date(date.getFullYear(), date.getMonth(), 1);
  d.setHours(0, 0, 0, 0);
  return d;
}

function endOfMonth(date) {
  const d = new Date(date.getFullYear(), date.getMonth() + 1, 0);
  d.setHours(23, 59, 59, 999);
  return d;
}

function getMonthMatrix(currentDate) {
  const first = startOfMonth(currentDate);
  const last = endOfMonth(currentDate);

  const firstDayOfWeek = first.getDay(); // 0 (Sun) - 6 (Sat)
  const daysInMonth = last.getDate();

  const weeks = [];
  let week = [];

  // leading blanks
  for (let i = 0; i < firstDayOfWeek; i += 1) {
    week.push(null);
  }

  for (let day = 1; day <= daysInMonth; day += 1) {
    const d = new Date(first.getFullYear(), first.getMonth(), day);
    week.push(d);
    if (week.length === 7) {
      weeks.push(week);
      week = [];
    }
  }

  if (week.length) {
    while (week.length < 7) week.push(null);
    weeks.push(week);
  }

  return weeks;
}

export default function CalendarPage() {
  const {
    settings,
    calendarCourts,
    bookings,
    addBooking,
    updateBooking,
    removeBooking,
    updateCalendarCourtName,
  } = useAppState(selectCalendarState);

  const safeCalendarCourts = Array.isArray(calendarCourts) ? calendarCourts : [];

  const [selectedDate, setSelectedDate] = useState(() => getYMD(new Date()));
  const [viewMode, setViewMode] = useState("month"); // "month" | "day"
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState("");
  const [toast, setToast] = useState(null); // { message, type: 'success'|'error' }
  const [relatedBookings, setRelatedBookings] = useState([]);
  const [confirmModal, setConfirmModal] = useState({
    isOpen: false,
    title: "",
    message: "",
    onConfirm: () => { },
    isDestructive: false
  });
  const closeConfirm = () => setConfirmModal(prev => ({ ...prev, isOpen: false }));

  // Auto-dismiss toast
  React.useEffect(() => {
    if (toast) {
      const timer = setTimeout(() => setToast(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [toast]);

  const openHour = settings?.calendarOpenHour ?? 7;
  const closeHour = settings?.calendarCloseHour ?? 21; // exclusive

  const HOURS = useMemo(
    () => Array.from({ length: closeHour - openHour }, (_, i) => openHour + i),
    [openHour, closeHour]
  );
  const dayBookings = useMemo(
    () => bookings.filter((b) => b.date === selectedDate),
    [bookings, selectedDate]
  );

  const selectedDateObj = useMemo(() => new Date(selectedDate), [selectedDate]);
  const monthMatrix = useMemo(() => getMonthMatrix(selectedDateObj), [selectedDateObj]);

  const dailySummaryMap = useMemo(() => {
    const map = new Map();
    if (!Array.isArray(bookings)) return map;
    const openMinutes = (closeHour - openHour) * 60;
    const courtCount = safeCalendarCourts.length || 0;
    const capacityMinutes = openMinutes * courtCount;

    bookings.forEach((b) => {
      if (!b?.date) return;
      const used = Math.max(0, (b.endMinutes ?? 0) - (b.startMinutes ?? 0));
      const prev =
        map.get(b.date) || {
          bookings: 0,
          usedMinutes: 0,
          rentalCount: 0,
          openPlayCount: 0,
        };
      map.set(b.date, {
        bookings: prev.bookings + 1,
        usedMinutes: prev.usedMinutes + used,
        capacityMinutes,
        rentalCount:
          (b.bookingType || "rental") === "rental"
            ? prev.rentalCount + 1
            : prev.rentalCount,
        openPlayCount:
          b.bookingType === "open_play_block"
            ? prev.openPlayCount + 1
            : prev.openPlayCount,
      });
    });
    return map;
  }, [bookings, safeCalendarCourts.length, openHour, closeHour]);

  const handleCreate = (courtId, hour) => {
    const id = `bk-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
    const startHour = hour;
    const endHour = hour + 1;
    setEditing({
      id,
      courtId,
      date: selectedDate,
      title: "",
      // Default booking type to rental; Open Play blocks can still be chosen explicitly in the modal.
      bookingType: "rental",
      // Default payment status is Unpaid until explicitly marked otherwise.
      paymentStatus: "unpaid",
      paymentMethod: null,
      rentalPrice: "", // empty means auto-calc or 0
      startMinutes: startHour * 60,
      endMinutes: endHour * 60,
      renterId: "",
      renterName: "",
      renterContact: "",
      renterEmail: "",
      recurrenceWeeks: 0,
      isNew: true,
    });
  };

  const handleEdit = (booking) => {
    // Find related bookings in same session
    const related = (booking.renterId && booking.bookingType === 'rental')
      ? bookings.filter(b => b.renterId === booking.renterId && b.id !== booking.id)
      : [];

    setRelatedBookings(related);
    setEditing({
      ...booking,
      bookingType: booking.bookingType || "rental",
      recurrenceWeeks: 0,
      isNew: false,
    });
  };

  const handleRemoveRelated = (id) => {
    setConfirmModal({
      isOpen: true,
      title: "Remove Linked Booking?",
      message: "Remove this specific court/hour block from the group?",
      confirmLabel: "Remove",
      isDestructive: true,
      onConfirm: () => {
        removeBooking(id);
        setRelatedBookings(prev => prev.filter(b => b.id !== id));
        setToast({ message: "Block removed.", type: 'success' });
        closeConfirm();
      }
    });
  };

  const handleDelete = (booking) => {
    if (booking.paymentStatus === 'paid') {
      setToast({ message: "Cannot delete a PAID booking. Please mark as Unpaid first.", type: 'error' });
      return;
    }
    setConfirmModal({
      isOpen: true,
      title: "Delete Booking?",
      message: "Are you sure you want to delete this booking? This action cannot be undone.",
      confirmLabel: "Delete",
      isDestructive: true,
      onConfirm: () => {
        removeBooking(booking.id);
        setEditing(null);
        setToast({ message: "Booking deleted.", type: 'success' });
        closeConfirm();
      }
    });
  };

  const handleSave = () => {
    if (!editing) return;
    setError("");
    const { isNew, recurrenceWeeks, recurrencePattern, targetCourtMode, selectedCourtIds, ...payload } = editing;

    // 1. Auto-Title & Type defaults
    if (payload.bookingType === "open_play_block") {
      payload.title = "Open Play";
      payload.paymentStatus = "unpaid";
    } else {
      // Rental Logic
      // 2. Validation
      if (!payload.renterName?.trim()) {
        setError("Renter Name is required.");
        return;
      }
      if (!payload.renterContact?.trim()) {
        setError("Renter Contact is required.");
        return;
      }
      // Email is often optional but user asked "all renter details is required"
      if (!payload.renterEmail?.trim()) {
        setError("Renter Email is required.");
        return;
      }

      // Auto-set title
      payload.title = `Rental ${payload.renterName}`;
    }

    try {
      if (editing.isNew) {
        const courtList =
          (editing.targetCourtMode || "single") === "multi" &&
            Array.isArray(editing.selectedCourtIds) &&
            editing.selectedCourtIds.length > 0
            ? editing.selectedCourtIds
            : [editing.courtId];

        // Auto-generate Renter ID for NEW rentals
        let finalRenterId = editing.renterId;
        if (editing.bookingType === "rental") {
          const ymd = editing.date.replace(/-/g, ""); // 20251217
          const courtCount = courtList.length;
          const durationHours = Math.round((editing.endMinutes - editing.startMinutes) / 60);

          const existingRentals = bookings.filter(b => b.date === editing.date && b.bookingType === "rental");
          let maxSeq = 0;

          const seenIds = new Set();
          existingRentals.forEach(b => {
            if (b.renterId) seenIds.add(b.renterId);
          });

          seenIds.forEach(id => {
            const parts = id.split('-');
            if (parts.length === 3 && parts[0] === ymd) {
              const seq = parseInt(parts[2], 10);
              if (!isNaN(seq) && seq > maxSeq) maxSeq = seq;
            }
          });

          const newSeq = maxSeq + 1;
          finalRenterId = `${ymd}-${courtCount}${durationHours}-${newSeq}`;
        }

        const newBookings = courtList.map((cId) => ({
          id: crypto.randomUUID(),
          courtId: cId,
          title: payload.title,
          date: editing.date,
          startMinutes: editing.startMinutes,
          endMinutes: editing.endMinutes,
          bookingType: editing.bookingType,
          paymentStatus: editing.paymentStatus || "unpaid",
          paymentMethod: editing.paymentMethod || null,
          rentalPrice: typeof editing.rentalPrice === 'number' ? editing.rentalPrice : null,
          renterName: editing.renterName || "",
          renterId: finalRenterId || "",
          renterContact: editing.renterContact || "",
          renterEmail: editing.renterEmail || "",
          notes: editing.notes || "",
          recurrenceId: null,
        }));

        const createdDates = [];
        const skippedDates = [];

        const isDaily = editing.recurrencePattern === "daily";
        const weeks = Math.min(Number(editing.recurrenceWeeks) || 0, 4);
        const stepDays = isDaily ? 1 : 7;
        const totalDays = weeks * 7;

        for (let dayOffset = 0; dayOffset <= totalDays; dayOffset += stepDays) {
          const d = new Date(editing.date);
          d.setDate(d.getDate() + dayOffset);
          const ymd = d.toISOString().slice(0, 10);

          for (const bookingTemplate of newBookings) {
            const booking = {
              ...bookingTemplate,
              id: dayOffset === 0 && bookingTemplate.courtId === editing.courtId
                ? (editing.id || bookingTemplate.id)
                : `bk-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
              date: ymd,
              seriesId: editing.bookingType === "open_play_block" && weeks > 0 ? `series-${Date.now()}` : null
            };

            try {
              addBooking(booking);
              createdDates.push(`${ymd}:${booking.courtId}`);
            } catch (err) {
              console.warn("Skipped conflicting", ymd, err);
              skippedDates.push(`${ymd}:${booking.courtId}`);
            }
          }
        }

        if (skippedDates.length > 0) {
          setToast({ message: "Some conflicting dates/courts were skipped.", type: 'error' });
        } else {
          setToast({ message: "Booking created successfully.", type: 'success' });
        }
      } else {
        // Edit Existing
        // TODO: Handle "Apply to Linked" logic if we add that checkbox
        updateBooking(editing.id, payload);
        setToast({ message: "Booking updated.", type: 'success' });
      }
      setEditing(null);
    } catch (e) {
      setError(e.message || "Unable to save booking.");
      setToast({ message: e.message || "Error saving booking", type: 'error' });
    }
  };

  const changeDay = (delta) => {
    const date = new Date(selectedDate);
    date.setDate(date.getDate() + delta);
    setSelectedDate(getYMD(date));
  };

  const changeMonth = (delta) => {
    const date = new Date(selectedDate);
    date.setMonth(date.getMonth() + delta);
    // clamp to same day-of-month when possible
    setSelectedDate(getYMD(date));
  };

  const handleSelectDayFromMonth = (dateObj) => {
    if (!dateObj) return;
    setSelectedDate(getYMD(dateObj));
    setViewMode("day");
  };

  const renderDayUsageBadge = () => {
    const summary = dailySummaryMap.get(selectedDate);
    if (!summary || !summary.capacityMinutes) return null;
    const pct = Math.round((summary.usedMinutes / summary.capacityMinutes) * 100);
    const { estimatedRevenue } = (() => {
      const list = bookings.filter(
        (b) => b.date === selectedDate && (b.bookingType || "rental") === "rental"
      );
      let revenue = 0;
      list.forEach((b) => {
        const price = typeof b.rentalPrice === "number" && !Number.isNaN(b.rentalPrice)
          ? b.rentalPrice
          : 0;
        revenue += price;
      });
      return { estimatedRevenue: Math.round(revenue) };
    })();
    return (
      <span className="ml-2 inline-flex items-center rounded-full bg-gray-100 px-2 py-0.5 text-[11px] text-gray-700">
        {summary.bookings} booking{summary.bookings !== 1 ? "s" : ""} • {pct}% of court-hours used
        {estimatedRevenue > 0 && (
          <>
            {" "}• est. rental {new Intl.NumberFormat("en-PH", {
              style: "currency",
              currency: "PHP",
              maximumFractionDigits: 0,
            }).format(estimatedRevenue)}
          </>
        )}
      </span>
    );
  };

  const dayUsageBadge = renderDayUsageBadge();

  return (
    <div className="p-4 flex flex-col gap-4 h-full bg-slate-50 overflow-hidden">
      <SurfaceCard
        title="Court Calendar"
        description="Admin-only view of court rentals and Open Play blocks, aligned with Queue & History."
      >
        {toast && (
          <div className={`fixed top-4 right-4 z-[100] px-4 py-2 rounded shadow-lg text-white text-sm font-medium animate-in fade-in slide-in-from-top-2 ${toast.type === 'error' ? 'bg-red-600' : 'bg-emerald-600'}`}>
            {toast.message}
          </div>
        )}
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between text-xs">
          <div className="flex items-center border border-slate-200 rounded-full overflow-hidden bg-white">
            <button
              type="button"
              onClick={() => setViewMode("month")}
              className={`px-3 py-1 text-xs rounded-full transition-colors ${viewMode === "month"
                ? "bg-[#1E3A8A] text-white"
                : "bg-white text-slate-700 hover:bg-slate-50"
                }`}
            >
              Month
            </button>
            <button
              type="button"
              onClick={() => setViewMode("day")}
              className={`px-3 py-1 text-xs rounded-full transition-colors ${viewMode === "day"
                ? "bg-[#1E3A8A] text-white"
                : "bg-white text-slate-700 hover:bg-slate-50"
                }`}
            >
              Day
            </button>
          </div>
          <div className="flex flex-wrap items-center gap-2 text-xs">
            <button
              type="button"
              onClick={() => (viewMode === "day" ? changeDay(-1) : changeMonth(-1))}
              className="px-2 py-1 border border-slate-200 rounded-lg text-xs bg-white hover:bg-slate-50"
            >
              Prev
            </button>
            <input
              type="date"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
              className="border border-slate-200 rounded-lg px-2 py-1 text-xs bg-white focus:outline-none focus:ring-1 focus:ring-sky-400 focus:border-sky-400"
            />
            <button
              type="button"
              onClick={() => (viewMode === "day" ? changeDay(1) : changeMonth(1))}
              className="px-2 py-1 border border-slate-200 rounded-lg text-xs bg-white hover:bg-slate-50"
            >
              Next
            </button>
            <button
              type="button"
              onClick={() => setSelectedDate(getYMD(new Date()))}
              className="px-2 py-1 border border-slate-200 rounded-lg text-xs bg-white hover:bg-slate-50"
            >
              Today
            </button>
          </div>
        </div>
        <div className="mt-2 text-[11px] text-gray-500 flex items-center gap-2 flex-wrap">
          <span>
            {safeCalendarCourts.length} calendar court{safeCalendarCourts.length !== 1 ? "s" : ""}
          </span>
        </div>
      </SurfaceCard>

      {viewMode === "month" ? (
        <SurfaceCard
          className="flex-1 min-h-0 overflow-hidden"
          padded={false}
          bodyClassName="h-full overflow-auto p-3"
        >
          <div className="mb-2 flex items-center justify-between text-xs text-gray-600">
            <div className="flex items-baseline gap-2">
              <span className="text-sm font-semibold text-gray-900">
                {selectedDateObj.toLocaleString("default", { month: "long", year: "numeric" })}
              </span>
              <span className="text-[11px] text-gray-500">
                Tap a day to switch to detailed day view
              </span>
            </div>
            <div className="hidden sm:flex items-center gap-3 text-[10px] text-gray-500">
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded bg-blue-100 border border-blue-300" />
                <span>Open Play blocks</span>
              </div>
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded bg-emerald-100 border border-emerald-300" />
                <span>Paid rentals</span>
              </div>
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded bg-amber-100 border border-amber-300" />
                <span>Tentative rentals</span>
              </div>
            </div>
          </div>
          <table className="w-full text-[11px]">
            <thead>
              <tr className="text-gray-500 border-b">
                {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d) => (
                  <th key={d} className="py-1 text-center font-normal">
                    {d}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {monthMatrix.map((week, wi) => (
                <tr key={wi}>
                  {week.map((dateObj, di) => {
                    if (!dateObj) {
                      return <td key={di} className="h-20 border-t bg-gray-50" />;
                    }
                    const ymd = getYMD(dateObj);
                    const summary = dailySummaryMap.get(ymd);
                    const isToday = ymd === getYMD(new Date());
                    const isSelected = ymd === selectedDate;

                    // derive a soft background based on utilization
                    let utilClass = "bg-white";
                    if (summary && summary.capacityMinutes > 0) {
                      const pct = (summary.usedMinutes / summary.capacityMinutes) * 100;
                      if (pct >= 60) utilClass = "bg-emerald-50";
                      else if (pct >= 30) utilClass = "bg-sky-50";
                      else if (pct > 0) utilClass = "bg-slate-50";
                    }

                    const highlightBorder = isSelected
                      ? "border-2 border-blue-500"
                      : isToday
                        ? "border border-emerald-400"
                        : "border border-gray-200";

                    return (
                      <td key={di} className="align-top p-1">
                        <button
                          type="button"
                          onClick={() => handleSelectDayFromMonth(dateObj)}
                          className={`w-full h-20 rounded-xl text-left px-2 pt-1 pb-1 flex flex-col ${utilClass} ${highlightBorder} hover:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500`}
                        >
                          <div className="flex items-center justify-between mb-0.5">
                            <span className="text-[11px] font-semibold text-gray-800">
                              {dateObj.getDate()}
                            </span>
                            {isToday && (
                              <span className="text-[10px] px-1 py-0.5 rounded-full bg-emerald-100 text-emerald-700">
                                Today
                              </span>
                            )}
                          </div>
                          {summary && summary.capacityMinutes > 0 ? (
                            <div className="mt-auto flex flex-col gap-0.5 text-[10px] leading-tight">
                              <div className="flex items-center justify-between text-gray-600">
                                <span>
                                  {summary.bookings} booking
                                  {summary.bookings !== 1 ? "s" : ""}
                                </span>
                                <span className="font-medium">
                                  {Math.round(
                                    (summary.usedMinutes / summary.capacityMinutes) * 100
                                  )}
                                  %
                                </span>
                              </div>
                              <div className="flex items-center justify-between text-gray-500">
                                <span>
                                  {summary.rentalCount || 0}R
                                  {" / "}
                                  {summary.openPlayCount || 0}OP
                                </span>
                              </div>
                              <div className="h-1.5 w-full rounded-full bg-gray-100 overflow-hidden">
                                <div
                                  className="h-full bg-emerald-500"
                                  style={{
                                    width: `${Math.min(
                                      100,
                                      Math.round(
                                        (summary.usedMinutes / summary.capacityMinutes) * 100
                                      )
                                    )}%`,
                                  }}
                                />
                              </div>
                            </div>
                          ) : (
                            <div className="mt-auto text-[10px] text-gray-400">No bookings</div>
                          )}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </SurfaceCard>
      ) : (
        <div className="flex-1 min-h-0 flex flex-col gap-3 overflow-hidden">
          <SurfaceCard>
            <div className="flex flex-col gap-1 sm:flex-row sm:items-center sm:justify-between text-[11px] text-slate-600">
              <span className="font-medium text-slate-800">
                {selectedDateObj.toLocaleDateString(undefined, {
                  weekday: "long",
                  month: "short",
                  day: "numeric",
                })}
              </span>
              {dayUsageBadge && <div className="flex items-center gap-2">{dayUsageBadge}</div>}
            </div>
          </SurfaceCard>
          <SurfaceCard
            className="flex-1 min-h-0"
            padded={false}
            bodyClassName="flex-1 min-h-0"
          >
            <div className="flex-1 min-h-0 overflow-auto">
              <table className="min-w-full text-xs">
                <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="p-2 text-left w-40 text-[11px] text-slate-600 font-semibold">Court</th>
                    {HOURS.map((h) => (
                      <th
                        key={h}
                        className="p-1 text-center border-l border-slate-100 text-[10px] text-slate-500 font-medium"
                      >
                        {formatHourLabel(h).replace(":00 ", " ")}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {safeCalendarCourts.map((court) => (
                    <tr key={court.id} className="border-t border-slate-100 align-top">
                      <td className="p-2 font-medium text-slate-700 border-r border-slate-100 whitespace-nowrap align-top bg-slate-50/60">
                        <input
                          type="text"
                          value={court.name}
                          onChange={(e) => updateCalendarCourtName(court.id, e.target.value)}
                          className="border border-slate-200 rounded-lg px-1.5 py-0.5 text-[11px] w-full bg-white focus:outline-none focus:ring-1 focus:ring-sky-400 focus:border-sky-400"
                        />
                      </td>
                      {HOURS.map((h) => {
                        const cellStart = h * 60;
                        const cellEnd = (h + 1) * 60;
                        const cellBookings = dayBookings.filter(
                          (b) =>
                            b.courtId === court.id &&
                            b.startMinutes < cellEnd &&
                            b.endMinutes > cellStart
                        );

                        const first = cellBookings[0];

                        return (
                          <td
                            key={h}
                            className="relative h-16 border-l border-slate-100 cursor-pointer hover:bg-slate-50/70"
                            onClick={() => handleCreate(court.id, h)}
                          >
                            {first && (
                              <div
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleEdit(first);
                                }}
                                className={`absolute inset-1 rounded-xl px-1.5 py-1 text-[11px] flex flex-col justify-center overflow-hidden text-white shadow-sm ${first.bookingType === "open_play_block"
                                  ? "bg-[#1E3A8A]"
                                  : (first.paymentStatus || "unpaid").toLowerCase() === "cancelled"
                                    ? "bg-red-600"
                                    : (first.paymentStatus === 'paid' || first.paymentStatus === 'free' || first.paymentStatus === 'cash' || first.paymentStatus === 'gcash')
                                      ? "bg-emerald-600"
                                      : "bg-amber-500"
                                  }`}
                              >
                                <span className="truncate font-semibold tracking-tight">
                                  {first.bookingType === "open_play_block" ? "Open Play" : first.title}
                                </span>
                                {first.bookingType !== "open_play_block" && (
                                  <span className="text-[10px] opacity-85 capitalize">
                                    {(() => {
                                      const s = (first.paymentStatus || "unpaid").toLowerCase();
                                      const m = (first.paymentMethod || "").toLowerCase();
                                      if (s === "cancelled") return "Cancelled";
                                      if (s === "free") return "Free";
                                      if (s === "paid") return m === 'gcash' ? 'GCash' : m === 'gotyme' ? 'GoTyme' : 'Cash';
                                      // Legacy fallback
                                      if (s === "cash") return "Cash";
                                      if (s === "gcash") return "GCash";
                                      return "Unpaid";
                                    })()}
                                  </span>
                                )}
                              </div>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </SurfaceCard>
          <SurfaceCard>
            <div className="text-[10px] text-slate-600 flex gap-4 flex-wrap">
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded-full bg-[#1E3A8A]" />
                <span>Open Play block</span>
              </div>
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded-full bg-emerald-600" />
                <span>Paid (Cash/GCash)</span>
              </div>
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded-full bg-amber-500" />
                <span>Unpaid / Tentative</span>
              </div>
              <div className="flex items-center gap-1">
                <span className="inline-block w-3 h-3 rounded-full bg-red-600" />
                <span>Cancelled</span>
              </div>
            </div>
          </SurfaceCard>
        </div>
      )}

      {editing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30">
          <div className="bg-white rounded-lg shadow-xl max-w-sm w-full mx-4 p-4 text-xs overflow-y-auto max-h-[90vh]">
            <h2 className="text-sm font-semibold mb-2">
              {editing.isNew ? "New Booking" : "Edit Booking"}
            </h2>
            <div className="space-y-2">
              {error && (
                <div className="text-[11px] text-red-600 mb-1">{error}</div>
              )}
              {/* Title Input Removed - Auto-generated */}

              {/* Renter Details Section */}
              {editing.bookingType !== "open_play_block" && (
                <div className="space-y-2 p-2 bg-slate-50 rounded border border-slate-100 mb-2">
                  {/* Handle Save Logic handles ID generation now */}
                  <div className="grid grid-cols-1 gap-2">
                    <div>
                      <label className="block mb-1 text-slate-600">Renter Name</label>
                      <input
                        type="text"
                        value={editing.renterName || ""}
                        onChange={(e) => setEditing({ ...editing, renterName: e.target.value })}
                        className="w-full border rounded px-2 py-1 text-xs bg-white"
                        placeholder="Name"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="block mb-1 text-slate-600">Contact</label>
                      <input
                        type="text"
                        value={editing.renterContact || ""}
                        onChange={(e) => setEditing({ ...editing, renterContact: e.target.value })}
                        className="w-full border rounded px-2 py-1 text-xs bg-white"
                        placeholder="Mobile/Phone"
                      />
                    </div>
                    <div>
                      <label className="block mb-1 text-slate-600">Email</label>
                      <input
                        type="email"
                        value={editing.renterEmail || ""}
                        onChange={(e) => setEditing({ ...editing, renterEmail: e.target.value })}
                        className="w-full border rounded px-2 py-1 text-xs bg-white"
                        placeholder="Email"
                      />
                    </div>
                  </div>
                </div>
              )}

              {/* Payment Details Section */}
              {editing.bookingType !== "open_play_block" && (
                <div className="space-y-3 p-3 bg-slate-50 rounded border border-slate-100 mb-2">
                  {/* Payment Status Toggle */}
                  <div>
                    <label className="block mb-2 text-slate-600 font-medium">Payment Status</label>
                    <div className="flex gap-2">
                      <button
                        type="button"
                        onClick={() => {
                          // Switch to Paid
                          // Default to GCash if no method set
                          let newMethod = editing.paymentMethod;
                          if (!newMethod) newMethod = 'gcash';

                          // Auto-calc price if missing
                          let newPrice = editing.rentalPrice;
                          if (newPrice === "" || newPrice === undefined || newPrice === null) {
                            const durationHours = Math.max(0, (editing.endMinutes - editing.startMinutes) / 60);
                            const rate = settings?.defaultRentalRate || 800;
                            newPrice = durationHours * rate;
                          }
                          setEditing({ ...editing, paymentStatus: 'paid', paymentMethod: newMethod, rentalPrice: newPrice });
                        }}
                        className={`flex-1 py-1.5 px-3 rounded-lg border text-xs font-semibold transition-all ${editing.paymentStatus === 'paid'
                          ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm'
                          : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                          }`}
                      >
                        Paid
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          // Switch to Unpaid
                          setEditing({ ...editing, paymentStatus: 'unpaid', paymentMethod: null });
                        }}
                        className={`flex-1 py-1.5 px-3 rounded-lg border text-xs font-semibold transition-all ${(editing.paymentStatus || 'unpaid') === 'unpaid'
                          ? 'bg-amber-500 text-white border-amber-500 shadow-sm'
                          : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                          }`}
                      >
                        Unpaid
                      </button>
                    </div>
                  </div>

                  {/* Payment Method & Price (Only if Paid) */}
                  {editing.paymentStatus === 'paid' && (
                    <div className="grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-200">
                      <div>
                        <label className="block mb-1 text-slate-600">Method</label>
                        <select
                          value={editing.paymentMethod || "gcash"}
                          onChange={(e) => {
                            const method = e.target.value;
                            let price = editing.rentalPrice;
                            // Logic: If Free, set price to 0
                            if (method === 'free') {
                              price = 0;
                            } else if (price === 0 && editing.rentalPrice === 0) {
                              // Optional: If switching away from Free, maybe restore price? 
                              // For now, let's just recalculate standard rate if it's 0 to be helpful
                              const durationHours = Math.max(0, (editing.endMinutes - editing.startMinutes) / 60);
                              const rate = settings?.defaultRentalRate || 800;
                              price = durationHours * rate;
                            }
                            setEditing({ ...editing, paymentMethod: method, rentalPrice: price });
                          }}
                          className="w-full border border-slate-300 rounded-lg px-2 py-1.5 text-xs bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                        >
                          <option value="cash">Cash</option>
                          <option value="gcash">GCash</option>
                          <option value="gotyme">GoTyme</option>
                          <option value="free">Free</option>
                        </select>
                      </div>
                      <div>
                        <label className="block mb-1 text-slate-600">Amount (PHP)</label>
                        <input
                          type="number"
                          value={editing.rentalPrice ?? ""}
                          onChange={(e) => setEditing({ ...editing, rentalPrice: e.target.value === "" ? "" : parseFloat(e.target.value) })}
                          placeholder="0.00"
                          className="w-full border border-slate-300 rounded-lg px-2 py-1.5 text-xs bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                        />
                      </div>
                    </div>
                  )}
                </div>
              )}

              <div className="flex gap-2">
                <div className="flex-1">
                  <label className="block mb-1">Start</label>
                  <select
                    value={Math.floor(editing.startMinutes / 60)}
                    onChange={(e) =>
                      setEditing({ ...editing, startMinutes: Number(e.target.value) * 60 })
                    }
                    className="w-full border rounded px-2 py-1 text-xs bg-white"
                  >
                    {HOURS.map((h) => (
                      <option key={h} value={h}>
                        {formatHourLabel(h)}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="flex-1">
                  <label className="block mb-1">End</label>
                  <select
                    value={Math.floor(editing.endMinutes / 60)}
                    onChange={(e) =>
                      setEditing({ ...editing, endMinutes: Number(e.target.value) * 60 })
                    }
                    className="w-full border rounded px-2 py-1 text-xs bg-white"
                  >
                    {HOURS.filter(
                      (h) => h > Math.floor(editing.startMinutes / 60)
                    ).map((h) => (
                      <option key={h} value={h}>
                        {formatHourLabel(h)}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              <div className="flex gap-2">
                <div className="flex-1">
                  <label className="block mb-1">Type</label>
                  <select
                    value={editing.bookingType || "rental"}
                    onChange={(e) => setEditing({ ...editing, bookingType: e.target.value })}
                    className="w-full border rounded px-2 py-1 text-xs"
                  >
                    <option value="rental">Rental</option>
                    <option value="open_play_block">Open Play block</option>
                  </select>
                </div>
                {editing.bookingType === "open_play_block" && (
                  <div className="flex-1">
                    <label className="block mb-1">Repeat</label>
                    <div className="flex gap-1">
                      <select
                        value={editing.recurrencePattern || "weekly"}
                        onChange={(e) =>
                          setEditing({
                            ...editing,
                            recurrencePattern: e.target.value,
                          })
                        }
                        className="flex-1 border rounded px-2 py-1 text-xs"
                      >
                        <option value="none">No repeat</option>
                        <option value="daily">Daily</option>
                        <option value="weekly">Weekly</option>
                      </select>
                      <select
                        value={editing.recurrenceWeeks ?? 0}
                        onChange={(e) =>
                          setEditing({
                            ...editing,
                            recurrenceWeeks: Math.min(Number(e.target.value) || 0, 4),
                          })
                        }
                        className="w-20 border rounded px-2 py-1 text-xs"
                      >
                        <option value={0}>0w</option>
                        <option value={1}>1w</option>
                        <option value={2}>2w</option>
                        <option value={3}>3w</option>
                        <option value={4}>4w</option>
                      </select>
                    </div>
                  </div>
                )}
              </div>
              {/* Multi-court selection for new bookings */}
              {editing.isNew && safeCalendarCourts.length > 1 && (
                <div>
                  <label className="block mb-1">Apply to courts</label>
                  <div className="flex flex-col gap-1 border rounded px-2 py-1 bg-slate-50/60">
                    <div className="flex items-center gap-2 text-[11px] mb-1">
                      <label className="inline-flex items-center gap-1">
                        <input
                          type="radio"
                          className="h-3 w-3"
                          checked={(editing.targetCourtMode || "single") === "single"}
                          onChange={() =>
                            setEditing({
                              ...editing,
                              targetCourtMode: "single",
                              selectedCourtIds: [editing.courtId],
                            })
                          }
                        />
                        <span>Only this court</span>
                      </label>
                      <label className="inline-flex items-center gap-1">
                        <input
                          type="radio"
                          className="h-3 w-3"
                          checked={(editing.targetCourtMode || "single") === "multi"}
                          onChange={() =>
                            setEditing({
                              ...editing,
                              targetCourtMode: "multi",
                              selectedCourtIds:
                                Array.isArray(editing.selectedCourtIds) &&
                                  editing.selectedCourtIds.length > 0
                                  ? editing.selectedCourtIds
                                  : safeCalendarCourts.map((c) => c.id),
                            })
                          }
                        />
                        <span>Multiple courts</span>
                      </label>
                    </div>
                    {(editing.targetCourtMode || "single") === "multi" && (
                      <div className="flex flex-wrap gap-1">
                        {safeCalendarCourts.map((court) => {
                          const activeIds = Array.isArray(editing.selectedCourtIds)
                            ? editing.selectedCourtIds
                            : [];
                          const checked = activeIds.includes(court.id);
                          return (
                            <label
                              key={court.id}
                              className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 border text-[11px] cursor-pointer ${checked
                                ? "bg-sky-600 text-white border-sky-600"
                                : "bg-white text-slate-700 border-slate-300"
                                }`}
                            >
                              <input
                                type="checkbox"
                                className="h-3 w-3"
                                checked={checked}
                                onChange={() => {
                                  const current = new Set(activeIds);
                                  if (current.has(court.id)) current.delete(court.id);
                                  else current.add(court.id);
                                  const next = Array.from(current);
                                  setEditing({
                                    ...editing,
                                    selectedCourtIds:
                                      next.length > 0 ? next : [editing.courtId],
                                  });
                                }}
                              />
                              <span>{court.name || `Court ${court.id}`}</span>
                            </label>
                          );
                        })}
                      </div>
                    )}
                    <p className="mt-1 text-[10px] text-slate-500">
                      Conflicting courts or times will be skipped automatically when saving.
                    </p>
                  </div>
                </div>
              )}
              {/* Duplicate Payment Status Dropdown Removed */}
              <div>
                <label className="block mb-1">Notes</label>
                <textarea
                  rows={3}
                  value={editing.notes || ""}
                  onChange={(e) => setEditing({ ...editing, notes: e.target.value })}
                  className="w-full border rounded px-2 py-1 text-xs resize-y"
                />
              </div>
            </div>
            {/* Session / Linked Bookings Management */}
            {!editing.isNew && editing.bookingType === 'rental' && (relatedBookings.length > 0 || editing.renterId) && (
              <div className="mt-4 border-t border-slate-100 pt-3">
                <div className="flex items-center justify-between mb-2">
                  <label className="text-xs font-bold text-slate-700">Rental Session (All Courts/Hours)</label>
                  {/* Future: Add Item features */}
                </div>
                <div className="space-y-2 bg-slate-50 p-2 rounded border border-slate-100 max-h-40 overflow-y-auto">
                  {/* Current Item (Highlighted) */}
                  <div className="flex items-center justify-between text-[11px] p-1.5 bg-white border border-blue-200 rounded shadow-sm">
                    <div className="flex flex-col">
                      <span className="font-semibold text-blue-700">
                        {safeCalendarCourts.find(c => c.id === editing.courtId)?.name || 'This Court'}
                      </span>
                      <span className="text-slate-500">
                        {formatHourLabel(Math.floor(editing.startMinutes / 60))} - {formatHourLabel(Math.floor(editing.endMinutes / 60))}
                      </span>
                    </div>
                    <span className="text-[10px] text-blue-600 font-medium px-2">Editing</span>
                  </div>

                  {/* Related Items */}
                  {relatedBookings.map(b => (
                    <div key={b.id} className="flex items-center justify-between text-[11px] p-1.5 bg-white border border-slate-200 rounded hover:bg-slate-50">
                      <div className="flex flex-col">
                        <span className="font-semibold text-slate-700">
                          {safeCalendarCourts.find(c => c.id === b.courtId)?.name || 'Unknown Court'}
                        </span>
                        <span className="text-slate-500">
                          {formatHourLabel(Math.floor(b.startMinutes / 60))} - {formatHourLabel(Math.floor(b.endMinutes / 60))}
                        </span>
                      </div>
                      <button
                        type="button"
                        onClick={() => handleRemoveRelated(b.id)}
                        className="text-red-500 hover:bg-red-50 px-2 py-1 rounded transition-colors"
                      >
                        Remove
                      </button>
                    </div>
                  ))}

                  {relatedBookings.length === 0 && !editing.renterId && (
                    <div className="text-center text-slate-400 italic py-2">Single booking</div>
                  )}
                </div>
              </div>
            )}

            <div className="mt-4 flex justify-end gap-2">
              {!editing.isNew && (
                <button
                  type="button"
                  onClick={() => handleDelete(editing)}
                  className="px-3 py-1.5 text-xs rounded bg-red-50 text-red-700 border border-red-200"
                >
                  Delete
                </button>
              )}
              <button
                type="button"
                onClick={() => setEditing(null)}
                className="px-3 py-1.5 text-xs rounded border border-gray-200 text-gray-600"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="px-3 py-1.5 text-xs rounded bg-[#1E3A8A] text-white"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
      <ConfirmationModal
        isOpen={confirmModal.isOpen}
        title={confirmModal.title}
        message={confirmModal.message}
        onConfirm={confirmModal.onConfirm}
        onCancel={closeConfirm}
        confirmLabel={confirmModal.confirmLabel}
        isDestructive={confirmModal.isDestructive}
      />
    </div>
  );
}
