import React, { useState, useEffect } from "react";

// Format is now set per-division, not per-tournament.
const SCORING_OPTIONS = [
  { value: "rally", label: "Rally Scoring" },
  { value: "sideout", label: "Side-Out Scoring" },
];

const BEST_OF_OPTIONS = [
  { value: 1, label: "1 Game" },
  { value: 3, label: "Best of 3" },
  { value: 5, label: "Best of 5" },
];

const defaults = {
  name: "",
  start_date: "",
  end_date: "",
  match_duration: 60,
  daily_window_start: "08:00",
  daily_window_end: "20:00",
  games_per_day: 0,
  court_count: 4,
  points_to_win: 11,
  win_by: 2,
  best_of: 1,
  scoring_type: "rally",
};

export default function TournamentModal({ tournament, onSave, onClose, isEditMode = false }) {
  const [form, setForm] = useState({ ...defaults, ...(tournament || {}) });

  useEffect(() => {
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const set = (key, val) => setForm((prev) => ({ ...prev, [key]: val }));

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    onSave({
      ...form,
      match_duration: Number(form.match_duration),
      games_per_day: Number(form.games_per_day),
      court_count: Number(form.court_count) || 4,
      points_to_win: Number(form.points_to_win),
      win_by: Number(form.win_by),
      best_of: Number(form.best_of),
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <form
        onSubmit={handleSubmit}
        className="relative bg-white rounded-xl shadow-2xl w-full max-w-lg overflow-y-auto max-h-[90vh] flex flex-col"
      >
        <div className="p-6 border-b border-slate-100">
          <h2 className="text-xl font-bold text-slate-900">
            {isEditMode ? "Edit Tournament" : "New Tournament"}
          </h2>
        </div>

        <div className="p-6 flex flex-col gap-4 flex-1 overflow-y-auto">
          {/* Name */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">Tournament Name *</label>
            <input
              className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
              value={form.name}
              onChange={(e) => set("name", e.target.value)}
              placeholder="e.g. Summer Slam 2025"
              required
            />
          </div>

          {/* Dates */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Start Date</label>
              <input
                type="date"
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                value={form.start_date || ""}
                onChange={(e) => set("start_date", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">End Date</label>
              <input
                type="date"
                className="w-full border border-slate-200 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-pickle-green/30"
                value={form.end_date || ""}
                onChange={(e) => set("end_date", e.target.value)}
              />
            </div>
          </div>

          {/* Daily window & match duration */}
          <div className="grid grid-cols-3 gap-3">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Window Start</label>
              <input
                type="time"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.daily_window_start}
                onChange={(e) => set("daily_window_start", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Window End</label>
              <input
                type="time"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.daily_window_end}
                onChange={(e) => set("daily_window_end", e.target.value)}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Match (min)</label>
              <input
                type="number"
                min="10"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.match_duration}
                onChange={(e) => set("match_duration", e.target.value)}
              />
            </div>
          </div>

          {/* Courts + max-per-day */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Number of Courts</label>
              <input
                type="number"
                min="1"
                max="20"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.court_count}
                onChange={(e) => set("court_count", e.target.value)}
              />
              <p className="text-[10px] text-slate-400 mt-1">Customise names in Settings</p>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Max Matches/Court/Day</label>
              <input
                type="number"
                min="0"
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none"
                value={form.games_per_day}
                onChange={(e) => set("games_per_day", e.target.value)}
              />
              <p className="text-[10px] text-slate-400 mt-1">0 = all games on start date</p>
            </div>
          </div>

          {/* Scoring rules — locked after start */}
          <div className="border-t border-slate-100 pt-4">
            <p className="text-xs font-semibold text-slate-400 uppercase tracking-wide mb-3">
              Scoring Rules {isEditMode && <span className="text-amber-500 ml-1">(locked)</span>}
            </p>
            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Points to Win</label>
                <input
                  type="number"
                  min="1"
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                  value={form.points_to_win}
                  onChange={(e) => set("points_to_win", e.target.value)}
                  disabled={isEditMode}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Win By</label>
                <input
                  type="number"
                  min="1"
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                  value={form.win_by}
                  onChange={(e) => set("win_by", e.target.value)}
                  disabled={isEditMode}
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1.5">Best Of</label>
                <select
                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                  value={form.best_of}
                  onChange={(e) => set("best_of", Number(e.target.value))}
                  disabled={isEditMode}
                >
                  {BEST_OF_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                </select>
              </div>
            </div>
            <div className="mt-3">
              <label className="block text-xs font-bold text-slate-700 mb-1.5">Scoring Type</label>
              <select
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none disabled:bg-slate-50 disabled:text-slate-400"
                value={form.scoring_type}
                onChange={(e) => set("scoring_type", e.target.value)}
                disabled={isEditMode}
              >
                {SCORING_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
              </select>
            </div>
          </div>
        </div>

        <div className="p-6 border-t border-slate-100 flex justify-end gap-3">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100 transition-colors"
          >
            Cancel
          </button>
          <button
            type="submit"
            className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-pickle-green hover:bg-pickle-green/90 shadow-sm transition-colors"
          >
            {isEditMode ? "Save Changes" : "Create Tournament"}
          </button>
        </div>
      </form>
    </div>
  );
}
