// src/utils/autoQueue.js
// ─────────────────────────────────────────────────────────────────────────────
// SCORED CANDIDATE SYSTEM — replaces old greedy seed-and-fill algorithm.
//
// Key improvements:
//  1. Generates ALL valid C(n,4) combinations and picks the globally best one
//  2. Pair Cooldown Matrix tracks every pair's last shared match → penalizes repeats
//  3. Late-arrival handicap: each 20-min increment late = +1 effective match count
//  4. Hard blocks: exact 4-player repeat (ever) + 3-player repeat (this session)
//  5. Returns rich check data so the UI can show exactly what passed / failed
// ─────────────────────────────────────────────────────────────────────────────

export const MIN_WAIT_FOR_PRIORITY = 13; // ≥13 min = priority player
export const MAX_GROUP_SIZE = 4;
export const MATCH_INTERVAL_MS = 20 * 60 * 1000; // ~20 min per match (late-arrival unit)

const LEVEL_RANK = { Beginner: 0, 'Low Intermediate': 1, 'High Intermediate': 2, Advance: 3 };
const rank = (lvl) => LEVEL_RANK[lvl ?? 'High Intermediate'] ?? 2;

export function waitMinutes(p, now = Date.now()) {
  if ((p.status !== 'waiting' && p.status !== 'queued') || !p.waitStart) return 0;
  return Math.max(0, Math.floor((now - p.waitStart) / 60000));
}

// ─── Pair Cooldown Matrix ─────────────────────────────────────────────────────
// Returns { [idA]: { [idB]: matchesAgo } }
// matchesAgo = 0 → last match, 1 → second-to-last, etc.
export function buildPairMatrix(pastMatches) {
  const matrix = {};
  const n = pastMatches.length;
  pastMatches.forEach((match, globalIdx) => {
    const matchesAgo = n - 1 - globalIdx;
    const ids = (match.lineup || []).map((p) => String(p.id));
    for (let i = 0; i < ids.length; i++) {
      for (let j = i + 1; j < ids.length; j++) {
        const a = ids[i];
        const b = ids[j];
        if (!matrix[a]) matrix[a] = {};
        if (!matrix[b]) matrix[b] = {};
        // Keep only the MOST RECENT encounter (lowest matchesAgo)
        if (matrix[a][b] === undefined || matchesAgo < matrix[a][b]) {
          matrix[a][b] = matchesAgo;
          matrix[b][a] = matchesAgo;
        }
      }
    }
  });
  return matrix;
}

// Penalty score per pair based on how recently they played together
function pairPenalty(matchesAgo) {
  if (matchesAgo === undefined) return 0; // never played together
  if (matchesAgo === 0) return 100; // played in the LAST match
  if (matchesAgo === 1) return 70;
  if (matchesAgo === 2) return 40; // within last 3 matches
  if (matchesAgo === 3) return 20;
  if (matchesAgo <= 5) return 10;
  if (matchesAgo <= 9) return 5;
  return 0;
}

// ─── Combination Generator ────────────────────────────────────────────────────
// Generates all C(n, 4) combinations. Safe up to ~50 players (<50ms).
function combinations4(arr) {
  const result = [];
  const n = arr.length;
  for (let a = 0; a < n - 3; a++)
    for (let b = a + 1; b < n - 2; b++)
      for (let c = b + 1; c < n - 1; c++)
        for (let d = c + 1; d < n; d++)
          result.push([arr[a], arr[b], arr[c], arr[d]]);
  return result;
}

// ─── Hard Rule Validators ─────────────────────────────────────────────────────

function validateGender(group) {
  const mCount = group.filter((p) => p.gender === 'M').length;
  const fCount = group.filter((p) => p.gender === 'F').length;
  return {
    valid: (mCount === 4 && fCount === 0) || (fCount === 4 && mCount === 0) || (mCount === 2 && fCount === 2),
    mCount,
    fCount,
  };
}

function validateLevel(group) {
  const ranks = group.map((p) => rank(p.level));
  const spread = Math.max(...ranks) - Math.min(...ranks);
  return { valid: spread <= 1, spread };
}

// Block if any 4 players appeared together before (ever), OR
// if any 3 players appeared together within this session.
function checkHardRepeats(group, pastMatches, sessionMatchIds) {
  const groupIds = new Set(group.map((p) => String(p.id)));

  for (let i = 0; i < pastMatches.length; i++) {
    const m = pastMatches[i];
    const lineupIds = (m.lineup || []).map((p) => String(p.id));
    const overlap = lineupIds.filter((id) => groupIds.has(id)).length;

    if (overlap >= 4) {
      return {
        blocked: true,
        type: '4player',
        reason: 'These exact 4 players have already played together before.',
      };
    }
    if (overlap >= 3 && sessionMatchIds.has(m.id)) {
      return {
        blocked: true,
        type: '3player',
        reason: '3 of these players appeared in the same match this session.',
      };
    }
  }
  return { blocked: false };
}

// Block if any 2 players played together in the last 3 matches (matchesAgo <= 2).
function checkHardPairs(group, pairMatrix) {
  const n = group.length;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = String(group[i].id);
      const b = String(group[j].id);
      const ago = pairMatrix[a]?.[b];
      if (ago !== undefined && ago <= 2) {
        return {
          blocked: true,
          idA: a,
          idB: b,
          matchesAgo: ago
        };
      }
    }
  }
  return { blocked: false };
}

// ─── Scoring ──────────────────────────────────────────────────────────────────
// Returns a score 0–~100 and detailed sub-scores + pair warnings.
// Weights: pairDiversity 35 + fairness 30 + wait 25 + level 10

const MAX_THEORETICAL_SCORE = 107; // with long-wait bonus at max

function scoreGroup(group, pairMatrix, allPoolPlayers) {
  // (A) Fairness: match-count variance across the 4 players
  const avg = group.reduce((s, p) => s + (p._effectiveMatches ?? 0), 0) / group.length;
  const variance =
    group.reduce((s, p) => s + Math.pow((p._effectiveMatches ?? 0) - avg, 2), 0) / group.length;
  const fairnessScore = 1 / (1 + variance); // 0→1

  // (B) Wait score + priority bonus/penalty
  const totalWaitMin = group.reduce((s, p) => s + (p._wait ?? 0), 0);
  const rawWaitScore = Math.min(totalWaitMin / 60, 1); // 0→1

  const longWaitersInGroup = group.filter((p) => (p._wait ?? 0) >= MIN_WAIT_FOR_PRIORITY);
  const longWaitersOutside = allPoolPlayers.filter(
    (p) => (p._wait ?? 0) >= MIN_WAIT_FOR_PRIORITY && !group.some((g) => g.id === p.id)
  );

  // Bonus for including a priority player; penalty for leaving one out when possible
  const longWaitBonus = longWaitersInGroup.length > 0 ? 0.3 : 0;
  const longWaitPenalty = longWaitersOutside.length > 0 && longWaitersInGroup.length === 0 ? -0.5 : 0;
  const waitScore = rawWaitScore + longWaitBonus + longWaitPenalty;

  // (C) Pair diversity: penalize pairs that played together recently
  const pairs = [];
  const n = group.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      pairs.push([String(group[i].id), String(group[j].id)]);

  let totalPairPenalty = 0;
  const pairWarnings = [];
  for (const [a, b] of pairs) {
    const ago = pairMatrix[a]?.[b];
    const penalty = pairPenalty(ago);
    totalPairPenalty += penalty;
    if (penalty > 0) {
      pairWarnings.push({ idA: a, idB: b, matchesAgo: ago, penalty });
    }
  }
  // 6 pairs × max 100 penalty = 600 max; normalize to 0→1
  const pairDiversityScore = Math.max(0, (600 - totalPairPenalty) / 600);

  // (D) Level tightness
  const ranks = group.map((p) => rank(p.level));
  const levelSpread = Math.max(...ranks) - Math.min(...ranks);
  const levelScore = Math.max(0, (2 - levelSpread) / 2); // 0→1

  const totalScore =
    fairnessScore * 30 +
    waitScore * 25 +
    pairDiversityScore * 35 +
    levelScore * 10;

  return {
    totalScore,
    fairnessScore,
    waitScore: rawWaitScore,
    pairDiversityScore,
    levelScore,
    pairWarnings,
    variance,
  };
}

// ─── Check Builder (for modal display) ───────────────────────────────────────
function buildChecks(group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult, pool, pairMatrix) {
  const checks = [];

  // 1. Level
  checks.push({
    id: 'level',
    label: 'Skill level compatibility (±1 rank)',
    status: levelResult.valid ? 'pass' : 'fail',
    reason: levelResult.valid
      ? 'All players are within one skill level of each other.'
      : `Skill levels are too spread apart (${levelResult.spread} rank gap). A valid match needs all players within ±1 level of each other.`,
  });

  // 2. Gender
  const { mCount, fCount } = genderResult;
  let genderReason;
  if (genderResult.valid) {
    genderReason =
      mCount === 4 ? 'All-male match.' : fCount === 4 ? 'All-female match.' : '2 male / 2 female mixed match.';
  } else {
    const needed =
      mCount === 3
        ? 'Need 1 more male player (for 4M) or 1 female player (for 2M+2F).'
        : fCount === 3
        ? 'Need 1 more female player (for 4F) or 1 male player (for 2M+2F).'
        : `Got ${mCount}M / ${fCount}F — valid formats are 4M, 4F, or 2M+2F only.`;
    genderReason = `Invalid gender combination: ${mCount}M / ${fCount}F. ${needed}`;
  }
  checks.push({
    id: 'gender',
    label: 'Gender format (4M / 4F / 2M+2F)',
    status: genderResult.valid ? 'pass' : 'fail',
    reason: genderReason,
  });

  // 3. Repeat history
  checks.push({
    id: 'repeat',
    label: 'No 3-player or 4-player repeat',
    status: repeatResult.blocked ? 'fail' : 'pass',
    reason: repeatResult.blocked
      ? `${repeatResult.reason} Wait for another court to finish so the player pool rotates.`
      : 'No three or four players in this group have all played together in the same match.',
  });

  // 4. Pair history (2 players)
  const allPairWarnings = scoreResult?.pairWarnings ?? [];

  // Enrich pair warnings with player names
  const poolById = {};
  pool.forEach((p) => { poolById[String(p.id)] = p; });

  const namedWarnings = allPairWarnings.map((w) => ({
    ...w,
    nameA: poolById[w.idA]?.name ?? w.idA,
    nameB: poolById[w.idB]?.name ?? w.idB,
  }));

  const warnPairs = namedWarnings.filter((w) => w.matchesAgo === 3);

  let pairStatus = 'pass';
  let pairReason = 'No two players in this group played together in the last 4 matches.';

  if (pairBlockResult?.blocked) {
    pairStatus = 'fail';
    const nameA = poolById[pairBlockResult.idA]?.name ?? pairBlockResult.idA;
    const nameB = poolById[pairBlockResult.idB]?.name ?? pairBlockResult.idB;
    const ago = pairBlockResult.matchesAgo;
    pairReason = `BLOCKED: ${nameA} & ${nameB} played together ${ago === 0 ? 'last match' : `${ago + 1} matches ago`}. Need at least 3 matches to separate them.`;
  } else if (warnPairs.length > 0) {
    pairStatus = 'warn';
    const desc = warnPairs.map((w) => `${w.nameA} & ${w.nameB}`).join('; ');
    pairReason = `WARNING: ${warnPairs.length} pair(s) played together exactly 4 matches ago: ${desc}.`;
  }

  checks.push({
    id: 'pairs',
    label: 'Recent pair history (2 players)',
    status: pairStatus,
    reason: pairReason,
    pairWarnings: namedWarnings,
  });

  // 5. Long-wait priority
  const longWaiters = pool.filter((p) => (p._wait ?? 0) >= MIN_WAIT_FOR_PRIORITY);
  const longWaitersInGroup = group.filter((p) => (p._wait ?? 0) >= MIN_WAIT_FOR_PRIORITY);
  let priorityStatus = 'pass';
  let priorityReason;
  if (longWaiters.length === 0) {
    priorityReason = 'No players have been waiting over 13 minutes.';
  } else if (longWaitersInGroup.length > 0) {
    priorityReason = `Priority player(s) included: ${longWaitersInGroup
      .map((p) => `${p.name} (${p._wait} min)`)
      .join(', ')}.`;
  } else {
    priorityStatus = 'warn';
    priorityReason = `${longWaiters.map((p) => p.name).join(', ')} ${longWaiters.length === 1 ? 'has' : 'have'} waited over 13 min but could not be included due to skill or gender constraints.`;
  }
  checks.push({ id: 'priority', label: 'Long-wait priority honored', status: priorityStatus, reason: priorityReason });

  // 6. Fairness / match count balance
  const effectiveCounts = group.map((p) => p._effectiveMatches ?? 0);
  const avgEC = effectiveCounts.reduce((a, b) => a + b, 0) / effectiveCounts.length;
  const stdDev = Math.sqrt(
    effectiveCounts.reduce((s, v) => s + Math.pow(v - avgEC, 2), 0) / effectiveCounts.length
  );
  const lateHandicapped = group.filter((p) => (p._lateHandicap ?? 0) > 0);
  const fairnessStatus = stdDev <= 1.5 ? 'pass' : 'warn';
  let fairnessReason =
    stdDev <= 1.5
      ? `Match count distribution is balanced (σ = ${stdDev.toFixed(1)}).`
      : `Some imbalance in match counts (σ = ${stdDev.toFixed(1)}). This may be unavoidable given current level and gender distribution.`;
  if (lateHandicapped.length > 0) {
    fairnessReason += ` Late-arrival offset applied to: ${lateHandicapped
      .map((p) => `${p.name} (+${p._lateHandicap} effective match${p._lateHandicap !== 1 ? 'es' : ''})`)
      .join(', ')}.`;
  }
  checks.push({ id: 'fairness', label: 'Fair match count distribution', status: fairnessStatus, reason: fairnessReason });

  return checks;
}

// ─── Main Export ──────────────────────────────────────────────────────────────
/**
 * buildAutoQueue(players, options)
 *
 * Returns:
 *  { success, groupIds, usedPlayers, confidencePct, checks, pairWarnings, reason, diagnostics }
 *
 * On failure, `groupIds` is empty but `checks` still show exactly what went wrong.
 */
export function buildAutoQueue(
  players,
  {
    maxGroupSize = MAX_GROUP_SIZE,
    pastMatches = [],
    excludeIds = [],
    partners = [],
    sessionStartTime = null,
    sessionMatchIds = null, // Set of match IDs belonging to current session
    excludeGroups = [],     // Array of sorted-id strings to skip (for Re-generate)
  } = {}
) {
  const now = Date.now();
  const excludeSet = new Set((excludeIds || []).map(String));

  // Active partner lookup
  const getActivePartnerId = (pid) => {
    const rel = partners.find(
      (r) => r.isActive && (r.player1Id === pid || r.player2Id === pid)
    );
    if (!rel) return null;
    return rel.player1Id === pid ? rel.player2Id : rel.player1Id;
  };

  // Session start: use explicit value, fall back to earliest player arrival
  const allArrivals = players.map((p) => p.arrivalTime).filter((t) => typeof t === 'number' && t > 0);
  const sessionStart = sessionStartTime ?? (allArrivals.length > 0 ? Math.min(...allArrivals) : now);

  // Session matches: default to all if not provided
  const sessionMatchSet =
    sessionMatchIds instanceof Set ? sessionMatchIds : new Set(pastMatches.map((m) => m.id));

  // Build pair cooldown matrix
  const pairMatrix = buildPairMatrix(pastMatches);

  // Diagnostics
  const diagnostics = { total: players.length, notWaiting: 0, excluded: 0, partnerBusy: 0, ok: 0 };

  // Filter & enrich pool
  const pool = players
    .filter((p) => {
      const s = (p.status || '').toLowerCase().trim();
      if (s !== 'waiting') { diagnostics.notWaiting++; return false; }
      if (excludeSet.has(String(p.id))) { diagnostics.excluded++; return false; }

      const partnerId = getActivePartnerId(p.id);
      if (partnerId) {
        const partner = players.find((x) => String(x.id) === String(partnerId));
        if (partner && (partner.status || '').toLowerCase().trim() !== 'waiting') {
          diagnostics.partnerBusy++;
          return false;
        }
      }
      diagnostics.ok++;
      return true;
    })
    .map((p) => {
      const lateByMs = Math.max(0, (p.arrivalTime || sessionStart) - sessionStart);
      const lateHandicap = Math.floor(lateByMs / MATCH_INTERVAL_MS);
      return {
        ...p,
        _wait: waitMinutes(p, now),
        _matches: p.matches ?? 0,
        _effectiveMatches: (p.matches ?? 0) + lateHandicap,
        _lateHandicap: lateHandicap,
      };
    });

  // ── Not enough players ──────────────────────────────────────────────────────
  if (pool.length < 4) {
    const notEnoughChecks = [
      {
        id: 'pool_size',
        label: 'Enough players waiting',
        status: 'fail',
        reason: `Only ${pool.length} eligible player(s) — need at least 4.${
          diagnostics.notWaiting > 0 ? ` ${diagnostics.notWaiting} player(s) are on court or stopped.` : ''
        }${diagnostics.partnerBusy > 0 ? ` ${diagnostics.partnerBusy} player(s) are waiting for their partner to finish.` : ''
        }${diagnostics.excluded > 0 ? ` ${diagnostics.excluded} player(s) are reserved in Requested Matches.` : ''}`,
      },
    ];
    return {
      success: false,
      groupIds: [],
      usedPlayers: [],
      confidencePct: 0,
      checks: notEnoughChecks,
      pairWarnings: [],
      reason: `Not enough players (${pool.length} of 4 needed)`,
      diagnostics,
    };
  }

  // ── Generate all C(n,4) combinations ───────────────────────────────────────
  const allCombos = combinations4(pool);

  // Build a Set of excluded group keys for Re-generate
  const excludeGroupKeys = new Set(excludeGroups.map((ids) => [...ids].sort().join(',')));

  let bestValid = null;
  let bestValidScore = -Infinity;
  let bestAttempt = null;
  let bestAttemptScore = -Infinity;

  for (const group of allCombos) {
    // Skip previously proposed groups (Re-generate)
    const groupKey = group.map((p) => String(p.id)).sort().join(',');
    if (excludeGroupKeys.has(groupKey)) continue;

    // Hard rule checks
    const genderResult = validateGender(group);
    const levelResult = validateLevel(group);
    const repeatResult = checkHardRepeats(group, pastMatches, sessionMatchSet);
    const pairBlockResult = checkHardPairs(group, pairMatrix);

    const hardPassed = genderResult.valid && levelResult.valid && !repeatResult.blocked && !pairBlockResult.blocked;

    const scoreResult = scoreGroup(group, pairMatrix, pool);
    const { totalScore } = scoreResult;

    const candidate = { group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult };

    if (hardPassed) {
      if (totalScore > bestValidScore) {
        bestValid = candidate;
        bestValidScore = totalScore;
      }
    } else {
      if (totalScore > bestAttemptScore) {
        bestAttempt = candidate;
        bestAttemptScore = totalScore;
      }
    }
  }

  // ── Success ─────────────────────────────────────────────────────────────────
  if (bestValid) {
    const { group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult } = bestValid;
    const checks = buildChecks(group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult, pool, pairMatrix);
    const confidencePct = Math.round(Math.min(100, (bestValidScore / MAX_THEORETICAL_SCORE) * 100));

    return {
      success: true,
      groupIds: group.map((p) => p.id),
      usedPlayers: group,
      confidencePct,
      checks,
      pairWarnings: scoreResult.pairWarnings,
      reason: 'Match found',
      diagnostics,
    };
  }

  // ── Failure: show best attempt with all failures ────────────────────────────
  const fail = bestAttempt;
  if (fail) {
    const { group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult } = fail;
    const checks = buildChecks(group, genderResult, levelResult, repeatResult, pairBlockResult, scoreResult, pool, pairMatrix);
    return {
      success: false,
      groupIds: [],
      usedPlayers: group,
      confidencePct: 0,
      checks,
      pairWarnings: scoreResult?.pairWarnings ?? [],
      reason: 'No valid match found — see checklist for details',
      diagnostics,
    };
  }

  // ── Total failure (no combos at all) ────────────────────────────────────────
  return {
    success: false,
    groupIds: [],
    usedPlayers: [],
    confidencePct: 0,
    checks: [
      {
        id: 'no_combos',
        label: 'Match generation',
        status: 'fail',
        reason: 'Could not form any 4-player group from the current waiting pool.',
      },
    ],
    pairWarnings: [],
    reason: 'No combinations possible',
    diagnostics,
  };
}
