import React, { useState, useEffect } from "react";

const PHASE_LABELS = {
  setup: { label: "Setup", cls: "bg-slate-700 text-slate-200" },
  group_stage: { label: "Group Stage", cls: "bg-blue-800 text-blue-100" },
  playoffs: { label: "Playoffs", cls: "bg-amber-700 text-amber-100" },
  completed: { label: "Completed", cls: "bg-green-800 text-green-100" },
};

const VIEW_LABELS = {
  tournament_info: "Tournament Info",
  current_match: "Now Playing",
  live_courts: "Live Courts",
  standings: "Standings",
  bracket: "Bracket",
  upcoming: "Upcoming Matches",
  results: "Recent Results",
  sponsor_highlight: "Sponsor",
  sponsor_slideshow: "Sponsors",
  slideshow: "Live Updates",
};

export default function DisplayHeader({ tournament, activeView, slideIndex, totalSlides }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  const phase = tournament?.phase || "setup";
  const phaseInfo = PHASE_LABELS[phase] || PHASE_LABELS.setup;

  // Time: 30% larger than original text-2xl (1.5rem → ~2rem)
  const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  // Date below time
  const dateStr = now.toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" });

  return (
    <header className="shrink-0 flex items-center justify-between px-6 py-3 bg-black/30 border-b border-white/10">
      {/* Left: tournament name + view label */}
      <div className="flex items-center gap-4">
        <div>
          <div className="font-display text-4xl text-white leading-tight">
            {tournament?.name || "Tournament"}
          </div>
          <div className="text-pickle-cream/70 text-base font-body mt-0.5">
            {VIEW_LABELS[activeView] || activeView}
            {activeView === "slideshow" && totalSlides > 1 && (
              <span className="ml-2 text-pickle-cream/40">
                {slideIndex + 1}/{totalSlides}
              </span>
            )}
          </div>
        </div>
      </div>

      {/* Right: phase badge + time + date */}
      <div className="flex items-center gap-4">
        <span className={`px-3 py-1.5 rounded-full text-sm font-semibold uppercase tracking-wider ${phaseInfo.cls}`}>
          {phaseInfo.label}
        </span>
        {/* Time & date stacked, both ~30% larger */}
        <div className="flex flex-col items-end leading-tight">
          <span className="text-pickle-cream font-oswald font-bold text-[2.25rem] leading-none">{timeStr}</span>
          <span className="text-pickle-cream/60 font-body text-[1.05rem] mt-0.5">{dateStr}</span>
        </div>
      </div>
    </header>
  );
}
