import React from "react";

export default function SurfaceCard({
  title,
  description,
  actions,
  children,
  className = "",
  bodyClassName = "",
  padded = true,
}) {
  const hasHeader = Boolean(title || description || actions);
  const innerSpacing = `${padded ? "px-4 pb-5" : ""} ${
    bodyClassName || (hasHeader ? "mt-3" : "")
  }`.trim();

  return (
    <section
      className={`rounded-2xl bg-white shadow-sm border border-slate-200 ${className}`.trim()}
    >
      {(title || description || actions) && (
        <header className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between px-5 pt-5">
          <div>
            {title && <h2 className="text-base font-semibold text-slate-800">{title}</h2>}
            {description && (
              <p className="text-xs text-slate-500 mt-1 max-w-prose">{description}</p>
            )}
          </div>
          {actions && <div className="flex items-center gap-2">{actions}</div>}
        </header>
      )}
      <div className={innerSpacing || undefined}>{children}</div>
    </section>
  );
}
