import React from "react";

// ─── Helper Components ────────────────────────────────────────────────────────

const LEVEL_EMOJI = {
  Beginner: "🟡",
  "Low Intermediate": "🟢",
  "High Intermediate": "🔵",
  Advance: "🟣",
};

const LEVEL_COLOR = {
  Beginner: "bg-yellow-100 text-yellow-800 border-yellow-200",
  "Low Intermediate": "bg-green-100 text-green-800 border-green-200",
  "High Intermediate": "bg-blue-100 text-blue-800 border-blue-200",
  Advance: "bg-purple-100 text-purple-800 border-purple-200",
};

function CheckRow({ check }) {
  const icons = {
    pass: (
      <span className="flex items-center justify-center w-5 h-5 rounded-full bg-emerald-100 text-emerald-600 text-xs font-bold shrink-0">
        ✓
      </span>
    ),
    warn: (
      <span className="flex items-center justify-center w-5 h-5 rounded-full bg-amber-100 text-amber-600 text-xs font-bold shrink-0">
        ⚠
      </span>
    ),
    fail: (
      <span className="flex items-center justify-center w-5 h-5 rounded-full bg-red-100 text-red-600 text-xs font-bold shrink-0">
        ✕
      </span>
    ),
  };

  const rowBg = {
    pass: "bg-emerald-50/60 border-emerald-100",
    warn: "bg-amber-50/60 border-amber-100",
    fail: "bg-red-50/60 border-red-100",
  };

  const labelColor = {
    pass: "text-emerald-800",
    warn: "text-amber-800",
    fail: "text-red-800",
  };

  const reasonColor = {
    pass: "text-emerald-700",
    warn: "text-amber-700",
    fail: "text-red-700",
  };

  return (
    <div className={`flex items-start gap-2.5 p-2.5 rounded-lg border ${rowBg[check.status]}`}>
      {icons[check.status]}
      <div className="min-w-0">
        <div className={`text-[11px] font-bold uppercase tracking-wide ${labelColor[check.status]}`}>
          {check.label}
        </div>
        <div className={`text-[11px] mt-0.5 leading-relaxed ${reasonColor[check.status]}`}>
          {check.reason}
        </div>
      </div>
    </div>
  );
}

function PlayerCard({ player }) {
  const isPriority = (player._wait ?? 0) >= 13;
  const isLate = (player._lateHandicap ?? 0) > 0;

  return (
    <div
      className={`relative flex items-center gap-2.5 p-2.5 rounded-xl border-2 transition-all ${
        player.gender === "F"
          ? "bg-pink-50 border-pink-200"
          : "bg-slate-50 border-slate-200"
      } ${isPriority ? "ring-2 ring-amber-400 ring-offset-1" : ""}`}
    >
      {/* Gender dot */}
      <div
        className={`w-2 h-2 rounded-full shrink-0 ${
          player.gender === "F" ? "bg-pink-400" : "bg-blue-400"
        }`}
      />

      {/* Level emoji */}
      <span className="text-base leading-none shrink-0">
        {LEVEL_EMOJI[player.level] ?? "🔵"}
      </span>

      {/* Name */}
      <div className="flex-1 min-w-0">
        <div className="font-bold text-sm text-slate-800 truncate">{player.name}</div>
        <div className="flex items-center gap-1.5 mt-0.5">
          <span
            className={`text-[9px] font-semibold px-1.5 py-0.5 rounded border ${
              LEVEL_COLOR[player.level] ?? LEVEL_COLOR["High Intermediate"]
            }`}
          >
            {player.level ?? "High Intermediate"}
          </span>
          {isPriority && (
            <span className="text-[9px] font-bold px-1.5 py-0.5 rounded bg-amber-100 border border-amber-300 text-amber-800">
              🔥 Priority
            </span>
          )}
          {isLate && (
            <span className="text-[9px] font-semibold px-1.5 py-0.5 rounded bg-slate-200 text-slate-600 border border-slate-300">
              +{player._lateHandicap} late
            </span>
          )}
        </div>
      </div>

      {/* Wait time */}
      <div className="text-right shrink-0">
        <div className={`text-xs font-bold tabular-nums ${isPriority ? "text-amber-600" : "text-slate-500"}`}>
          {player._wait ?? 0}m
        </div>
        <div className="text-[9px] text-slate-400">{player._matches ?? 0} played</div>
      </div>
    </div>
  );
}

function ConfidenceBar({ pct }) {
  const color =
    pct >= 75
      ? "bg-emerald-500"
      : pct >= 50
      ? "bg-amber-400"
      : pct >= 25
      ? "bg-orange-500"
      : "bg-red-500";

  const label =
    pct >= 80
      ? "Excellent match"
      : pct >= 60
      ? "Good match"
      : pct >= 40
      ? "Acceptable match"
      : pct >= 20
      ? "Fair match — conflicts present"
      : "Poor match — waiting recommended";

  return (
    <div className="space-y-1">
      <div className="flex items-center justify-between text-[11px]">
        <span className="font-semibold text-slate-600">{label}</span>
        <span className="font-bold text-slate-700 tabular-nums">{pct}%</span>
      </div>
      <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-200">
        <div
          className={`h-full rounded-full transition-all duration-700 ${color}`}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

// ─── Main Modal ───────────────────────────────────────────────────────────────

/**
 * MatchProposalModal
 *
 * Props:
 *  isOpen         — bool
 *  proposal       — result from buildAutoQueue:
 *                   { success, usedPlayers, groupIds, confidencePct, checks, pairWarnings, reason }
 *  onConfirm()    — called when operator clicks "Queue This Match"
 *  onReGenerate() — called when operator clicks "Try Different"
 *  onClose()      — called when modal is dismissed
 *  isRegenerating — bool (show loading state on Try Different)
 */
export default function MatchProposalModal({
  isOpen,
  proposal,
  onConfirm,
  onReGenerate,
  onClose,
  isRegenerating = false,
}) {
  if (!isOpen || !proposal) return null;

  const { success, usedPlayers = [], confidencePct = 0, checks = [], reason } = proposal;
  const hasPlayers = usedPlayers.length > 0;

  const failCount = checks.filter((c) => c.status === "fail").length;
  const warnCount = checks.filter((c) => c.status === "warn").length;

  const men = usedPlayers.filter((p) => p.gender === "M").length;
  const women = usedPlayers.filter((p) => p.gender === "F").length;
  const genderLabel =
    men === 4 ? "All Male (4M)" : women === 4 ? "All Female (4F)" : men === 2 && women === 2 ? "Mixed (2M + 2F)" : "";

  return (
    <div
      className="fixed inset-0 z-[999] flex items-center justify-center bg-black/50 backdrop-blur-sm"
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.(); }}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md mx-4 overflow-hidden border border-slate-200 animate-in fade-in slide-in-from-bottom-4 duration-200">

        {/* ── Header ── */}
        <div
          className={`px-5 py-4 flex items-center justify-between ${
            success
              ? "bg-gradient-to-r from-pickle-green to-green-600"
              : "bg-gradient-to-r from-amber-500 to-orange-500"
          }`}
        >
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-full bg-white/20 flex items-center justify-center text-lg">
              {success ? "🤖" : "⚠️"}
            </div>
            <div>
              <div className="font-bold text-white text-base leading-none">
                {success ? "Match Proposal" : "No Clean Match Found"}
              </div>
              <div className="text-white/70 text-[11px] mt-0.5">
                {success
                  ? "AI analysis complete — review before queuing"
                  : "See what failed and why below"}
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-7 h-7 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center text-white text-sm transition-colors"
          >
            ✕
          </button>
        </div>

        <div className="max-h-[70vh] overflow-y-auto custom-scrollbar">
          {/* ── Player Cards ── */}
          {hasPlayers && (
            <div className="px-4 pt-4 pb-2">
              <div className="flex items-center justify-between mb-2">
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {success ? "Proposed Group" : "Best Available (Conflicted)"}
                </div>
                {genderLabel && (
                  <span className="text-[10px] font-semibold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full border border-slate-200">
                    {genderLabel}
                  </span>
                )}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {usedPlayers.map((p) => (
                  <PlayerCard key={p.id} player={p} />
                ))}
              </div>
            </div>
          )}

          {/* ── Confidence Bar (only on success) ── */}
          {success && hasPlayers && (
            <div className="px-4 pt-1 pb-3">
              <ConfidenceBar pct={confidencePct} />
            </div>
          )}

          {/* ── Checklist ── */}
          <div className="px-4 pb-4">
            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">
              Match Quality Checks
              {!success && failCount > 0 && (
                <span className="ml-2 text-red-500">
                  {failCount} failed · {warnCount} warning{warnCount !== 1 ? "s" : ""}
                </span>
              )}
            </div>
            <div className="space-y-1.5">
              {checks.map((check) => (
                <CheckRow key={check.id} check={check} />
              ))}
            </div>
          </div>

          {/* ── Failure message ── */}
          {!success && (
            <div className="mx-4 mb-4 p-3 rounded-xl bg-amber-50 border border-amber-200">
              <div className="text-[11px] font-bold text-amber-800 mb-1">
                What to do
              </div>
              <div className="text-[11px] text-amber-700 leading-relaxed">
                Wait for at least one court to finish so players rotate back into the
                waiting pool. This should resolve most of the conflicts above.
              </div>
            </div>
          )}
        </div>

        {/* ── Actions ── */}
        <div className="px-4 py-3 border-t border-slate-100 bg-slate-50 flex items-center gap-2">
          {success ? (
            <>
              <button
                onClick={onReGenerate}
                disabled={isRegenerating}
                className="flex-1 py-2 text-xs font-bold text-pickle-green bg-white border border-pickle-green/30 rounded-xl hover:bg-pickle-green/5 transition-all active:scale-95 disabled:opacity-50 disabled:cursor-wait"
              >
                {isRegenerating ? "Searching…" : "🔄 Try Different"}
              </button>
              <button
                onClick={onConfirm}
                className="flex-1 py-2 text-xs font-bold text-white bg-pickle-green rounded-xl hover:bg-pickle-green/90 transition-all shadow-sm shadow-pickle-green/30 active:scale-95"
              >
                ✅ Queue This Match
              </button>
            </>
          ) : (
            <button
              onClick={onClose}
              className="flex-1 py-2 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all active:scale-95"
            >
              Got it — I'll wait
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
