import React, { useCallback, useEffect, useMemo, useState } from "react";
import Select from "react-select";
import { MoreVertical, ArrowRightLeft, Undo2 } from "lucide-react";
import { speak } from "../../../common/utils/tts";

const formatDuration = (ms) => {
  if (!ms || ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60)
    .toString()
    .padStart(2, "0");
  const seconds = (totalSeconds % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
};

const MAX_TEAM_SIZE = 2;

const LEVEL_SYMBOLS = {
  "High Intermediate": "🔵",
  "Low Intermediate": "🟢",
  Advance: "🟣",
  Beginner: "🟡",
};

const LEVEL_TONE_CLASSES = {
  Beginner: "from-yellow-300 to-yellow-500",
  "Low Intermediate": "from-green-400 to-green-600",
  "High Intermediate": "from-blue-400 to-blue-600",
  Advance: "from-purple-500 to-purple-700",
  default: "from-slate-300 to-slate-400",
};

const getLevelToneClass = (level) => LEVEL_TONE_CLASSES[level] || LEVEL_TONE_CLASSES.default;

export default function CourtCard({
  court,
  players,
  onAssign,
  onRemove,
  onUnlockCourt,
  onUpdateCourtName,
  onRemoveCourt,
  onSetTeams = () => { },
  onCompleteMatch = () => { },
  readOnly = false,
  compact = false,
  isDisplayOpen = false,
  onDisplayOpen = () => { },
  onDisplayClose = () => { },
  isDefault = false,
  variant,
  onRequestMove = () => { },
  onReturnToQueue = () => { },
}) {
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [optionsTick, setOptionsTick] = useState(0);
  const [displayTimer, setDisplayTimer] = useState(60);

  useEffect(() => {
    if (!isDisplayOpen) {
      setDisplayTimer(60);
      return;
    }

    const timerId = setInterval(() => {
      setDisplayTimer((prev) => {
        if (prev <= 1) {
          clearInterval(timerId);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timerId);
  }, [isDisplayOpen]);

  const timer = useMemo(() => court?.timer || {}, [court.timer]);

  useEffect(() => {
    const id = setInterval(() => setOptionsTick((tick) => tick + 1), 30000);
    return () => clearInterval(id);
  }, []);

  const playersOnCourt = useMemo(
    () => players.filter((p) => court.players.includes(p.id)),
    [players, court.players]
  );

  const teamAssignments = useMemo(() => {
    const map = new Map();
    (court.teamGreen || []).forEach((id) => map.set(id, "green"));
    (court.teamBlue || []).forEach((id) => map.set(id, "blue"));
    return map;
  }, [court.teamGreen, court.teamBlue]);

  const computeElapsedMs = useCallback(() => {
    const { startTime, lastResumedAt, accumulatedMs = 0, isPaused } = timer;
    if (!startTime) return 0;
    if (!isPaused && lastResumedAt) {
      return accumulatedMs + Math.max(0, Date.now() - lastResumedAt);
    }
    if (!isPaused && !lastResumedAt) {
      return Math.max(0, Date.now() - startTime);
    }
    return accumulatedMs;
  }, [timer]);

  const [elapsedMs, setElapsedMs] = useState(() => computeElapsedMs());

  useEffect(() => {
    setElapsedMs(computeElapsedMs());
    if (!timer.startTime || timer.isPaused) return undefined;
    const id = setInterval(() => setElapsedMs(computeElapsedMs()), 1000);
    return () => clearInterval(id);
  }, [computeElapsedMs, timer.isPaused, timer.startTime]);

  const waitMinutes = (player) => {
    if ((player.status === "waiting" || player.status === "queued") && player.waitStart) {
      return Math.floor((Date.now() - player.waitStart) / 60000);
    }
    return 0;
  };

  const waitingOptions = useMemo(() => {
    const refreshKey = optionsTick;
    return players
      .filter((p) => p.status === "waiting")
      .sort((a, b) => {
        const aWait = waitMinutes(a) + refreshKey * 0;
        const bWait = waitMinutes(b) + refreshKey * 0;
        if (aWait !== bWait) return bWait - aWait;
        if (a.matches !== b.matches) return a.matches - b.matches;
        return a.name.localeCompare(b.name);
      })
      .map((p) => ({
        value: p.id,
        label: p.name,
        level: p.level,
        gender: p.gender,
        matches: p.matches,
        wait: waitMinutes(p),
      }));
  }, [players, optionsTick]);

  const genderSymbol = (gender) => {
    switch (gender) {
      case "M":
        return <span className="font-extrabold text-blue-600">M</span>;
      case "F":
        return <span className="font-extrabold text-pink-500">F</span>;
      default:
        return <span className="font-extrabold text-blue-600">M</span>;
    }
  };

  const isFull = playersOnCourt.length >= 4;
  const isLocked = !!court.locked;

  const statusLabel = useMemo(() => {
    if (isLocked) return court.lockReason || "RENTED";
    if (readOnly) return isFull ? "IN USE" : "OPEN"; // Changed for Display Variant style
    if (timer.startTime) {
      if (timer.isPaused) return "Paused";
      return "In Progress";
    }
    if (isFull) return "Ready";
    if (playersOnCourt.length > 0) return "Filling";
    return "Available";
  }, [court.lockReason, isFull, isLocked, playersOnCourt.length, readOnly, timer.isPaused, timer.startTime]);

  // Updated status colors for Pickle Studio
  const statusClass = useMemo(() => {
    if (isLocked) {
      return "bg-amber-100 text-amber-900 border border-amber-200";
    }
    if (readOnly) {
      // For Display Variant: use solid blocks if variant is display, but here we just return base classes
      return isFull ? "bg-red-50 text-red-700 border border-red-100" : "bg-pickle-green/10 text-pickle-green border border-pickle-green/20";
    }
    if (timer.startTime && !timer.isPaused) return "bg-blue-50 text-blue-700 border border-blue-100";
    if (timer.isPaused) return "bg-amber-50 text-amber-700 border border-amber-100";
    if (isFull) return "bg-purple-50 text-purple-700 border border-purple-100";
    if (playersOnCourt.length > 0) return "bg-gray-50 text-gray-600 border border-gray-100";
    return "bg-pickle-green/10 text-pickle-green border border-pickle-green/20";
  }, [isFull, isLocked, playersOnCourt.length, readOnly, timer.isPaused, timer.startTime]);

  const speakCourt = useCallback(
    (message) => {
      let text = message || "";
      if (!text) {
        if (playersOnCourt.length === 0) text = `${court.name} has no players.`;
        else text = `${court.name}. Players are: ${playersOnCourt.map((p) => p.name).join(", ")}.`;
      }
      const voiceName = localStorage.getItem("dm_voiceName") || "";
      const rate = Number(localStorage.getItem("dm_rate") || 0.9);
      const pitch = Number(localStorage.getItem("dm_pitch") || 1.0);
      speak(text, { voiceName, rate, pitch });
    },
    [court.name, playersOnCourt]
  );

  const handleAssignPlayer = useCallback(
    (option) => {
      if (!option) return;
      if (court.locked) return;
      onAssign(court.id, option.value);
      setSelectedPlayer(null);
    },
    [court.id, court.locked, onAssign]
  );

  const changeTeam = (playerId, team) => {
    const current = teamAssignments.get(playerId) || null;
    if (current === team) team = null;

    const desired = {
      green: court.teamGreen || [],
      blue: court.teamBlue || [],
    };

    if (desired.green.includes(playerId)) desired.green = desired.green.filter((id) => id !== playerId);
    if (desired.blue.includes(playerId)) desired.blue = desired.blue.filter((id) => id !== playerId);

    if (team === "green" && desired.green.length < MAX_TEAM_SIZE) {
      desired.green = [...desired.green, playerId];
    } else if (team === "blue" && desired.blue.length < MAX_TEAM_SIZE) {
      desired.blue = [...desired.blue, playerId];
    }

    onSetTeams(court.id, desired);
  };

  const orderedCourtPlayers = playersOnCourt;

  const handleEndGame = () => {
    speakCourt(`Game finished on ${court.name}`);
    onCompleteMatch(court.id);
  };

  const cardCls = compact
    ? "border border-pickle-green/10 rounded-lg p-2 shadow-none bg-white hover:border-pickle-green/30 transition-all text-xs"
    : "border border-pickle-green/10 rounded-xl p-2.5 shadow-sm bg-white hover:shadow-md transition-all";

  // Pickel Studio Header Text
  const headerTextCls = compact
    ? "font-bold text-sm text-pickle-green font-display tracking-tight"
    : "font-bold text-base text-pickle-green font-display tracking-wide";

  const displayButtonClass = isDisplayOpen
    ? "bg-pickle-green text-pickle-cream px-2 py-1 text-[10px] w-full rounded-full transition ring-1 ring-pickle-green/30"
    : "bg-pickle-green hover:bg-pickle-green/90 text-pickle-cream px-2 py-1 text-[10px] w-full rounded-full transition shadow-sm active:scale-95";

  if (readOnly) {
    // ... (Display Variant logic skipped for brevity, only touching Queue Page ReadOnly below)
    if (variant === "display") {
      // ... existing display logic ...
      // Re-inserting the display logic just to match the block if needed, but I'll skip to the Queue Page part
      return (
        <div className="bg-white rounded-[2rem] p-5 flex flex-col h-full border-[6px] border-white relative overflow-hidden shadow-sm">
          {/* Header Row */}
          <div className="flex justify-between items-start mb-4 px-1">
            <div className="flex flex-col">
              <h3 className="text-6xl font-oswald font-bold text-pickle-brown uppercase leading-none tracking-tight">
                {court.name.replace(/[^0-9]/g, "") ? `COURT ${court.name.replace(/[^0-9]/g, "")}` : court.name}
              </h3>
              <div className={`text-3xl font-oswald font-medium tracking-wide mt-2 ${timer.startTime && !timer.isPaused ? 'text-pickle-red' : 'text-slate-400'}`}>
                {timer.startTime ? formatDuration(elapsedMs) : "00:00"} {timer.startTime ? (timer.isPaused ? "PAUSED" : "RUNNING") : "IDLE"}
              </div>
            </div>
            <div className={`px-6 py-2 rounded-full ${isFull ? "bg-pickle-dgreen text-pickle-cream" : "bg-pickle-green/20 text-pickle-green"}`}>
              <span className="text-3xl font-oswald uppercase tracking-widest font-bold">
                {statusLabel}
              </span>
            </div>
          </div>

          {/* Players Grid (2x2) */}
          <div className="grid grid-cols-2 gap-x-6 gap-y-4 flex-1">
            {[0, 1, 2, 3].map(i => {
              const p = playersOnCourt[i];
              return (
                <div key={i} className="bg-white border-4 border-pickle-brown rounded-full px-6 py-2 flex items-center justify-between shadow-sm h-full max-h-[6rem]">
                  {p ? (
                    <>
                      <span className="font-oswald text-4xl text-pickle-brown font-bold uppercase truncate max-w-[70%] leading-tight pl-2">{p.name}</span>
                      <span className="font-oswald text-3xl text-pickle-brown/60 font-bold pr-2">({p.matches ?? 0})</span>
                    </>
                  ) : (
                    <span className="font-oswald text-3xl text-pickle-brown/20 uppercase w-full text-center">Empty</span>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )
    }

    // --- EXISTING READONLY VIEW (Queue Page) ---
    return (
      <div className={cardCls}>
        <div className="flex justify-between items-center mb-2 gap-2">
          <div className="flex flex-col">
            <input
              type="text"
              value={court.name}
              readOnly
              className={`${headerTextCls} bg-transparent border-none focus:ring-0 p-0 w-28`}
            />
            <div className="text-[10px] text-slate-400 font-mono flex items-center gap-1 leading-tight">
              <span>{formatDuration(elapsedMs)}</span>
              <span className="uppercase tracking-wide font-semibold text-[9px]">
                {timer.startTime ? (timer.isPaused ? "P" : "R") : "I"}
              </span>
            </div>
          </div>
          <span className={`text-[9px] uppercase tracking-wider font-bold px-1.5 py-0.5 rounded ${statusClass}`}>{statusLabel}</span>
        </div>

        <ul className="mb-0 grid grid-cols-2 gap-1.5">
          {playersOnCourt.map((p) => {
            const levelTone = getLevelToneClass(p.level);
            return (
              <li
                key={p.id}
                className="flex w-full flex-wrap items-center gap-x-1 gap-y-0.5 rounded border px-1.5 py-1 shadow-sm bg-white border-slate-100 min-h-[2rem]"
              >
                <div className="flex min-w-0 flex-1 items-center gap-1">
                  <span
                    aria-hidden="true"
                    className={`h-2 w-2 shrink-0 rounded-full bg-gradient-to-br shadow-inner ${levelTone}`}
                  />
                  <span className="truncate text-[10px] font-semibold tracking-tight text-gray-700 leading-tight">
                    {p.name ? p.name.toUpperCase() : "REQ"}
                  </span>
                </div>
                <span className="ml-auto text-[9px] font-semibold text-gray-400 leading-none">({p.matches ?? 0})</span>
              </li>
            );
          })}
          {/* Fill empty spots to maintain grid height? Optional but looks uniform */}
          {Array.from({ length: 4 - playersOnCourt.length }).map((_, i) => (
            <li key={`empty-${i}`} className="border border-dashed border-slate-100 rounded h-[2rem] bg-slate-50/50"></li>
          ))}
        </ul>
      </div>
    );
  }



  return (
    <div className={cardCls}>
      <div className="flex justify-between items-start mb-3 gap-2">
        <div className="flex flex-col gap-1">
          <input
            type="text"
            value={court.name}
            onChange={(e) => onUpdateCourtName(court.id, e.target.value)}
            onBlur={(e) => {
              if (!e.target.value.trim()) onUpdateCourtName(court.id, `Court ${court.id}`);
            }}
            className={`${headerTextCls} bg-transparent border-b border-transparent hover:border-pickle-green/20 focus:border-pickle-green focus:outline-none w-36 transition-colors`}
          />
          <div className="text-xs text-slate-500 font-mono flex items-center gap-2">
            <span>{formatDuration(elapsedMs)}</span>
            <span className="uppercase tracking-wide text-[10px] font-semibold">
              {timer.startTime ? (timer.isPaused ? "Paused" : "Running") : "Idle"}
            </span>
          </div>
        </div>

        <div className="flex flex-col items-end gap-2 relative">
          <div className="flex items-center gap-1">
            <span className={`text-[10px] uppercase tracking-wider font-bold px-2 py-1 rounded-md ${statusClass}`}>{statusLabel}</span>

            {/* Kebab Menu */}
            {!readOnly && playersOnCourt.length > 0 && (
              <div className="relative group">
                <button className="p-1 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600 transition-colors">
                  <MoreVertical className="h-4 w-4" />
                </button>

                {/* Dropdown with bridge */}
                <div className="absolute right-0 top-full pt-1 z-20 hidden group-hover:block hover:block">
                  <div className="w-40 bg-white rounded-lg shadow-lg border border-slate-100 overflow-hidden">
                    <button
                      onClick={() => onRequestMove(court.id)}
                      className="w-full text-left px-3 py-2 text-xs font-medium text-slate-600 hover:bg-slate-50 flex items-center gap-2"
                    >
                      <ArrowRightLeft className="h-3 w-3" />
                      Move Match
                    </button>
                    <button
                      onClick={() => onReturnToQueue(court.id)}
                      className="w-full text-left px-3 py-2 text-xs font-medium text-slate-600 hover:bg-slate-50 flex items-center gap-2 border-t border-slate-50"
                    >
                      <Undo2 className="h-3 w-3" />
                      Return to Queue
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>

          {isLocked && !readOnly && (
            <button
              type="button"
              className="text-[10px] text-amber-700 hover:text-amber-900 underline-offset-2 hover:underline"
              onClick={() => onUnlockCourt?.(court.id)}
            >
              Unlock court
            </button>
          )}
          {!isDefault && (
            <button
              className="text-[10px] text-red-400 hover:text-red-600 transition-colors"
              onClick={() => {
                if (isDisplayOpen) onDisplayClose(court.id);
                onRemoveCourt(court.id);
              }}
            >
              Remove Court
            </button>
          )}
        </div>
      </div>

      <ul className="mb-3 grid grid-cols-2 gap-2">
        {orderedCourtPlayers.map((player) => {
          const team = teamAssignments.get(player.id) || null;
          const levelTone = getLevelToneClass(player.level);
          const buttonBase =
            "px-2 py-0.5 rounded-md border text-[9px] font-bold uppercase transition-colors shrink-0";
          const greenSelected = team === "green";
          const blueSelected = team === "blue";
          const greenDisabled = !greenSelected && (court.teamGreen?.length || 0) >= MAX_TEAM_SIZE;
          const blueDisabled = !blueSelected && (court.teamBlue?.length || 0) >= MAX_TEAM_SIZE;

          // Pink styling for female players
          const isFemale = player.gender === "F";
          const cardBg = isFemale ? "bg-pink-50 border-pink-100 hover:border-pink-200" : "bg-white border-slate-100/80 hover:border-pickle-green/20";

          return (
            <li
              key={player.id}
              className={`flex w-full flex-col gap-y-1.5 rounded-xl border px-2.5 py-2 shadow-sm transition-all ${cardBg}`}
            >
              <div className="flex w-full items-center justify-between">
                {/* Team Selection Buttons - MOVED ABOVE NAME */}
                <div className="flex items-center gap-1">
                  <button
                    type="button"
                    className={`${buttonBase} ${greenSelected
                      ? "bg-green-600 text-white border-green-600 shadow-sm"
                      : greenDisabled
                        ? "bg-white text-green-300 border-green-100 cursor-not-allowed"
                        : "bg-white text-green-600 border-green-200 hover:bg-green-50"
                      }`}
                    onClick={() => changeTeam(player.id, "green")}
                    disabled={greenDisabled}
                  >
                    G
                  </button>
                  <button
                    type="button"
                    className={`${buttonBase} ${blueSelected
                      ? "bg-blue-600 text-white border-blue-600 shadow-sm"
                      : blueDisabled
                        ? "bg-white text-blue-300 border-blue-100 cursor-not-allowed"
                        : "bg-white text-blue-600 border-blue-200 hover:bg-blue-50"
                      }`}
                    onClick={() => changeTeam(player.id, "blue")}
                    disabled={blueDisabled}
                  >
                    B
                  </button>
                </div>

                <div className="flex items-center gap-1">
                  <span className="text-[9px] font-semibold text-slate-300">
                    ({player.matches ?? 0})
                  </span>
                  <button
                    type="button"
                    className="ml-1 text-xs font-bold text-red-300 transition-colors hover:text-red-500"
                    onClick={() => onRemove(court.id, player.id)}
                    aria-label={`Remove ${player.name} from court`}
                  >
                    ×
                  </button>
                </div>
              </div>

              <div className="flex min-w-0 flex-1 items-center gap-1.5 pt-0.5">
                <span
                  aria-hidden="true"
                  className={`h-2.5 w-2.5 shrink-0 rounded-full bg-gradient-to-br shadow-inner ${levelTone}`}
                  title={player.level ? `${player.level} level` : "Level not set"}
                />
                <span className={`truncate text-[11px] font-semibold tracking-wide ${isFemale ? 'text-pink-900' : 'text-slate-700'}`}>
                  {player.name ? player.name.toUpperCase() : "UNKNOWN"}
                </span>
              </div>
            </li>
          );
        })}
      </ul>

      <Select
        className="text-sm"
        isDisabled={isFull}
        isSearchable
        placeholder={isFull ? "Court full (4 players)" : "+ Add player"}
        value={selectedPlayer}
        options={waitingOptions}
        onChange={handleAssignPlayer}
        onInputChange={(_, action) => {
          if (action.action === "menu-close") setSelectedPlayer(null);
        }}
        isClearable
        formatOptionLabel={(option) => (
          <div className="flex items-center gap-2">
            {genderSymbol(option.gender)}
            <span className="font-medium text-slate-800">{option.label}</span>
            <span className="px-2 py-0.5 rounded text-[10px] font-semibold bg-slate-100 text-slate-600">
              {LEVEL_SYMBOLS[option.level] || "⚪"} {option.level || ""}
            </span>
            <span className="text-[10px] text-slate-400">({option.matches})</span>
            <span className="text-[10px] text-slate-400 font-mono">{option.wait}m</span>
          </div>
        )}
        classNames={{
          control: (state) => `!rounded-lg !border-slate-200 hover:!border-pickle-green/40 focus:!border-pickle-green !shadow-none ${state.isDisabled ? "!bg-slate-50" : ""}`,
          option: (state) => state.isSelected ? "!bg-pickle-green !text-white" : state.isFocused ? "!bg-pickle-green/10" : "",
        }}
      />

      <div className="flex gap-2 mt-3">
        <button
          type="button"
          className={displayButtonClass}
          onClick={() => {
            if (isDisplayOpen) onDisplayClose(court.id);
            else onDisplayOpen(court.id);
          }}
        >
          {isDisplayOpen ? "Close Display Modal" : "Show On Display"}
        </button>
        <button
          type="button"
          className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 py-1.5 text-xs rounded-full transition font-medium"
          onClick={handleEndGame}
        >
          End Game
        </button>
      </div>

      {isDisplayOpen && (
        <div className="mt-3 flex items-center justify-between rounded-lg border border-pickle-green/20 bg-pickle-green/5 px-3 py-2 text-xs text-pickle-green">
          <span className="font-semibold flex items-center gap-2">
            <span aria-hidden="true">📺</span>
            Display modal is live
            <span className="text-red-500 font-bold ml-1">({displayTimer}s)</span>
          </span>
          <div className="flex items-center gap-3">
            <button
              type="button"
              className="text-[11px] font-semibold underline hover:no-underline"
              onClick={() => speakCourt()}
            >
              Call
            </button>
            <button
              type="button"
              className="text-[11px] font-semibold underline hover:no-underline"
              onClick={() => onDisplayClose(court.id)}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
